const SHELL_EXEC_TRUNCATE_BYTES: usize = 131_072; // 128 KB

fn mcp_schema_codex_context() -> bool {
    let client = std::env::var("AGENT_BRIDGE_CLIENT").ok();
    let toolset = std::env::var("AGENT_BRIDGE_TOOLSET").ok();
    let codex_host = std::env::var("AGENT_BRIDGE_CODEX_HOST").ok();

    client
        .as_deref()
        .map(normalize_tool_policy_value)
        .is_some_and(|v| v.starts_with("codex"))
        || toolset
            .as_deref()
            .map(normalize_tool_policy_value)
            .is_some_and(|v| v.starts_with("codex"))
        || codex_host.as_deref().is_some_and(|v| !v.trim().is_empty())
}

fn append_codex_native_hint(base: &str, codex_note: &str, codex_context: bool) -> String {
    if codex_context {
        format!("{base} Codex note: {codex_note}")
    } else {
        base.to_string()
    }
}

fn mcp_schema_description(base: &str, codex_note: &str) -> String {
    append_codex_native_hint(base, codex_note, mcp_schema_codex_context())
}

fn compact_mcp_output_default() -> bool {
    let policy = ToolPolicy::from_env();
    compact_mcp_output_default_for_policy(policy)
}

fn compact_mcp_output_default_for_policy(policy: ToolPolicy) -> bool {
    matches!(policy.set, ToolSet::CodexEssential | ToolSet::CodexLean)
        || matches!(policy.profile(), ToolProfile::Compact)
}

const FORUM_READ_DEFAULT_LIMIT: u32 = 50;
const FORUM_READ_COMPACT_DEFAULT_LIMIT: u32 = 8;

pub(crate) fn truncate_chars(s: &str, max_chars: usize) -> (String, bool, usize) {
    let total = s.chars().count();
    if max_chars == 0 || total <= max_chars {
        (s.to_string(), false, total)
    } else {
        let mut out: String = s.chars().take(max_chars).collect();
        out.push('…');
        (out, true, total)
    }
}

pub(crate) fn project_forum_posts(
    posts: &[ForumPostRecord],
    body_max_chars: usize,
    include_refs: bool,
) -> (Vec<Value>, usize) {
    let mut truncated = 0usize;
    let out = posts
        .iter()
        .map(|post| {
            let (body, body_truncated, body_total_chars) =
                truncate_chars(&post.body, body_max_chars);
            if body_truncated {
                truncated += 1;
            }
            let mut obj = Map::new();
            obj.insert("id".to_string(), json!(post.id));
            obj.insert("thread_id".to_string(), json!(post.thread_id));
            obj.insert("author".to_string(), json!(post.author));
            obj.insert("kind".to_string(), json!(post.kind));
            obj.insert("body".to_string(), json!(body));
            if body_truncated {
                obj.insert("body_truncated".to_string(), json!(true));
                obj.insert("body_total_chars".to_string(), json!(body_total_chars));
            }
            if include_refs {
                obj.insert("refs".to_string(), post.refs.clone());
            } else if !post.refs.is_null() {
                obj.insert("refs_omitted".to_string(), json!(true));
            }
            obj.insert("created_at".to_string(), json!(post.created_at));
            Value::Object(obj)
        })
        .collect();
    (out, truncated)
}

fn capabilities_summary(capabilities: &Value) -> Value {
    let Some(obj) = capabilities.as_object() else {
        return json!({"type": capabilities_type_label(capabilities)});
    };
    let mut keys: Vec<&str> = obj.keys().map(|s| s.as_str()).collect();
    keys.sort_unstable();
    let mut out = Map::new();
    out.insert("keys".to_string(), json!(keys));
    if let Some(avatar) = obj.get("avatar_state").and_then(|v| v.as_object()) {
        let mut compact = Map::new();
        for key in [
            "mode",
            "activity_state",
            "focus",
            "next_action",
            "risk_level",
            "updated_at",
            "source",
        ] {
            if let Some(v) = avatar.get(key) {
                compact.insert(key.to_string(), v.clone());
            }
        }
        if let Some(policy) = avatar.get("voice_policy").and_then(|v| v.as_object()) {
            if let Some(default_silent) = policy.get("default_silent") {
                compact.insert("voice_default_silent".to_string(), default_silent.clone());
            }
        }
        if !compact.is_empty() {
            out.insert("avatar_state".to_string(), Value::Object(compact));
        }
    }
    if let Some(pet) = obj.get("pet_state").and_then(|v| v.as_object()) {
        let mut compact = Map::new();
        for key in [
            "mode",
            "activity_state",
            "focus",
            "next_action",
            "risk_level",
        ] {
            if let Some(v) = pet.get(key) {
                compact.insert(key.to_string(), v.clone());
            }
        }
        if !compact.is_empty() {
            out.insert("pet_state".to_string(), Value::Object(compact));
        }
    }
    Value::Object(out)
}

fn capabilities_type_label(v: &Value) -> &'static str {
    match v {
        Value::Null => "null",
        Value::Bool(_) => "bool",
        Value::Number(_) => "number",
        Value::String(_) => "string",
        Value::Array(_) => "array",
        Value::Object(_) => "object",
    }
}

fn project_agent_presence_rows(
    rows: &[AgentPresenceRecord],
    include_capabilities: bool,
    include_skills: bool,
) -> (Vec<Value>, usize, usize) {
    let mut capabilities_omitted = 0usize;
    let mut skills_omitted = 0usize;
    let out = rows
        .iter()
        .map(|row| {
            let mut obj = Map::new();
            obj.insert("session_id".to_string(), json!(row.session_id));
            obj.insert("name".to_string(), json!(row.name));
            if let Some(v) = &row.description {
                obj.insert("description".to_string(), json!(v));
            }
            if let Some(v) = &row.version {
                obj.insert("version".to_string(), json!(v));
            }
            if let Some(v) = &row.url {
                obj.insert("url".to_string(), json!(v));
            }
            if include_capabilities {
                if let Some(v) = &row.capabilities {
                    obj.insert("capabilities".to_string(), v.clone());
                }
            } else if let Some(v) = &row.capabilities {
                capabilities_omitted += 1;
                obj.insert("capabilities_omitted".to_string(), json!(true));
                obj.insert("capabilities_summary".to_string(), capabilities_summary(v));
            }
            if include_skills {
                if let Some(v) = &row.skills {
                    obj.insert("skills".to_string(), v.clone());
                }
            } else if row.skills.is_some() {
                skills_omitted += 1;
                obj.insert("skills_omitted".to_string(), json!(true));
            }
            obj.insert("node".to_string(), json!(row.node));
            obj.insert("project".to_string(), json!(row.project));
            obj.insert("role".to_string(), json!(row.role));
            if let Some(v) = &row.tag {
                obj.insert("tag".to_string(), json!(v));
            }
            if let Some(v) = &row.cwd {
                obj.insert("cwd".to_string(), json!(v));
            }
            if let Some(v) = row.pid {
                obj.insert("pid".to_string(), json!(v));
            }
            obj.insert("started_at".to_string(), json!(row.started_at));
            obj.insert(
                "last_heartbeat_at".to_string(),
                json!(row.last_heartbeat_at),
            );
            Value::Object(obj)
        })
        .collect();
    (out, capabilities_omitted, skills_omitted)
}

pub struct ShellExecTool {
    hub: Hub,
}

impl ShellExecTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

#[async_trait]
impl McpTool for ShellExecTool {
    fn name(&self) -> &'static str {
        "shell_exec"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: mcp_schema_description(
                "Run a shell command synchronously; returns exit code, stdout, \
                 stderr, wall-clock duration. Unlike terminal_send_keys this captures \
                 output directly; no PTY needed. stdout/stderr truncated at 128 KB. \
                 Default timeout 30 s, max 300 s.",
                "Prefer Codex native shell/exec tools for ordinary local commands; use \
                 this Agent-Bridge tool only when you need MCP-level execution, dispatch \
                 telemetry, or Agent-Bridge security/env limits.",
            ),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "cmd": {
                        "type": "string",
                        "description": "Shell command to run (executed via sh -c)."
                    },
                    "cwd": {
                        "type": "string",
                        "description": "Working directory. Defaults to the agent-bridge process cwd."
                    },
                    "timeout_ms": {
                        "type": "integer",
                        "minimum": 1000,
                        "maximum": 300000,
                        "default": 30000,
                        "description": "Milliseconds before the process is killed."
                    },
                    "env": {
                        "type": "object",
                        "description": "Extra environment variables to inject (string keys + values).",
                        "additionalProperties": { "type": "string" }
                    }
                },
                "required": ["cmd"]
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        if let Err(e) = self.hub.security.check(Cap::ShellExec) {
            return Ok(ToolResult::error(e));
        }
        let cmd = match args.get("cmd").and_then(|v| v.as_str()) {
            Some(s) if !s.is_empty() => s.to_string(),
            _ => return Ok(ToolResult::error("missing or empty 'cmd'")),
        };
        let timeout_max = self.hub.security.shell_exec_timeout_max_ms;
        let timeout_ms = args
            .get("timeout_ms")
            .and_then(|v| v.as_u64())
            .unwrap_or(30_000)
            .clamp(1_000, timeout_max);

        let mut child = {
            let mut builder = killable_command("sh");
            builder.arg("-c").arg(&cmd);
            builder.stdout(std::process::Stdio::piped());
            builder.stderr(std::process::Stdio::piped());
            if let Some(cwd) = args.get("cwd").and_then(|v| v.as_str()) {
                builder.current_dir(cwd);
            }
            if let Some(env_map) = args.get("env").and_then(|v| v.as_object()) {
                for (k, v) in env_map {
                    if let Some(val) = v.as_str() {
                        builder.env(k, val);
                    }
                }
            }
            match builder.spawn() {
                Ok(c) => c,
                Err(e) => return Ok(ToolResult::error(format!("spawn failed: {e}"))),
            }
        };

        let started = Instant::now();
        let deadline = Duration::from_millis(timeout_ms);

        // Drain stdout + stderr in background tasks so the process doesn't block on full pipes.
        use tokio::io::AsyncReadExt as _;
        let mut stdout_pipe = child.stdout.take().expect("stdout piped");
        let mut stderr_pipe = child.stderr.take().expect("stderr piped");
        let stdout_task = tokio::spawn(async move {
            let mut buf = Vec::new();
            let _ = stdout_pipe.read_to_end(&mut buf).await;
            buf
        });
        let stderr_task = tokio::spawn(async move {
            let mut buf = Vec::new();
            let _ = stderr_pipe.read_to_end(&mut buf).await;
            buf
        });

        let timed_out = tokio::time::timeout(deadline, child.wait()).await;
        let duration_ms = started.elapsed().as_millis() as u64;

        let exit_code = match timed_out {
            Err(_) => {
                child.start_kill().ok();
                stdout_task.abort();
                stderr_task.abort();
                return Ok(ToolResult::json_text(&json!({
                    "exit_code": -1,
                    "stdout": "",
                    "stderr": format!("killed after {timeout_ms} ms timeout"),
                    "duration_ms": duration_ms,
                    "truncated": false
                })));
            }
            Ok(Err(e)) => return Ok(ToolResult::error(format!("wait failed: {e}"))),
            Ok(Ok(status)) => status.code().unwrap_or(-1),
        };

        let stdout_bytes = stdout_task.await.unwrap_or_default();
        let stderr_bytes = stderr_task.await.unwrap_or_default();
        let (stdout_str, stdout_truncated) = lossy_truncate(&stdout_bytes);
        let (stderr_str, stderr_truncated) = lossy_truncate(&stderr_bytes);

        Ok(ToolResult::json_text(&json!({
            "exit_code": exit_code,
            "stdout": stdout_str,
            "stderr": stderr_str,
            "duration_ms": duration_ms,
            "truncated": stdout_truncated || stderr_truncated
        })))
    }
}

fn lossy_truncate(bytes: &[u8]) -> (String, bool) {
    if bytes.len() <= SHELL_EXEC_TRUNCATE_BYTES {
        (String::from_utf8_lossy(bytes).into_owned(), false)
    } else {
        let s = String::from_utf8_lossy(&bytes[..SHELL_EXEC_TRUNCATE_BYTES]).into_owned();
        (
            format!(
                "{s}\n[... truncated at {} KB]",
                SHELL_EXEC_TRUNCATE_BYTES / 1024
            ),
            true,
        )
    }
}

// ===========================================================================
//                              system_control
// ===========================================================================

#[derive(Debug, Clone, PartialEq, Eq)]
struct SystemControlPlan {
    argv: Vec<String>,
    risk: &'static str,
    read_only: bool,
}

fn system_control_plan(
    domain: &str,
    action: &str,
    confirm: bool,
    tail_lines: u64,
    topic: Option<&str>,
) -> std::result::Result<SystemControlPlan, String> {
    let mut argv = Vec::new();
    let (risk, read_only) = match domain {
        "display" if matches!(action, "off" | "on") => {
            argv.extend([domain.to_string(), action.to_string()]);
            ("low", false)
        }
        "audio" if matches!(action, "up" | "down" | "mute" | "micmute") => {
            argv.extend([domain.to_string(), action.to_string()]);
            ("low", false)
        }
        "brightness" if matches!(action, "up" | "down") => {
            argv.extend([domain.to_string(), action.to_string()]);
            ("low", false)
        }
        "screenshot" if matches!(action, "full" | "region") => {
            argv.extend([domain.to_string(), action.to_string()]);
            ("low", false)
        }
        "wifi"
            if matches!(
                action,
                "networks" | "actions" | "reconnect" | "toggle" | "nmtui"
            ) =>
        {
            argv.extend([domain.to_string(), action.to_string()]);
            ("medium", false)
        }
        "desktop" if action == "doctor" => {
            argv.extend([domain.to_string(), action.to_string()]);
            ("low", true)
        }
        "desktop" if action == "heal" => {
            if !confirm {
                return Err("desktop heal requires confirm=true".to_string());
            }
            argv.extend([
                domain.to_string(),
                action.to_string(),
                "--confirm".to_string(),
            ]);
            ("medium", false)
        }
        "desktop" if action == "watchdog" => {
            if !confirm {
                return Err("desktop watchdog requires confirm=true".to_string());
            }
            argv.extend([
                domain.to_string(),
                action.to_string(),
                "--confirm".to_string(),
            ]);
            ("medium", false)
        }
        "desktop" if action == "repair" => {
            if !confirm {
                return Err("desktop repair requires confirm=true".to_string());
            }
            argv.extend([
                domain.to_string(),
                action.to_string(),
                "--confirm".to_string(),
            ]);
            ("medium", false)
        }
        "events" if action == "tail" => {
            argv.push("events".to_string());
            argv.push("tail".to_string());
            argv.push(tail_lines.clamp(1, 500).to_string());
            ("low", true)
        }
        "events" if action == "diagnose" => {
            let topic = topic
                .map(str::trim)
                .filter(|s| !s.is_empty())
                .ok_or_else(|| "events diagnose requires non-empty topic".to_string())?;
            if !topic
                .chars()
                .all(|c| c.is_ascii_alphanumeric() || matches!(c, '_' | '-' | '.'))
            {
                return Err("events diagnose topic may only contain ASCII letters, digits, '_', '-', or '.'".to_string());
            }
            argv.push("events".to_string());
            argv.push("diagnose".to_string());
            argv.push(topic.to_string());
            argv.push(tail_lines.clamp(1, 500).to_string());
            ("low", true)
        }
        "status"
            if matches!(
                action,
                "summary" | "snapshot" | "history" | "diagnose" | "report"
            ) =>
        {
            argv.extend([domain.to_string(), action.to_string()]);
            if matches!(action, "history" | "diagnose" | "report") {
                argv.push(tail_lines.clamp(1, 200).to_string());
            }
            ("low", true)
        }
        "status" if action == "record" => {
            argv.extend([domain.to_string(), action.to_string()]);
            ("low", false)
        }
        "lid" if matches!(action, "off" | "on") => {
            argv.extend([domain.to_string(), action.to_string()]);
            ("low", false)
        }
        "power" if action == "press" => {
            argv.extend([domain.to_string(), action.to_string()]);
            ("medium", false)
        }
        "power" if action == "off" => {
            if !confirm {
                return Err("power off requires confirm=true".to_string());
            }
            argv.extend([
                domain.to_string(),
                action.to_string(),
                "--confirm".to_string(),
            ]);
            ("high", false)
        }
        "audit" if action == "tail" => {
            argv.push("audit-tail".to_string());
            argv.push(tail_lines.clamp(1, 500).to_string());
            ("low", true)
        }
        _ => {
            return Err(format!(
                "unsupported system_control action: domain={domain:?} action={action:?}"
            ));
        }
    };
    Ok(SystemControlPlan {
        argv,
        risk,
        read_only,
    })
}

fn default_system_control_bin() -> PathBuf {
    std::env::var_os("AB_SYSTEM_CONTROL_BIN")
        .map(PathBuf::from)
        .or_else(|| {
            std::env::var_os("HOME").map(|home| {
                PathBuf::from(home)
                    .join(".local")
                    .join("bin")
                    .join("ab-system-control")
            })
        })
        .unwrap_or_else(|| PathBuf::from("/home/pallasting/.local/bin/ab-system-control"))
}

pub struct SystemControlTool {
    hub: Hub,
}

impl SystemControlTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

#[async_trait]
impl McpTool for SystemControlTool {
    fn name(&self) -> &'static str {
        "system_control"
    }

    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "LLM-safe local Sway/system control wrapper. Calls the \
                 allowlisted `ab-system-control` actions for display, audio, \
                 brightness, screenshot, WiFi, desktop doctor/heal/watchdog/repair, status summary/snapshot/record/history/diagnose/report, event timeline/diagnosis, lid, power button, and audit-tail; \
                 it never accepts arbitrary shell commands. Each action is audited \
                 by the local script. High-risk power off, desktop heal, desktop watchdog, and desktop repair require confirm=true."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "domain": {
                        "type": "string",
                        "enum": ["display", "audio", "brightness", "screenshot", "wifi", "desktop", "events", "status", "lid", "power", "audit"],
                        "description": "Control surface."
                    },
                    "action": {
                        "type": "string",
                        "description": "Allowed actions: display off|on; audio up|down|mute|micmute; brightness up|down; screenshot full|region; wifi networks|actions|reconnect|toggle|nmtui; desktop doctor|heal|watchdog|repair; events tail|diagnose; status summary|snapshot|record|history|diagnose|report; lid off|on; power press|off; audit tail."
                    },
                    "confirm": {
                        "type": "boolean",
                        "default": false,
                        "description": "Required for power off, desktop heal, desktop watchdog, and desktop repair."
                    },
                    "tail_lines": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": 500,
                        "default": 40,
                        "description": "Line count for domain=audit action=tail."
                    },
                    "topic": {
                        "type": "string",
                        "description": "Required for domain=events action=diagnose; examples: audio, brightness, wifi, power, statusbar, screenshot."
                    },
                    "timeout_ms": {
                        "type": "integer",
                        "minimum": 1000,
                        "maximum": 60000,
                        "default": 15000,
                        "description": "Milliseconds before the control process is killed."
                    },
                    "bin": {
                        "type": "string",
                        "description": "Optional absolute path to ab-system-control, mainly for tests or alternate installs."
                    }
                },
                "required": ["domain", "action"],
                "additionalProperties": false
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        if let Err(e) = self.hub.security.check(Cap::ShellExec) {
            return Ok(ToolResult::error(e));
        }
        let domain = match args.get("domain").and_then(|v| v.as_str()) {
            Some(s) if !s.is_empty() => s,
            _ => return Ok(ToolResult::error("missing or empty 'domain'")),
        };
        let action = match args.get("action").and_then(|v| v.as_str()) {
            Some(s) if !s.is_empty() => s,
            _ => return Ok(ToolResult::error("missing or empty 'action'")),
        };
        let confirm = args
            .get("confirm")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let tail_lines = args
            .get("tail_lines")
            .and_then(|v| v.as_u64())
            .unwrap_or(40)
            .clamp(1, 500);
        let topic = args.get("topic").and_then(|v| v.as_str());
        let plan = match system_control_plan(domain, action, confirm, tail_lines, topic) {
            Ok(plan) => plan,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        let bin = args
            .get("bin")
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty())
            .map(PathBuf::from)
            .unwrap_or_else(default_system_control_bin);
        if !bin.is_absolute() {
            return Ok(ToolResult::error(
                "system_control 'bin' must be an absolute path",
            ));
        }

        let timeout_ceiling = self
            .hub
            .security
            .shell_exec_timeout_max_ms
            .clamp(1_000, 60_000);
        let timeout_ms = args
            .get("timeout_ms")
            .and_then(|v| v.as_u64())
            .unwrap_or(15_000)
            .clamp(1_000, timeout_ceiling);

        let mut child = {
            let mut builder = killable_command(&bin);
            builder.args(&plan.argv);
            builder.env("AB_ACTOR", "agent-bridge:mcp:system_control");
            builder.stdout(std::process::Stdio::piped());
            builder.stderr(std::process::Stdio::piped());
            match builder.spawn() {
                Ok(c) => c,
                Err(e) => return Ok(ToolResult::error(format!("spawn failed: {e}"))),
            }
        };

        let started = Instant::now();
        let deadline = Duration::from_millis(timeout_ms);
        use tokio::io::AsyncReadExt as _;
        let mut stdout_pipe = child.stdout.take().expect("stdout piped");
        let mut stderr_pipe = child.stderr.take().expect("stderr piped");
        let stdout_task = tokio::spawn(async move {
            let mut buf = Vec::new();
            let _ = stdout_pipe.read_to_end(&mut buf).await;
            buf
        });
        let stderr_task = tokio::spawn(async move {
            let mut buf = Vec::new();
            let _ = stderr_pipe.read_to_end(&mut buf).await;
            buf
        });

        let timed_out = tokio::time::timeout(deadline, child.wait()).await;
        let duration_ms = started.elapsed().as_millis() as u64;
        let exit_code = match timed_out {
            Err(_) => {
                child.start_kill().ok();
                stdout_task.abort();
                stderr_task.abort();
                return Ok(ToolResult::json_text(&json!({
                    "schema": "agent_bridge.system_control.mcp_result.v0",
                    "domain": domain,
                    "action": action,
                    "risk": plan.risk,
                    "read_only": plan.read_only,
                    "confirmed": confirm,
                    "argv": plan.argv,
                    "exit_code": -1,
                    "stdout": "",
                    "stderr": format!("killed after {timeout_ms} ms timeout"),
                    "duration_ms": duration_ms,
                    "truncated": false,
                    "timed_out": true
                })));
            }
            Ok(Err(e)) => return Ok(ToolResult::error(format!("wait failed: {e}"))),
            Ok(Ok(status)) => status.code().unwrap_or(-1),
        };

        let stdout_bytes = stdout_task.await.unwrap_or_default();
        let stderr_bytes = stderr_task.await.unwrap_or_default();
        let (stdout, stdout_truncated) = lossy_truncate(&stdout_bytes);
        let (stderr, stderr_truncated) = lossy_truncate(&stderr_bytes);

        Ok(ToolResult::json_text(&json!({
            "schema": "agent_bridge.system_control.mcp_result.v0",
            "domain": domain,
            "action": action,
            "risk": plan.risk,
            "read_only": plan.read_only,
            "confirmed": confirm,
            "argv": plan.argv,
            "exit_code": exit_code,
            "stdout": stdout,
            "stderr": stderr,
            "duration_ms": duration_ms,
            "truncated": stdout_truncated || stderr_truncated,
            "timed_out": false
        })))
    }
}

// ===========================================================================
//                              desktop_snapshot
// ===========================================================================

const DESKTOP_SNAPSHOT_SEMANTIC_SCHEMA: &str = "agent_bridge.semantic_bus.desktop_snapshot.v0";
const DESKTOP_SNAPSHOT_SOURCE_SCHEMA: &str = "desktop_snapshot/v0.5";

pub struct DesktopSnapshotTool {
    _hub: Hub,
}

impl DesktopSnapshotTool {
    pub fn new(hub: Hub) -> Self {
        Self { _hub: hub }
    }
}

#[async_trait]
impl McpTool for DesktopSnapshotTool {
    fn name(&self) -> &'static str {
        "desktop_snapshot"
    }

    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Read-only Linux desktop structure snapshot. Wraps \
                 scripts/desktop_snapshot.py and returns sway outputs/windows plus optional \
                 AT-SPI semantics. It does not click, type, move windows, or expose \
                 --activate-a11y; screenshots are opt-in to avoid surprise file writes."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "cwd": {
                        "type": "string",
                        "description": "Workspace/repo root used to resolve scripts/desktop_snapshot.py. Defaults to the MCP process cwd, then the build-time repo root."
                    },
                    "script_path": {
                        "type": "string",
                        "description": "Optional explicit desktop_snapshot.py path. Use mainly for tests or alternate checkouts."
                    },
                    "include_screenshot": {
                        "type": "boolean",
                        "default": false,
                        "description": "When true, allow grim to write per-output PNG files. Default false keeps the MCP call non-mutating except process execution."
                    },
                    "screenshot_dir": {
                        "type": "string",
                        "description": "Directory for PNG screenshots when include_screenshot=true."
                    },
                    "include_atspi": {
                        "type": "boolean",
                        "default": true,
                        "description": "Collect AT-SPI semantic elements when available. This does not enable global a11y."
                    },
                    "max_elements": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": 1000,
                        "default": 120,
                        "description": "Cap AT-SPI elements per app."
                    },
                    "atspi_budget": {
                        "type": "number",
                        "minimum": 0.25,
                        "maximum": 10.0,
                        "default": 2.0,
                        "description": "Per-app AT-SPI traversal budget in seconds."
                    },
                    "timeout_ms": {
                        "type": "integer",
                        "minimum": 1000,
                        "maximum": 60000,
                        "default": 15000,
                        "description": "Milliseconds before the snapshot process is killed."
                    },
                    "semantic_bus": {
                        "type": "boolean",
                        "default": false,
                        "description": "When true, wrap the read-only desktop_snapshot/v0.5 payload as agent_bridge.semantic_bus.desktop_snapshot.v0. Default false preserves the existing payload exactly apart from mcp_wrapper."
                    },
                    "semantic_include_raw": {
                        "type": "boolean",
                        "default": false,
                        "description": "Only with semantic_bus=true: include the original desktop_snapshot payload as raw_snapshot. Default false keeps the semantic envelope compact."
                    }
                }
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let timeout_ms = args
            .get("timeout_ms")
            .and_then(|v| v.as_u64())
            .unwrap_or(15_000)
            .clamp(1_000, 60_000);
        let include_screenshot = args
            .get("include_screenshot")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let include_atspi = args
            .get("include_atspi")
            .and_then(|v| v.as_bool())
            .unwrap_or(true);
        let max_elements = args
            .get("max_elements")
            .and_then(|v| v.as_u64())
            .unwrap_or(120)
            .clamp(1, 1000);
        let atspi_budget = args
            .get("atspi_budget")
            .and_then(|v| v.as_f64())
            .unwrap_or(2.0)
            .clamp(0.25, 10.0);
        let semantic_bus = args
            .get("semantic_bus")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let semantic_include_raw = args
            .get("semantic_include_raw")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);

        let cwd = args.get("cwd").and_then(|v| v.as_str()).map(PathBuf::from);
        let script = desktop_snapshot_script_path(&args, cwd.as_ref());
        if !script.exists() {
            return Ok(desktop_snapshot_error(json!({
                "code": "script_missing",
                "message": format!("desktop_snapshot.py not found at {}", script.display()),
                "hint": "pass script_path or run from the Agent-Bridge repo root"
            })));
        }

        let mut cmd = killable_command(
            std::env::var("PYTHON")
                .ok()
                .filter(|s| !s.trim().is_empty())
                .unwrap_or_else(|| "python3".to_string()),
        );
        cmd.arg(&script).arg("--compact");
        if !include_screenshot {
            cmd.arg("--no-screenshot");
        } else if let Some(dir) = args.get("screenshot_dir").and_then(|v| v.as_str()) {
            cmd.arg("--screenshot-dir").arg(dir);
        }
        if !include_atspi {
            cmd.arg("--no-atspi");
        }
        cmd.arg("--max-elements").arg(max_elements.to_string());
        cmd.arg("--atspi-budget").arg(atspi_budget.to_string());
        cmd.stdout(std::process::Stdio::piped());
        cmd.stderr(std::process::Stdio::piped());
        if let Some(cwd) = cwd {
            cmd.current_dir(cwd);
        }

        let started = Instant::now();
        let output =
            match tokio::time::timeout(Duration::from_millis(timeout_ms), cmd.output()).await {
                Err(_) => {
                    return Ok(desktop_snapshot_error(json!({
                        "code": "timeout",
                        "message": format!("desktop_snapshot exceeded {timeout_ms} ms"),
                        "duration_ms": started.elapsed().as_millis() as u64
                    })));
                }
                Ok(Err(e)) => {
                    return Ok(desktop_snapshot_error(json!({
                        "code": "spawn_failed",
                        "message": e.to_string(),
                        "duration_ms": started.elapsed().as_millis() as u64
                    })));
                }
                Ok(Ok(output)) => output,
            };
        let duration_ms = started.elapsed().as_millis() as u64;
        let (stdout, stdout_truncated) = lossy_truncate(&output.stdout);
        let (stderr, stderr_truncated) = lossy_truncate(&output.stderr);

        if !output.status.success() {
            return Ok(desktop_snapshot_error(json!({
                "code": "script_failed",
                "exit_code": output.status.code().unwrap_or(-1),
                "stderr": stderr,
                "stdout": stdout,
                "duration_ms": duration_ms,
                "truncated": stdout_truncated || stderr_truncated
            })));
        }

        match serde_json::from_str::<Value>(&stdout) {
            Ok(mut payload) => {
                if let Some(obj) = payload.as_object_mut() {
                    obj.insert(
                        "mcp_wrapper".to_string(),
                        json!({
                            "tool": self.name(),
                            "read_only": true,
                            "include_screenshot": include_screenshot,
                            "include_atspi": include_atspi,
                            "duration_ms": duration_ms,
                            "stderr": stderr,
                            "stderr_truncated": stderr_truncated
                        }),
                    );
                }
                if semantic_bus {
                    let semantic_payload =
                        desktop_snapshot_semantic_bus_payload(&payload, semantic_include_raw);
                    Ok(ToolResult::json_text(&semantic_payload))
                } else {
                    Ok(ToolResult::json_text(&payload))
                }
            }
            Err(e) => Ok(desktop_snapshot_error(json!({
                "code": "invalid_json",
                "message": e.to_string(),
                "stdout": stdout,
                "stderr": stderr,
                "duration_ms": duration_ms,
                "truncated": stdout_truncated || stderr_truncated
            }))),
        }
    }
}

fn desktop_snapshot_semantic_bus_payload(snapshot: &Value, include_raw: bool) -> Value {
    let source_schema = snapshot
        .get("schema")
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    let captured_at = snapshot.get("captured_at").cloned().unwrap_or(Value::Null);
    let captured_label = desktop_snapshot_value_label(&captured_at, "unknown");
    let session_object_id = format!("desktop:linux:session:{captured_label}");
    let event_id = format!("evt-desktop-snapshot-{captured_label}");
    let verified = source_schema == DESKTOP_SNAPSHOT_SOURCE_SCHEMA;
    let reason = if verified {
        Value::Null
    } else {
        json!("unexpected_source_schema")
    };

    let windows = snapshot
        .get("windows")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    let mut semantic_objects = Vec::new();
    let mut affordances = Vec::new();
    let mut window_ids_by_pid: HashMap<String, String> = HashMap::new();

    semantic_objects.push(json!({
        "schema": "agent_bridge.semantic_bus.object.v0",
        "object_id": session_object_id,
        "object_type": "desktop.session",
        "source_adapter": "linux.sway.session",
        "label": "Linux desktop session",
        "state": {
            "session": snapshot.get("session").cloned().unwrap_or_else(|| json!({})),
            "window_count": snapshot.get("window_count").cloned().unwrap_or(Value::Null),
            "screenshots": snapshot.get("screenshots").cloned().unwrap_or(Value::Null),
        },
        "relations": [],
        "confidence": if verified { 0.95 } else { 0.25 },
        "observed_at": captured_at,
        "provenance": {
            "tool": "desktop_snapshot",
            "schema": source_schema,
        }
    }));

    for (idx, window) in windows.iter().enumerate() {
        if window.get("error").is_some() {
            continue;
        }
        let object_id = desktop_snapshot_window_object_id(window, idx);
        if let Some(pid) = window.get("pid").and_then(Value::as_i64) {
            window_ids_by_pid.insert(pid.to_string(), object_id.clone());
        }
        let title = desktop_snapshot_str(window, "name").unwrap_or("window");
        semantic_objects.push(json!({
            "schema": "agent_bridge.semantic_bus.object.v0",
            "object_id": object_id,
            "object_type": "desktop.window",
            "source_adapter": "linux.sway.tree",
            "label": title,
            "state": {
                "id": window.get("id").cloned().unwrap_or(Value::Null),
                "app_id": window.get("app_id").cloned().unwrap_or(Value::Null),
                "x11_class": window.get("x11_class").cloned().unwrap_or(Value::Null),
                "pid": window.get("pid").cloned().unwrap_or(Value::Null),
                "title": window.get("name").cloned().unwrap_or(Value::Null),
                "focused": window.get("focused").cloned().unwrap_or(Value::Null),
                "visible": window.get("visible").cloned().unwrap_or(Value::Null),
                "grounding": window.get("grounding").cloned().unwrap_or(Value::Null),
                "rect": window.get("rect").cloned().unwrap_or(Value::Null),
                "output": window.get("output").cloned().unwrap_or(Value::Null),
            },
            "relations": [
                { "type": "member_of", "target": session_object_id }
            ],
            "confidence": 0.9,
            "observed_at": captured_at,
            "provenance": {
                "tool": "desktop_snapshot",
                "schema": source_schema,
                "source_path": "windows"
            }
        }));
        affordances.push(json!({
            "affordance_id": format!("{object_id}:verify-window"),
            "object_id": object_id,
            "action_type": "desktop.verify",
            "args_schema": {
                "expect": "window_appeared",
                "win_app_id": window.get("app_id").cloned().unwrap_or(Value::Null),
                "win_title": window.get("name").cloned().unwrap_or(Value::Null),
                "win_pid": window.get("pid").cloned().unwrap_or(Value::Null),
            },
            "risk_level": "low",
            "requires_gate": false,
            "expected_effect": "re-observes matching window state without mutating the desktop"
        }));
    }

    if let Some(apps) = snapshot
        .get("atspi")
        .and_then(|v| v.get("apps"))
        .and_then(Value::as_array)
    {
        for app in apps {
            let pid_label = app
                .get("pid")
                .and_then(Value::as_i64)
                .map(|pid| pid.to_string())
                .unwrap_or_else(|| "unknown".to_string());
            let parent_window = window_ids_by_pid.get(&pid_label).cloned();
            if let Some(elements) = app.get("elements").and_then(Value::as_array) {
                for (idx, element) in elements.iter().enumerate() {
                    let role = desktop_snapshot_str(element, "role").unwrap_or("element");
                    let name = desktop_snapshot_str(element, "name").unwrap_or("");
                    let element_slug = desktop_snapshot_slug(&format!("{role}-{name}-{idx}"));
                    let object_id = format!("desktop:linux:atspi:{pid_label}:{}", element_slug);
                    let mut relations = vec![json!({
                        "type": "member_of",
                        "target": session_object_id
                    })];
                    if let Some(parent) = &parent_window {
                        relations.push(json!({
                            "type": "contained_by",
                            "target": parent
                        }));
                    }
                    semantic_objects.push(json!({
                        "schema": "agent_bridge.semantic_bus.object.v0",
                        "object_id": object_id,
                        "object_type": format!("desktop.accessible.{}", desktop_snapshot_slug(role)),
                        "source_adapter": "linux.atspi",
                        "label": if name.is_empty() { role } else { name },
                        "state": {
                            "app": app.get("name").cloned().unwrap_or(Value::Null),
                            "pid": app.get("pid").cloned().unwrap_or(Value::Null),
                            "role": role,
                            "name": element.get("name").cloned().unwrap_or(Value::Null),
                            "bounds": element.get("bounds").cloned().unwrap_or(Value::Null),
                            "states": element.get("states").cloned().unwrap_or(Value::Null),
                        },
                        "relations": relations,
                        "confidence": 0.88,
                        "observed_at": captured_at,
                        "provenance": {
                            "tool": "desktop_snapshot",
                            "schema": source_schema,
                            "source_path": "atspi.apps[].elements[]"
                        }
                    }));
                    affordances.push(json!({
                        "affordance_id": format!("{object_id}:verify-element"),
                        "object_id": object_id,
                        "action_type": "desktop.verify",
                        "args_schema": {
                            "app": app.get("name").cloned().unwrap_or(Value::Null),
                            "role": role,
                            "name": element.get("name").cloned().unwrap_or(Value::Null),
                            "expect": "state_is"
                        },
                        "risk_level": "low",
                        "requires_gate": false,
                        "expected_effect": "re-observes matching AT-SPI element state"
                    }));
                    if desktop_snapshot_role_is_actionable(role) {
                        affordances.push(json!({
                            "affordance_id": format!("{object_id}:invoke"),
                            "object_id": object_id,
                            "action_type": "desktop.invoke",
                            "args_schema": {
                                "app": app.get("name").cloned().unwrap_or(Value::Null),
                                "role": role,
                                "name": element.get("name").cloned().unwrap_or(Value::Null),
                            },
                            "risk_level": "medium",
                            "requires_gate": true,
                            "expected_effect": "semantic AT-SPI invoke; exposed here only as gated affordance metadata"
                        }));
                    }
                }
            }
        }
    }

    let object_count = semantic_objects.len();
    let affordance_count = affordances.len();
    let window_count = windows.iter().filter(|w| w.get("error").is_none()).count();
    let atspi_object_count = semantic_objects
        .iter()
        .filter(|o| {
            o.get("source_adapter")
                .and_then(Value::as_str)
                .is_some_and(|s| s == "linux.atspi")
        })
        .count();

    let mut payload = json!({
        "schema": DESKTOP_SNAPSHOT_SEMANTIC_SCHEMA,
        "source_schema": source_schema,
        "source_adapter": "linux.desktop_snapshot",
        "captured_at": captured_at,
        "read_only": true,
        "raw_available": true,
        "raw_included": include_raw,
        "semantic_objects": semantic_objects,
        "affordances": affordances,
        "events": [
            {
                "event_id": event_id,
                "event_type": "desktop.snapshot.observed",
                "subject_id": session_object_id,
                "source": "desktop_snapshot",
                "actor": "agent",
                "payload_json": {
                    "object_count": object_count,
                    "affordance_count": affordance_count,
                    "window_count": window_count,
                    "atspi_object_count": atspi_object_count,
                    "screenshot_required": false
                },
                "source_event_ids": []
            }
        ],
        "verification": {
            "verdict": if verified { "verified" } else { "not_verified" },
            "reason": reason,
            "method": "desktop_snapshot.semantic_normalizer",
            "evidence": {
                "source_schema": source_schema,
                "object_count": object_count,
                "window_count": window_count,
                "atspi_object_count": atspi_object_count,
                "raw_included": include_raw
            },
            "verified_to": if verified { json!("semantic_objects") } else { Value::Null },
            "recover": if verified { "proceed" } else { "replan" },
            "raw_available": true
        },
        "presentation": {
            "presentation_id": format!("present-desktop-snapshot-{captured_label}"),
            "source_event_ids": [event_id],
            "human_summary": format!(
                "Normalized desktop_snapshot into {object_count} semantic objects and {affordance_count} affordances."
            ),
            "machine_payload": {
                "object_count": object_count,
                "affordance_count": affordance_count,
                "window_count": window_count,
                "atspi_object_count": atspi_object_count
            },
            "ingestion": {
                "allowed": false,
                "reason": "runtime_snapshot_not_durable_memory"
            },
            "artifact": Value::Null
        }
    });
    if include_raw {
        if let Some(obj) = payload.as_object_mut() {
            obj.insert("raw_snapshot".to_string(), snapshot.clone());
        }
    }
    payload
}

fn desktop_snapshot_str<'a>(value: &'a Value, key: &str) -> Option<&'a str> {
    value
        .get(key)
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|s| !s.is_empty())
}

fn desktop_snapshot_value_label(value: &Value, fallback: &str) -> String {
    match value {
        Value::String(s) => desktop_snapshot_slug(s),
        Value::Number(n) => n.to_string(),
        _ => fallback.to_string(),
    }
}

fn desktop_snapshot_window_object_id(window: &Value, idx: usize) -> String {
    if let Some(id) = window.get("id").and_then(Value::as_i64) {
        return format!("desktop:linux:sway:window:{id}");
    }
    if let Some(pid) = window.get("pid").and_then(Value::as_i64) {
        return format!("desktop:linux:sway:window-pid:{pid}");
    }
    format!("desktop:linux:sway:window-index:{idx}")
}

fn desktop_snapshot_slug(raw: &str) -> String {
    let mut out = String::new();
    let mut last_dash = false;
    for ch in raw.chars() {
        if ch.is_ascii_alphanumeric() {
            out.push(ch.to_ascii_lowercase());
            last_dash = false;
        } else if !last_dash && !out.is_empty() {
            out.push('-');
            last_dash = true;
        }
    }
    while out.ends_with('-') {
        out.pop();
    }
    if out.is_empty() {
        "unknown".to_string()
    } else {
        out
    }
}

fn desktop_snapshot_role_is_actionable(role: &str) -> bool {
    let r = role.to_ascii_lowercase();
    r.contains("button")
        || r.contains("menu item")
        || r.contains("check box")
        || r.contains("radio button")
        || r.contains("combo box")
        || r.contains("slider")
        || r.contains("spin button")
        || r == "link"
}

fn desktop_snapshot_script_path(args: &Value, cwd: Option<&PathBuf>) -> PathBuf {
    if let Some(path) = args.get("script_path").and_then(|v| v.as_str()) {
        return PathBuf::from(path);
    }
    if let Ok(path) = std::env::var("AGENT_BRIDGE_DESKTOP_SNAPSHOT_SCRIPT") {
        if !path.trim().is_empty() {
            return PathBuf::from(path);
        }
    }
    if let Some(cwd) = cwd {
        let path = cwd.join("scripts/desktop_snapshot.py");
        if path.exists() {
            return path;
        }
    }
    if let Ok(cwd) = std::env::current_dir() {
        let path = cwd.join("scripts/desktop_snapshot.py");
        if path.exists() {
            return path;
        }
    }
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../scripts/desktop_snapshot.py")
}

fn desktop_snapshot_error(error: Value) -> ToolResult {
    let mut result = ToolResult::json_text(&json!({
        "schema": "desktop_snapshot_mcp_error.v0",
        "status": "error",
        "error": error,
    }));
    result.is_error = true;
    result
}

// ===========================================================================
//                            desktop_verify
// ===========================================================================
// Read-only postflight verifier — the "verify"+"recover" leg of the Linux Computer
// Use loop (thread 79). After a desktop_invoke / desktop_action, this re-observes the
// bus (AT-SPI registry + sway tree) and checks ONE expectation, POLLING until it holds
// or times out, returning a `recover` hint (proceed|retry|replan|escalate) that maps
// 1:1 to the caller's next move. It never clicks/types/moves anything, so observing the
// REAL desktop is safe + ungated (like desktop_snapshot); --cage-pid / --swaysock only
// SCOPE what counts as present.

const DESKTOP_VERIFY_SEMANTIC_SCHEMA: &str = "agent_bridge.semantic_bus.desktop_verify.v0";
const DESKTOP_VERIFY_SOURCE_SCHEMA: &str = "desktop_verify/v0";

pub struct DesktopVerifyTool {
    _hub: Hub,
}

impl DesktopVerifyTool {
    pub fn new(hub: Hub) -> Self {
        Self { _hub: hub }
    }
}

#[async_trait]
impl McpTool for DesktopVerifyTool {
    fn name(&self) -> &'static str {
        "desktop_verify"
    }

    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Read-only postflight verifier for the desktop act loop. After a \
                 desktop_invoke/desktop_action, re-observes the bus (AT-SPI + sway tree) and \
                 checks ONE expectation, polling until it holds or `poll_timeout_secs` elapses \
                 (GUIs animate — a single check races the toolkit). Reuses the SAME selector you \
                 acted on. Returns verdict (verified|unmet|error) and a `recover` hint \
                 (proceed|retry|replan|escalate) that maps 1:1 to your next move; an optional \
                 before-fingerprint splits a miss into unchanged (retry) vs diverged (replan). \
                 Never clicks/types/moves — observing the real desktop is safe; cage_pid/swaysock \
                 only scope what counts as present."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "cwd": { "type": "string", "description": "Repo root to resolve scripts/desktop_verify.py." },
                    "script_path": { "type": "string", "description": "Explicit desktop_verify.py path (tests/alternate checkouts)." },
                    "expect": {
                        "type": "string",
                        "enum": ["element_gone", "element_appeared", "state_is", "state_not", "window_gone", "window_appeared", "focus_is"],
                        "description": "The postcondition to check. element_*/state_* use the AT-SPI selector (app/role/name); window_*/focus_is use the window selector (win_*)."
                    },
                    "app": { "type": "string", "description": "AT-SPI application name substring (element_*/state_*)." },
                    "role": { "type": "string", "description": "AT-SPI role substring, e.g. button." },
                    "name": { "type": "string", "description": "AT-SPI accessible name substring, e.g. OK." },
                    "nth": { "type": "integer", "default": 0 },
                    "cage_pid": { "type": "integer", "description": "Scope AT-SPI matches to this process subtree (isolated verify)." },
                    "state": { "type": "string", "description": "For state_is/state_not: checked|expanded|selected|showing|visible|focused|sensitive|enabled|pressed|active." },
                    "win_app_id": { "type": "string", "description": "sway app_id substring (window_*/focus_is)." },
                    "win_pid": { "type": "integer", "description": "Window PID (exact)." },
                    "win_title": { "type": "string", "description": "Window title substring." },
                    "swaysock": { "type": "string", "description": "Nested sway IPC socket for window checks (isolated verify)." },
                    "poll_timeout_secs": {
                        "type": "number", "minimum": 0.0, "maximum": 30.0, "default": 4.0,
                        "description": "Poll until the expectation holds or this many seconds elapse."
                    },
                    "poll_interval_secs": { "type": "number", "minimum": 0.05, "maximum": 5.0, "default": 0.3 },
                    "settle_secs": {
                        "type": "number", "minimum": 0.0, "maximum": 5.0, "default": 0.0,
                        "description": "Initial delay before the first check (let the GUI start reacting)."
                    },
                    "before_present": {
                        "type": "string", "enum": ["true", "false"],
                        "description": "Was the AT-SPI target present BEFORE the act? Splits a miss into unchanged vs diverged."
                    },
                    "before_focus": { "type": "string", "description": "Focused 'app_id|title' BEFORE the act (for focus_is)." },
                    "semantic_bus": {
                        "type": "boolean",
                        "default": false,
                        "description": "When true, wrap the read-only desktop_verify/v0 payload as agent_bridge.semantic_bus.desktop_verify.v0. Default false preserves the existing payload exactly apart from mcp_wrapper."
                    },
                    "semantic_include_raw": {
                        "type": "boolean",
                        "default": false,
                        "description": "Only with semantic_bus=true: include the original desktop_verify payload as raw_verify. Default false keeps the semantic envelope compact."
                    },
                    "timeout_ms": {
                        "type": "integer", "minimum": 2000, "maximum": 60000, "default": 12000,
                        "description": "Milliseconds before the verify process is killed (kept above poll_timeout_secs)."
                    }
                },
                "required": ["expect"]
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let expect = match required_str_arg(&args, "expect") {
            Ok(v) => v,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        let poll_timeout_secs = args
            .get("poll_timeout_secs")
            .and_then(|v| v.as_f64())
            .unwrap_or(4.0)
            .clamp(0.0, 30.0);
        // keep the process-kill timeout safely above the in-script poll window
        let min_proc_ms = (poll_timeout_secs * 1000.0) as u64 + 3000;
        let timeout_ms = args
            .get("timeout_ms")
            .and_then(|v| v.as_u64())
            .unwrap_or(12_000)
            .clamp(2_000, 60_000)
            .max(min_proc_ms);
        let semantic_bus = args
            .get("semantic_bus")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        let semantic_include_raw = args
            .get("semantic_include_raw")
            .and_then(Value::as_bool)
            .unwrap_or(false);

        let cwd = args.get("cwd").and_then(|v| v.as_str()).map(PathBuf::from);
        let script = desktop_verify_script_path(&args, cwd.as_ref());
        if !script.exists() {
            return Ok(desktop_verify_error(json!({
                "code": "script_missing",
                "message": format!("desktop_verify.py not found at {}", script.display()),
                "hint": "pass script_path or run from the Agent-Bridge repo root"
            })));
        }

        let mut cmd = killable_command(
            std::env::var("PYTHON")
                .ok()
                .filter(|s| !s.trim().is_empty())
                .unwrap_or_else(|| "python3".to_string()),
        );
        cmd.arg(&script)
            .arg("--compact")
            .arg("--expect")
            .arg(expect)
            .arg("--timeout")
            .arg(poll_timeout_secs.to_string());
        push_optional_str_arg(&mut cmd, &args, "app", "--app");
        push_optional_str_arg(&mut cmd, &args, "role", "--role");
        push_optional_str_arg(&mut cmd, &args, "name", "--name");
        push_optional_value_arg(&mut cmd, &args, "nth", "--nth");
        push_optional_value_arg(&mut cmd, &args, "cage_pid", "--cage-pid");
        push_optional_str_arg(&mut cmd, &args, "state", "--state");
        push_optional_str_arg(&mut cmd, &args, "win_app_id", "--win-app-id");
        push_optional_value_arg(&mut cmd, &args, "win_pid", "--win-pid");
        push_optional_str_arg(&mut cmd, &args, "win_title", "--win-title");
        push_optional_str_arg(&mut cmd, &args, "swaysock", "--swaysock");
        push_optional_str_arg(&mut cmd, &args, "before_present", "--before-present");
        push_optional_str_arg(&mut cmd, &args, "before_focus", "--before-focus");
        if let Some(pi) = args.get("poll_interval_secs").and_then(|v| v.as_f64()) {
            cmd.arg("--poll-interval")
                .arg(pi.clamp(0.05, 5.0).to_string());
        }
        if let Some(s) = args.get("settle_secs").and_then(|v| v.as_f64()) {
            if s > 0.0 {
                cmd.arg("--settle").arg(s.clamp(0.0, 5.0).to_string());
            }
        }
        cmd.stdout(std::process::Stdio::piped());
        cmd.stderr(std::process::Stdio::piped());
        if let Some(cwd) = cwd {
            cmd.current_dir(cwd);
        }

        let started = Instant::now();
        let output =
            match tokio::time::timeout(Duration::from_millis(timeout_ms), cmd.output()).await {
                Err(_) => {
                    return Ok(desktop_verify_error(json!({
                        "code": "timeout",
                        "message": format!("desktop_verify exceeded {timeout_ms} ms"),
                        "duration_ms": started.elapsed().as_millis() as u64
                    })));
                }
                Ok(Err(e)) => {
                    return Ok(desktop_verify_error(json!({
                        "code": "spawn_failed",
                        "message": e.to_string(),
                        "duration_ms": started.elapsed().as_millis() as u64
                    })));
                }
                Ok(Ok(output)) => output,
            };
        let duration_ms = started.elapsed().as_millis() as u64;
        let (stdout, stdout_truncated) = lossy_truncate(&output.stdout);
        let (stderr, stderr_truncated) = lossy_truncate(&output.stderr);
        // NOTE: the script exits 2 for unmet and 3 for error by design, so a non-zero
        // status is NOT a wrapper failure — parse stdout regardless and only fall back
        // to an error envelope when the JSON itself is unreadable.
        match serde_json::from_str::<Value>(&stdout) {
            Ok(mut payload) => {
                if let Some(obj) = payload.as_object_mut() {
                    obj.insert(
                        "mcp_wrapper".to_string(),
                        json!({
                            "tool": self.name(),
                            "read_only": true,
                            "exit_code": output.status.code().unwrap_or(-1),
                            "duration_ms": duration_ms,
                            "stderr": stderr,
                            "stderr_truncated": stderr_truncated
                        }),
                    );
                }
                if semantic_bus {
                    payload = desktop_verify_semantic_bus_payload(&payload, semantic_include_raw);
                }
                Ok(ToolResult::json_text(&payload))
            }
            Err(e) => Ok(desktop_verify_error(json!({
                "code": "invalid_json",
                "message": e.to_string(),
                "exit_code": output.status.code().unwrap_or(-1),
                "stdout": stdout,
                "stderr": stderr,
                "duration_ms": duration_ms,
                "truncated": stdout_truncated || stderr_truncated
            }))),
        }
    }
}

fn desktop_verify_semantic_bus_payload(verify: &Value, include_raw: bool) -> Value {
    let source_schema = verify
        .get("schema")
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    let ts = verify.get("ts").cloned().unwrap_or(Value::Null);
    let ts_label = desktop_snapshot_value_label(&ts, "unknown");
    let expect = verify
        .get("expect")
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    let source_verdict = verify
        .get("verdict")
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    let source_recover = verify
        .get("recover")
        .and_then(Value::as_str)
        .unwrap_or_else(|| match source_verdict {
            "verified" => "proceed",
            "error" => "escalate",
            "unmet" => "retry",
            _ => "replan",
        });
    let selector = verify.get("selector").cloned().unwrap_or_else(|| json!({}));
    let scope = verify.get("scope").cloned().unwrap_or_else(|| json!({}));
    let observed = verify.get("observed").cloned().unwrap_or_else(|| json!({}));
    let target_family = desktop_verify_target_family(expect);
    let target_summary = desktop_verify_selector_summary(&selector);
    let target_seed = format!("{expect}-{target_summary}");
    let target_object_id = format!(
        "desktop:linux:verify:{target_family}:{}",
        desktop_snapshot_slug(&target_seed)
    );
    let event_id = format!(
        "evt-desktop-verify-{ts_label}-{}",
        desktop_snapshot_slug(expect)
    );
    let schema_ok = source_schema == DESKTOP_VERIFY_SOURCE_SCHEMA;
    let semantic_verdict = if !schema_ok {
        "not_verified"
    } else {
        match source_verdict {
            "verified" => "verified",
            "error" => "error",
            _ => "not_verified",
        }
    };
    let semantic_recover = if schema_ok { source_recover } else { "replan" };
    let reason = if !schema_ok {
        json!("unexpected_source_schema")
    } else if source_verdict == "verified" {
        Value::Null
    } else if source_verdict == "error" {
        verify
            .get("error")
            .cloned()
            .filter(|v| !v.is_null())
            .unwrap_or_else(|| json!("desktop_verify_error"))
    } else if source_verdict == "unmet" {
        json!("postcondition_unmet")
    } else {
        json!("unknown_source_verdict")
    };
    let observed_count = observed.get("count").cloned().unwrap_or(Value::Null);
    let mut verify_args = selector.as_object().cloned().unwrap_or_default();
    verify_args.insert("expect".to_string(), json!(expect));

    let mut payload = json!({
        "schema": DESKTOP_VERIFY_SEMANTIC_SCHEMA,
        "source_schema": source_schema,
        "source_adapter": "linux.desktop_verify",
        "observed_at": ts,
        "read_only": true,
        "raw_available": true,
        "raw_included": include_raw,
        "semantic_objects": [
            {
                "schema": "agent_bridge.semantic_bus.object.v0",
                "object_id": target_object_id,
                "object_type": format!("desktop.verify.target.{target_family}"),
                "source_adapter": "linux.desktop_verify",
                "label": format!("desktop_verify {expect} {target_summary}"),
                "state": {
                    "expect": expect,
                    "selector": selector,
                    "scope": scope,
                    "source_verdict": source_verdict,
                    "recover": source_recover,
                    "change": verify.get("change").cloned().unwrap_or(Value::Null),
                    "held_after_ms": verify.get("held_after_ms").cloned().unwrap_or(Value::Null),
                    "polls": verify.get("polls").cloned().unwrap_or(Value::Null),
                    "observed": observed,
                    "error": verify.get("error").cloned().unwrap_or(Value::Null)
                },
                "relations": [],
                "confidence": if schema_ok { 0.9 } else { 0.25 },
                "observed_at": ts,
                "provenance": {
                    "tool": "desktop_verify",
                    "schema": source_schema
                }
            }
        ],
        "affordances": [
            {
                "affordance_id": format!("{target_object_id}:reverify"),
                "object_id": target_object_id,
                "action_type": "desktop.verify",
                "args_schema": Value::Object(verify_args),
                "risk_level": "low",
                "requires_gate": false,
                "expected_effect": "re-observes the same postcondition without mutating the desktop"
            }
        ],
        "events": [
            {
                "event_id": event_id,
                "event_type": "desktop.verify.completed",
                "subject_id": target_object_id,
                "source": "desktop_verify",
                "actor": "agent",
                "payload_json": {
                    "expect": expect,
                    "source_verdict": source_verdict,
                    "recover": source_recover,
                    "change": verify.get("change").cloned().unwrap_or(Value::Null),
                    "observed_count": observed_count,
                    "held_after_ms": verify.get("held_after_ms").cloned().unwrap_or(Value::Null),
                    "polls": verify.get("polls").cloned().unwrap_or(Value::Null)
                },
                "source_event_ids": []
            }
        ],
        "verification": {
            "verdict": semantic_verdict,
            "source_verdict": source_verdict,
            "reason": reason,
            "method": "desktop_verify.semantic_normalizer",
            "evidence": {
                "source_schema": source_schema,
                "expect": expect,
                "selector": verify.get("selector").cloned().unwrap_or_else(|| json!({})),
                "scope": verify.get("scope").cloned().unwrap_or_else(|| json!({})),
                "observed_count": observed.get("count").cloned().unwrap_or(Value::Null),
                "raw_included": include_raw
            },
            "verified_to": if semantic_verdict == "verified" { json!("postcondition") } else { Value::Null },
            "recover": semantic_recover,
            "raw_available": true
        },
        "presentation": {
            "presentation_id": format!("present-desktop-verify-{ts_label}"),
            "source_event_ids": [event_id],
            "human_summary": format!(
                "desktop_verify {expect} returned {source_verdict}; recover={semantic_recover}."
            ),
            "machine_payload": {
                "expect": expect,
                "source_verdict": source_verdict,
                "recover": semantic_recover,
                "observed_count": observed.get("count").cloned().unwrap_or(Value::Null)
            },
            "ingestion": {
                "allowed": false,
                "reason": "runtime_verify_not_durable_memory"
            },
            "artifact": Value::Null
        }
    });
    if include_raw {
        if let Some(obj) = payload.as_object_mut() {
            obj.insert("raw_verify".to_string(), verify.clone());
        }
    }
    payload
}

fn desktop_verify_target_family(expect: &str) -> &'static str {
    match expect {
        "window_gone" | "window_appeared" | "focus_is" => "window",
        "element_gone" | "element_appeared" | "state_is" | "state_not" => "accessible",
        _ => "target",
    }
}

fn desktop_verify_selector_summary(selector: &Value) -> String {
    let mut parts = Vec::new();
    for key in [
        "app",
        "role",
        "name",
        "state",
        "win_app_id",
        "win_title",
        "win_pid",
    ] {
        if let Some(value) = selector.get(key) {
            match value {
                Value::String(s) if !s.trim().is_empty() => {
                    parts.push(format!("{key}:{}", s.trim()));
                }
                Value::Number(n) => parts.push(format!("{key}:{n}")),
                Value::Bool(b) => parts.push(format!("{key}:{b}")),
                _ => {}
            }
        }
    }
    if parts.is_empty() {
        "unspecified-target".to_string()
    } else {
        parts.join(" ")
    }
}

fn desktop_verify_script_path(args: &Value, cwd: Option<&PathBuf>) -> PathBuf {
    if let Some(path) = args.get("script_path").and_then(|v| v.as_str()) {
        return PathBuf::from(path);
    }
    if let Ok(path) = std::env::var("AGENT_BRIDGE_DESKTOP_VERIFY_SCRIPT") {
        if !path.trim().is_empty() {
            return PathBuf::from(path);
        }
    }
    if let Some(cwd) = cwd {
        let path = cwd.join("scripts/desktop_verify.py");
        if path.exists() {
            return path;
        }
    }
    if let Ok(cwd) = std::env::current_dir() {
        let path = cwd.join("scripts/desktop_verify.py");
        if path.exists() {
            return path;
        }
    }
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../scripts/desktop_verify.py")
}

fn desktop_verify_error(error: Value) -> ToolResult {
    let mut result = ToolResult::json_text(&json!({
        "schema": "desktop_verify_mcp_error.v0",
        "status": "error",
        "error": error,
    }));
    result.is_error = true;
    result
}

// ===========================================================================
//                              macos_ax_probe
// ===========================================================================

const MACOS_AX_PROBE_SEMANTIC_SCHEMA: &str = "agent_bridge.semantic_bus.macos_ax_probe.v0";
const MACOS_AX_PROBE_SOURCE_SCHEMA: &str = "macos_ax_probe/v0";

pub struct MacosAxProbeTool {
    _hub: Hub,
}

impl MacosAxProbeTool {
    pub fn new(hub: Hub) -> Self {
        Self { _hub: hub }
    }
}

#[async_trait]
impl McpTool for MacosAxProbeTool {
    fn name(&self) -> &'static str {
        "macos_ax_probe"
    }

    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Read-only macOS Accessibility feasibility probe. Reports platform \
                 support, AX trust state, frontmost app metadata, and a bounded window summary \
                 only when Accessibility is already trusted. It never prompts for permission, \
                 clicks, types, focuses apps, or mutates window state."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "cwd": {
                        "type": "string",
                        "description": "Workspace/repo root used to resolve scripts/macos_ax_probe.py. Defaults to the MCP process cwd, then the build-time repo root."
                    },
                    "script_path": {
                        "type": "string",
                        "description": "Optional explicit macos_ax_probe.py path. Use mainly for tests or alternate checkouts."
                    },
                    "include_windows": {
                        "type": "boolean",
                        "default": true,
                        "description": "When true, read a bounded frontmost app/window summary through System Events only if AX is already trusted."
                    },
                    "max_windows": {
                        "type": "integer",
                        "minimum": 0,
                        "maximum": 50,
                        "default": 8,
                        "description": "Maximum frontmost-app windows to return."
                    },
                    "jxa_timeout_secs": {
                        "type": "number",
                        "minimum": 0.25,
                        "maximum": 10.0,
                        "default": 4.0,
                        "description": "Timeout for the bounded System Events/JXA read."
                    },
                    "semantic_bus": {
                        "type": "boolean",
                        "default": false,
                        "description": "When true, wrap the macos_ax_probe/v0 payload as agent_bridge.semantic_bus.macos_ax_probe.v0. Default false preserves the probe payload exactly apart from mcp_wrapper."
                    },
                    "semantic_include_raw": {
                        "type": "boolean",
                        "default": false,
                        "description": "Only with semantic_bus=true: include the original macos_ax_probe payload as raw_probe. Default false keeps the semantic envelope compact."
                    },
                    "timeout_ms": {
                        "type": "integer",
                        "minimum": 1000,
                        "maximum": 30000,
                        "default": 8000,
                        "description": "Milliseconds before the probe process is killed."
                    }
                }
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let timeout_ms = args
            .get("timeout_ms")
            .and_then(Value::as_u64)
            .unwrap_or(8_000)
            .clamp(1_000, 30_000);
        let include_windows = args
            .get("include_windows")
            .and_then(Value::as_bool)
            .unwrap_or(true);
        let max_windows = args
            .get("max_windows")
            .and_then(Value::as_u64)
            .unwrap_or(8)
            .min(50);
        let jxa_timeout_secs = args
            .get("jxa_timeout_secs")
            .and_then(Value::as_f64)
            .unwrap_or(4.0)
            .clamp(0.25, 10.0);
        let semantic_bus = args
            .get("semantic_bus")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        let semantic_include_raw = args
            .get("semantic_include_raw")
            .and_then(Value::as_bool)
            .unwrap_or(false);

        let cwd = args.get("cwd").and_then(Value::as_str).map(PathBuf::from);
        let script = macos_ax_probe_script_path(&args, cwd.as_ref());
        if !script.exists() {
            return Ok(macos_ax_probe_error(json!({
                "code": "script_missing",
                "message": format!("macos_ax_probe.py not found at {}", script.display()),
                "hint": "pass script_path or run from the Agent-Bridge repo root"
            })));
        }

        let mut cmd = killable_command(
            std::env::var("PYTHON")
                .ok()
                .filter(|s| !s.trim().is_empty())
                .unwrap_or_else(|| "python3".to_string()),
        );
        cmd.arg(&script)
            .arg("--compact")
            .arg("--max-windows")
            .arg(max_windows.to_string())
            .arg("--jxa-timeout-secs")
            .arg(jxa_timeout_secs.to_string());
        if !include_windows {
            cmd.arg("--no-windows");
        }
        cmd.stdout(std::process::Stdio::piped());
        cmd.stderr(std::process::Stdio::piped());
        if let Some(cwd) = cwd {
            cmd.current_dir(cwd);
        }

        let started = Instant::now();
        let output =
            match tokio::time::timeout(Duration::from_millis(timeout_ms), cmd.output()).await {
                Err(_) => {
                    return Ok(macos_ax_probe_error(json!({
                        "code": "timeout",
                        "message": format!("macos_ax_probe exceeded {timeout_ms} ms"),
                        "duration_ms": started.elapsed().as_millis() as u64
                    })));
                }
                Ok(Err(e)) => {
                    return Ok(macos_ax_probe_error(json!({
                        "code": "spawn_failed",
                        "message": e.to_string(),
                        "duration_ms": started.elapsed().as_millis() as u64
                    })));
                }
                Ok(Ok(output)) => output,
            };
        let duration_ms = started.elapsed().as_millis() as u64;
        let (stdout, stdout_truncated) = lossy_truncate(&output.stdout);
        let (stderr, stderr_truncated) = lossy_truncate(&output.stderr);

        if !output.status.success() {
            return Ok(macos_ax_probe_error(json!({
                "code": "script_failed",
                "exit_code": output.status.code().unwrap_or(-1),
                "stdout": stdout,
                "stderr": stderr,
                "duration_ms": duration_ms,
                "truncated": stdout_truncated || stderr_truncated
            })));
        }

        match serde_json::from_str::<Value>(&stdout) {
            Ok(mut payload) => {
                if let Some(obj) = payload.as_object_mut() {
                    obj.insert(
                        "mcp_wrapper".to_string(),
                        json!({
                            "tool": self.name(),
                            "read_only": true,
                            "include_windows": include_windows,
                            "duration_ms": duration_ms,
                            "exit_code": output.status.code().unwrap_or(-1),
                            "stderr": stderr,
                            "stderr_truncated": stderr_truncated
                        }),
                    );
                }
                if semantic_bus {
                    payload = macos_ax_probe_semantic_bus_payload(&payload, semantic_include_raw);
                }
                Ok(ToolResult::json_text(&payload))
            }
            Err(e) => Ok(macos_ax_probe_error(json!({
                "code": "invalid_json",
                "message": e.to_string(),
                "stdout": stdout,
                "stderr": stderr,
                "duration_ms": duration_ms,
                "truncated": stdout_truncated || stderr_truncated
            }))),
        }
    }
}

fn macos_ax_probe_semantic_bus_payload(probe: &Value, include_raw: bool) -> Value {
    let source_schema = probe
        .get("schema")
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    let captured_at = probe.get("captured_at").cloned().unwrap_or(Value::Null);
    let captured_label = desktop_snapshot_value_label(&captured_at, "unknown");
    let status = probe
        .get("status")
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    let schema_ok = source_schema == MACOS_AX_PROBE_SOURCE_SCHEMA;
    let supported = status != "unsupported_platform";
    let semantic_verdict = if !schema_ok {
        "not_verified"
    } else if supported {
        "verified"
    } else {
        "blocked"
    };
    let recover = if !schema_ok {
        "replan"
    } else if status == "ready" || status == "degraded" {
        "proceed"
    } else {
        "replan"
    };
    let reason = if !schema_ok {
        json!("unexpected_source_schema")
    } else if status == "unsupported_platform" {
        json!("unsupported_platform")
    } else if status == "degraded" {
        json!("limited_accessibility_or_window_read")
    } else {
        Value::Null
    };
    let session_object_id = format!("desktop:macos:session:{captured_label}");
    let event_id = format!("evt-macos-ax-probe-{captured_label}");

    let mut semantic_objects = vec![json!({
        "schema": "agent_bridge.semantic_bus.object.v0",
        "object_id": session_object_id,
        "object_type": "desktop.session",
        "source_adapter": "macos.ax_probe",
        "label": "macOS desktop session",
        "state": {
            "platform": probe.get("platform").cloned().unwrap_or_else(|| json!({})),
            "status": status,
            "permission": probe.get("permission").cloned().unwrap_or_else(|| json!({})),
            "frontmost_app": probe.get("frontmost_app").cloned().unwrap_or(Value::Null),
            "window_count": probe.get("window_count").cloned().unwrap_or(Value::Null),
            "source_window_count": probe.get("source_window_count").cloned().unwrap_or(Value::Null),
            "limits": probe.get("limits").cloned().unwrap_or_else(|| json!({})),
        },
        "relations": [],
        "confidence": if schema_ok { 0.85 } else { 0.2 },
        "observed_at": captured_at,
        "provenance": {
            "tool": "macos_ax_probe",
            "schema": source_schema
        }
    })];
    let mut affordances = Vec::new();

    if let Some(app) = probe.get("frontmost_app").filter(|v| v.is_object()) {
        let app_id = macos_ax_app_object_id(app);
        semantic_objects.push(json!({
            "schema": "agent_bridge.semantic_bus.object.v0",
            "object_id": app_id,
            "object_type": "desktop.application",
            "source_adapter": "macos.system_events",
            "label": app.get("name").and_then(Value::as_str).unwrap_or("frontmost app"),
            "state": {
                "name": app.get("name").cloned().unwrap_or(Value::Null),
                "pid": app.get("pid").cloned().unwrap_or(Value::Null),
                "bundle_id": app.get("bundle_id").cloned().unwrap_or(Value::Null),
                "role": app.get("role").cloned().unwrap_or(Value::Null),
                "frontmost": true
            },
            "relations": [
                { "type": "member_of", "target": session_object_id }
            ],
            "confidence": 0.86,
            "observed_at": captured_at,
            "provenance": {
                "tool": "macos_ax_probe",
                "schema": source_schema,
                "source_path": "frontmost_app"
            }
        }));
    }

    if let Some(windows) = probe.get("windows").and_then(Value::as_array) {
        for (idx, window) in windows.iter().enumerate() {
            let object_id = macos_ax_window_object_id(probe, window, idx);
            semantic_objects.push(json!({
                "schema": "agent_bridge.semantic_bus.object.v0",
                "object_id": object_id,
                "object_type": "desktop.window",
                "source_adapter": "macos.ax.window",
                "label": window.get("title").and_then(Value::as_str).unwrap_or("macOS window"),
                "state": {
                    "index": window.get("index").cloned().unwrap_or(Value::Null),
                    "title": window.get("title").cloned().unwrap_or(Value::Null),
                    "role": window.get("role").cloned().unwrap_or(Value::Null),
                    "subrole": window.get("subrole").cloned().unwrap_or(Value::Null),
                    "focused": window.get("focused").cloned().unwrap_or(Value::Null),
                    "position": window.get("position").cloned().unwrap_or(Value::Null),
                    "size": window.get("size").cloned().unwrap_or(Value::Null),
                    "rect": window.get("rect").cloned().unwrap_or(Value::Null),
                    "app": probe.get("frontmost_app").cloned().unwrap_or(Value::Null),
                    "platform": probe.get("platform").cloned().unwrap_or_else(|| json!({})),
                },
                "relations": [
                    { "type": "member_of", "target": session_object_id }
                ],
                "confidence": 0.82,
                "observed_at": captured_at,
                "provenance": {
                    "tool": "macos_ax_probe",
                    "schema": source_schema,
                    "source_path": "windows"
                }
            }));
            affordances.push(json!({
                "affordance_id": format!("{object_id}:reobserve"),
                "object_id": object_id,
                "action_type": "macos_ax_probe.reobserve",
                "args_schema": {
                    "include_windows": true,
                    "max_windows": probe
                        .get("limits")
                        .and_then(|v| v.get("max_windows"))
                        .cloned()
                        .unwrap_or_else(|| json!(8))
                },
                "risk_level": "low",
                "requires_gate": false,
                "expected_effect": "re-runs the read-only macOS AX probe without mutating app or window state"
            }));
        }
    }

    let object_count = semantic_objects.len();
    let window_count = probe.get("window_count").cloned().unwrap_or(Value::Null);
    let mut payload = json!({
        "schema": MACOS_AX_PROBE_SEMANTIC_SCHEMA,
        "source_schema": source_schema,
        "source_adapter": "macos.ax_probe",
        "captured_at": captured_at,
        "read_only": true,
        "raw_available": true,
        "raw_included": include_raw,
        "semantic_objects": semantic_objects,
        "affordances": affordances,
        "events": [
            {
                "event_id": event_id,
                "event_type": "desktop.snapshot.observed",
                "subject_id": session_object_id,
                "source": "macos_ax_probe",
                "actor": "agent",
                "payload_json": {
                    "status": status,
                    "object_count": object_count,
                    "window_count": window_count,
                    "ax_trusted": probe
                        .get("permission")
                        .and_then(|v| v.get("ax_trusted"))
                        .cloned()
                        .unwrap_or(Value::Null),
                    "prompted": probe
                        .get("permission")
                        .and_then(|v| v.get("prompted"))
                        .cloned()
                        .unwrap_or(Value::Null)
                },
                "source_event_ids": []
            }
        ],
        "verification": {
            "verdict": semantic_verdict,
            "reason": reason,
            "method": "macos_ax_probe.semantic_normalizer",
            "evidence": {
                "source_schema": source_schema,
                "status": status,
                "permission": probe.get("permission").cloned().unwrap_or_else(|| json!({})),
                "window_count": window_count,
                "raw_included": include_raw
            },
            "verified_to": if semantic_verdict == "verified" { json!("semantic_objects") } else { Value::Null },
            "recover": recover,
            "raw_available": true
        },
        "presentation": {
            "presentation_id": format!("present-macos-ax-probe-{captured_label}"),
            "source_event_ids": [event_id],
            "human_summary": format!(
                "macos_ax_probe returned {status}; normalized {object_count} semantic objects."
            ),
            "machine_payload": {
                "status": status,
                "object_count": object_count,
                "window_count": probe.get("window_count").cloned().unwrap_or(Value::Null),
                "source_window_count": probe.get("source_window_count").cloned().unwrap_or(Value::Null)
            },
            "ingestion": {
                "allowed": false,
                "reason": "runtime_probe_not_durable_memory"
            },
            "artifact": Value::Null
        }
    });
    if include_raw {
        if let Some(obj) = payload.as_object_mut() {
            obj.insert("raw_probe".to_string(), probe.clone());
        }
    }
    payload
}

fn macos_ax_app_object_id(app: &Value) -> String {
    if let Some(pid) = app.get("pid").and_then(Value::as_i64) {
        return format!("desktop:macos:app:{pid}");
    }
    if let Some(bundle) = app.get("bundle_id").and_then(Value::as_str) {
        return format!("desktop:macos:app:{}", desktop_snapshot_slug(bundle));
    }
    format!(
        "desktop:macos:app:{}",
        desktop_snapshot_slug(app.get("name").and_then(Value::as_str).unwrap_or("unknown"))
    )
}

fn macos_ax_window_object_id(probe: &Value, window: &Value, idx: usize) -> String {
    let pid = probe
        .get("frontmost_app")
        .and_then(|v| v.get("pid"))
        .and_then(Value::as_i64)
        .map(|p| p.to_string())
        .unwrap_or_else(|| "unknown".to_string());
    let source_index = window
        .get("index")
        .and_then(Value::as_i64)
        .map(|i| i.to_string())
        .unwrap_or_else(|| idx.to_string());
    format!("desktop:macos:window:{pid}:{source_index}")
}

fn macos_ax_probe_script_path(args: &Value, cwd: Option<&PathBuf>) -> PathBuf {
    if let Some(path) = args.get("script_path").and_then(Value::as_str) {
        return PathBuf::from(path);
    }
    if let Ok(path) = std::env::var("AGENT_BRIDGE_MACOS_AX_PROBE_SCRIPT") {
        if !path.trim().is_empty() {
            return PathBuf::from(path);
        }
    }
    if let Some(cwd) = cwd {
        let path = cwd.join("scripts/macos_ax_probe.py");
        if path.exists() {
            return path;
        }
    }
    if let Ok(cwd) = std::env::current_dir() {
        let path = cwd.join("scripts/macos_ax_probe.py");
        if path.exists() {
            return path;
        }
    }
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../scripts/macos_ax_probe.py")
}

fn macos_ax_probe_error(error: Value) -> ToolResult {
    let mut result = ToolResult::json_text(&json!({
        "schema": "macos_ax_probe_mcp_error.v0",
        "status": "error",
        "error": error,
    }));
    result.is_error = true;
    result
}

// ===========================================================================
//                              macos_ax_verify
// ===========================================================================

const MACOS_AX_VERIFY_SEMANTIC_SCHEMA: &str = "agent_bridge.semantic_bus.macos_ax_verify.v0";
const MACOS_AX_VERIFY_SOURCE_SCHEMA: &str = "macos_ax_verify/v0";

pub struct MacosAxVerifyTool {
    _hub: Hub,
}

impl MacosAxVerifyTool {
    pub fn new(hub: Hub) -> Self {
        Self { _hub: hub }
    }
}

#[async_trait]
impl McpTool for MacosAxVerifyTool {
    fn name(&self) -> &'static str {
        "macos_ax_verify"
    }

    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Read-only macOS Accessibility verifier. Re-observes the bounded \
                 macOS AX/System Events surface and checks one predicate such as AX trust, \
                 frontmost app identity, window appeared/gone, or focused window. It never \
                 prompts for permission, activates apps, focuses windows, clicks, types, \
                 resizes, moves, or closes windows."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "cwd": {
                        "type": "string",
                        "description": "Workspace/repo root used to resolve scripts/macos_ax_verify.py. Defaults to the MCP process cwd, then the build-time repo root."
                    },
                    "script_path": {
                        "type": "string",
                        "description": "Optional explicit macos_ax_verify.py path. Use mainly for tests or alternate checkouts."
                    },
                    "expect": {
                        "type": "string",
                        "enum": ["ax_trusted_is", "frontmost_app_is", "window_appeared", "window_gone", "window_focused"],
                        "description": "The read-only postcondition to check against frontmost app/window state."
                    },
                    "app": {
                        "type": "string",
                        "description": "Frontmost app name substring."
                    },
                    "bundle_id": {
                        "type": "string",
                        "description": "Frontmost app bundle identifier substring."
                    },
                    "pid": {
                        "type": "integer",
                        "description": "Frontmost app process id."
                    },
                    "title": {
                        "type": "string",
                        "description": "Window title substring."
                    },
                    "role": {
                        "type": "string",
                        "description": "Window AXRole substring."
                    },
                    "index": {
                        "type": "integer",
                        "description": "Window index from macos_ax_probe."
                    },
                    "state": {
                        "type": "string",
                        "description": "For ax_trusted_is: true|false."
                    },
                    "max_windows": {
                        "type": "integer",
                        "minimum": 0,
                        "maximum": 50,
                        "default": 8,
                        "description": "Maximum frontmost-app windows to inspect."
                    },
                    "jxa_timeout_secs": {
                        "type": "number",
                        "minimum": 0.25,
                        "maximum": 10.0,
                        "default": 4.0,
                        "description": "Timeout for each bounded System Events/JXA read."
                    },
                    "poll_timeout_secs": {
                        "type": "number",
                        "minimum": 0.0,
                        "maximum": 30.0,
                        "default": 4.0,
                        "description": "Poll until the predicate holds or this many seconds elapse."
                    },
                    "poll_interval_secs": {
                        "type": "number",
                        "minimum": 0.05,
                        "maximum": 5.0,
                        "default": 0.3
                    },
                    "settle_secs": {
                        "type": "number",
                        "minimum": 0.0,
                        "maximum": 5.0,
                        "default": 0.0,
                        "description": "Initial delay before the first read."
                    },
                    "semantic_bus": {
                        "type": "boolean",
                        "default": false,
                        "description": "When true, wrap the macos_ax_verify/v0 payload as agent_bridge.semantic_bus.macos_ax_verify.v0. Default false preserves the verify payload exactly apart from mcp_wrapper."
                    },
                    "semantic_include_raw": {
                        "type": "boolean",
                        "default": false,
                        "description": "Only with semantic_bus=true: include the original macos_ax_verify payload as raw_verify. Default false keeps the semantic envelope compact."
                    },
                    "timeout_ms": {
                        "type": "integer",
                        "minimum": 2000,
                        "maximum": 60000,
                        "default": 12000,
                        "description": "Milliseconds before the verifier process is killed (kept above poll_timeout_secs)."
                    }
                },
                "required": ["expect"]
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let expect = match required_str_arg(&args, "expect") {
            Ok(v) => v,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        let poll_timeout_secs = args
            .get("poll_timeout_secs")
            .and_then(Value::as_f64)
            .unwrap_or(4.0)
            .clamp(0.0, 30.0);
        let min_proc_ms = (poll_timeout_secs * 1000.0) as u64 + 5_000;
        let timeout_ms = args
            .get("timeout_ms")
            .and_then(Value::as_u64)
            .unwrap_or(12_000)
            .clamp(2_000, 60_000)
            .max(min_proc_ms);
        let max_windows = args
            .get("max_windows")
            .and_then(Value::as_u64)
            .unwrap_or(8)
            .min(50);
        let jxa_timeout_secs = args
            .get("jxa_timeout_secs")
            .and_then(Value::as_f64)
            .unwrap_or(4.0)
            .clamp(0.25, 10.0);
        let semantic_bus = args
            .get("semantic_bus")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        let semantic_include_raw = args
            .get("semantic_include_raw")
            .and_then(Value::as_bool)
            .unwrap_or(false);

        let cwd = args.get("cwd").and_then(Value::as_str).map(PathBuf::from);
        let script = macos_ax_verify_script_path(&args, cwd.as_ref());
        if !script.exists() {
            return Ok(macos_ax_verify_error(json!({
                "code": "script_missing",
                "message": format!("macos_ax_verify.py not found at {}", script.display()),
                "hint": "pass script_path or run from the Agent-Bridge repo root"
            })));
        }

        let mut cmd = killable_command(
            std::env::var("PYTHON")
                .ok()
                .filter(|s| !s.trim().is_empty())
                .unwrap_or_else(|| "python3".to_string()),
        );
        cmd.arg(&script)
            .arg("--compact")
            .arg("--expect")
            .arg(expect)
            .arg("--max-windows")
            .arg(max_windows.to_string())
            .arg("--jxa-timeout-secs")
            .arg(jxa_timeout_secs.to_string())
            .arg("--timeout")
            .arg(poll_timeout_secs.to_string());
        push_optional_str_arg(&mut cmd, &args, "app", "--app");
        push_optional_str_arg(&mut cmd, &args, "bundle_id", "--bundle-id");
        push_optional_value_arg(&mut cmd, &args, "pid", "--pid");
        push_optional_str_arg(&mut cmd, &args, "title", "--title");
        push_optional_str_arg(&mut cmd, &args, "role", "--role");
        push_optional_value_arg(&mut cmd, &args, "index", "--index");
        push_optional_str_arg(&mut cmd, &args, "state", "--state");
        if let Some(pi) = args.get("poll_interval_secs").and_then(Value::as_f64) {
            cmd.arg("--poll-interval")
                .arg(pi.clamp(0.05, 5.0).to_string());
        }
        if let Some(s) = args.get("settle_secs").and_then(Value::as_f64) {
            if s > 0.0 {
                cmd.arg("--settle").arg(s.clamp(0.0, 5.0).to_string());
            }
        }
        cmd.stdout(std::process::Stdio::piped());
        cmd.stderr(std::process::Stdio::piped());
        if let Some(cwd) = cwd {
            cmd.current_dir(cwd);
        }

        let started = Instant::now();
        let output =
            match tokio::time::timeout(Duration::from_millis(timeout_ms), cmd.output()).await {
                Err(_) => {
                    return Ok(macos_ax_verify_error(json!({
                        "code": "timeout",
                        "message": format!("macos_ax_verify exceeded {timeout_ms} ms"),
                        "duration_ms": started.elapsed().as_millis() as u64
                    })));
                }
                Ok(Err(e)) => {
                    return Ok(macos_ax_verify_error(json!({
                        "code": "spawn_failed",
                        "message": e.to_string(),
                        "duration_ms": started.elapsed().as_millis() as u64
                    })));
                }
                Ok(Ok(output)) => output,
            };
        let duration_ms = started.elapsed().as_millis() as u64;
        let (stdout, stdout_truncated) = lossy_truncate(&output.stdout);
        let (stderr, stderr_truncated) = lossy_truncate(&output.stderr);

        match serde_json::from_str::<Value>(&stdout) {
            Ok(mut payload) => {
                if let Some(obj) = payload.as_object_mut() {
                    obj.insert(
                        "mcp_wrapper".to_string(),
                        json!({
                            "tool": self.name(),
                            "read_only": true,
                            "exit_code": output.status.code().unwrap_or(-1),
                            "duration_ms": duration_ms,
                            "stderr": stderr,
                            "stderr_truncated": stderr_truncated
                        }),
                    );
                }
                if semantic_bus {
                    payload = macos_ax_verify_semantic_bus_payload(&payload, semantic_include_raw);
                }
                Ok(ToolResult::json_text(&payload))
            }
            Err(e) => Ok(macos_ax_verify_error(json!({
                "code": "invalid_json",
                "message": e.to_string(),
                "exit_code": output.status.code().unwrap_or(-1),
                "stdout": stdout,
                "stderr": stderr,
                "duration_ms": duration_ms,
                "truncated": stdout_truncated || stderr_truncated
            }))),
        }
    }
}

fn macos_ax_verify_semantic_bus_payload(verify: &Value, include_raw: bool) -> Value {
    let source_schema = verify
        .get("schema")
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    let ts = verify.get("ts").cloned().unwrap_or(Value::Null);
    let ts_label = desktop_snapshot_value_label(&ts, "unknown");
    let expect = verify
        .get("expect")
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    let source_verdict = verify
        .get("verdict")
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    let source_recover = verify
        .get("recover")
        .and_then(Value::as_str)
        .unwrap_or_else(|| match source_verdict {
            "verified" => "proceed",
            "error" => "escalate",
            "unmet" => "retry",
            _ => "replan",
        });
    let selector = verify.get("selector").cloned().unwrap_or_else(|| json!({}));
    let scope = verify.get("scope").cloned().unwrap_or_else(|| json!({}));
    let observed = verify.get("observed").cloned().unwrap_or_else(|| json!({}));
    let target_family = macos_ax_verify_target_family(expect);
    let target_summary = macos_ax_verify_selector_summary(&selector);
    let target_object_id = format!(
        "desktop:macos:verify:{target_family}:{}",
        desktop_snapshot_slug(&format!("{expect}-{target_summary}"))
    );
    let event_id = format!(
        "evt-macos-ax-verify-{ts_label}-{}",
        desktop_snapshot_slug(expect)
    );
    let schema_ok = source_schema == MACOS_AX_VERIFY_SOURCE_SCHEMA;
    let semantic_verdict = if !schema_ok {
        "not_verified"
    } else {
        match source_verdict {
            "verified" => "verified",
            "error" => "error",
            _ => "not_verified",
        }
    };
    let reason = if !schema_ok {
        json!("unexpected_source_schema")
    } else if source_verdict == "verified" {
        Value::Null
    } else if source_verdict == "error" {
        verify
            .get("error")
            .cloned()
            .filter(|v| !v.is_null())
            .unwrap_or_else(|| json!("macos_ax_verify_error"))
    } else if source_verdict == "unmet" {
        json!("postcondition_unmet")
    } else {
        json!("unknown_source_verdict")
    };
    let observed_count = observed.get("count").cloned().unwrap_or(Value::Null);
    let mut verify_args = selector.as_object().cloned().unwrap_or_default();
    verify_args.insert("expect".to_string(), json!(expect));

    let mut payload = json!({
        "schema": MACOS_AX_VERIFY_SEMANTIC_SCHEMA,
        "source_schema": source_schema,
        "source_adapter": "macos.ax.verify",
        "observed_at": ts,
        "read_only": true,
        "raw_available": true,
        "raw_included": include_raw,
        "semantic_objects": [
            {
                "schema": "agent_bridge.semantic_bus.object.v0",
                "object_id": target_object_id,
                "object_type": format!("desktop.verify.target.{target_family}"),
                "source_adapter": "macos.ax.verify",
                "label": format!("macos_ax_verify {expect} {target_summary}"),
                "state": {
                    "expect": expect,
                    "selector": selector,
                    "scope": scope,
                    "source_verdict": source_verdict,
                    "recover": source_recover,
                    "change": verify.get("change").cloned().unwrap_or(Value::Null),
                    "held_after_ms": verify.get("held_after_ms").cloned().unwrap_or(Value::Null),
                    "polls": verify.get("polls").cloned().unwrap_or(Value::Null),
                    "observed": observed,
                    "error": verify.get("error").cloned().unwrap_or(Value::Null)
                },
                "relations": [],
                "confidence": if schema_ok { 0.86 } else { 0.25 },
                "observed_at": ts,
                "provenance": {
                    "tool": "macos_ax_verify",
                    "schema": source_schema
                }
            }
        ],
        "affordances": [
            {
                "affordance_id": format!("{target_object_id}:reverify"),
                "object_id": target_object_id,
                "action_type": "macos_ax_verify",
                "args_schema": Value::Object(verify_args),
                "risk_level": "low",
                "requires_gate": false,
                "expected_effect": "re-observes the same macOS AX predicate without mutating desktop state"
            }
        ],
        "events": [
            {
                "event_id": event_id,
                "event_type": "desktop.verify.completed",
                "subject_id": target_object_id,
                "source": "macos_ax_verify",
                "actor": "agent",
                "payload_json": {
                    "expect": expect,
                    "source_verdict": source_verdict,
                    "recover": source_recover,
                    "observed_count": observed_count,
                    "held_after_ms": verify.get("held_after_ms").cloned().unwrap_or(Value::Null),
                    "polls": verify.get("polls").cloned().unwrap_or(Value::Null)
                },
                "source_event_ids": []
            }
        ],
        "verification": {
            "verdict": semantic_verdict,
            "source_verdict": source_verdict,
            "reason": reason,
            "method": "macos_ax_verify.semantic_normalizer",
            "evidence": {
                "source_schema": source_schema,
                "expect": expect,
                "selector": verify.get("selector").cloned().unwrap_or_else(|| json!({})),
                "scope": verify.get("scope").cloned().unwrap_or_else(|| json!({})),
                "observed_count": observed.get("count").cloned().unwrap_or(Value::Null),
                "probe_status": observed.get("probe_status").cloned().unwrap_or(Value::Null),
                "raw_included": include_raw
            },
            "verified_to": if semantic_verdict == "verified" { json!("postcondition") } else { Value::Null },
            "recover": if schema_ok { source_recover } else { "replan" },
            "raw_available": true
        },
        "presentation": {
            "presentation_id": format!("present-macos-ax-verify-{ts_label}"),
            "source_event_ids": [event_id],
            "human_summary": format!(
                "macos_ax_verify {expect} returned {source_verdict}; recover={source_recover}."
            ),
            "machine_payload": {
                "expect": expect,
                "source_verdict": source_verdict,
                "recover": source_recover,
                "observed_count": observed.get("count").cloned().unwrap_or(Value::Null),
                "probe_status": observed.get("probe_status").cloned().unwrap_or(Value::Null)
            },
            "ingestion": {
                "allowed": false,
                "reason": "runtime_verify_not_durable_memory"
            },
            "artifact": Value::Null
        }
    });
    if include_raw {
        if let Some(obj) = payload.as_object_mut() {
            obj.insert("raw_verify".to_string(), verify.clone());
        }
    }
    payload
}

fn macos_ax_verify_target_family(expect: &str) -> &'static str {
    match expect {
        "window_appeared" | "window_gone" | "window_focused" => "window",
        "frontmost_app_is" => "application",
        "ax_trusted_is" => "permission",
        _ => "target",
    }
}

fn macos_ax_verify_selector_summary(selector: &Value) -> String {
    let mut parts = Vec::new();
    for key in ["app", "bundle_id", "pid", "title", "role", "index", "state"] {
        if let Some(value) = selector.get(key) {
            match value {
                Value::String(s) if !s.trim().is_empty() => {
                    parts.push(format!("{key}:{}", s.trim()));
                }
                Value::Number(n) => parts.push(format!("{key}:{n}")),
                Value::Bool(b) => parts.push(format!("{key}:{b}")),
                _ => {}
            }
        }
    }
    if parts.is_empty() {
        "unspecified-target".to_string()
    } else {
        parts.join(" ")
    }
}

fn macos_ax_verify_script_path(args: &Value, cwd: Option<&PathBuf>) -> PathBuf {
    if let Some(path) = args.get("script_path").and_then(Value::as_str) {
        return PathBuf::from(path);
    }
    if let Ok(path) = std::env::var("AGENT_BRIDGE_MACOS_AX_VERIFY_SCRIPT") {
        if !path.trim().is_empty() {
            return PathBuf::from(path);
        }
    }
    if let Some(cwd) = cwd {
        let path = cwd.join("scripts/macos_ax_verify.py");
        if path.exists() {
            return path;
        }
    }
    if let Ok(cwd) = std::env::current_dir() {
        let path = cwd.join("scripts/macos_ax_verify.py");
        if path.exists() {
            return path;
        }
    }
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../scripts/macos_ax_verify.py")
}

fn macos_ax_verify_error(error: Value) -> ToolResult {
    let mut result = ToolResult::json_text(&json!({
        "schema": "macos_ax_verify_mcp_error.v0",
        "status": "error",
        "error": error,
    }));
    result.is_error = true;
    result
}

