fn semantic_bus_adapter_report_repo_root(args: &Value) -> PathBuf {
    if let Some(cwd) = args.get("cwd").and_then(Value::as_str) {
        return PathBuf::from(cwd);
    }
    if let Ok(cwd) = std::env::current_dir() {
        if cwd.join("crates/bridge/fixtures/semantic_bus").exists() {
            return cwd;
        }
    }
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../..")
}

fn semantic_bus_adapter_row(
    repo_root: &Path,
    include_details: bool,
    spec: SemanticBusAdapterSpec,
) -> Value {
    let runtime_assets = semantic_bus_asset_list(repo_root, spec.runtime_assets);
    let fixture_assets = semantic_bus_fixture_asset_list(repo_root, spec.fixture_assets);
    let doc_assets = semantic_bus_asset_list(repo_root, spec.doc_assets);
    let all_runtime_present = runtime_assets.iter().all(semantic_bus_asset_present);
    let any_fixture_present = fixture_assets.iter().any(semantic_bus_asset_present);
    let any_doc_present = doc_assets.iter().any(semantic_bus_asset_present);
    let ready_for_runtime =
        spec.evidence_level == "runtime_backed" && all_runtime_present && any_doc_present;
    let fixture_adapter_contract_present = fixture_assets
        .iter()
        .any(|asset| asset.get("has_adapter_contract").and_then(Value::as_bool) == Some(true));
    let fixture_without_adapter_contract = fixture_assets.iter().any(|asset| {
        semantic_bus_asset_present(asset)
            && asset.get("has_adapter_contract").and_then(Value::as_bool) == Some(false)
    });

    let mut row = json!({
        "adapter_id": spec.adapter_id,
        "platform": spec.platform,
        "adapter_family": spec.adapter_family,
        "tool": spec.tool,
        "semantic_schema": spec.semantic_schema,
        "source_schema": spec.source_schema,
        "evidence_level": spec.evidence_level,
        "status": spec.status,
        "read_only": true,
        "broad_host_mutation": false,
        "channels": spec.channels,
        "fallback_order": spec.fallback_order,
        "runtime_assets": spec.runtime_assets,
        "fixture_assets": spec.fixture_assets,
        "doc_assets": spec.doc_assets,
        "notes": spec.notes,
        "ready_for_runtime": ready_for_runtime,
        "asset_summary": {
            "runtime_assets_present": all_runtime_present,
            "fixture_assets_present": any_fixture_present,
            "doc_assets_present": any_doc_present,
            "fixture_adapter_contract_present": fixture_adapter_contract_present,
            "fixture_without_adapter_contract": fixture_without_adapter_contract
        }
    });
    if include_details {
        if let Some(obj) = row.as_object_mut() {
            obj.insert(
                "assets".to_string(),
                json!({
                    "runtime": runtime_assets,
                    "fixtures": fixture_assets,
                    "docs": doc_assets
                }),
            );
        }
    }
    row
}

fn semantic_bus_asset_list(repo_root: &Path, rels: &[&str]) -> Vec<Value> {
    rels.iter()
        .map(|rel| semantic_bus_asset(repo_root, rel))
        .collect()
}

fn semantic_bus_fixture_asset_list(repo_root: &Path, rels: &[&str]) -> Vec<Value> {
    rels.iter()
        .map(|rel| semantic_bus_fixture_asset(repo_root, rel))
        .collect()
}

fn semantic_bus_asset(repo_root: &Path, rel: &str) -> Value {
    json!({
        "path": rel,
        "exists": repo_root.join(rel).exists()
    })
}

fn semantic_bus_fixture_asset(repo_root: &Path, rel: &str) -> Value {
    let path = repo_root.join(rel);
    let has_adapter_contract = if path.exists() {
        std::fs::read_to_string(&path)
            .ok()
            .and_then(|s| serde_json::from_str::<Value>(&s).ok())
            .and_then(|v| v.get("adapter_contract").cloned())
            .is_some()
    } else {
        false
    };
    json!({
        "path": rel,
        "exists": path.exists(),
        "has_adapter_contract": has_adapter_contract
    })
}

fn semantic_bus_asset_present(asset: &Value) -> bool {
    asset
        .get("exists")
        .and_then(Value::as_bool)
        .unwrap_or(false)
}

fn semantic_bus_adapter_report_summary(adapters: &[Value]) -> Value {
    let mut by_evidence = Map::new();
    let mut by_platform = Map::new();
    let mut ready_for_runtime = 0u64;
    for row in adapters {
        semantic_bus_increment_count(
            &mut by_evidence,
            row.get("evidence_level")
                .and_then(Value::as_str)
                .unwrap_or("unknown"),
        );
        semantic_bus_increment_count(
            &mut by_platform,
            row.get("platform")
                .and_then(Value::as_str)
                .unwrap_or("unknown"),
        );
        if row
            .get("ready_for_runtime")
            .and_then(Value::as_bool)
            .unwrap_or(false)
        {
            ready_for_runtime += 1;
        }
    }
    json!({
        "adapter_count": adapters.len(),
        "by_evidence_level": by_evidence,
        "by_platform": by_platform,
        "ready_for_runtime_count": ready_for_runtime
    })
}

fn semantic_bus_increment_count(counts: &mut Map<String, Value>, key: &str) {
    let count = counts.get(key).and_then(Value::as_u64).unwrap_or(0) + 1;
    counts.insert(key.to_string(), json!(count));
}

fn semantic_bus_adapter_report_gaps(adapters: &[Value]) -> Vec<Value> {
    let mut gaps = Vec::new();
    for row in adapters {
        let adapter_id = row
            .get("adapter_id")
            .and_then(Value::as_str)
            .unwrap_or("unknown");
        let evidence_level = row
            .get("evidence_level")
            .and_then(Value::as_str)
            .unwrap_or("unknown");
        let assets = row.get("asset_summary").unwrap_or(&Value::Null);
        if evidence_level == "design_only" {
            gaps.push(json!({
                "adapter_id": adapter_id,
                "gap": "design_only_no_runtime_or_fixture_contract",
                "recommendation": "add a bounded read-only runtime adapter or downgrade expectations in planning"
            }));
        }
        if assets
            .get("fixture_without_adapter_contract")
            .and_then(Value::as_bool)
            .unwrap_or(false)
        {
            gaps.push(json!({
                "adapter_id": adapter_id,
                "gap": "fixture_missing_adapter_contract",
                "recommendation": "add adapter_contract metadata before treating the fixture as an adapter contract"
            }));
        }
        if evidence_level == "runtime_backed"
            && !row
                .get("ready_for_runtime")
                .and_then(Value::as_bool)
                .unwrap_or(false)
        {
            gaps.push(json!({
                "adapter_id": adapter_id,
                "gap": "runtime_assets_or_docs_missing",
                "recommendation": "restore expected script/doc assets before advertising runtime-backed status"
            }));
        }
    }
    gaps
}

// ===========================================================================
//                       semantic_bus_runtime_health
// ===========================================================================

pub struct SemanticBusRuntimeHealthTool {
    _hub: Hub,
}

impl SemanticBusRuntimeHealthTool {
    pub fn new(hub: Hub) -> Self {
        Self { _hub: hub }
    }
}

#[async_trait]
impl McpTool for SemanticBusRuntimeHealthTool {
    fn name(&self) -> &'static str {
        "semantic_bus_runtime_health"
    }

    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Read-only Semantic System Bus runtime health report for local \
                 daemon-http and Palace memory-region state. It performs bounded HTTP GET \
                 checks; it never restarts services, mutates Palace, captures screenshots, \
                 or writes memory graph edges."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "daemon_http_url": {
                        "type": "string",
                        "default": "http://127.0.0.1:7878",
                        "description": "Base URL for daemon-http healthz."
                    },
                    "palace_url": {
                        "type": "string",
                        "default": "http://127.0.0.1:7979",
                        "description": "Base URL for Palace."
                    },
                    "include_all": {
                        "type": "boolean",
                        "default": false,
                        "description": "When true, call Palace /api/graph?all=1."
                    },
                    "check_semantic_events": {
                        "type": "boolean",
                        "default": true,
                        "description": "Also probe Palace /api/semantic-events. Missing endpoint is optional."
                    },
                    "include_raw": {
                        "type": "boolean",
                        "default": false,
                        "description": "Include parsed raw Palace graph/events JSON."
                    },
                    "timeout_ms": {
                        "type": "integer",
                        "minimum": 500,
                        "maximum": 10000,
                        "default": 2500,
                        "description": "Per-request HTTP timeout in milliseconds."
                    }
                }
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        Ok(ToolResult::json_text(
            &semantic_bus_runtime_health_payload(&args).await,
        ))
    }
}

async fn semantic_bus_runtime_health_payload(args: &Value) -> Value {
    let daemon_http_url =
        semantic_bus_runtime_arg(args, "daemon_http_url", "http://127.0.0.1:7878");
    let palace_url = semantic_bus_runtime_arg(args, "palace_url", "http://127.0.0.1:7979");
    let include_all = args
        .get("include_all")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let check_semantic_events = args
        .get("check_semantic_events")
        .and_then(Value::as_bool)
        .unwrap_or(true);
    let include_raw = args
        .get("include_raw")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let timeout_ms = args
        .get("timeout_ms")
        .and_then(Value::as_u64)
        .unwrap_or(2_500)
        .clamp(500, 10_000);
    let now_secs = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs();

    let client = match reqwest::Client::builder()
        .timeout(Duration::from_millis(timeout_ms))
        .user_agent("agent-bridge-semantic-bus-runtime-health/0")
        .build()
    {
        Ok(client) => client,
        Err(e) => {
            return semantic_bus_runtime_health_report(
                now_secs,
                &daemon_http_url,
                &palace_url,
                timeout_ms,
                semantic_bus_runtime_error_check("/healthz", "client_init_error", &e.to_string()),
                None,
                semantic_bus_runtime_error_check("/healthz", "client_init_error", &e.to_string()),
                None,
                semantic_bus_runtime_error_check("/api/graph", "client_init_error", &e.to_string()),
                None,
                semantic_bus_runtime_error_check(
                    "/api/semantic-events",
                    "skipped_client_init_error",
                    &e.to_string(),
                ),
                None,
                include_raw,
            );
        }
    };
    let graph_endpoint = if include_all {
        "/api/graph?all=1"
    } else {
        "/api/graph"
    };

    let (daemon_health, daemon_body) =
        semantic_bus_runtime_get_text(&client, &daemon_http_url, "/healthz").await;
    let (palace_health, palace_body) =
        semantic_bus_runtime_get_text(&client, &palace_url, "/healthz").await;
    let (mut graph_check, graph_body) =
        semantic_bus_runtime_get_text(&client, &palace_url, graph_endpoint).await;
    let graph = semantic_bus_runtime_parse_json(&mut graph_check, graph_body.as_deref());
    let (mut events_check, events_body) = if check_semantic_events {
        semantic_bus_runtime_get_text(&client, &palace_url, "/api/semantic-events").await
    } else {
        (
            json!({
                "endpoint": "/api/semantic-events",
                "url": semantic_bus_runtime_join_url(&palace_url, "/api/semantic-events").ok(),
                "ok": null,
                "status": "skipped",
                "optional": true
            }),
            None,
        )
    };
    let events = semantic_bus_runtime_parse_json(&mut events_check, events_body.as_deref());
    semantic_bus_runtime_mark_optional(&mut events_check);

    semantic_bus_runtime_health_report(
        now_secs,
        &daemon_http_url,
        &palace_url,
        timeout_ms,
        daemon_health,
        daemon_body,
        palace_health,
        palace_body,
        graph_check,
        graph,
        events_check,
        events,
        include_raw,
    )
}

#[allow(clippy::too_many_arguments)]
fn semantic_bus_runtime_health_report(
    now_secs: u64,
    daemon_http_url: &str,
    palace_url: &str,
    timeout_ms: u64,
    daemon_health: Value,
    daemon_body: Option<String>,
    palace_health: Value,
    palace_body: Option<String>,
    graph_check: Value,
    graph: Option<Value>,
    events_check: Value,
    events: Option<Value>,
    include_raw: bool,
) -> Value {
    let daemon_ok = semantic_bus_runtime_health_ok(&daemon_health, daemon_body.as_deref());
    let palace_ok = semantic_bus_runtime_health_ok(&palace_health, palace_body.as_deref());
    let graph_ok = graph.is_some();
    let required_ok = daemon_ok && palace_ok && graph_ok;
    let any_ok = daemon_ok || palace_ok || graph_ok;
    let status = if required_ok {
        "ready"
    } else if any_ok {
        "degraded"
    } else {
        "blocked"
    };
    let graph_stats = graph.as_ref().map(semantic_bus_runtime_graph_stats);
    let events_status = events_check
        .get("status")
        .and_then(Value::as_str)
        .unwrap_or("unknown");

    let mut objects = vec![
        semantic_bus_runtime_service_object(
            "daemon-http",
            "Agent-Bridge daemon-http",
            "service.http.daemon",
            "daemon_http.healthz",
            daemon_http_url,
            &daemon_health,
            daemon_ok,
            now_secs,
        ),
        semantic_bus_runtime_service_object(
            "palace",
            "Agent-Bridge Palace",
            "service.http.ui",
            "palace.healthz",
            palace_url,
            &palace_health,
            palace_ok,
            now_secs,
        ),
    ];
    if let Some(stats) = graph_stats.as_ref() {
        objects.push(json!({
            "schema": "agent_bridge.semantic_bus.object.v0",
            "object_id": "palace:memory-region:agent-bridge",
            "object_type": "memory.region",
            "source_adapter": "palace.memory_graph",
            "label": "Agent-Bridge Palace memory region",
            "state": {
                "status": "observed",
                "stats": stats
            },
            "relations": [
                {
                    "rel": "served_by",
                    "target": semantic_bus_runtime_service_id("palace", palace_url)
                }
            ],
            "confidence": 0.9,
            "observed_at": now_secs
        }));
    }

    let mut checks = Map::new();
    checks.insert("daemon_http_health".into(), daemon_health.clone());
    checks.insert("palace_health".into(), palace_health.clone());
    checks.insert("palace_graph".into(), graph_check.clone());
    checks.insert("palace_semantic_events".into(), events_check.clone());

    let mut payload = json!({
        "schema": SEMANTIC_BUS_RUNTIME_HEALTH_SCHEMA,
        "source_adapter": "runtime.health.local",
        "generated_at_unix": now_secs,
        "read_only": true,
        "live_checks_executed": true,
        "timeout_ms": timeout_ms,
        "targets": {
            "daemon_http_url": daemon_http_url,
            "palace_url": palace_url
        },
        "status": status,
        "summary": {
            "daemon_http_healthy": daemon_ok,
            "palace_healthy": palace_ok,
            "palace_graph_observed": graph_ok,
            "palace_semantic_events_status": events_status,
            "memory_region_stats": graph_stats
        },
        "verification": {
            "verdict": if required_ok { "verified" } else { "not_verified" },
            "reason": if required_ok {
                "daemon-http healthz, Palace healthz, and Palace graph were observed"
            } else {
                "one or more required runtime health checks were unavailable"
            },
            "recover": if required_ok { "proceed" } else if any_ok { "retry" } else { "replan" },
            "required_checks": {
                "daemon_http_health": daemon_ok,
                "palace_health": palace_ok,
                "palace_graph": graph_ok
            },
            "optional_checks": {
                "palace_semantic_events": events_status
            }
        },
        "semantic_objects": objects,
        "events": [
            semantic_bus_runtime_event("daemon-http-health-observed", daemon_http_url, daemon_ok, &daemon_health, now_secs),
            semantic_bus_runtime_event("palace-health-observed", palace_url, palace_ok, &palace_health, now_secs)
        ],
        "checks": checks
    });

    if include_raw {
        if let Some(obj) = payload.as_object_mut() {
            obj.insert(
                "raw".to_string(),
                json!({
                    "palace_graph": graph,
                    "palace_semantic_events": events
                }),
            );
        }
    }
    payload
}

async fn semantic_bus_runtime_get_text(
    client: &reqwest::Client,
    base_url: &str,
    endpoint: &str,
) -> (Value, Option<String>) {
    let url = match semantic_bus_runtime_join_url(base_url, endpoint) {
        Ok(url) => url,
        Err(e) => {
            return (
                semantic_bus_runtime_error_check(endpoint, "invalid_url", &e),
                None,
            )
        }
    };
    let started = Instant::now();
    let response = client
        .get(&url)
        .header("Accept", "application/json, text/plain;q=0.9, */*;q=0.1")
        .send()
        .await;
    match response {
        Ok(resp) => {
            let http_status = resp.status().as_u16();
            let ok = resp.status().is_success();
            let content_type = resp
                .headers()
                .get("content-type")
                .and_then(|v| v.to_str().ok())
                .map(str::to_string);
            match resp.text().await {
                Ok(body) => (
                    json!({
                        "endpoint": endpoint,
                        "url": url,
                        "ok": ok,
                        "status": if ok { "ok" } else { "http_error" },
                        "http_status": http_status,
                        "elapsed_ms": semantic_bus_runtime_elapsed_ms(started),
                        "content_type": content_type,
                        "body_preview": body.chars().take(512).collect::<String>()
                    }),
                    Some(body),
                ),
                Err(e) => (
                    json!({
                        "endpoint": endpoint,
                        "url": url,
                        "ok": false,
                        "status": "body_error",
                        "http_status": http_status,
                        "elapsed_ms": semantic_bus_runtime_elapsed_ms(started),
                        "content_type": content_type,
                        "error": e.to_string()
                    }),
                    None,
                ),
            }
        }
        Err(e) => (
            json!({
                "endpoint": endpoint,
                "url": url,
                "ok": false,
                "status": "unreachable",
                "elapsed_ms": semantic_bus_runtime_elapsed_ms(started),
                "error": e.to_string()
            }),
            None,
        ),
    }
}

fn semantic_bus_runtime_parse_json(check: &mut Value, body: Option<&str>) -> Option<Value> {
    if !semantic_bus_runtime_check_ok(check) {
        return None;
    }
    match body.and_then(|b| serde_json::from_str::<Value>(b).ok()) {
        Some(value) => Some(value),
        None => {
            if let Some(obj) = check.as_object_mut() {
                obj.insert("ok".to_string(), json!(false));
                obj.insert("status".to_string(), json!("invalid_json"));
                obj.insert("error".to_string(), json!("response was not valid JSON"));
            }
            None
        }
    }
}

fn semantic_bus_runtime_arg(args: &Value, key: &str, default: &str) -> String {
    args.get(key)
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .unwrap_or(default)
        .trim_end_matches('/')
        .to_string()
}

fn semantic_bus_runtime_join_url(
    base_url: &str,
    endpoint: &str,
) -> std::result::Result<String, String> {
    let base_url = base_url.trim();
    if base_url.is_empty() {
        return Err("base URL is empty".to_string());
    }
    let base = reqwest::Url::parse(&format!("{}/", base_url.trim_end_matches('/')))
        .map_err(|e| format!("parse base URL {base_url}: {e}"))?;
    if !matches!(base.scheme(), "http" | "https") {
        return Err(format!("unsupported URL scheme: {}", base.scheme()));
    }
    base.join(endpoint.trim_start_matches('/'))
        .map(|url| url.to_string())
        .map_err(|e| format!("join endpoint {endpoint}: {e}"))
}

fn semantic_bus_runtime_error_check(endpoint: &str, status: &str, error: &str) -> Value {
    json!({
        "endpoint": endpoint,
        "url": null,
        "ok": false,
        "status": status,
        "error": error
    })
}

fn semantic_bus_runtime_mark_optional(check: &mut Value) {
    if let Some(obj) = check.as_object_mut() {
        obj.insert("optional".to_string(), json!(true));
    }
}

fn semantic_bus_runtime_elapsed_ms(started: Instant) -> u64 {
    let elapsed = started.elapsed().as_millis();
    elapsed.min(u128::from(u64::MAX)) as u64
}

fn semantic_bus_runtime_check_ok(check: &Value) -> bool {
    check.get("ok").and_then(Value::as_bool).unwrap_or(false)
}

fn semantic_bus_runtime_health_ok(check: &Value, body: Option<&str>) -> bool {
    semantic_bus_runtime_check_ok(check) && body.map(str::trim) == Some("ok")
}

fn semantic_bus_runtime_service_id(name: &str, base_url: &str) -> String {
    let authority =
        semantic_bus_runtime_url_authority(base_url).unwrap_or_else(|| "unknown".to_string());
    format!("service:agent-bridge:{name}:{authority}")
}

fn semantic_bus_runtime_url_authority(base_url: &str) -> Option<String> {
    let url = reqwest::Url::parse(&format!("{}/", base_url.trim_end_matches('/'))).ok()?;
    let host = url.host_str()?;
    let port = url
        .port_or_known_default()
        .map(|p| p.to_string())
        .unwrap_or_else(|| "unknown".to_string());
    Some(format!("{host}:{port}"))
}

fn semantic_bus_runtime_service_object(
    name: &str,
    label: &str,
    object_type: &str,
    source_adapter: &str,
    base_url: &str,
    health_check: &Value,
    healthy: bool,
    now_secs: u64,
) -> Value {
    json!({
        "schema": "agent_bridge.semantic_bus.object.v0",
        "object_id": semantic_bus_runtime_service_id(name, base_url),
        "object_type": object_type,
        "source_adapter": source_adapter,
        "label": label,
        "state": {
            "status": if healthy { "healthy" } else { "unhealthy" },
            "health_endpoint": health_check.get("url").cloned().unwrap_or(Value::Null),
            "http_status": health_check.get("http_status").cloned().unwrap_or(Value::Null)
        },
        "confidence": if healthy { 0.95 } else { 0.4 },
        "observed_at": now_secs
    })
}

fn semantic_bus_runtime_event(
    event_type: &str,
    base_url: &str,
    healthy: bool,
    health_check: &Value,
    now_secs: u64,
) -> Value {
    json!({
        "schema": "agent_bridge.semantic_bus.event.v0",
        "event_id": format!("evt-{event_type}-{now_secs}"),
        "event_type": event_type,
        "object_id": semantic_bus_runtime_service_id(event_type.trim_end_matches("-health-observed"), base_url),
        "observed_at": now_secs,
        "source_adapter": health_check.get("endpoint").and_then(Value::as_str).unwrap_or("healthz"),
        "severity": if healthy { "info" } else { "warning" },
        "status": if healthy { "healthy" } else { "unhealthy" },
        "delta": null,
        "evidence": health_check
    })
}

fn semantic_bus_runtime_i64(v: &Value) -> Option<i64> {
    v.as_i64()
        .or_else(|| v.as_u64().and_then(|n| i64::try_from(n).ok()))
}

fn semantic_bus_runtime_graph_stats(graph: &Value) -> Value {
    let nodes = graph
        .get("nodes")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    let edges = graph
        .get("edges")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    let now_secs = semantic_bus_runtime_i64(graph.get("now").unwrap_or(&Value::Null)).unwrap_or(0);
    let mut degree = HashMap::<String, i64>::new();
    let mut sqlite_nodes = 0i64;
    let mut markdown_nodes = 0i64;
    let mut fresh_nodes = 0i64;
    let mut stale_nodes = 0i64;
    for node in &nodes {
        if let Some(id) = node.get("id").and_then(Value::as_str) {
            degree.insert(id.to_string(), 0);
        }
        match node.get("source").and_then(Value::as_str).unwrap_or("") {
            "sqlite" => sqlite_nodes += 1,
            "markdown" => markdown_nodes += 1,
            _ => {}
        }
        let last_accessed =
            semantic_bus_runtime_i64(node.get("last_accessed").unwrap_or(&Value::Null))
                .unwrap_or(0);
        if last_accessed > 0 {
            let age = now_secs.saturating_sub(last_accessed);
            if age < 3600 {
                fresh_nodes += 1;
            }
            if age > 7 * 24 * 3600 {
                stale_nodes += 1;
            }
        }
    }

    let mut explicit_edges = 0i64;
    let mut coactivation_edges = 0i64;
    for edge in &edges {
        if edge.get("type").and_then(Value::as_str) == Some("coactivation") {
            coactivation_edges += 1;
            continue;
        }
        explicit_edges += 1;
        for key in ["source", "target"] {
            if let Some(id) = edge.get(key).and_then(Value::as_str) {
                if let Some(d) = degree.get_mut(id) {
                    *d += 1;
                }
            }
        }
    }
    let node_count = nodes.len() as i64;
    let edge_count = edges.len() as i64;
    let orphan_nodes = degree.values().filter(|d| **d == 0).count() as i64;
    let connected_ratio = if node_count > 0 {
        (node_count - orphan_nodes) as f64 / node_count as f64
    } else {
        0.0
    };
    let explicit_density = explicit_edges as f64 / node_count.max(1) as f64;
    let mut degrees: Vec<i64> = degree.values().copied().filter(|d| *d > 0).collect();
    degrees.sort_unstable();
    let hub_threshold = degrees
        .get(
            degrees
                .len()
                .saturating_sub(1)
                .min(degrees.len() * 95 / 100),
        )
        .copied()
        .unwrap_or(0)
        .max(5);
    let hub_nodes = if degrees.len() >= 20 {
        degree.values().filter(|d| **d >= hub_threshold).count() as i64
    } else {
        0
    };

    json!({
        "nodes": node_count,
        "edges": edge_count,
        "sqlite_nodes": sqlite_nodes,
        "markdown_nodes": markdown_nodes,
        "explicit_edges": explicit_edges,
        "coactivation_edges": coactivation_edges,
        "orphan_nodes": orphan_nodes,
        "hub_nodes": hub_nodes,
        "fresh_nodes": fresh_nodes,
        "stale_nodes": stale_nodes,
        "hub_threshold": hub_threshold,
        "connected_ratio": (connected_ratio * 1000.0).round() / 1000.0,
        "explicit_density": (explicit_density * 1000.0).round() / 1000.0
    })
}

// ===========================================================================
//                       semantic_bus_runtime_conformance
// ===========================================================================

pub struct SemanticBusRuntimeConformanceTool {
    _hub: Hub,
}

impl SemanticBusRuntimeConformanceTool {
    pub fn new(hub: Hub) -> Self {
        Self { _hub: hub }
    }
}

#[async_trait]
impl McpTool for SemanticBusRuntimeConformanceTool {
    fn name(&self) -> &'static str {
        "semantic_bus_runtime_conformance"
    }

    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Read-only Semantic System Bus runtime conformance snapshot. \
                 It combines adapter evidence with local runtime health into a compact \
                 coverage report and leaves unavailable platform adapters explicit; it \
                 never mutates host state, restarts services, or writes memory graph edges."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "cwd": {
                        "type": "string",
                        "description": "Agent-Bridge repo root for source-backed adapter evidence."
                    },
                    "include_runtime_health": {
                        "type": "boolean",
                        "default": true,
                        "description": "Run local daemon-http/Palace runtime health checks."
                    },
                    "daemon_http_url": {
                        "type": "string",
                        "default": "http://127.0.0.1:7878",
                        "description": "Base URL for daemon-http healthz when include_runtime_health=true."
                    },
                    "palace_url": {
                        "type": "string",
                        "default": "http://127.0.0.1:7979",
                        "description": "Base URL for Palace when include_runtime_health=true."
                    },
                    "timeout_ms": {
                        "type": "integer",
                        "minimum": 500,
                        "maximum": 10000,
                        "default": 2500,
                        "description": "Per-request timeout for runtime health checks."
                    }
                }
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        Ok(ToolResult::json_text(
            &semantic_bus_runtime_conformance_payload(&args).await,
        ))
    }
}

pub(crate) async fn semantic_bus_runtime_conformance_payload(args: &Value) -> Value {
    let now_secs = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs();
    let mut adapter_args = json!({
        "include_details": false,
        "include_design_only": true
    });
    if let Some(cwd) = args.get("cwd").and_then(Value::as_str) {
        adapter_args["cwd"] = json!(cwd);
    }
    let adapter_report = semantic_bus_adapter_report_payload(&adapter_args);
    let include_runtime_health = args
        .get("include_runtime_health")
        .and_then(Value::as_bool)
        .unwrap_or(true);
    let runtime_health = if include_runtime_health {
        let runtime_args = json!({
            "daemon_http_url": semantic_bus_runtime_arg(args, "daemon_http_url", "http://127.0.0.1:7878"),
            "palace_url": semantic_bus_runtime_arg(args, "palace_url", "http://127.0.0.1:7979"),
            "timeout_ms": args.get("timeout_ms").and_then(Value::as_u64).unwrap_or(2_500),
            "include_raw": false,
            "check_semantic_events": true
        });
        Some(semantic_bus_runtime_health_payload(&runtime_args).await)
    } else {
        None
    };
    semantic_bus_runtime_conformance_report(now_secs, adapter_report, runtime_health)
}

fn semantic_bus_runtime_conformance_report(
    now_secs: u64,
    adapter_report: Value,
    runtime_health: Option<Value>,
) -> Value {
    let current_platform = std::env::consts::OS;
    let adapters = adapter_report
        .get("adapters")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    let runtime_health_status = runtime_health
        .as_ref()
        .and_then(|v| v.get("status"))
        .and_then(Value::as_str)
        .unwrap_or("not_checked");
    let runtime_health_verified = runtime_health
        .as_ref()
        .and_then(|v| v.get("verification"))
        .and_then(|v| v.get("verdict"))
        .and_then(Value::as_str)
        == Some("verified");

    let mut rows = Vec::new();
    let mut live_ready = 0u64;
    let mut current_platform_runtime_backed = 0u64;
    let mut fixture_only = 0u64;
    let mut design_only = 0u64;
    for adapter in adapters {
        let adapter_id = adapter
            .get("adapter_id")
            .and_then(Value::as_str)
            .unwrap_or("unknown");
        let platform = adapter
            .get("platform")
            .and_then(Value::as_str)
            .unwrap_or("unknown");
        let evidence_level = adapter
            .get("evidence_level")
            .and_then(Value::as_str)
            .unwrap_or("unknown");
        let tool = adapter.get("tool").and_then(Value::as_str);
        let live_status = if tool == Some("semantic_bus_runtime_health") {
            runtime_health_status
        } else if evidence_level == "runtime_backed" && platform == current_platform {
            current_platform_runtime_backed += 1;
            "runtime_backed_available_not_checked"
        } else if evidence_level == "runtime_backed" {
            "runtime_backed_not_current_platform"
        } else if evidence_level == "fixture_backed" {
            fixture_only += 1;
            "fixture_only"
        } else if evidence_level == "design_only" {
            design_only += 1;
            "design_only"
        } else {
            "unknown"
        };
        if live_status == "ready" {
            live_ready += 1;
        }
        rows.push(json!({
            "adapter_id": adapter_id,
            "platform": platform,
            "adapter_family": adapter.get("adapter_family").cloned().unwrap_or(Value::Null),
            "tool": tool,
            "evidence_level": evidence_level,
            "ready_for_runtime": adapter.get("ready_for_runtime").cloned().unwrap_or(json!(false)),
            "live_status": live_status,
            "current_platform": platform == current_platform,
            "read_only": adapter.get("read_only").cloned().unwrap_or(json!(true))
        }));
    }

    let gaps = adapter_report
        .get("gaps")
        .cloned()
        .unwrap_or_else(|| json!([]));
    let windows_slot = rows
        .iter()
        .find(|row| {
            row.get("adapter_id").and_then(Value::as_str) == Some("windows_uia_runtime_adapter")
        })
        .cloned()
        .unwrap_or_else(|| {
            json!({
                "adapter_id": "windows_uia_runtime_adapter",
                "live_status": "missing_from_adapter_report"
            })
        });
    let verdict = if runtime_health_verified {
        "verified"
    } else if runtime_health.is_some() {
        "degraded"
    } else {
        "not_checked"
    };

    json!({
        "schema": SEMANTIC_BUS_RUNTIME_CONFORMANCE_SCHEMA,
        "generated_at_unix": now_secs,
        "read_only": true,
        "live_checks_executed": runtime_health.is_some(),
        "current_platform": current_platform,
        "summary": {
            "adapter_count": rows.len(),
            "live_ready_count": live_ready,
            "current_platform_runtime_backed_count": current_platform_runtime_backed,
            "fixture_only_count": fixture_only,
            "design_only_count": design_only,
            "runtime_health_status": runtime_health_status,
            "runtime_health_verified": runtime_health_verified,
            "gap_count": gaps.as_array().map(|g| g.len()).unwrap_or(0)
        },
        "runtime_health_summary": runtime_health.as_ref().map(|v| json!({
            "status": v.get("status").cloned().unwrap_or(Value::Null),
            "verification": v.get("verification").cloned().unwrap_or(Value::Null),
            "summary": v.get("summary").cloned().unwrap_or(Value::Null)
        })),
        "adapters": rows,
        "gaps": gaps,
        "windows_uia_runtime_slot": windows_slot,
        "verification": {
            "verdict": verdict,
            "reason": if runtime_health_verified {
                "local runtime health is verified and adapter evidence is source-backed"
            } else if runtime_health.is_some() {
                "adapter evidence is source-backed but local runtime health is degraded"
            } else {
                "adapter evidence is source-backed but live runtime health was not checked"
            },
            "recover": if runtime_health_verified { "proceed" } else { "retry" }
        },
        "next_recommended_slice": {
            "id": "ssb-16-windows-uia-runtime-host",
            "reason": "the harness and peer-query transport keep Windows UIA explicit as a planned slot until a Windows host can provide runtime evidence"
        }
    })
}

// ===========================================================================
//                       semantic_bus_peer_conformance
// ===========================================================================

pub struct SemanticBusPeerConformanceTool {
    _hub: Hub,
}

impl SemanticBusPeerConformanceTool {
    pub fn new(hub: Hub) -> Self {
        Self { _hub: hub }
    }
}

#[async_trait]
impl McpTool for SemanticBusPeerConformanceTool {
    fn name(&self) -> &'static str {
        "semantic_bus_peer_conformance"
    }

    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Read-only Semantic System Bus peer conformance query. \
                 It fetches one or more daemon-http /semantic-bus/runtime-conformance \
                 exports and returns a compact multi-node summary; it never restarts \
                 services, captures screenshots, injects input, mutates Palace, or \
                 writes memory graph edges."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "endpoints": {
                        "type": "array",
                        "items": { "type": "string" },
                        "minItems": 1,
                        "maxItems": 16,
                        "description": "Base daemon-http URLs such as http://127.0.0.1:7878, or full /semantic-bus/runtime-conformance URLs."
                    },
                    "endpoint": {
                        "type": "string",
                        "description": "Compatibility shortcut for a single endpoint when endpoints is omitted."
                    },
                    "include_runtime_health": {
                        "type": "boolean",
                        "default": true,
                        "description": "Ask each peer endpoint to include its local runtime health summary."
                    },
                    "timeout_ms": {
                        "type": "integer",
                        "minimum": 500,
                        "maximum": 10000,
                        "default": 2500,
                        "description": "Per-peer HTTP timeout."
                    },
                    "include_raw": {
                        "type": "boolean",
                        "default": false,
                        "description": "Include each peer's raw conformance payload. Default false keeps the summary compact."
                    }
                }
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        Ok(ToolResult::json_text(
            &semantic_bus_peer_conformance_payload(&args).await,
        ))
    }
}

async fn semantic_bus_peer_conformance_payload(args: &Value) -> Value {
    let endpoints = semantic_bus_peer_conformance_endpoints(args);
    let include_runtime_health = args
        .get("include_runtime_health")
        .and_then(Value::as_bool)
        .unwrap_or(true);
    let include_raw = args
        .get("include_raw")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let timeout_ms = args
        .get("timeout_ms")
        .and_then(Value::as_u64)
        .unwrap_or(2_500)
        .clamp(500, 10_000);
    let now_secs = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs();

    if endpoints.is_empty() {
        return semantic_bus_peer_conformance_report(
            now_secs,
            timeout_ms,
            include_runtime_health,
            Vec::new(),
        );
    }

    let client = match reqwest::Client::builder()
        .timeout(Duration::from_millis(timeout_ms))
        .user_agent("agent-bridge-semantic-bus-peer-conformance/0")
        .build()
    {
        Ok(client) => client,
        Err(e) => {
            let peers = endpoints
                .iter()
                .enumerate()
                .map(|(idx, endpoint)| {
                    semantic_bus_peer_conformance_error_row(
                        idx,
                        endpoint,
                        None,
                        "client_init_error",
                        &e.to_string(),
                    )
                })
                .collect();
            return semantic_bus_peer_conformance_report(
                now_secs,
                timeout_ms,
                include_runtime_health,
                peers,
            );
        }
    };

    let mut peers = Vec::with_capacity(endpoints.len());
    for (idx, endpoint) in endpoints.iter().enumerate() {
        peers.push(
            semantic_bus_peer_conformance_fetch(
                &client,
                idx,
                endpoint,
                include_runtime_health,
                timeout_ms,
                include_raw,
            )
            .await,
        );
    }
    semantic_bus_peer_conformance_report(now_secs, timeout_ms, include_runtime_health, peers)
}

fn semantic_bus_peer_conformance_endpoints(args: &Value) -> Vec<String> {
    let mut endpoints = Vec::new();
    if let Some(items) = args.get("endpoints").and_then(Value::as_array) {
        endpoints.extend(
            items
                .iter()
                .filter_map(Value::as_str)
                .map(str::trim)
                .filter(|s| !s.is_empty())
                .map(str::to_string),
        );
    } else if let Some(endpoint) = args
        .get("endpoint")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|s| !s.is_empty())
    {
        endpoints.push(endpoint.to_string());
    }
    endpoints.truncate(16);
    endpoints
}

async fn semantic_bus_peer_conformance_fetch(
    client: &reqwest::Client,
    idx: usize,
    endpoint: &str,
    include_runtime_health: bool,
    timeout_ms: u64,
    include_raw: bool,
) -> Value {
    let url = match semantic_bus_peer_conformance_url(endpoint, include_runtime_health, timeout_ms)
    {
        Ok(url) => url,
        Err(e) => {
            return semantic_bus_peer_conformance_error_row(idx, endpoint, None, "invalid_url", &e)
        }
    };
    let started = Instant::now();
    let response = client
        .get(&url)
        .header("Accept", "application/json")
        .send()
        .await;
    match response {
        Ok(resp) => {
            let http_status = resp.status().as_u16();
            let http_ok = resp.status().is_success();
            let content_type = resp
                .headers()
                .get("content-type")
                .and_then(|v| v.to_str().ok())
                .map(str::to_string);
            match resp.text().await {
                Ok(body) => {
                    if !http_ok {
                        return semantic_bus_peer_conformance_http_error_row(
                            idx,
                            endpoint,
                            &url,
                            "http_error",
                            http_status,
                            semantic_bus_runtime_elapsed_ms(started),
                            content_type,
                            body,
                        );
                    }
                    match serde_json::from_str::<Value>(&body) {
                        Ok(payload) => semantic_bus_peer_conformance_payload_row(
                            idx,
                            endpoint,
                            &url,
                            http_status,
                            semantic_bus_runtime_elapsed_ms(started),
                            content_type,
                            payload,
                            include_raw,
                        ),
                        Err(e) => semantic_bus_peer_conformance_http_error_row(
                            idx,
                            endpoint,
                            &url,
                            "invalid_json",
                            http_status,
                            semantic_bus_runtime_elapsed_ms(started),
                            content_type,
                            format!("response was not valid JSON: {e}"),
                        ),
                    }
                }
                Err(e) => semantic_bus_peer_conformance_http_error_row(
                    idx,
                    endpoint,
                    &url,
                    "body_error",
                    http_status,
                    semantic_bus_runtime_elapsed_ms(started),
                    content_type,
                    e.to_string(),
                ),
            }
        }
        Err(e) => semantic_bus_peer_conformance_error_row(
            idx,
            endpoint,
            Some(url),
            "unreachable",
            &e.to_string(),
        ),
    }
}

fn semantic_bus_peer_conformance_url(
    endpoint: &str,
    include_runtime_health: bool,
    timeout_ms: u64,
) -> std::result::Result<String, String> {
    let trimmed = endpoint.trim();
    let url = if trimmed.contains("/semantic-bus/runtime-conformance") {
        trimmed.to_string()
    } else {
        semantic_bus_runtime_join_url(trimmed, "/semantic-bus/runtime-conformance")?
    };
    let mut parsed =
        reqwest::Url::parse(&url).map_err(|e| format!("parse conformance URL {url}: {e}"))?;
    if !matches!(parsed.scheme(), "http" | "https") {
        return Err(format!("unsupported URL scheme: {}", parsed.scheme()));
    }
    {
        let mut qp = parsed.query_pairs_mut();
        qp.append_pair(
            "include_runtime_health",
            if include_runtime_health {
                "true"
            } else {
                "false"
            },
        );
        qp.append_pair("timeout_ms", &timeout_ms.to_string());
    }
    Ok(parsed.to_string())
}

fn semantic_bus_peer_conformance_payload_row(
    idx: usize,
    endpoint: &str,
    url: &str,
    http_status: u16,
    elapsed_ms: u64,
    content_type: Option<String>,
    payload: Value,
    include_raw: bool,
) -> Value {
    let schema = payload
        .get("schema")
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    let schema_ok = schema == SEMANTIC_BUS_RUNTIME_CONFORMANCE_SCHEMA;
    let verification = payload.get("verification").cloned().unwrap_or(Value::Null);
    let verdict = verification
        .get("verdict")
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    let summary = payload.get("summary").cloned().unwrap_or_else(|| json!({}));
    let runtime_health_summary = payload
        .get("runtime_health_summary")
        .cloned()
        .unwrap_or(Value::Null);
    let runtime_health_status = summary
        .get("runtime_health_status")
        .and_then(Value::as_str)
        .or_else(|| runtime_health_summary.get("status").and_then(Value::as_str))
        .unwrap_or("unknown");
    let runtime_health_verified = summary
        .get("runtime_health_verified")
        .and_then(Value::as_bool)
        .unwrap_or_else(|| {
            runtime_health_summary
                .get("verification")
                .and_then(|v| v.get("verdict"))
                .and_then(Value::as_str)
                == Some("verified")
        });
    let windows_slot = semantic_bus_peer_conformance_windows_slot(&payload);

    let mut row = json!({
        "peer_index": idx,
        "peer_id": semantic_bus_peer_conformance_peer_id(endpoint, url, idx),
        "endpoint": endpoint,
        "url": url,
        "ok": schema_ok,
        "status": if schema_ok { "ok" } else { "schema_mismatch" },
        "http_status": http_status,
        "elapsed_ms": elapsed_ms,
        "content_type": content_type,
        "schema": schema,
        "current_platform": payload.get("current_platform").cloned().unwrap_or(Value::Null),
        "verdict": verdict,
        "runtime_health_status": runtime_health_status,
        "runtime_health_verified": runtime_health_verified,
        "adapter_count": summary.get("adapter_count").cloned().unwrap_or(Value::Null),
        "live_ready_count": summary.get("live_ready_count").cloned().unwrap_or(Value::Null),
        "gap_count": summary.get("gap_count").cloned().unwrap_or(Value::Null),
        "windows_uia_runtime_slot": windows_slot,
        "verification": verification
    });
    if include_raw {
        if let Some(obj) = row.as_object_mut() {
            obj.insert("raw".to_string(), payload);
        }
    }
    row
}

fn semantic_bus_peer_conformance_windows_slot(payload: &Value) -> Value {
    let slot = payload
        .get("windows_uia_runtime_slot")
        .cloned()
        .unwrap_or(Value::Null);
    json!({
        "adapter_id": slot.get("adapter_id").cloned().unwrap_or(json!("windows_uia_runtime_adapter")),
        "platform": slot.get("platform").cloned().unwrap_or(Value::Null),
        "evidence_level": slot.get("evidence_level").cloned().unwrap_or(Value::Null),
        "live_status": slot.get("live_status").cloned().unwrap_or(json!("unknown")),
        "tool": slot.get("tool").cloned().unwrap_or(Value::Null)
    })
}

fn semantic_bus_peer_conformance_peer_id(endpoint: &str, url: &str, idx: usize) -> String {
    semantic_bus_runtime_url_authority(endpoint)
        .or_else(|| semantic_bus_runtime_url_authority(url))
        .map(|authority| format!("peer:{authority}"))
        .unwrap_or_else(|| format!("peer:{idx}"))
}

fn semantic_bus_peer_conformance_http_error_row(
    idx: usize,
    endpoint: &str,
    url: &str,
    status: &str,
    http_status: u16,
    elapsed_ms: u64,
    content_type: Option<String>,
    error_or_body: String,
) -> Value {
    json!({
        "peer_index": idx,
        "peer_id": semantic_bus_peer_conformance_peer_id(endpoint, url, idx),
        "endpoint": endpoint,
        "url": url,
        "ok": false,
        "status": status,
        "http_status": http_status,
        "elapsed_ms": elapsed_ms,
        "content_type": content_type,
        "error": error_or_body.chars().take(512).collect::<String>(),
        "recover": "retry"
    })
}

fn semantic_bus_peer_conformance_error_row(
    idx: usize,
    endpoint: &str,
    url: Option<String>,
    status: &str,
    error: &str,
) -> Value {
    let url_ref = url.as_deref().unwrap_or(endpoint);
    json!({
        "peer_index": idx,
        "peer_id": semantic_bus_peer_conformance_peer_id(endpoint, url_ref, idx),
        "endpoint": endpoint,
        "url": url,
        "ok": false,
        "status": status,
        "error": error,
        "recover": if status == "invalid_url" { "replan" } else { "retry" }
    })
}

fn semantic_bus_peer_conformance_report(
    now_secs: u64,
    timeout_ms: u64,
    include_runtime_health: bool,
    peers: Vec<Value>,
) -> Value {
    let peer_count = peers.len() as u64;
    let ok_count = peers
        .iter()
        .filter(|row| row.get("ok").and_then(Value::as_bool) == Some(true))
        .count() as u64;
    let verified_count = peers
        .iter()
        .filter(|row| {
            row.get("ok").and_then(Value::as_bool) == Some(true)
                && row.get("verdict").and_then(Value::as_str) == Some("verified")
        })
        .count() as u64;
    let degraded_count = peers
        .iter()
        .filter(|row| {
            row.get("ok").and_then(Value::as_bool) == Some(true)
                && row.get("verdict").and_then(Value::as_str) == Some("degraded")
        })
        .count() as u64;
    let not_checked_count = peers
        .iter()
        .filter(|row| {
            row.get("ok").and_then(Value::as_bool) == Some(true)
                && row.get("verdict").and_then(Value::as_str) == Some("not_checked")
        })
        .count() as u64;
    let error_count = peer_count.saturating_sub(ok_count);
    let windows_runtime_ready_count = peers
        .iter()
        .filter(|row| {
            row.get("windows_uia_runtime_slot")
                .and_then(|slot| slot.get("live_status"))
                .and_then(Value::as_str)
                == Some("ready")
        })
        .count() as u64;
    let verdict = if peer_count == 0 {
        "blocked"
    } else if error_count == 0 && verified_count == peer_count {
        "verified"
    } else if ok_count > 0 {
        "degraded"
    } else {
        "not_verified"
    };

    json!({
        "schema": SEMANTIC_BUS_PEER_CONFORMANCE_SCHEMA,
        "generated_at_unix": now_secs,
        "read_only": true,
        "live_checks_executed": peer_count > 0,
        "timeout_ms": timeout_ms,
        "request": {
            "include_runtime_health": include_runtime_health,
            "endpoint_count": peer_count
        },
        "summary": {
            "peer_count": peer_count,
            "ok_count": ok_count,
            "verified_count": verified_count,
            "degraded_count": degraded_count,
            "not_checked_count": not_checked_count,
            "error_count": error_count,
            "windows_runtime_ready_count": windows_runtime_ready_count
        },
        "peers": peers,
        "verification": {
            "verdict": verdict,
            "reason": if peer_count == 0 {
                "no peer endpoints were supplied"
            } else if error_count == 0 && verified_count == peer_count {
                "all queried peers returned verified runtime conformance"
            } else if ok_count > 0 {
                "at least one peer returned a conformance snapshot, but not every peer is verified"
            } else {
                "no peer returned a valid runtime conformance snapshot"
            },
            "recover": if verdict == "verified" {
                "proceed"
            } else if ok_count > 0 {
                "retry"
            } else {
                "replan"
            }
        },
        "next_recommended_slice": {
            "id": if windows_runtime_ready_count > 0 {
                "ssb-16-cross-node-windows-uia-validation"
            } else {
                "ssb-16-windows-uia-runtime-host"
            },
            "reason": if windows_runtime_ready_count > 0 {
                "at least one peer reports a ready Windows UIA runtime slot; validate semantic snapshot/verify evidence next"
            } else {
                "peer query is live, but Windows UIA remains unavailable until a Windows host exports runtime evidence"
            }
        }
    })
}

// ===========================================================================
//                            vision_grounding_ocr
// ===========================================================================

pub struct VisionGroundingOcrTool {
    _hub: Hub,
}

impl VisionGroundingOcrTool {
    pub fn new(hub: Hub) -> Self {
        Self { _hub: hub }
    }
}

#[async_trait]
impl McpTool for VisionGroundingOcrTool {
    fn name(&self) -> &'static str {
        "vision_grounding_ocr"
    }

    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Run the non-mutating OCR vision grounding reference runner. \
                 It reads an existing image plus desktop_snapshot metadata and returns \
                 `vision_grounding_result.v0` candidates; it never clicks, types, takes \
                 screenshots, or controls the desktop."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "cwd": {
                        "type": "string",
                        "description": "Workspace/repo root used to resolve scripts/vision_grounding_ocr.py. Defaults to the MCP process cwd, then the build-time repo root."
                    },
                    "script_path": {
                        "type": "string",
                        "description": "Optional explicit vision_grounding_ocr.py path. Use mainly for tests or alternate checkouts."
                    },
                    "image": {
                        "type": "string",
                        "description": "Existing PNG/JPEG image path to OCR. The tool does not capture screenshots."
                    },
                    "engine": {
                        "type": "string",
                        "enum": ["tesseract", "fixture-tsv", "none"],
                        "default": "tesseract"
                    },
                    "fixture_tsv": {
                        "type": "string",
                        "description": "TSV fixture path when engine=fixture-tsv."
                    },
                    "request_id": { "type": "string" },
                    "snapshot_id": {
                        "type": "string",
                        "description": "desktop_snapshot snapshot id associated with this image."
                    },
                    "snapshot_hash": {
                        "type": "string",
                        "description": "Hash of the source desktop_snapshot payload."
                    },
                    "snapshot_schema": {
                        "type": "string",
                        "default": "desktop_snapshot/v0.5"
                    },
                    "snapshot_captured_at": { "type": "string" },
                    "image_hash": { "type": "string" },
                    "image_kind": {
                        "type": "string",
                        "enum": ["desktop", "output", "window"],
                        "default": "window"
                    },
                    "coordinate_space": {
                        "type": "string",
                        "enum": ["desktop", "output", "window"],
                        "default": "window"
                    },
                    "output": { "type": "string" },
                    "crop_rect": {
                        "type": "string",
                        "description": "Optional x,y,width,height crop rect."
                    },
                    "crop_image": {
                        "type": "boolean",
                        "default": false,
                        "description": "Actually crop the OCR input to crop_rect before OCR (not just translate coords). Fixes small-UI-text misses on full-frame images (#1803). Output coords are mapped back to coordinate_space."
                    },
                    "upscale": {
                        "type": "number",
                        "minimum": 1.0,
                        "maximum": 8.0,
                        "default": 1.0,
                        "description": "LANCZOS upscale factor for the OCR input so sub-~30px UI glyphs clear tesseract's resolution floor; output coords are divided back by this factor. Pair with crop_rect + crop_image on a small region (e.g. a button bbox from desktop_snapshot)."
                    },
                    "psm": {
                        "type": "integer",
                        "minimum": 0,
                        "maximum": 13,
                        "description": "tesseract page segmentation mode (7=single text line, 8=single word — good for a cropped button/label)."
                    },
                    "window_id": { "type": "integer" },
                    "pid": { "type": "integer" },
                    "app_id": { "type": "string" },
                    "title_hash": { "type": "string" },
                    "window_rect": {
                        "type": "string",
                        "description": "Optional x,y,width,height target window rect."
                    },
                    "task": { "type": "string", "default": "find text" },
                    "hint_text": { "type": "string" },
                    "hint_role": { "type": "string", "default": "unknown" },
                    "language": { "type": "string", "default": "auto" },
                    "engine_timeout_secs": {
                        "type": "number",
                        "minimum": 0.5,
                        "maximum": 60.0,
                        "default": 8.0,
                        "description": "Timeout forwarded to the OCR engine."
                    },
                    "timeout_ms": {
                        "type": "integer",
                        "minimum": 1000,
                        "maximum": 90000,
                        "default": 20000,
                        "description": "Milliseconds before the wrapper process is killed."
                    }
                },
                "required": ["image", "snapshot_id", "snapshot_hash"]
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let image = match required_str_arg(&args, "image") {
            Ok(v) => v,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        let snapshot_id = match required_str_arg(&args, "snapshot_id") {
            Ok(v) => v,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        let snapshot_hash = match required_str_arg(&args, "snapshot_hash") {
            Ok(v) => v,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        let engine = args
            .get("engine")
            .and_then(|v| v.as_str())
            .unwrap_or("tesseract");
        if !matches!(engine, "tesseract" | "fixture-tsv" | "none") {
            return Ok(ToolResult::error(
                "engine must be tesseract, fixture-tsv, or none",
            ));
        }
        let timeout_ms = args
            .get("timeout_ms")
            .and_then(|v| v.as_u64())
            .unwrap_or(20_000)
            .clamp(1_000, 90_000);
        let engine_timeout_secs = args
            .get("engine_timeout_secs")
            .and_then(|v| v.as_f64())
            .unwrap_or(8.0)
            .clamp(0.5, 60.0);

        let cwd = args.get("cwd").and_then(|v| v.as_str()).map(PathBuf::from);
        let script = vision_grounding_ocr_script_path(&args, cwd.as_ref());
        if !script.exists() {
            return Ok(vision_grounding_ocr_error(json!({
                "code": "script_missing",
                "message": format!("vision_grounding_ocr.py not found at {}", script.display()),
                "hint": "pass script_path or run from the Agent-Bridge repo root"
            })));
        }

        let mut cmd = killable_command(
            std::env::var("PYTHON")
                .ok()
                .filter(|s| !s.trim().is_empty())
                .unwrap_or_else(|| "python3".to_string()),
        );
        cmd.arg(&script)
            .arg("--compact")
            .arg("--image")
            .arg(image)
            .arg("--engine")
            .arg(engine)
            .arg("--snapshot-id")
            .arg(snapshot_id)
            .arg("--snapshot-hash")
            .arg(snapshot_hash)
            .arg("--timeout")
            .arg(engine_timeout_secs.to_string());

        push_optional_str_arg(&mut cmd, &args, "fixture_tsv", "--fixture-tsv");
        push_optional_str_arg(&mut cmd, &args, "request_id", "--request-id");
        push_optional_str_arg(&mut cmd, &args, "snapshot_schema", "--snapshot-schema");
        push_optional_str_arg(
            &mut cmd,
            &args,
            "snapshot_captured_at",
            "--snapshot-captured-at",
        );
        push_optional_str_arg(&mut cmd, &args, "image_hash", "--image-hash");
        push_optional_str_arg(&mut cmd, &args, "image_kind", "--image-kind");
        push_optional_str_arg(&mut cmd, &args, "coordinate_space", "--coordinate-space");
        push_optional_str_arg(&mut cmd, &args, "output", "--output");
        push_optional_str_arg(&mut cmd, &args, "crop_rect", "--crop-rect");
        if args
            .get("crop_image")
            .and_then(|v| v.as_bool())
            .unwrap_or(false)
        {
            cmd.arg("--crop-image");
        }
        // upscale is a float; push_optional_value_arg only handles ints/strings.
        if let Some(u) = args.get("upscale").and_then(|v| v.as_f64()) {
            if (u - 1.0).abs() > 1e-9 {
                cmd.arg("--upscale").arg(u.to_string());
            }
        }
        push_optional_value_arg(&mut cmd, &args, "psm", "--psm");
        push_optional_value_arg(&mut cmd, &args, "window_id", "--window-id");
        push_optional_value_arg(&mut cmd, &args, "pid", "--pid");
        push_optional_str_arg(&mut cmd, &args, "app_id", "--app-id");
        push_optional_str_arg(&mut cmd, &args, "title_hash", "--title-hash");
        push_optional_str_arg(&mut cmd, &args, "window_rect", "--window-rect");
        push_optional_str_arg(&mut cmd, &args, "task", "--task");
        push_optional_str_arg(&mut cmd, &args, "hint_text", "--hint-text");
        push_optional_str_arg(&mut cmd, &args, "hint_role", "--hint-role");
        push_optional_str_arg(&mut cmd, &args, "language", "--language");

        cmd.stdout(std::process::Stdio::piped());
        cmd.stderr(std::process::Stdio::piped());
        if let Some(cwd) = cwd {
            cmd.current_dir(cwd);
        }

        let started = Instant::now();
        let output =
            match tokio::time::timeout(Duration::from_millis(timeout_ms), cmd.output()).await {
                Err(_) => {
                    return Ok(vision_grounding_ocr_error(json!({
                        "code": "timeout",
                        "message": format!("vision_grounding_ocr exceeded {timeout_ms} ms"),
                        "duration_ms": started.elapsed().as_millis() as u64
                    })));
                }
                Ok(Err(e)) => {
                    return Ok(vision_grounding_ocr_error(json!({
                        "code": "spawn_failed",
                        "message": e.to_string(),
                        "duration_ms": started.elapsed().as_millis() as u64
                    })));
                }
                Ok(Ok(output)) => output,
            };
        let duration_ms = started.elapsed().as_millis() as u64;
        let (stdout, stdout_truncated) = lossy_truncate(&output.stdout);
        let (stderr, stderr_truncated) = lossy_truncate(&output.stderr);

        if !output.status.success() {
            return Ok(vision_grounding_ocr_error(json!({
                "code": "script_failed",
                "exit_code": output.status.code().unwrap_or(-1),
                "stdout": stdout,
                "stderr": stderr,
                "duration_ms": duration_ms,
                "truncated": stdout_truncated || stderr_truncated
            })));
        }

        match serde_json::from_str::<Value>(&stdout) {
            Ok(mut payload) => {
                if let Some(obj) = payload.as_object_mut() {
                    obj.insert(
                        "mcp_wrapper".to_string(),
                        json!({
                            "tool": self.name(),
                            "read_only": true,
                            "engine": engine,
                            "duration_ms": duration_ms,
                            "stderr": stderr,
                            "stderr_truncated": stderr_truncated
                        }),
                    );
                }
                Ok(ToolResult::json_text(&payload))
            }
            Err(e) => Ok(vision_grounding_ocr_error(json!({
                "code": "invalid_json",
                "message": e.to_string(),
                "stdout": stdout,
                "stderr": stderr,
                "duration_ms": duration_ms,
                "truncated": stdout_truncated || stderr_truncated
            }))),
        }
    }
}

fn required_str_arg(args: &Value, key: &str) -> std::result::Result<String, String> {
    match args.get(key).and_then(|v| v.as_str()) {
        Some(v) if !v.trim().is_empty() => Ok(v.to_string()),
        _ => Err(format!("missing or empty '{key}'")),
    }
}

fn push_optional_str_arg(cmd: &mut TokioCommand, args: &Value, key: &str, flag: &str) {
    if let Some(value) = args.get(key).and_then(|v| v.as_str()) {
        if !value.trim().is_empty() {
            cmd.arg(flag).arg(value);
        }
    }
}

fn push_optional_value_arg(cmd: &mut TokioCommand, args: &Value, key: &str, flag: &str) {
    if let Some(value) = args.get(key) {
        if let Some(n) = value.as_i64() {
            cmd.arg(flag).arg(n.to_string());
        } else if let Some(s) = value.as_str() {
            if !s.trim().is_empty() {
                cmd.arg(flag).arg(s);
            }
        }
    }
}

fn vision_grounding_ocr_script_path(args: &Value, cwd: Option<&PathBuf>) -> PathBuf {
    if let Some(path) = args.get("script_path").and_then(|v| v.as_str()) {
        return PathBuf::from(path);
    }
    if let Ok(path) = std::env::var("AGENT_BRIDGE_VISION_GROUNDING_OCR_SCRIPT") {
        if !path.trim().is_empty() {
            return PathBuf::from(path);
        }
    }
    if let Some(cwd) = cwd {
        let path = cwd.join("scripts/vision_grounding_ocr.py");
        if path.exists() {
            return path;
        }
    }
    if let Ok(cwd) = std::env::current_dir() {
        let path = cwd.join("scripts/vision_grounding_ocr.py");
        if path.exists() {
            return path;
        }
    }
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../scripts/vision_grounding_ocr.py")
}

fn vision_grounding_ocr_error(error: Value) -> ToolResult {
    let mut result = ToolResult::json_text(&json!({
        "schema": "vision_grounding_ocr_mcp_error.v0",
        "status": "error",
        "error": error,
    }));
    result.is_error = true;
    result
}

// ===========================================================================
//                              desktop_action
// ===========================================================================

pub struct DesktopActionTool {
    hub: Hub,
}

impl DesktopActionTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

#[async_trait]
impl McpTool for DesktopActionTool {
    fn name(&self) -> &'static str {
        "desktop_action"
    }

    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Gated Linux desktop input injection (ISOLATED-ONLY MVP). Wraps \
                 scripts/desktop_action.py. Safe by construction: this MCP surface NEVER \
                 touches the real host desktop. An action runs only as (a) dry_run=true \
                 (logs intent + audits, injects nothing), or (b) isolated — a nested \
                 compositor addressed by a non-host `display` plus its `swaysock`, where \
                 absolute moveto/click go through the sway-IPC backend (which itself \
                 refuses physical-output sockets). Host injection stays closed by default; \
                 set confirm_host:true to instead stage a single-use, TTL-bounded pending \
                 token (executed only by a subsequent human-approved desktop_confirm) — host \
                 injection never happens inline. Every call is audited to desktop_action_audit.jsonl."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "action": {
                        "type": "string",
                        "enum": ["type", "key", "move", "moveto", "click", "scroll"],
                        "description": "type/key need `text`; moveto needs x,y; move needs dx,dy; scroll needs dy[,dx]; click takes optional `button`."
                    },
                    "text": { "type": "string", "description": "For type (literal text) or key (keysym, e.g. Return, ctrl+c)." },
                    "x": { "type": "integer", "description": "Absolute X for moveto (nested compositor coords)." },
                    "y": { "type": "integer", "description": "Absolute Y for moveto." },
                    "dx": { "type": "integer", "description": "Relative X for move, or horizontal scroll." },
                    "dy": { "type": "integer", "description": "Relative Y for move, or vertical scroll." },
                    "button": { "type": "string", "enum": ["left", "right", "middle"], "default": "left", "description": "Mouse button for click." },
                    "display": { "type": "string", "description": "Target WAYLAND_DISPLAY. Must be a nested (non-host) display for any real injection." },
                    "swaysock": { "type": "string", "description": "Nested sway IPC socket; required (with a non-host display) for any non-dry-run injection. Enables the isolated sway-IPC absolute backend." },
                    "dry_run": { "type": "boolean", "default": false, "description": "When true, log intent + audit but inject nothing. Allowed against any target." },
                    "confirm_host": { "type": "boolean", "default": false, "description": "Host target only: do not inject; stage a single-use pending token + on-screen notify for a two-phase human-approved confirm (then call desktop_confirm). Default false keeps host injection closed." },
                    "use_grant": { "type": "boolean", "default": false, "description": "Host target only: inject directly IF a human-minted capability grant (scripts/desktop_grant.py) covers this action. Default false; no covering grant => denied. Trades per-action confirm for a bounded (ttl/max-uses/scope), revocable window (path C)." },
                    "cwd": { "type": "string", "description": "Repo root to resolve scripts/desktop_action.py." },
                    "script_path": { "type": "string", "description": "Explicit desktop_action.py path (tests / alternate checkouts)." },
                    "timeout_ms": { "type": "integer", "minimum": 1000, "maximum": 30000, "default": 10000, "description": "Milliseconds before the action process is killed." }
                },
                "required": ["action"]
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let action = match args.get("action").and_then(|v| v.as_str()) {
            Some(a) if ["type", "key", "move", "moveto", "click", "scroll"].contains(&a) => {
                a.to_string()
            }
            Some(a) => {
                return Ok(desktop_action_error(json!({
                    "code": "bad_action",
                    "message": format!("unknown action {a}")
                })));
            }
            None => {
                return Ok(desktop_action_error(json!({
                    "code": "missing_action",
                    "message": "`action` is required"
                })));
            }
        };
        let timeout_ms = args
            .get("timeout_ms")
            .and_then(|v| v.as_u64())
            .unwrap_or(10_000)
            .clamp(1_000, 30_000);
        let dry_run = args
            .get("dry_run")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let display = args.get("display").and_then(|v| v.as_str());
        let swaysock = args.get("swaysock").and_then(|v| v.as_str());

        // SAFETY (isolated-only MVP): this surface never touches the host desktop.
        // Allowed iff dry_run, or isolated = a non-host display WITH its swaysock.
        let host_display = std::env::var("AB_HOST_WAYLAND_DISPLAY")
            .ok()
            .filter(|s| !s.trim().is_empty())
            .unwrap_or_else(|| "wayland-1".to_string());
        let confirm_host = args
            .get("confirm_host")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let use_grant = args
            .get("use_grant")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let is_isolated = swaysock.map(|s| !s.is_empty()).unwrap_or(false)
            && display
                .map(|d| !d.is_empty() && d != host_display)
                .unwrap_or(false);
        // A host action is refused by default. Two opt-in host paths: confirm_host stages a
        // single-use pending token for a human-approved desktop_confirm (path A); use_grant
        // injects directly IF a human-minted capability grant covers it (path C). Neither
        // ever passes --confirm; host injection is never silent/inline.
        let host_target = !dry_run && !is_isolated;
        if host_target && !confirm_host && !use_grant {
            // Anti-laundering: a host action that the MCP refuses to inject did
            // NOT take effect — stamp it not_verified so it can never read as a
            // silent success on the event spine.
            record_desktop_action_event(
                &self.hub,
                &action,
                "refused",
                false,
                "host_mutation_not_exposed",
                json!({ "mode": "refused", "host_target": true }),
            )
            .await;
            return Ok(desktop_action_error(json!({
                "code": "host_mutation_not_exposed",
                "message": "this MCP injects only dry_run or isolated (non-host display + swaysock) \
                            actions; for a host action set confirm_host:true (two-phase confirm) or \
                            use_grant:true (a human-minted capability grant must cover it)",
                "hint": "set dry_run:true, provide a nested `display` (!= host) and its `swaysock`, \
                         set confirm_host:true, or set use_grant:true with a desktop_grant.py grant"
            })));
        }

        let need_text = matches!(action.as_str(), "type" | "key");
        let text = args.get("text").and_then(|v| v.as_str());
        if need_text && text.map(|t| t.is_empty()).unwrap_or(true) {
            return Ok(desktop_action_error(json!({
                "code": "missing_text",
                "message": format!("action {action} requires a non-empty `text`")
            })));
        }

        let cwd = args.get("cwd").and_then(|v| v.as_str()).map(PathBuf::from);
        let script = desktop_action_script_path(&args, cwd.as_ref());
        if !script.exists() {
            return Ok(desktop_action_error(json!({
                "code": "script_missing",
                "message": format!("desktop_action.py not found at {}", script.display()),
                "hint": "pass script_path or run from the Agent-Bridge repo root"
            })));
        }

        let mut cmd = killable_command(
            std::env::var("PYTHON")
                .ok()
                .filter(|s| !s.trim().is_empty())
                .unwrap_or_else(|| "python3".to_string()),
        );
        cmd.arg(&script).arg(&action);
        match action.as_str() {
            "type" | "key" => {
                cmd.arg(text.unwrap_or(""));
            }
            "moveto" => {
                let x = args.get("x").and_then(|v| v.as_i64()).unwrap_or(0);
                let y = args.get("y").and_then(|v| v.as_i64()).unwrap_or(0);
                cmd.arg(x.to_string()).arg(y.to_string());
            }
            "move" => {
                let dx = args.get("dx").and_then(|v| v.as_i64()).unwrap_or(0);
                let dy = args.get("dy").and_then(|v| v.as_i64()).unwrap_or(0);
                cmd.arg(dx.to_string()).arg(dy.to_string());
            }
            "scroll" => {
                let dy = args.get("dy").and_then(|v| v.as_i64()).unwrap_or(0);
                let dx = args.get("dx").and_then(|v| v.as_i64()).unwrap_or(0);
                cmd.arg(dy.to_string()).arg(dx.to_string());
            }
            "click" => {
                if let Some(btn) = args.get("button").and_then(|v| v.as_str()) {
                    cmd.arg(btn);
                }
            }
            _ => {}
        }
        if let Some(d) = display {
            cmd.arg("--display").arg(d);
        }
        if let Some(s) = swaysock {
            cmd.arg("--swaysock").arg(s);
        }
        if dry_run {
            cmd.arg("--dry-run");
        }
        if host_target && use_grant {
            // Path C: inject directly IF a human-minted capability grant covers it.
            cmd.arg("--use-grant");
        } else if host_target && confirm_host {
            // Path A phase 1: stage a pending token, inject NOTHING; execution waits for a
            // human-approved desktop_confirm(token).
            cmd.arg("--request-host-confirm");
        }
        // NOTE: --confirm / --i-understand-this-touches-the-real-desktop are NEVER passed by
        // this MCP surface. Host injection is reachable only via a human-approved confirm
        // token (path A) or a human-minted grant (path C), never silent/inline.
        cmd.stdout(std::process::Stdio::piped());
        cmd.stderr(std::process::Stdio::piped());
        if let Some(cwd) = cwd {
            cmd.current_dir(cwd);
        }

        let started = Instant::now();
        let output =
            match tokio::time::timeout(Duration::from_millis(timeout_ms), cmd.output()).await {
                Err(_) => {
                    return Ok(desktop_action_error(json!({
                        "code": "timeout",
                        "message": format!("desktop_action exceeded {timeout_ms} ms"),
                        "duration_ms": started.elapsed().as_millis() as u64
                    })));
                }
                Ok(Err(e)) => {
                    return Ok(desktop_action_error(json!({
                        "code": "spawn_failed",
                        "message": e.to_string(),
                        "duration_ms": started.elapsed().as_millis() as u64
                    })));
                }
                Ok(Ok(output)) => output,
            };
        let duration_ms = started.elapsed().as_millis() as u64;
        let (stdout, stdout_truncated) = lossy_truncate(&output.stdout);
        let (stderr, stderr_truncated) = lossy_truncate(&output.stderr);

        let mode = if dry_run {
            "dry-run"
        } else if !host_target {
            "isolated"
        } else if use_grant {
            "host-grant"
        } else {
            "pending-host-confirm"
        };
        let ok = output.status.success();
        // Capture the error text for the event before `stderr` is moved into the
        // mcp_wrapper payload below.
        let event_err = if ok { String::new() } else { stderr.clone() };

        // desktop_action.py prints a JSON record; nonzero exit = blocked/error.
        match serde_json::from_str::<Value>(&stdout) {
            Ok(mut payload) => {
                if let Some(obj) = payload.as_object_mut() {
                    obj.insert(
                        "mcp_wrapper".to_string(),
                        json!({
                            "tool": self.name(),
                            "read_only": false,
                            "mode": mode,
                            "host_protected": true,
                            "duration_ms": duration_ms,
                            "exit_code": output.status.code().unwrap_or(-1),
                            "stderr": stderr,
                            "stderr_truncated": stderr_truncated
                        }),
                    );
                }
                // SSB Phase-1 typed event spine: stamp the verify-first verdict
                // for this injection AT ACTION TIME (Unknown on success — no
                // readback; NotVerified on a failed/blocked injection).
                record_desktop_action_event(
                    &self.hub,
                    &action,
                    mode,
                    ok,
                    &event_err,
                    json!({ "mode": mode, "dry_run": dry_run, "exit_code": output.status.code().unwrap_or(-1) }),
                )
                .await;
                let mut result = ToolResult::json_text(&payload);
                if !ok {
                    result.is_error = true;
                }
                Ok(result)
            }
            Err(e) => Ok(desktop_action_error(json!({
                "code": "invalid_json",
                "message": e.to_string(),
                "stdout": stdout,
                "stderr": stderr,
                "exit_code": output.status.code().unwrap_or(-1),
                "duration_ms": duration_ms,
                "truncated": stdout_truncated || stderr_truncated
            }))),
        }
    }
}

fn desktop_action_script_path(args: &Value, cwd: Option<&PathBuf>) -> PathBuf {
    if let Some(path) = args.get("script_path").and_then(|v| v.as_str()) {
        return PathBuf::from(path);
    }
    if let Ok(path) = std::env::var("AGENT_BRIDGE_DESKTOP_ACTION_SCRIPT") {
        if !path.trim().is_empty() {
            return PathBuf::from(path);
        }
    }
    if let Some(cwd) = cwd {
        let path = cwd.join("scripts/desktop_action.py");
        if path.exists() {
            return path;
        }
    }
    if let Ok(cwd) = std::env::current_dir() {
        let path = cwd.join("scripts/desktop_action.py");
        if path.exists() {
            return path;
        }
    }
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../scripts/desktop_action.py")
}

fn desktop_action_error(error: Value) -> ToolResult {
    let mut result = ToolResult::json_text(&json!({
        "schema": "desktop_action_mcp_error.v0",
        "status": "error",
        "error": error,
    }));
    result.is_error = true;
    result
}

/// SSB Phase-1 typed event spine: emit a verify-first semantic event for a
/// `desktop_action` outcome AT ACTION TIME. Best-effort — a telemetry write must
/// never fail the action. The verdict records whether input was actually injected
/// without readback (Unknown), refused/failed (NotVerified — the anti-laundering
/// signal), or intentionally not injected in dry-run/pending modes (Unknown).
async fn record_desktop_action_event(
    hub: &Hub,
    action: &str,
    mode: &str,
    ok: bool,
    err_msg: &str,
    facts: Value,
) {
    if let Some(store) = &hub.store {
        let verdict = crate::semantic_event::classify_action(mode, ok, err_msg);
        // SSB unified contract: same Object/Affordance vocabulary as browser_click.
        // Risk tracks how close the mode gets to real host mutation.
        let risk_level = match mode {
            "dry-run" => "low",
            "isolated" => "medium",
            _ => "high", // host-grant / pending-host-confirm / refused
        };
        let object = crate::semantic_event::SemanticObject {
            object_type: "desktop_input_surface".to_string(),
            source_adapter: "desktop".to_string(),
            label: None,
            object_id: None,
        };
        let affordance = crate::semantic_event::Affordance {
            action_type: action.to_string(),
            risk_level: risk_level.to_string(),
            requires_gate: true,
            expected_effect: Some(format!("inject {action} into the {mode} target")),
        };
        let ev = crate::semantic_event::SemanticEvent {
            ts: dispatch_now_secs(),
            actor: "mcp".to_string(),
            source: "desktop".to_string(),
            action: action.to_string(),
            target: None,
            object,
            affordance,
            verdict,
            facts,
        };
        if let Err(e) = store.record_semantic_event(ev.to_record()).await {
            tracing::debug!(error = %e, "record_semantic_event (desktop_action) failed");
        }
    }
}

// ===========================================================================
//   Linux Computer Use — L2 semantic AT-SPI invoke (desktop_invoke)
// ===========================================================================

pub struct DesktopInvokeTool {
    _hub: Hub,
}

impl DesktopInvokeTool {
    pub fn new(hub: Hub) -> Self {
        Self { _hub: hub }
    }
}

#[async_trait]
impl McpTool for DesktopInvokeTool {
    fn name(&self) -> &'static str {
        "desktop_invoke"
    }

    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Gated Linux desktop SEMANTIC input via AT-SPI (ISOLATED-ONLY MVP). \
                 Wraps scripts/desktop_invoke.py. Finds an accessible by app/role/name and \
                 calls its AT-SPI action (e.g. a button's \"click\") — no screenshot, no OCR, \
                 no coordinates; the L2 dual of desktop_snapshot's bus-first read. Safe by \
                 construction: AT-SPI is a session-global bus, so isolation is by PROCESS — an \
                 invoke runs only as (a) dry_run=true (locates + audits, invokes nothing), or \
                 (b) isolated — `cage_pid` set to a nested compositor whose process subtree owns \
                 the target accessible. Host-app invoke stays closed by default; set \
                 confirm_host:true to instead mint a single-use, TTL-bounded pending token \
                 (executed only by a subsequent human-approved desktop_confirm) — host mutation \
                 never happens inline. Every call is audited to desktop_invoke_audit.jsonl."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "app": { "type": "string", "description": "Application name substring (e.g. 'firefox')." },
                    "role": { "type": "string", "description": "AT-SPI role-name substring (e.g. 'button', 'menu item'). Note GTK buttons report 'button', not 'push button'." },
                    "name": { "type": "string", "description": "Accessible name/label substring (e.g. 'Save')." },
                    "nth": { "type": "integer", "minimum": 0, "default": 0, "description": "Which match if several (0-based)." },
                    "action": { "type": "string", "description": "AT-SPI action name to invoke; default auto-picks click/press/activate/first." },
                    "cage_pid": { "type": "integer", "description": "Nested compositor PID; the target accessible's app PID must be its descendant for an isolated (non-dry-run) invoke." },
                    "wait": { "type": "number", "minimum": 0, "maximum": 30, "default": 4.0, "description": "Seconds to poll for the accessible to appear (a11y subtree can lag app registration)." },
                    "dry_run": { "type": "boolean", "default": false, "description": "When true, locate + log intent but invoke nothing. Allowed against any target." },
                    "confirm_host": { "type": "boolean", "default": false, "description": "Host target only: do not invoke; mint a single-use pending token + on-screen notify for a two-phase human-approved confirm (then call desktop_confirm). Default false keeps host invoke closed." },
                    "use_grant": { "type": "boolean", "default": false, "description": "Host target only: invoke directly IF a human-minted capability grant (scripts/desktop_grant.py) covers this app/action. Default false; no covering grant => denied. Trades per-action confirm for a bounded (ttl/max-uses/scope), revocable window (path C)." },
                    "cwd": { "type": "string", "description": "Repo root to resolve scripts/desktop_invoke.py." },
                    "script_path": { "type": "string", "description": "Explicit desktop_invoke.py path (tests / alternate checkouts)." },
                    "timeout_ms": { "type": "integer", "minimum": 1000, "maximum": 30000, "default": 10000, "description": "Milliseconds before the invoke process is killed." }
                }
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let app = args.get("app").and_then(|v| v.as_str());
        let role = args.get("role").and_then(|v| v.as_str());
        let name = args.get("name").and_then(|v| v.as_str());
        if app.map(|s| s.is_empty()).unwrap_or(true)
            && role.map(|s| s.is_empty()).unwrap_or(true)
            && name.map(|s| s.is_empty()).unwrap_or(true)
        {
            return Ok(desktop_invoke_error(json!({
                "code": "missing_selector",
                "message": "at least one of `app`, `role`, or `name` is required"
            })));
        }
        let timeout_ms = args
            .get("timeout_ms")
            .and_then(|v| v.as_u64())
            .unwrap_or(10_000)
            .clamp(1_000, 30_000);
        let dry_run = args
            .get("dry_run")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let cage_pid = args
            .get("cage_pid")
            .and_then(|v| v.as_i64())
            .filter(|p| *p > 0);

        // SAFETY: inline invoke is allowed iff dry_run or isolated (cage_pid). A host
        // target is refused by default; with confirm_host the call does NOT invoke — it
        // mints a single-use pending token for a separate human-approved desktop_confirm
        // (two-phase host-confirm path A). Host mutation never happens inline here.
        let confirm_host = args
            .get("confirm_host")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let use_grant = args
            .get("use_grant")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let is_isolated = cage_pid.is_some();
        // Host invoke is refused by default. Two opt-in host paths: confirm_host stages a
        // single-use pending token for a human-approved desktop_confirm (path A); use_grant
        // invokes directly IF a human-minted capability grant covers it (path C). Neither
        // passes --confirm; host mutation is never silent/inline.
        let host_target = !dry_run && !is_isolated;
        if host_target && !confirm_host && !use_grant {
            return Ok(desktop_invoke_error(json!({
                "code": "host_invoke_not_exposed",
                "message": "this MCP invokes only dry_run or isolated (cage_pid) targets; \
                            for a host target set confirm_host:true (two-phase confirm) or \
                            use_grant:true (a human-minted capability grant must cover it)",
                "hint": "set dry_run:true, provide `cage_pid`, set confirm_host:true, or set use_grant:true with a desktop_grant.py grant"
            })));
        }

        let cwd = args.get("cwd").and_then(|v| v.as_str()).map(PathBuf::from);
        let script = desktop_invoke_script_path(&args, cwd.as_ref());
        if !script.exists() {
            return Ok(desktop_invoke_error(json!({
                "code": "script_missing",
                "message": format!("desktop_invoke.py not found at {}", script.display()),
                "hint": "pass script_path or run from the Agent-Bridge repo root"
            })));
        }

        let mut cmd = killable_command(
            std::env::var("PYTHON")
                .ok()
                .filter(|s| !s.trim().is_empty())
                .unwrap_or_else(|| "python3".to_string()),
        );
        cmd.arg(&script);
        if let Some(v) = app {
            if !v.is_empty() {
                cmd.arg("--app").arg(v);
            }
        }
        if let Some(v) = role {
            if !v.is_empty() {
                cmd.arg("--role").arg(v);
            }
        }
        if let Some(v) = name {
            if !v.is_empty() {
                cmd.arg("--name").arg(v);
            }
        }
        if let Some(n) = args.get("nth").and_then(|v| v.as_i64()) {
            cmd.arg("--nth").arg(n.to_string());
        }
        if let Some(a) = args.get("action").and_then(|v| v.as_str()) {
            if !a.is_empty() {
                cmd.arg("--action").arg(a);
            }
        }
        if let Some(w) = args.get("wait").and_then(|v| v.as_f64()) {
            cmd.arg("--wait").arg(format!("{w}"));
        }
        if let Some(p) = cage_pid {
            cmd.arg("--cage-pid").arg(p.to_string());
        }
        if dry_run {
            cmd.arg("--dry-run");
        }
        if host_target && use_grant {
            // Path C: invoke directly IF a human-minted capability grant covers it.
            cmd.arg("--use-grant");
        } else if host_target && confirm_host {
            // Path A phase 1: mint a pending token, invoke NOTHING; execution waits for a
            // human-approved desktop_confirm(token).
            cmd.arg("--request-host-confirm");
        }
        // NOTE: --confirm / --i-understand-this-touches-the-real-desktop are NEVER passed by
        // this MCP surface. Host mutation is reachable only via a human-approved confirm
        // token (path A) or a human-minted grant (path C), never silent/inline.
        cmd.stdout(std::process::Stdio::piped());
        cmd.stderr(std::process::Stdio::piped());
        if let Some(cwd) = cwd {
            cmd.current_dir(cwd);
        }

        let started = Instant::now();
        let output =
            match tokio::time::timeout(Duration::from_millis(timeout_ms), cmd.output()).await {
                Err(_) => {
                    return Ok(desktop_invoke_error(json!({
                        "code": "timeout",
                        "message": format!("desktop_invoke exceeded {timeout_ms} ms"),
                        "duration_ms": started.elapsed().as_millis() as u64
                    })));
                }
                Ok(Err(e)) => {
                    return Ok(desktop_invoke_error(json!({
                        "code": "spawn_failed",
                        "message": e.to_string(),
                        "duration_ms": started.elapsed().as_millis() as u64
                    })));
                }
                Ok(Ok(output)) => output,
            };
        let duration_ms = started.elapsed().as_millis() as u64;
        let (stdout, stdout_truncated) = lossy_truncate(&output.stdout);
        let (stderr, stderr_truncated) = lossy_truncate(&output.stderr);

        match serde_json::from_str::<Value>(&stdout) {
            Ok(mut payload) => {
                if let Some(obj) = payload.as_object_mut() {
                    obj.insert(
                        "mcp_wrapper".to_string(),
                        json!({
                            "tool": self.name(),
                            "read_only": false,
                            "mode": if dry_run { "dry-run" } else if !host_target { "isolated" } else if use_grant { "host-grant" } else { "pending-host-confirm" },
                            "host_protected": true,
                            "duration_ms": duration_ms,
                            "exit_code": output.status.code().unwrap_or(-1),
                            "stderr": stderr,
                            "stderr_truncated": stderr_truncated
                        }),
                    );
                }
                let mut result = ToolResult::json_text(&payload);
                if !output.status.success() {
                    result.is_error = true;
                }
                Ok(result)
            }
            Err(e) => Ok(desktop_invoke_error(json!({
                "code": "invalid_json",
                "message": e.to_string(),
                "stdout": stdout,
                "stderr": stderr,
                "exit_code": output.status.code().unwrap_or(-1),
                "duration_ms": duration_ms,
                "truncated": stdout_truncated || stderr_truncated
            }))),
        }
    }
}

fn desktop_invoke_script_path(args: &Value, cwd: Option<&PathBuf>) -> PathBuf {
    if let Some(path) = args.get("script_path").and_then(|v| v.as_str()) {
        return PathBuf::from(path);
    }
    if let Ok(path) = std::env::var("AGENT_BRIDGE_DESKTOP_INVOKE_SCRIPT") {
        if !path.trim().is_empty() {
            return PathBuf::from(path);
        }
    }
    if let Some(cwd) = cwd {
        let path = cwd.join("scripts/desktop_invoke.py");
        if path.exists() {
            return path;
        }
    }
    if let Ok(cwd) = std::env::current_dir() {
        let path = cwd.join("scripts/desktop_invoke.py");
        if path.exists() {
            return path;
        }
    }
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../scripts/desktop_invoke.py")
}

/// Resolve scripts/desktop_steer.py — the blessed phase-2 executor for `kind=steer`
/// pendings (cross-process tmux injection). Mirrors desktop_{action,invoke}_script_path:
/// explicit `script_path` arg > AGENT_BRIDGE_DESKTOP_STEER_SCRIPT env > cwd/scripts >
/// current_dir/scripts > compile-time repo fallback.
fn desktop_steer_script_path(args: &Value, cwd: Option<&PathBuf>) -> PathBuf {
    if let Some(path) = args.get("script_path").and_then(|v| v.as_str()) {
        return PathBuf::from(path);
    }
    if let Ok(path) = std::env::var("AGENT_BRIDGE_DESKTOP_STEER_SCRIPT") {
        if !path.trim().is_empty() {
            return PathBuf::from(path);
        }
    }
    if let Some(cwd) = cwd {
        let path = cwd.join("scripts/desktop_steer.py");
        if path.exists() {
            return path;
        }
    }
    if let Ok(cwd) = std::env::current_dir() {
        let path = cwd.join("scripts/desktop_steer.py");
        if path.exists() {
            return path;
        }
    }
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../scripts/desktop_steer.py")
}

fn desktop_invoke_error(error: Value) -> ToolResult {
    let mut result = ToolResult::json_text(&json!({
        "schema": "desktop_invoke_mcp_error.v0",
        "status": "error",
        "error": error,
    }));
    result.is_error = true;
    result
}

/// Read a pending host-confirm record's `kind` ("invoke" | "action" | "steer") WITHOUT
/// consuming it, so desktop_confirm can dispatch to the right backend script. Token must be
/// hex (path safety); returns None if malformed, missing, or unreadable (caller defaults to
/// the invoke backend, which then reports "no such pending token").
fn desktop_pending_kind(token: &str) -> Option<String> {
    if token.is_empty() || !token.chars().all(|c| c.is_ascii_hexdigit()) {
        return None;
    }
    let cache = std::env::var("XDG_CACHE_HOME")
        .ok()
        .filter(|s| !s.trim().is_empty())
        .unwrap_or_else(|| {
            format!(
                "{}/.cache",
                std::env::var("HOME").unwrap_or_else(|_| ".".to_string())
            )
        });
    let path = format!("{cache}/agent-bridge/desktop_pending/{token}.json");
    let txt = std::fs::read_to_string(path).ok()?;
    let v: Value = serde_json::from_str(&txt).ok()?;
    v.get("kind").and_then(|k| k.as_str()).map(str::to_string)
}

/// Phase 2 of the host-confirm path: execute a host action a human approved.
///
/// `desktop_invoke`/`desktop_action` with `confirm_host:true` mint a single-use,
/// TTL-bounded pending token (and an on-screen notify); they act on NOTHING. This tool
/// takes that token and executes the pending host action — the only way host mutation
/// reaches the real desktop through MCP. It dispatches by the record's kind (invoke ->
/// desktop_invoke.py, action -> desktop_action.py, steer -> desktop_steer.py cross-process
/// tmux injection); the backend validates the token (exists, unconsumed, unexpired) and
/// marks it consumed before acting, so it runs once.
pub struct DesktopConfirmTool {
    _hub: Hub,
}

impl DesktopConfirmTool {
    pub fn new(hub: Hub) -> Self {
        Self { _hub: hub }
    }
}

#[async_trait]
impl McpTool for DesktopConfirmTool {
    fn name(&self) -> &'static str {
        "desktop_confirm"
    }

    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Execute a host desktop action previously staged by \
                 desktop_invoke(confirm_host:true). Pass the single-use `token` it minted; \
                 the backend re-resolves the stored selector and invokes it once (the token \
                 is validated + consumed first). This is the ONLY path by which an MCP-driven \
                 invoke touches the REAL desktop, and only after a human approved the pending \
                 summary. Audited to desktop_invoke_audit.jsonl (phase=confirm)."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "token": { "type": "string", "description": "The single-use token minted by desktop_invoke or desktop_action with confirm_host:true. desktop_confirm dispatches to the right backend by the token's kind." },
                    "wait": { "type": "number", "minimum": 0, "maximum": 30, "default": 4.0, "description": "Seconds to poll for the accessible to reappear before invoking." },
                    "cwd": { "type": "string", "description": "Repo root to resolve scripts/desktop_invoke.py." },
                    "script_path": { "type": "string", "description": "Explicit desktop_invoke.py path (tests / alternate checkouts)." },
                    "timeout_ms": { "type": "integer", "minimum": 1000, "maximum": 30000, "default": 10000, "description": "Milliseconds before the confirm process is killed." }
                },
                "required": ["token"]
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let token = args.get("token").and_then(|v| v.as_str()).unwrap_or("");
        if token.is_empty() {
            return Ok(desktop_invoke_error(json!({
                "code": "missing_token",
                "message": "`token` is required (minted by desktop_invoke/desktop_action with confirm_host:true)"
            })));
        }
        let timeout_ms = args
            .get("timeout_ms")
            .and_then(|v| v.as_u64())
            .unwrap_or(10_000)
            .clamp(1_000, 30_000);

        let cwd = args.get("cwd").and_then(|v| v.as_str()).map(PathBuf::from);
        // Dispatch to the right backend by the pending record's kind: "action" ->
        // desktop_action.py (coordinate click), "steer" -> desktop_steer.py (cross-process
        // tmux injection), otherwise desktop_invoke.py (AT-SPI doAction). All three share the
        // single-use --confirm-token contract (validate + consume before acting).
        let script = match desktop_pending_kind(token).as_deref() {
            Some("action") => desktop_action_script_path(&args, cwd.as_ref()),
            Some("steer") => desktop_steer_script_path(&args, cwd.as_ref()),
            _ => desktop_invoke_script_path(&args, cwd.as_ref()),
        };
        if !script.exists() {
            return Ok(desktop_invoke_error(json!({
                "code": "script_missing",
                "message": format!("backend confirm script not found at {}", script.display()),
                "hint": "pass script_path or run from the Agent-Bridge repo root"
            })));
        }

        let mut cmd = killable_command(
            std::env::var("PYTHON")
                .ok()
                .filter(|s| !s.trim().is_empty())
                .unwrap_or_else(|| "python3".to_string()),
        );
        cmd.arg(&script).arg("--confirm-token").arg(token);
        if let Some(w) = args.get("wait").and_then(|v| v.as_f64()) {
            cmd.arg("--wait").arg(format!("{w}"));
        }
        cmd.stdout(std::process::Stdio::piped());
        cmd.stderr(std::process::Stdio::piped());
        if let Some(cwd) = cwd {
            cmd.current_dir(cwd);
        }

        let started = Instant::now();
        let output =
            match tokio::time::timeout(Duration::from_millis(timeout_ms), cmd.output()).await {
                Err(_) => {
                    return Ok(desktop_invoke_error(json!({
                        "code": "timeout",
                        "message": format!("desktop_confirm exceeded {timeout_ms} ms"),
                        "duration_ms": started.elapsed().as_millis() as u64
                    })));
                }
                Ok(Err(e)) => {
                    return Ok(desktop_invoke_error(json!({
                        "code": "spawn_failed",
                        "message": e.to_string(),
                        "duration_ms": started.elapsed().as_millis() as u64
                    })));
                }
                Ok(Ok(output)) => output,
            };
        let duration_ms = started.elapsed().as_millis() as u64;
        let (stdout, stdout_truncated) = lossy_truncate(&output.stdout);
        let (stderr, stderr_truncated) = lossy_truncate(&output.stderr);

        match serde_json::from_str::<Value>(&stdout) {
            Ok(mut payload) => {
                if let Some(obj) = payload.as_object_mut() {
                    obj.insert(
                        "mcp_wrapper".to_string(),
                        json!({
                            "tool": self.name(),
                            "read_only": false,
                            "mode": "host-confirm-phase2",
                            "host_protected": true,
                            "duration_ms": duration_ms,
                            "exit_code": output.status.code().unwrap_or(-1),
                            "stderr": stderr,
                            "stderr_truncated": stderr_truncated
                        }),
                    );
                }
                let mut result = ToolResult::json_text(&payload);
                if !output.status.success() {
                    result.is_error = true;
                }
                Ok(result)
            }
            Err(e) => Ok(desktop_invoke_error(json!({
                "code": "invalid_json",
                "message": e.to_string(),
                "stdout": stdout,
                "stderr": stderr,
                "exit_code": output.status.code().unwrap_or(-1),
                "duration_ms": duration_ms,
                "truncated": stdout_truncated || stderr_truncated
            }))),
        }
    }
}

// ===========================================================================
//                        mobile / Android ADB tools
// ===========================================================================

const MOBILE_UI_DUMP_PATH: &str = "/sdcard/agent_bridge_window.xml";
const MOBILE_DEFAULT_TIMEOUT_MS: u64 = 30_000;

#[derive(Debug, Clone)]
struct AdbCommandOutput {
    exit_code: i32,
    stdout: String,
    stderr: String,
    duration_ms: u64,
    truncated: bool,
}

impl AdbCommandOutput {
    fn ok(&self) -> bool {
        self.exit_code == 0
    }

    fn as_json(&self) -> Value {
        json!({
            "exit_code": self.exit_code,
            "stdout": self.stdout,
            "stderr": self.stderr,
            "duration_ms": self.duration_ms,
            "truncated": self.truncated,
        })
    }
}

#[derive(Debug, Clone)]
struct AdbBinaryOutput {
    exit_code: i32,
    stdout: Vec<u8>,
    stderr: String,
    duration_ms: u64,
    stderr_truncated: bool,
}

impl AdbBinaryOutput {
    fn ok(&self) -> bool {
        self.exit_code == 0
    }

    fn as_json(&self) -> Value {
        json!({
            "exit_code": self.exit_code,
            "stdout_bytes": self.stdout.len(),
            "stderr": self.stderr,
            "duration_ms": self.duration_ms,
            "stderr_truncated": self.stderr_truncated,
        })
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct MobileDevice {
    serial: String,
    state: String,
    attrs: HashMap<String, String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct MobileBounds {
    left: i64,
    top: i64,
    right: i64,
    bottom: i64,
}

impl MobileBounds {
    fn center(self) -> (i64, i64) {
        ((self.left + self.right) / 2, (self.top + self.bottom) / 2)
    }

    fn as_json(self) -> Value {
        let (x, y) = self.center();
        json!({
            "left": self.left,
            "top": self.top,
            "right": self.right,
            "bottom": self.bottom,
            "center": { "x": x, "y": y },
        })
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct MobileUiNode {
    ordinal: usize,
    index: String,
    text: String,
    resource_id: String,
    class_name: String,
    package_name: String,
    content_desc: String,
    clickable: bool,
    enabled: bool,
    focusable: bool,
    focused: bool,
    scrollable: bool,
    bounds: Option<MobileBounds>,
}

impl MobileUiNode {
    fn has_semantic_label(&self) -> bool {
        !self.text.is_empty() || !self.resource_id.is_empty() || !self.content_desc.is_empty()
    }

    fn is_actionable(&self) -> bool {
        self.clickable || self.focusable || self.scrollable || self.has_semantic_label()
    }

    fn is_surface_view(&self) -> bool {
        self.class_name == "android.view.SurfaceView"
    }

    fn compact_json(&self) -> Value {
        let mut obj = Map::new();
        obj.insert("ordinal".into(), json!(self.ordinal));
        if !self.index.is_empty() {
            obj.insert("index".into(), json!(self.index));
        }
        if !self.text.is_empty() {
            obj.insert("text".into(), json!(self.text));
        }
        if !self.resource_id.is_empty() {
            obj.insert("resource_id".into(), json!(self.resource_id));
        }
        if !self.class_name.is_empty() {
            obj.insert("class".into(), json!(self.class_name));
        }
        if !self.package_name.is_empty() {
            obj.insert("package".into(), json!(self.package_name));
        }
        if !self.content_desc.is_empty() {
            obj.insert("content_desc".into(), json!(self.content_desc));
        }
        if self.clickable {
            obj.insert("clickable".into(), json!(true));
        }
        if self.focusable {
            obj.insert("focusable".into(), json!(true));
        }
        if self.focused {
            obj.insert("focused".into(), json!(true));
        }
        if self.scrollable {
            obj.insert("scrollable".into(), json!(true));
        }
        obj.insert("enabled".into(), json!(self.enabled));
        if let Some(bounds) = self.bounds {
            obj.insert("bounds".into(), bounds.as_json());
        }
        Value::Object(obj)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct MobileUiAnalysis {
    node_count: usize,
    semantic_node_count: usize,
    actionable_node_count: usize,
    surface_view_count: usize,
    focused_surface_view_count: usize,
    semantic_nodes: bool,
    canvas_only: bool,
    surface_dominated: bool,
}

impl MobileUiAnalysis {
    fn from_nodes(nodes: &[MobileUiNode]) -> Self {
        let semantic_node_count = nodes.iter().filter(|n| n.has_semantic_label()).count();
        let actionable_node_count = nodes.iter().filter(|n| n.is_actionable()).count();
        let surface_view_count = nodes.iter().filter(|n| n.is_surface_view()).count();
        let focused_surface_view_count = nodes
            .iter()
            .filter(|n| n.is_surface_view() && n.focused)
            .count();
        let semantic_nodes = semantic_node_count > 0;
        let canvas_only = surface_view_count > 0 && !semantic_nodes;
        let surface_dominated = surface_view_count > 0 && semantic_node_count <= 2;
        Self {
            node_count: nodes.len(),
            semantic_node_count,
            actionable_node_count,
            surface_view_count,
            focused_surface_view_count,
            semantic_nodes,
            canvas_only,
            surface_dominated,
        }
    }

    fn as_json(self) -> Value {
        json!({
            "node_count": self.node_count,
            "semantic_node_count": self.semantic_node_count,
            "actionable_node_count": self.actionable_node_count,
            "surface_view_count": self.surface_view_count,
            "focused_surface_view_count": self.focused_surface_view_count,
            "semantic_nodes": self.semantic_nodes,
            "canvas_only": self.canvas_only,
            "surface_dominated": self.surface_dominated,
            "hint": if self.canvas_only {
                "UIAutomator sees a SurfaceView/canvas shell but no semantic child controls; use screenshot or engine-side hooks for in-canvas targets."
            } else if self.surface_dominated {
                "UIAutomator sees a SurfaceView/canvas app with limited semantic overlays; selector actions may only work for native overlays."
            } else {
                "UIAutomator exposes semantic nodes; prefer selectors over coordinates when possible."
            },
        })
    }
}

#[derive(Debug, Clone, Default)]
struct MobileSelector {
    text: Option<String>,
    text_contains: Option<String>,
    resource_id: Option<String>,
    content_desc: Option<String>,
    class_name: Option<String>,
    package_name: Option<String>,
    clickable: Option<bool>,
    focused: Option<bool>,
    enabled: Option<bool>,
}

impl MobileSelector {
    fn from_value(value: &Value) -> std::result::Result<Self, String> {
        let Some(obj) = value.as_object() else {
            return Err("'selector' must be an object".to_string());
        };
        let selector = Self {
            text: obj
                .get("text")
                .and_then(|v| v.as_str())
                .filter(|s| !s.is_empty())
                .map(str::to_string),
            text_contains: obj
                .get("text_contains")
                .and_then(|v| v.as_str())
                .filter(|s| !s.is_empty())
                .map(str::to_string),
            resource_id: obj
                .get("resource_id")
                .or_else(|| obj.get("resource-id"))
                .and_then(|v| v.as_str())
                .filter(|s| !s.is_empty())
                .map(str::to_string),
            content_desc: obj
                .get("content_desc")
                .or_else(|| obj.get("content-desc"))
                .and_then(|v| v.as_str())
                .filter(|s| !s.is_empty())
                .map(str::to_string),
            class_name: obj
                .get("class")
                .or_else(|| obj.get("class_name"))
                .and_then(|v| v.as_str())
                .filter(|s| !s.is_empty())
                .map(str::to_string),
            package_name: obj
                .get("package")
                .or_else(|| obj.get("package_name"))
                .and_then(|v| v.as_str())
                .filter(|s| !s.is_empty())
                .map(str::to_string),
            clickable: obj.get("clickable").and_then(|v| v.as_bool()),
            focused: obj.get("focused").and_then(|v| v.as_bool()),
            enabled: obj.get("enabled").and_then(|v| v.as_bool()),
        };
        if selector.is_empty() {
            return Err("selector must include at least one matching field".to_string());
        }
        Ok(selector)
    }

    fn is_empty(&self) -> bool {
        self.text.is_none()
            && self.text_contains.is_none()
            && self.resource_id.is_none()
            && self.content_desc.is_none()
            && self.class_name.is_none()
            && self.package_name.is_none()
            && self.clickable.is_none()
            && self.focused.is_none()
            && self.enabled.is_none()
    }

    fn matches(&self, node: &MobileUiNode) -> bool {
        if let Some(expected) = &self.text {
            if &node.text != expected {
                return false;
            }
        }
        if let Some(expected) = &self.text_contains {
            if !node.text.contains(expected) {
                return false;
            }
        }
        if let Some(expected) = &self.resource_id {
            if &node.resource_id != expected {
                return false;
            }
        }
        if let Some(expected) = &self.content_desc {
            if &node.content_desc != expected {
                return false;
            }
        }
        if let Some(expected) = &self.class_name {
            if &node.class_name != expected {
                return false;
            }
        }
        if let Some(expected) = &self.package_name {
            if &node.package_name != expected {
                return false;
            }
        }
        if let Some(expected) = self.clickable {
            if node.clickable != expected {
                return false;
            }
        }
        if let Some(expected) = self.focused {
            if node.focused != expected {
                return false;
            }
        }
        if let Some(expected) = self.enabled {
            if node.enabled != expected {
                return false;
            }
        }
        true
    }
}

fn mobile_schema_serial() -> Value {
    json!({
        "type": "string",
        "description": "ADB serial. Required when multiple online devices are connected."
    })
}

fn mobile_schema_selector() -> Value {
    json!({
        "type": "object",
        "description": "UI Automator node selector. All supplied fields must match.",
        "properties": {
            "text": { "type": "string" },
            "text_contains": { "type": "string" },
            "resource_id": { "type": "string" },
            "resource-id": { "type": "string" },
            "content_desc": { "type": "string" },
            "content-desc": { "type": "string" },
            "class": { "type": "string" },
            "package": { "type": "string" },
            "clickable": { "type": "boolean" },
            "focused": { "type": "boolean" },
            "enabled": { "type": "boolean" }
        }
    })
}

fn adb_args(parts: &[&str]) -> Vec<String> {
    parts.iter().map(|s| (*s).to_string()).collect()
}

fn mobile_timeout_ms(args: &Value) -> u64 {
    args.get("timeout_ms")
        .and_then(|v| v.as_u64())
        .unwrap_or(MOBILE_DEFAULT_TIMEOUT_MS)
        .clamp(1_000, 120_000)
}

fn resolve_adb_bin() -> String {
    if let Ok(v) = std::env::var("AGENT_BRIDGE_ADB") {
        if !v.trim().is_empty() {
            return v;
        }
    }
    if let Ok(v) = std::env::var("ADB") {
        if !v.trim().is_empty() {
            return v;
        }
    }
    if let Ok(home) = std::env::var("ANDROID_HOME") {
        let candidate = PathBuf::from(home).join("platform-tools").join("adb");
        if candidate.exists() {
            return candidate.to_string_lossy().into_owned();
        }
    }
    for candidate in [
        "/opt/homebrew/share/android-commandlinetools/platform-tools/adb",
        "/opt/homebrew/bin/adb",
        "/usr/local/bin/adb",
    ] {
        if PathBuf::from(candidate).exists() {
            return candidate.to_string();
        }
    }
    "adb".to_string()
}

async fn run_adb_command(
    serial: Option<&str>,
    args: &[String],
    timeout_ms: u64,
) -> std::result::Result<AdbCommandOutput, String> {
    let mut cmd = killable_command(resolve_adb_bin());
    if let Some(serial) = serial.filter(|s| !s.trim().is_empty()) {
        cmd.arg("-s").arg(serial);
    }
    cmd.args(args);
    cmd.stdin(std::process::Stdio::null());
    cmd.stdout(std::process::Stdio::piped());
    cmd.stderr(std::process::Stdio::piped());

    let started = Instant::now();
    let out = tokio::time::timeout(Duration::from_millis(timeout_ms), cmd.output()).await;
    let duration_ms = started.elapsed().as_millis() as u64;
    let output = match out {
        Ok(Ok(output)) => output,
        Ok(Err(e)) => return Err(format!("spawn adb failed: {e}")),
        Err(_) => {
            return Ok(AdbCommandOutput {
                exit_code: -1,
                stdout: String::new(),
                stderr: format!("killed after {timeout_ms} ms timeout"),
                duration_ms,
                truncated: false,
            });
        }
    };
    let (stdout, stdout_truncated) = lossy_truncate(&output.stdout);
    let (stderr, stderr_truncated) = lossy_truncate(&output.stderr);
    Ok(AdbCommandOutput {
        exit_code: output.status.code().unwrap_or(-1),
        stdout,
        stderr,
        duration_ms,
        truncated: stdout_truncated || stderr_truncated,
    })
}

async fn run_adb_binary_command(
    serial: Option<&str>,
    args: &[String],
    timeout_ms: u64,
) -> std::result::Result<AdbBinaryOutput, String> {
    let mut cmd = killable_command(resolve_adb_bin());
    if let Some(serial) = serial.filter(|s| !s.trim().is_empty()) {
        cmd.arg("-s").arg(serial);
    }
    cmd.args(args);
    cmd.stdin(std::process::Stdio::null());
    cmd.stdout(std::process::Stdio::piped());
    cmd.stderr(std::process::Stdio::piped());

    let started = Instant::now();
    let out = tokio::time::timeout(Duration::from_millis(timeout_ms), cmd.output()).await;
    let duration_ms = started.elapsed().as_millis() as u64;
    let output = match out {
        Ok(Ok(output)) => output,
        Ok(Err(e)) => return Err(format!("spawn adb failed: {e}")),
        Err(_) => {
            return Ok(AdbBinaryOutput {
                exit_code: -1,
                stdout: Vec::new(),
                stderr: format!("killed after {timeout_ms} ms timeout"),
                duration_ms,
                stderr_truncated: false,
            });
        }
    };
    let (stderr, stderr_truncated) = lossy_truncate(&output.stderr);
    Ok(AdbBinaryOutput {
        exit_code: output.status.code().unwrap_or(-1),
        stdout: output.stdout,
        stderr,
        duration_ms,
        stderr_truncated,
    })
}

fn parse_adb_devices(stdout: &str) -> Vec<MobileDevice> {
    stdout
        .lines()
        .filter_map(|line| {
            let line = line.trim();
            if line.is_empty() || line.starts_with("List of devices") {
                return None;
            }
            let mut parts = line.split_whitespace();
            let serial = parts.next()?.to_string();
            let state = parts.next()?.to_string();
            let attrs = parts
                .filter_map(|part| {
                    let (k, v) = part.split_once(':')?;
                    Some((k.to_string(), v.to_string()))
                })
                .collect();
            Some(MobileDevice {
                serial,
                state,
                attrs,
            })
        })
        .collect()
}

fn mobile_device_json(device: &MobileDevice, android_version: Option<String>) -> Value {
    let mut obj = Map::new();
    obj.insert("serial".into(), json!(device.serial));
    obj.insert("state".into(), json!(device.state));
    for (k, v) in &device.attrs {
        obj.insert(k.clone(), json!(v));
    }
    if let Some(version) = android_version.filter(|s| !s.is_empty()) {
        obj.insert("android_version".into(), json!(version));
    }
    Value::Object(obj)
}

async fn mobile_online_devices(timeout_ms: u64) -> std::result::Result<Vec<MobileDevice>, String> {
    let out = run_adb_command(None, &adb_args(&["devices", "-l"]), timeout_ms).await?;
    if !out.ok() {
        return Err(format!("adb devices failed: {}", out.stderr.trim()));
    }
    Ok(parse_adb_devices(&out.stdout)
        .into_iter()
        .filter(|d| d.state == "device")
        .collect())
}

async fn resolve_mobile_serial(
    args: &Value,
    timeout_ms: u64,
) -> std::result::Result<String, String> {
    if let Some(serial) = args
        .get("serial")
        .and_then(|v| v.as_str())
        .filter(|s| !s.trim().is_empty())
    {
        return Ok(serial.to_string());
    }
    let devices = mobile_online_devices(timeout_ms).await?;
    match devices.len() {
        0 => Err("no online ADB devices found".to_string()),
        1 => Ok(devices[0].serial.clone()),
        _ => Err(format!(
            "multiple online devices found; pass serial (available: {})",
            devices
                .iter()
                .map(|d| d.serial.as_str())
                .collect::<Vec<_>>()
                .join(", ")
        )),
    }
}

async fn mobile_getprop(serial: &str, prop: &str, timeout_ms: u64) -> Option<String> {
    let args = vec!["shell".to_string(), "getprop".to_string(), prop.to_string()];
    let out = run_adb_command(Some(serial), &args, timeout_ms)
        .await
        .ok()?;
    if out.ok() {
        Some(out.stdout.trim().to_string())
    } else {
        None
    }
}

fn parse_focus_lines(stdout: &str) -> Vec<String> {
    stdout
        .lines()
        .map(str::trim)
        .filter(|line| {
            line.contains("mCurrentFocus")
                || line.contains("mFocusedApp")
                || line.contains("topResumedActivity")
        })
        .map(str::to_string)
        .collect()
}

fn focus_token_package(token: &str) -> Option<String> {
    let clean = token.trim_matches(|c: char| {
        c == '{' || c == '}' || c == ')' || c == '(' || c == ',' || c == ';'
    });
    let (pkg, _) = clean.split_once('/')?;
    if pkg.contains('.')
        && pkg
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '.')
    {
        Some(pkg.to_string())
    } else {
        None
    }
}

fn parse_foreground_package(focus_lines: &[String]) -> Option<String> {
    for line in focus_lines {
        for token in line.split_whitespace() {
            if let Some(pkg) = focus_token_package(token) {
                return Some(pkg);
            }
        }
    }
    None
}

fn summarize_mobile_logcat(stdout: &str, package: Option<&str>) -> Value {
    let mut fatal_count = 0usize;
    let mut error_count = 0usize;
    let mut warning_count = 0usize;
    let mut surface_line_count = 0usize;
    let mut package_mentions = 0usize;
    let mut markers = Vec::new();
    let mut push_marker = |kind: &str, line: &str| {
        if markers.len() >= 30 {
            return;
        }
        let (text, truncated, total_chars) = truncate_chars(line, 500);
        markers.push(json!({
            "kind": kind,
            "line": text,
            "truncated": truncated,
            "total_chars": total_chars,
        }));
    };

    for line in stdout.lines() {
        let lower = line.to_ascii_lowercase();
        let package_hit = package.map(|pkg| line.contains(pkg)).unwrap_or(false);
        if package_hit {
            package_mentions += 1;
        }

        let is_fatal = line.contains("FATAL EXCEPTION")
            || lower.contains("fatal signal")
            || lower.contains("androidruntime")
            || lower.contains(" anr ")
            || lower.contains(" crash");
        let is_error = is_fatal
            || line.contains(" E ")
            || line.contains(" E/")
            || (lower.contains("exception") && (line.contains(" E ") || package_hit));
        let is_warning = line.contains(" W ") || line.contains(" W/");
        let is_surface = lower.contains("surfaceview")
            || lower.contains("surfaceflinger")
            || lower.contains("choreographer")
            || lower.contains("fps")
            || lower.contains("godot");

        if is_fatal {
            fatal_count += 1;
            push_marker("fatal", line);
        } else if is_error {
            error_count += 1;
            push_marker("error", line);
        } else if is_warning {
            warning_count += 1;
        }
        if is_surface {
            surface_line_count += 1;
        }
    }

    json!({
        "line_count": stdout.lines().count(),
        "fatal_count": fatal_count,
        "error_count": error_count,
        "warning_count": warning_count,
        "surface_line_count": surface_line_count,
        "package_mentions": package_mentions,
        "has_crash_markers": fatal_count > 0,
        "markers": markers,
    })
}

fn parse_mobile_bounds(raw: &str) -> Option<MobileBounds> {
    let nums: Vec<i64> = raw
        .split(|c| matches!(c, '[' | ']' | ','))
        .filter(|s| !s.trim().is_empty())
        .filter_map(|s| s.trim().parse::<i64>().ok())
        .collect();
    if nums.len() == 4 {
        Some(MobileBounds {
            left: nums[0],
            top: nums[1],
            right: nums[2],
            bottom: nums[3],
        })
    } else {
        None
    }
}

fn attr_bool(attrs: &HashMap<String, String>, key: &str) -> bool {
    attrs.get(key).map(|v| v == "true").unwrap_or(false)
}

fn decode_xml_attr_value(raw: &str) -> String {
    raw.replace("&quot;", "\"")
        .replace("&apos;", "'")
        .replace("&lt;", "<")
        .replace("&gt;", ">")
        .replace("&amp;", "&")
}

fn parse_xml_attrs(tag_body: &str) -> HashMap<String, String> {
    let mut attrs = HashMap::new();
    let bytes = tag_body.as_bytes();
    let mut i = 0usize;
    while i < bytes.len() {
        while i < bytes.len() && (bytes[i].is_ascii_whitespace() || bytes[i] == b'/') {
            i += 1;
        }
        let key_start = i;
        while i < bytes.len()
            && !bytes[i].is_ascii_whitespace()
            && bytes[i] != b'='
            && bytes[i] != b'/'
        {
            i += 1;
        }
        if key_start == i {
            i += 1;
            continue;
        }
        let key = &tag_body[key_start..i];
        while i < bytes.len() && bytes[i].is_ascii_whitespace() {
            i += 1;
        }
        if i >= bytes.len() || bytes[i] != b'=' {
            continue;
        }
        i += 1;
        while i < bytes.len() && bytes[i].is_ascii_whitespace() {
            i += 1;
        }
        if i >= bytes.len() || (bytes[i] != b'"' && bytes[i] != b'\'') {
            continue;
        }
        let quote = bytes[i];
        i += 1;
        let value_start = i;
        while i < bytes.len() && bytes[i] != quote {
            i += 1;
        }
        if i > bytes.len() {
            break;
        }
        let value = decode_xml_attr_value(&tag_body[value_start..i]);
        attrs.insert(key.to_string(), value);
        i += 1;
    }
    attrs
}

fn node_from_attrs(ordinal: usize, attrs: HashMap<String, String>) -> MobileUiNode {
    let bounds = attrs.get("bounds").and_then(|s| parse_mobile_bounds(s));
    MobileUiNode {
        ordinal,
        index: attrs.get("index").cloned().unwrap_or_default(),
        text: attrs.get("text").cloned().unwrap_or_default(),
        resource_id: attrs.get("resource-id").cloned().unwrap_or_default(),
        class_name: attrs.get("class").cloned().unwrap_or_default(),
        package_name: attrs.get("package").cloned().unwrap_or_default(),
        content_desc: attrs.get("content-desc").cloned().unwrap_or_default(),
        clickable: attr_bool(&attrs, "clickable"),
        enabled: attrs.get("enabled").map(|v| v == "true").unwrap_or(true),
        focusable: attr_bool(&attrs, "focusable"),
        focused: attr_bool(&attrs, "focused"),
        scrollable: attr_bool(&attrs, "scrollable"),
        bounds,
    }
}

fn parse_uiautomator_nodes(xml: &str) -> std::result::Result<Vec<MobileUiNode>, String> {
    let mut nodes = Vec::new();
    let mut search_start = 0usize;
    while let Some(rel) = xml[search_start..].find("<node") {
        let tag_start = search_start + rel;
        let after_name = tag_start + "<node".len();
        let next = xml[after_name..].chars().next();
        if !matches!(next, Some(c) if c.is_ascii_whitespace() || c == '/' || c == '>') {
            search_start = after_name;
            continue;
        }
        let Some(tag_end_rel) = xml[tag_start..].find('>') else {
            return Err("unterminated <node> tag in UI XML".to_string());
        };
        let tag_end = tag_start + tag_end_rel;
        let tag_body = &xml[after_name..tag_end];
        let attrs = parse_xml_attrs(tag_body);
        let ordinal = nodes.len();
        nodes.push(node_from_attrs(ordinal, attrs));
        search_start = tag_end + 1;
    }
    Ok(nodes)
}

async fn mobile_dump_ui_xml(
    serial: &str,
    timeout_ms: u64,
) -> std::result::Result<(AdbCommandOutput, AdbCommandOutput), String> {
    let dump_args = vec![
        "shell".to_string(),
        "uiautomator".to_string(),
        "dump".to_string(),
        MOBILE_UI_DUMP_PATH.to_string(),
    ];
    let dump = run_adb_command(Some(serial), &dump_args, timeout_ms).await?;
    if !dump.ok() {
        return Err(format!("uiautomator dump failed: {}", dump.stderr.trim()));
    }
    let cat_args = vec![
        "exec-out".to_string(),
        "cat".to_string(),
        MOBILE_UI_DUMP_PATH.to_string(),
    ];
    let cat = run_adb_command(Some(serial), &cat_args, timeout_ms).await?;
    if !cat.ok() {
        return Err(format!("read UI XML failed: {}", cat.stderr.trim()));
    }
    Ok((dump, cat))
}

fn sanitize_mobile_path_component(s: &str) -> String {
    let sanitized: String = s
        .chars()
        .map(|c| {
            if c.is_ascii_alphanumeric() || c == '-' || c == '_' {
                c
            } else {
                '-'
            }
        })
        .collect();
    if sanitized.is_empty() {
        "device".to_string()
    } else {
        sanitized
    }
}

fn mobile_screenshot_path(args: &Value, serial: &str) -> PathBuf {
    if let Some(path) = args
        .get("path")
        .and_then(|v| v.as_str())
        .filter(|s| !s.trim().is_empty())
    {
        return PathBuf::from(path);
    }
    let ts = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0);
    std::env::temp_dir().join(format!(
        "agent-bridge-mobile-screenshot-{}-{ts}.png",
        sanitize_mobile_path_component(serial)
    ))
}

fn adb_input_text_arg(text: &str) -> String {
    text.replace(' ', "%s")
}

macro_rules! mobile_tool_struct {
    ($name:ident) => {
        pub struct $name {
            hub: Hub,
        }
        impl $name {
            pub fn new(hub: Hub) -> Self {
                Self { hub }
            }
        }
    };
}

mobile_tool_struct!(MobileListDevicesTool);
#[async_trait]
impl McpTool for MobileListDevicesTool {
    fn name(&self) -> &'static str {
        "mobile_list_devices"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "List Android devices visible to ADB. Returns serials, connection \
                 state, `adb devices -l` attributes, and optional Android version/model \
                 properties. Use before any mobile_* action when multiple devices may be \
                 connected."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "include_props": { "type": "boolean", "default": true, "description": "Read model and Android version via getprop for online devices." },
                    "timeout_ms": { "type": "integer", "minimum": 1000, "maximum": 120000, "default": MOBILE_DEFAULT_TIMEOUT_MS }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        if let Err(e) = self.hub.security.check(Cap::ShellExec) {
            return Ok(ToolResult::error(e));
        }
        let timeout_ms = mobile_timeout_ms(&args);
        let include_props = args
            .get("include_props")
            .and_then(|v| v.as_bool())
            .unwrap_or(true);
        let out = match run_adb_command(None, &adb_args(&["devices", "-l"]), timeout_ms).await {
            Ok(out) => out,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        if !out.ok() {
            return Ok(ToolResult::json_text(&json!({
                "status": "error",
                "adb": out.as_json(),
            })));
        }
        let devices = parse_adb_devices(&out.stdout);
        let mut rows = Vec::new();
        for device in &devices {
            let android_version = if include_props && device.state == "device" {
                mobile_getprop(&device.serial, "ro.build.version.release", timeout_ms).await
            } else {
                None
            };
            rows.push(mobile_device_json(device, android_version));
        }
        Ok(ToolResult::json_text(&json!({
            "status": "ok",
            "adb_bin": resolve_adb_bin(),
            "count": rows.len(),
            "devices": rows,
        })))
    }
}

