pub struct BrowserNavigateTool {
    hub: Hub,
}
impl BrowserNavigateTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for BrowserNavigateTool {
    fn name(&self) -> &'static str {
        "browser_navigate"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Open a URL in the agent-bridge browser and return a page id you can \
                 pass to other browser_* tools. The browser is launched lazily on first \
                 call (headed by default; set AGENT_BRIDGE_HEADLESS=1 for headless)."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": { "url": { "type": "string", "description": "Absolute URL." } },
                "required": ["url"]
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        if let Err(e) = self.hub.security.check(Cap::Browser) {
            return Ok(ToolResult::error(e));
        }
        let b = match &self.hub.browser {
            Some(b) => b.clone(),
            None => return Ok(ToolResult::error("no browser backend configured")),
        };
        let url = match args.get("url").and_then(|v| v.as_str()) {
            Some(u) => u,
            None => return Ok(ToolResult::error("missing 'url'")),
        };
        match b.navigate(url).await {
            Ok(pid) => Ok(ToolResult::text(format!("page: {pid}"))),
            Err(e) => Ok(ToolResult::error(format!("browser: {e}"))),
        }
    }
}

/// Output / expression lane — E1 `present()` static-artifact sink.
/// Renders a structured result into a self-verified standalone HTML artifact
/// carrying both a human render and a machine-facing `#ab-payload`
/// (dual-encoding) + provenance. See `crate::present`.
pub struct PresentTool {
    hub: Hub,
}
impl PresentTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for PresentTool {
    fn name(&self) -> &'static str {
        "present"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Output-expression lane E1: render a structured result into a \
                 self-verified standalone HTML artifact that carries BOTH a human-facing \
                 render AND a machine-facing structured payload (dual-encoding) + provenance. \
                 Linear terminal text is lossy for non-linear results (tables, graphs, diagrams); \
                 `present` writes an artifact to ~/.cache/agent-bridge/presentations/<id>.html, \
                 self-verifies it by loading it in the browser, and returns the path + verify \
                 status. Pass `payload` (the structured JSON the artifact visualizes) so other \
                 agents read structure instead of OCR-ing pixels. Degrades to \
                 verify_status=no_browser when no browser is available."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "kind": {
                        "type": "string",
                        "enum": ["table", "markdown_table", "html", "svg", "mermaid"],
                        "description": "Artifact kind. table=structured rows (from payload); markdown_table=a markdown pipe table in artifact; html/svg=raw markup in artifact; mermaid=diagram source in artifact. NOTE: html/svg are inlined WITHOUT sanitization and, when verify runs, are loaded in a real browser (their scripts execute) — use html/svg only with trusted/self-authored content, not untrusted input."
                    },
                    "artifact": {
                        "type": "string",
                        "description": "Source content for html/svg/mermaid/markdown_table. For kind=table, optional (data comes from payload, or a JSON array string here)."
                    },
                    "payload": {
                        "type": ["object", "array"],
                        "description": "Structured JSON the artifact visualizes. Embedded as #ab-payload (dual-encoding). For kind=table, an array of objects/arrays renders the table. Pass a JSON object/array (NOT a stringified blob — declaring the type stops clients double-encoding; a stringified value is still defensively decoded, see #1786). Strongly encouraged."
                    },
                    "title": { "type": "string", "description": "Document title." },
                    "intent": {
                        "type": "string",
                        "description": "Optional: what this render is the outcome of (the intent half of the action→outcome record). Recorded in the `<id>.outcome.json` sidecar and surfaced by present_outcomes; does not affect the artifact."
                    },
                    "channel": {
                        "type": "string",
                        "enum": ["file"],
                        "default": "file",
                        "description": "Sink. Only 'file' implemented in v0 (browser_tab/notify/avatar are future rungs)."
                    },
                    "provenance": {
                        "type": "object",
                        "description": "Where the data came from: {source_tool, source_event_ids, cwd, ...}. generated_by/session_id/ts are auto-added."
                    },
                    "verify": {
                        "type": "boolean",
                        "default": true,
                        "description": "Self-verify by loading the artifact in the browser and checking the #ab-render region rendered visible content (verify_status: rendered_ok|blank|no_browser|error|skipped). Requires the Browser capability + a configured backend; otherwise returns no_browser (see verify_detail). Result also includes artifact_path, screenshot_path (when captured), dual_encoding, and provenance."
                    },
                    "interactive": {
                        "type": "boolean",
                        "default": false,
                        "description": "E2 output-expression rung: when true AND kind=table with an array-of-objects payload, the artifact gains client-side filter + per-column sort controls over the embedded #ab-payload (no author code — a fixed server runtime; #ab-payload stays the single-encoded machine structure). Otherwise a no-op (interactive_status=not_applicable). When verify runs, a second headless probe drives a control and returns interactive_status: verified|dead|not_applicable|skipped|no_browser|error (dead = a control that does not actually change the view). Default false → E1 output is byte-identical."
                    }
                },
                "required": ["kind"]
            }),
        }
    }
    async fn execute(&self, args: Value, ctx: &ToolContext) -> Result<ToolResult> {
        let kind_str = match required_str_arg(&args, "kind") {
            Ok(v) => v,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        let kind = match crate::present::PresentKind::parse(&kind_str) {
            Some(k) => k,
            None => {
                return Ok(ToolResult::error(format!(
                    "unknown kind '{kind_str}': use table|markdown_table|html|svg|mermaid"
                )))
            }
        };
        let artifact = args
            .get("artifact")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_string();
        // Explicit `null` means "no payload" (not an embedded JSON null) so
        // dual_encoding is not falsely reported true. normalize_payload undoes
        // a client that JSON-stringified the structured arg (forum #1786) so
        // #ab-payload embeds the structure single-encoded, not a quoted blob.
        let payload = args
            .get("payload")
            .filter(|v| !v.is_null())
            .map(crate::present::normalize_payload);
        let title = args.get("title").and_then(|v| v.as_str());
        // Slice A: optional caller-supplied "what was this the outcome of" — the
        // intent half of the (intent → action → verified-outcome) record.
        let intent = args.get("intent").and_then(|v| v.as_str());
        let channel = args
            .get("channel")
            .and_then(|v| v.as_str())
            .unwrap_or("file")
            .to_string();
        // v0 implements only the `file` sink; reject others so the echoed
        // channel always matches what actually happened.
        if channel != "file" {
            return Ok(ToolResult::error(format!(
                "unsupported channel '{channel}': v0 implements only 'file'"
            )));
        }
        let verify = args.get("verify").and_then(|v| v.as_bool()).unwrap_or(true);
        // E2: interactivity is opt-in; `enhanced` is true only when the kind+payload
        // can actually be driven (keyed table), so the tool never claims interactivity
        // it didn't add.
        let interactive_req = args
            .get("interactive")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let enhanced =
            interactive_req && crate::present::is_enhanceable(kind, &artifact, payload.as_ref());

        // Provenance: caller-supplied + auto fields (generated_by/session_id/ts).
        // A non-object provenance is wrapped as {given: <value>} so the auto
        // integrity fields are never silently dropped.
        let mut provenance = match args.get("provenance").cloned() {
            Some(v) if v.is_object() => v,
            Some(v) => json!({ "given": v }),
            None => json!({}),
        };
        if let Some(obj) = provenance.as_object_mut() {
            obj.entry("generated_by")
                .or_insert_with(|| json!(crate::present::PRESENT_SCHEMA));
            if let Some(sid) = &ctx.session_id {
                obj.entry("session_id")
                    .or_insert_with(|| json!(sid.to_string()));
            }
            obj.insert("ts".into(), json!(crate::present::now_unix()));
            // record the kind so present_list can reconstruct the index from
            // the self-describing artifact (dual-encoding consumer side).
            obj.insert("kind".into(), json!(kind.as_str()));
        }

        let html = if interactive_req {
            crate::present::build_html_interactive(
                kind,
                &artifact,
                title,
                payload.as_ref(),
                Some(&provenance),
            )
        } else {
            crate::present::build_html(kind, &artifact, title, payload.as_ref(), Some(&provenance))
        };
        // Enhanced markdown_table embeds a synthesized #ab-payload even though the
        // caller passed none, so dual_encoding tracks the artifact, not just the arg.
        let dual_encoding = payload.is_some() || enhanced;
        // Content-addressed id: hash the SOURCE (kind+title+artifact+payload+enhanced),
        // NOT the rendered HTML — the HTML embeds a per-call provenance ts, so
        // hashing it would defeat dedupe. `enhanced` (not interactive_req) keys the
        // id so an interactive-but-non-enhanceable call dedupes with its E1 twin.
        let canonical = format!(
            "{}\u{0}{}\u{0}{}\u{0}{}\u{0}{}",
            kind.as_str(),
            title.unwrap_or(""),
            artifact,
            payload.as_ref().map(|p| p.to_string()).unwrap_or_default(),
            enhanced
        );
        let id = crate::present::derive_id(&canonical);
        let dir = crate::present::presentations_dir();
        let path = dir.join(format!("{id}.html"));
        if let Err(e) = crate::present::write_artifact_atomic(&path, &html) {
            return Ok(ToolResult::error(format!("present: write failed: {e}")));
        }

        // Self-verify: load the artifact in the browser and check it rendered.
        let mut verify_status = crate::present::VerifyStatus::Skipped;
        let mut verify_detail: Option<String> = None;
        let mut screenshot_path: Option<String> = None;
        // E2 interactivity status (orthogonal to verify_status). None unless
        // requested; not_applicable when not enhanceable; the enhanced+verify case
        // defaults to no_browser and is overwritten iff the drive probe runs.
        let mut interactive_status: Option<crate::present::InteractStatus> = if !interactive_req {
            None
        } else if !enhanced {
            Some(crate::present::InteractStatus::NotApplicable)
        } else if !verify {
            Some(crate::present::InteractStatus::Skipped)
        } else {
            Some(crate::present::InteractStatus::NoBrowser)
        };
        let mut interactive_detail: Option<String> = None;
        if verify && channel == "file" {
            if let Err(e) = self.hub.security.check(Cap::Browser) {
                verify_status = crate::present::VerifyStatus::NoBrowser;
                verify_detail = Some(format!("capability: {e}"));
            } else if let Some(b) = self.hub.browser.clone() {
                let file_url = format!("file://{}", path.display());
                match b.navigate(&file_url).await {
                    Ok(page) => {
                        match b.eval(&page, crate::present::VERIFY_METRICS_JS).await {
                            Ok(mv) => {
                                let metrics = crate::present::parse_metrics(&mv);
                                verify_status = crate::present::classify_render(&metrics);
                            }
                            Err(e) => {
                                verify_status = crate::present::VerifyStatus::Error;
                                verify_detail = Some(format!("eval: {e}"));
                            }
                        }
                        if let Ok(bytes) = b.screenshot(&page).await {
                            let png = dir.join(format!("{id}.png"));
                            if std::fs::write(&png, bytes.as_ref()).is_ok() {
                                screenshot_path = Some(png.display().to_string());
                            }
                        }
                        // E2: after the static-render check, drive a control on the
                        // SAME loaded page and classify whether the interactivity is
                        // real. Only when enhanced AND the initial render passed
                        // (no point proving interactivity on a blank artifact).
                        if enhanced {
                            if verify_status == crate::present::VerifyStatus::RenderedOk {
                                match b.eval(&page, crate::present::INTERACT_DRIVE_JS).await {
                                    Ok(sv) => {
                                        let sig = crate::present::parse_interact_signature(&sv);
                                        interactive_detail = Some(format!(
                                            "filtered_changed={} restored={} sorted_changed={} rows0={}{}",
                                            sig.filtered_changed,
                                            sig.restored,
                                            sig.sorted_changed,
                                            sig.rowcount0,
                                            sig.reason
                                                .as_deref()
                                                .map(|r| format!(" reason={r}"))
                                                .unwrap_or_default()
                                        ));
                                        interactive_status =
                                            Some(crate::present::classify_interactivity(&sig));
                                    }
                                    Err(e) => {
                                        interactive_status =
                                            Some(crate::present::InteractStatus::Error);
                                        interactive_detail = Some(format!("interact eval: {e}"));
                                    }
                                }
                            } else {
                                // initial render didn't pass → interactivity unprovable;
                                // a blank render is a real fault for an interactive artifact.
                                interactive_status = Some(match verify_status {
                                    crate::present::VerifyStatus::Blank => {
                                        crate::present::InteractStatus::Dead
                                    }
                                    _ => crate::present::InteractStatus::Skipped,
                                });
                            }
                        }
                    }
                    Err(e) => {
                        // Some(browser) != launchable Chrome — navigate failure
                        // (missing binary / launch error) degrades, not fails.
                        verify_status = crate::present::VerifyStatus::NoBrowser;
                        verify_detail = Some(format!("navigate: {e}"));
                    }
                }
            } else {
                verify_status = crate::present::VerifyStatus::NoBrowser;
                verify_detail = Some("no browser backend configured".to_string());
            }
        }

        // Slice A: persist a falsifier-gated action→outcome record sidecar
        // (`<id>.outcome.json`, next to the artifact + its `<id>.png`) so the
        // lane's verified results become a queryable training-signal stream
        // (`present_outcomes`), not a one-shot tool result. Best-effort: a sidecar
        // write failure never fails the present() call. The gate that decides
        // eligibility lives in present_outcomes (read side), so this record stays
        // a faithful log of what actually happened (verified or not).
        let verify_method = if !verify {
            "none"
        } else if verify_status.as_str() == "no_browser" {
            "no_browser"
        } else {
            "browser_eval"
        };
        // Provenance: the present_replay chain_head over the lane's artifacts NOW
        // (including the one just written) — the chain state this outcome
        // contributes to. A future opt-in memory ingest can back-link the verified
        // outcome to the chain that produced it. Local SHA-256 chain only (the same
        // idiom present_replay reports); does NOT touch event_spine. Best-effort —
        // a listing failure leaves it empty rather than failing the render.
        let chain_head = {
            let artifacts = crate::present::list_artifacts(&dir, 500, None);
            crate::present::present_replay_snapshot(
                &artifacts,
                0usize,
                0u64,
                crate::present::now_unix(),
            )
            .get("chain_head")
            .and_then(|v| v.as_str())
            .map(|s| s.to_string())
            .unwrap_or_default()
        };
        let outcome_record = json!({
            "artifact_id": id,
            "intent": intent,
            "action_tool": "present",
            "kind": kind.as_str(),
            "verify_status": verify_status.as_str(),
            "embody_status": crate::present::EmbodyStatus::NotApplicable.as_str(),
            "interactive_status": interactive_status.map(|s| s.as_str()),
            "verify_method": verify_method,
            "dual_encoding": dual_encoding,
            "chain_head": chain_head,
            "session_id": ctx.session_id.as_ref().map(|s| s.to_string()),
            "ts": crate::present::now_unix(),
        });
        let _ = crate::present::write_outcome_sidecar(&dir, &id, &outcome_record);

        let result = json!({
            "schema": crate::present::PRESENT_SCHEMA,
            "id": id,
            "kind": kind.as_str(),
            "channel": channel,
            "artifact_path": path.display().to_string(),
            "screenshot_path": screenshot_path,
            "verify_status": verify_status.as_str(),
            "verify_detail": verify_detail,
            "interactive_status": interactive_status.map(|s| s.as_str()),
            "interactive_detail": interactive_detail,
            "dual_encoding": dual_encoding,
            "bytes": html.len(),
            "provenance": provenance,
        });
        Ok(ToolResult::json_text(&result))
    }
}

/// Output / expression lane — list persisted `present()` artifacts by reading
/// their self-describing HTML (embedded provenance + payload). Read-only.
pub struct PresentListTool {
    _hub: Hub,
}
impl PresentListTool {
    pub fn new(hub: Hub) -> Self {
        Self { _hub: hub }
    }
}
#[async_trait]
impl McpTool for PresentListTool {
    fn name(&self) -> &'static str {
        "present_list"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "List artifacts previously written by `present` (read-only). Scans \
                 ~/.cache/agent-bridge/presentations and reconstructs each entry from the \
                 artifact's embedded provenance + payload (id, kind, ts, generated_by, \
                 session_id, dual_encoding, has_screenshot, bytes), most-recent first."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "limit": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": 500,
                        "default": 50,
                        "description": "Max artifacts to return (most-recent first)."
                    },
                    "kind": {
                        "type": "string",
                        "enum": ["table", "markdown_table", "html", "svg", "mermaid"],
                        "description": "Optional kind filter."
                    }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let limit = args
            .get("limit")
            .and_then(|v| v.as_u64())
            .unwrap_or(50)
            .clamp(1, 500) as usize;
        let kind = args.get("kind").and_then(|v| v.as_str());
        let dir = crate::present::presentations_dir();
        let infos = crate::present::list_artifacts(&dir, limit, kind);
        let artifacts: Vec<Value> = infos
            .iter()
            .map(|a| {
                json!({
                    "id": a.id,
                    "artifact_path": a.artifact_path,
                    "kind": a.kind,
                    "ts": a.ts,
                    "generated_by": a.generated_by,
                    "session_id": a.session_id,
                    "dual_encoding": a.dual_encoding,
                    "has_screenshot": a.has_screenshot,
                    "bytes": a.bytes,
                })
            })
            .collect();
        Ok(ToolResult::json_text(&json!({
            "schema": "present_list/v0",
            "dir": dir.display().to_string(),
            "count": artifacts.len(),
            "artifacts": artifacts,
        })))
    }
}

/// Output-expression lane slice 2: read-only replay/audit projection over the
/// artifacts `present` has persisted. Complements `present_list` (flat index)
/// with an ordered hash chain + drift + dual-encoding audit. See
/// `crate::present::present_replay_snapshot`.
pub struct PresentReplayTool {
    hub: Hub,
}
impl PresentReplayTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

#[async_trait]
impl McpTool for PresentReplayTool {
    fn name(&self) -> &'static str {
        "present_replay"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Output-expression lane slice 2: READ-ONLY replay/audit projection over \
                 persisted present() artifacts. Does NOT create a new source of truth — it orders \
                 the self-describing on-disk artifacts (~/.cache/agent-bridge/presentations) \
                 oldest→newest, derives an event_spine-style SHA-256 hash chain over their \
                 identity (chain_head makes loss/tamper detectable), cross-checks the artifact \
                 count against the `present` calls already recorded in mcp_tool_calls (drift), and \
                 tallies how many carry a machine-readable #ab-payload (dual_encoding). Use to \
                 audit/replay what present() has emitted without re-reading every artifact."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "window_secs": {
                        "type": "integer",
                        "minimum": 60,
                        "maximum": 31536000,
                        "default": 86400,
                        "description": "Look-back window for both present calls and artifacts (by provenance ts)."
                    },
                    "limit": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": 500,
                        "default": 200,
                        "description": "Max artifacts scanned (most-recent-first) and present-call rows fetched."
                    },
                    "kind": {
                        "type": "string",
                        "description": "Optional kind filter (table|markdown_table|html|svg|mermaid)."
                    }
                }
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let window_secs = args
            .get("window_secs")
            .and_then(|v| v.as_i64())
            .unwrap_or(86_400)
            .clamp(60, 31_536_000);
        let limit = args
            .get("limit")
            .and_then(|v| v.as_u64())
            .unwrap_or(200)
            .clamp(1, 500) as usize;
        let kind_filter = args.get("kind").and_then(|v| v.as_str());

        let now = dispatch_now_secs();
        let cutoff = now.saturating_sub(window_secs);

        // Count present() calls already recorded in mcp_tool_calls within the
        // window (bounded by `limit` fetched rows — drift is best-effort, not exact
        // for very high-volume windows).
        let calls = match store.recent_mcp_tool_calls(window_secs, limit as u32).await {
            Ok(rows) => rows,
            Err(e) => return Ok(ToolResult::error(format!("recent_mcp_tool_calls: {e}"))),
        };
        let present_calls_logged = calls.iter().filter(|c| c.tool_name == "present").count();

        // On-disk artifacts (self-describing index), filtered to the window by
        // provenance ts (artifacts lacking a ts are kept for visibility).
        let dir = crate::present::presentations_dir();
        let artifacts: Vec<_> = crate::present::list_artifacts(&dir, limit, kind_filter)
            .into_iter()
            .filter(|a| a.ts.map_or(true, |t| t as i64 >= cutoff))
            .collect();

        let snapshot = crate::present::present_replay_snapshot(
            &artifacts,
            present_calls_logged,
            window_secs as u64,
            now.max(0) as u64,
        );
        Ok(ToolResult::json_text(&snapshot))
    }
}

/// Build the read-only `present_replay` snapshot the E3 dashboard mirrors. Shared
/// by `present_dashboard` for both the embedded render AND the verify-time
/// recompute (so the embodiment check compares the surface against a freshly
/// derived current `chain_head`, not an echo of the value it embedded). The
/// stable dashboard file is excluded by [`crate::present::list_artifacts`], so it
/// never perturbs the chain it reflects.
async fn dashboard_replay_snapshot(
    store: &Arc<dyn StateStore>,
    window_secs: i64,
    limit: usize,
    kind_filter: Option<&str>,
) -> std::result::Result<Value, String> {
    let calls = store
        .recent_mcp_tool_calls(window_secs, limit as u32)
        .await
        .map_err(|e| format!("recent_mcp_tool_calls: {e}"))?;
    let present_calls_logged = calls.iter().filter(|c| c.tool_name == "present").count();
    let now = dispatch_now_secs();
    let cutoff = now.saturating_sub(window_secs);
    let dir = crate::present::presentations_dir();
    let artifacts: Vec<_> = crate::present::list_artifacts(&dir, limit, kind_filter)
        .into_iter()
        .filter(|a| a.ts.map_or(true, |t| t as i64 >= cutoff))
        .collect();
    Ok(crate::present::present_replay_snapshot(
        &artifacts,
        present_calls_logged,
        window_secs as u64,
        now.max(0) as u64,
    ))
}

/// First 12 chars of a chain head, for compact `embody_detail` diagnostics.
fn short_head(h: &str) -> String {
    h.chars().take(12).collect()
}

/// Output-expression lane E3 (embodied mirror): renders a PERSISTENT dashboard
/// surface that mirrors the `present_replay` snapshot, and self-verifies the
/// embodiment by reading back the `chain_head` the rendered surface shows. See
/// `crate::present::build_dashboard_html` / `classify_embody`.
// ===========================================================================
//                            present_voice (audio embodiment)
// ===========================================================================
// Output-expression lane, AUDIO domain. Emits a KNOWN signal (a defined-frequency
// tone) to an output sink and reads it back off the SYSTEM BUS (the PipeWire sink
// `.monitor` loopback) to prove the requested signal actually reached the bus — a
// SPECTRAL-PEAK falsifier (Goertzel at the target freq vs the local spectral floor),
// robust to concurrent audio. HONEST BOUNDARY (the unverifiable last mile): this
// verifies the signal reached the OUTPUT BUS, NOT the physical transducer
// (headphone/speaker driver) — only a human, or (for speakers) the mic channel,
// can confirm that. Thin wrapper over scripts/audio_embody.py (the analysis +
// pure decision live there with Python truth-table tests), mirroring the
// desktop_verify / vision_grounding_ocr pattern. Writes a verified-outcome sidecar
// that flows into present_outcomes exactly like the display surfaces.
pub struct PresentVoiceTool {
    _hub: Hub,
}

impl PresentVoiceTool {
    pub fn new(hub: Hub) -> Self {
        Self { _hub: hub }
    }
}

#[async_trait]
impl McpTool for PresentVoiceTool {
    fn name(&self) -> &'static str {
        "present_voice"
    }

    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Output-expression lane, AUDIO embodiment. backend=tone (default) emits a known \
                 tone (freq/duration); backend=kokoro SPEAKS `text` via the offline Rust Kokoro TTS engine. \
                 Either way the audio is played to an output sink and read back off the system bus (PipeWire \
                 sink .monitor loopback) to prove it reached the bus: tone uses a spectral-peak falsifier \
                 (Goertzel vs local floor); speech uses an energy-envelope cross-correlation falsifier (the \
                 captured bus signal's loudness-over-time must match the played WAV's shape) + voiced span — \
                 both robust to concurrent audio. Returns status (emitted|silent|mismatch|no_capture|error) \
                 plus an HONEST boundary: verified_to=output_bus, NOT the physical headphone/speaker driver \
                 (the unverifiable last mile — only a human, or the mic channel for speakers, confirms that). \
                 Writes a verified-outcome sidecar that flows into present_outcomes. capture_channel= \
                 sink_monitor (bus loopback, default) or mic. Requires PipeWire + ffmpeg/paplay; backend=kokoro \
                 needs ab-tts-synth (env AB_TTS_SYNTH_BIN) + the Kokoro model assets. Opt-in (Niche)."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "backend": {"type": "string", "enum": ["tone", "kokoro", "piper"], "default": "tone", "description": "tone = fixed-freq tone (default, no model); kokoro = speak `text` via the offline Rust Kokoro TTS (24kHz); piper = speak `text` via the offline Rust Piper TTS (22.05kHz). kokoro/piper both bus-verify the speech."},
                    "text": {"type": "string", "description": "backend=kokoro: the text to speak (required for kokoro)."},
                    "voice": {"type": "string", "default": "af_sarah", "description": "backend=kokoro: TTS voice name (e.g. af_sarah, af_heart, bf_*)."},
                    "speed": {"type": "number", "minimum": 0.5, "maximum": 2.0, "default": 1.0, "description": "backend=kokoro: speech speed."},
                    "freq": {"type": "number", "minimum": 50, "maximum": 18000, "default": 440, "description": "backend=tone: tone frequency (Hz) whose presence on the bus is verified."},
                    "duration_ms": {"type": "integer", "minimum": 100, "maximum": 8000, "default": 1500},
                    "amplitude": {"type": "number", "minimum": 0.0, "maximum": 1.0, "default": 0.25, "description": "backend=tone: output amplitude 0..1 (gentle by default)."},
                    "sink": {"type": "string", "description": "PipeWire output sink to emit to. Defaults to the system default sink; the SAME sink's .monitor is the bus-loopback readback."},
                    "capture_channel": {"type": "string", "enum": ["sink_monitor", "mic"], "default": "sink_monitor", "description": "Readback channel: sink_monitor = emit sink's .monitor (bus loopback, default); mic = default input (acoustic, phase 2)."},
                    "intent": {"type": "string", "description": "What this emission is the outcome of (recorded in the outcome sidecar; does not affect playback)."},
                    "synth_bin": {"type": "string", "description": "backend=kokoro: explicit ab-tts-synth path (else env AB_TTS_SYNTH_BIN)."},
                    "verify_intelligibility": {"type": "boolean", "default": false, "description": "backend=kokoro: ALSO transcribe the bus capture (whisper.cpp) and check the requested words came back — a stronger, layered falsifier. Needs ab-tts STT (env AB_TTS_STT_BIN/_MODEL or stt_bin/stt_model)."},
                    "stt_bin": {"type": "string", "description": "verify_intelligibility: whisper.cpp CLI path (else env AB_TTS_STT_BIN)."},
                    "stt_model": {"type": "string", "description": "verify_intelligibility: whisper ggml model path (else env AB_TTS_STT_MODEL)."},
                    "cwd": {"type": "string", "description": "Repo root to resolve scripts/audio_embody.py."},
                    "script_path": {"type": "string", "description": "Explicit audio_embody.py path (tests/alternate checkouts)."}
                }
            }),
        }
    }

    async fn execute(&self, args: Value, ctx: &ToolContext) -> Result<ToolResult> {
        let backend = args
            .get("backend")
            .and_then(|v| v.as_str())
            .unwrap_or("tone")
            .to_string();
        let is_speech = backend != "tone";
        let freq = args
            .get("freq")
            .and_then(|v| v.as_f64())
            .unwrap_or(440.0)
            .clamp(50.0, 18000.0);
        let duration_ms = args
            .get("duration_ms")
            .and_then(|v| v.as_u64())
            .unwrap_or(1500)
            .clamp(100, 8000);
        let amplitude = args
            .get("amplitude")
            .and_then(|v| v.as_f64())
            .unwrap_or(0.25)
            .clamp(0.0, 1.0);
        let text = args
            .get("text")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_string();
        let voice = args
            .get("voice")
            .and_then(|v| v.as_str())
            .unwrap_or("af_sarah")
            .to_string();
        let speed = args
            .get("speed")
            .and_then(|v| v.as_f64())
            .unwrap_or(1.0)
            .clamp(0.5, 2.0);
        let verify_intelligibility = args
            .get("verify_intelligibility")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let capture_channel = args
            .get("capture_channel")
            .and_then(|v| v.as_str())
            .unwrap_or("sink_monitor")
            .to_string();
        let intent = args
            .get("intent")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_string();
        let cwd = args.get("cwd").and_then(|v| v.as_str()).map(PathBuf::from);

        if is_speech && text.trim().is_empty() {
            return Ok(ToolResult::error(
                "present_voice backend=kokoro requires a non-empty `text` to speak".to_string(),
            ));
        }

        let script = present_voice_script_path(&args, cwd.as_ref());
        if !script.exists() {
            return Ok(ToolResult::error(format!(
                "audio_embody.py not found at {} (pass script_path or run from the Agent-Bridge repo root)",
                script.display()
            )));
        }

        let mut cmd = killable_command(
            std::env::var("PYTHON")
                .ok()
                .filter(|s| !s.trim().is_empty())
                .unwrap_or_else(|| "python3".to_string()),
        );
        cmd.arg(&script).arg("--json");
        if is_speech {
            // backend=kokoro|piper: synthesize `text` with that engine and verify via
            // envelope correlation. `backend` is exactly the audio_embody synth engine.
            cmd.arg("--mode")
                .arg("speech")
                .arg("--text")
                .arg(&text)
                .arg("--voice")
                .arg(&voice)
                .arg("--speed")
                .arg(format!("{speed}"))
                .arg("--synth-backend")
                .arg(&backend)
                .arg("--capture-channel")
                .arg(&capture_channel);
            push_optional_str_arg(&mut cmd, &args, "synth_bin", "--synth-bin");
            if verify_intelligibility {
                cmd.arg("--check-intelligibility");
                push_optional_str_arg(&mut cmd, &args, "stt_bin", "--stt-bin");
                push_optional_str_arg(&mut cmd, &args, "stt_model", "--stt-model");
            }
        } else {
            cmd.arg("--freq")
                .arg(format!("{freq}"))
                .arg("--duration-ms")
                .arg(duration_ms.to_string())
                .arg("--amplitude")
                .arg(format!("{amplitude}"))
                .arg("--capture-channel")
                .arg(&capture_channel);
        }
        push_optional_str_arg(&mut cmd, &args, "sink", "--sink");
        cmd.stdout(std::process::Stdio::piped());
        cmd.stderr(std::process::Stdio::piped());
        if let Some(cwd) = cwd.as_ref() {
            cmd.current_dir(cwd);
        }

        // process kill ceiling. tone: emit duration + capture/ffmpeg margin. speech:
        // generous — first call loads the ~300 MB model (~3-4s) + synth + realtime play.
        let timeout_ms = if is_speech {
            120_000
        } else {
            duration_ms + 8_000
        };
        let output =
            match tokio::time::timeout(Duration::from_millis(timeout_ms), cmd.output()).await {
                Err(_) => {
                    return Ok(ToolResult::error(format!(
                        "present_voice: audio_embody exceeded {timeout_ms} ms"
                    )))
                }
                Ok(Err(e)) => {
                    return Ok(ToolResult::error(format!(
                        "present_voice: spawn failed: {e}"
                    )))
                }
                Ok(Ok(o)) => o,
            };
        let (stdout, _) = lossy_truncate(&output.stdout);
        let (stderr, _) = lossy_truncate(&output.stderr);
        let res: Value = match serde_json::from_str(&stdout) {
            Ok(v) => v,
            Err(e) => {
                return Ok(ToolResult::error(format!(
                    "present_voice: audio_embody returned invalid JSON: {e}; stderr={stderr}"
                )));
            }
        };

        let status = res
            .get("status")
            .and_then(|v| v.as_str())
            .unwrap_or("error");
        let verify_status = res
            .get("verify_status")
            .and_then(|v| v.as_str())
            .unwrap_or("error");

        // Provenance: the present_replay chain_head over the lane's artifacts NOW
        // (same idiom present()/present_dashboard use). build_outcome_memory now
        // forwards chain_head into the durable row (P-defer #2), so an ingested
        // voice outcome carries the same provenance the bus readback saw.
        let dir = crate::present::presentations_dir();
        let chain_head = {
            let artifacts = crate::present::list_artifacts(&dir, 500, None);
            crate::present::present_replay_snapshot(
                &artifacts,
                0usize,
                0u64,
                crate::present::now_unix(),
            )
            .get("chain_head")
            .and_then(|v| v.as_str())
            .map(|s| s.to_string())
            .unwrap_or_default()
        };
        let ts = crate::present::now_unix();
        let id = if is_speech {
            format!("voice_{backend}_{ts}")
        } else {
            format!("voice_{}hz_{}", freq as u64, ts)
        };
        // Faithful log regardless of outcome (the gate decides eligibility on the
        // read side). verify_status=rendered_ok ONLY when the played audio was
        // confirmed on the bus (tone: spectral peak; speech: envelope correlation).
        // Mode-specific metrics are present for the active backend, null otherwise.
        let outcome_record = json!({
            "artifact_id": id,
            "intent": intent,
            "action_tool": "present_voice",
            "kind": "voice",
            "backend": backend,
            "verify_status": verify_status,
            "embody_status": crate::present::EmbodyStatus::NotApplicable.as_str(),
            "verify_method": "audio_bus_readback",
            "audio_status": status,
            "capture_channel": capture_channel,
            "verified_to": res.get("verified_to"),
            "not_verified": res.get("not_verified"),
            // speech-mode fields
            "text": if is_speech { json!(text) } else { Value::Null },
            "voice": res.get("voice"),
            "played_dur_s": res.get("played_dur_s"),
            "env_corr": res.get("env_corr"),
            "voiced_secs": res.get("voiced_secs"),
            "capture_rms": res.get("capture_rms"),
            // intelligibility (STT round-trip; present only when verify_intelligibility)
            "intelligibility": res.get("intelligibility"),
            "word_overlap": res.get("word_overlap"),
            "stt_transcript": res.get("stt_transcript"),
            // tone-mode fields
            "freq": if is_speech { Value::Null } else { json!(freq) },
            "rms": res.get("rms"),
            "goertzel": res.get("goertzel"),
            "goertzel_floor": res.get("goertzel_floor"),
            "peak_ratio": res.get("peak_ratio"),
            "chain_head": chain_head,
            "session_id": ctx.session_id.as_ref().map(|s| s.to_string()),
            "ts": ts,
        });
        let _ = crate::present::write_outcome_sidecar(&dir, &id, &outcome_record);

        let mut result = res;
        if let Some(obj) = result.as_object_mut() {
            obj.insert("id".to_string(), json!(id));
            obj.insert("action_tool".to_string(), json!("present_voice"));
            obj.insert("verify_method".to_string(), json!("audio_bus_readback"));
            obj.insert("chain_head".to_string(), json!(chain_head));
            obj.insert(
                "outcome_sidecar".to_string(),
                json!(format!("{id}.outcome.json")),
            );
            obj.insert(
                "mcp_wrapper".to_string(),
                json!({
                    "tool": "present_voice",
                    "exit_code": output.status.code().unwrap_or(-1),
                    "stderr_present": !stderr.is_empty()
                }),
            );
        }
        Ok(ToolResult::json_text(&result))
    }
}

fn present_voice_script_path(args: &Value, cwd: Option<&PathBuf>) -> PathBuf {
    if let Some(path) = args.get("script_path").and_then(|v| v.as_str()) {
        return PathBuf::from(path);
    }
    if let Ok(path) = std::env::var("AGENT_BRIDGE_AUDIO_EMBODY_SCRIPT") {
        if !path.trim().is_empty() {
            return PathBuf::from(path);
        }
    }
    if let Some(cwd) = cwd {
        let path = cwd.join("scripts/audio_embody.py");
        if path.exists() {
            return path;
        }
    }
    if let Ok(cwd) = std::env::current_dir() {
        let path = cwd.join("scripts/audio_embody.py");
        if path.exists() {
            return path;
        }
    }
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../scripts/audio_embody.py")
}

pub struct PresentDashboardTool {
    hub: Hub,
}
impl PresentDashboardTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

#[async_trait]
impl McpTool for PresentDashboardTool {
    fn name(&self) -> &'static str {
        "present_dashboard"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Output-expression lane E3 (embodied mirror): render a PERSISTENT \
                 dashboard surface (~/.cache/agent-bridge/presentations/_ab_dashboard.html) that \
                 MIRRORS the present_replay snapshot — the lane's current chain_head, the \
                 count/drift/dual-encoding summary, and a recent-artifacts table — into one stable \
                 browser tab a human keeps open (every call refreshes the same file). Read-only \
                 over present() artifacts (NOT a new source of truth). When verify runs, a headless \
                 probe reads the chain_head the rendered surface shows and compares it to the \
                 lane's CURRENT chain_head, returning embody_status: \
                 embodied|stale|dead|no_browser|error|skipped (stale = the surface is behind the \
                 lane; dead = it rendered nothing / no head — the lane never claims an embodiment \
                 it didn't achieve). The whole snapshot is dual-encoded as #ab-payload for bypass \
                 agents. Degrades to no_browser when no browser is available."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "window_secs": {
                        "type": "integer",
                        "minimum": 60,
                        "maximum": 31536000,
                        "default": 86400,
                        "description": "Look-back window for both present calls and artifacts (by provenance ts)."
                    },
                    "limit": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": 500,
                        "default": 200,
                        "description": "Max artifacts scanned (most-recent-first) and present-call rows fetched."
                    },
                    "kind": {
                        "type": "string",
                        "description": "Optional kind filter (table|markdown_table|html|svg|mermaid)."
                    },
                    "title": { "type": "string", "description": "Dashboard document title." },
                    "verify": {
                        "type": "boolean",
                        "default": true,
                        "description": "Self-verify embodiment by loading the dashboard in the browser and comparing the chain_head it renders to the lane's current chain_head (embody_status). Degrades to no_browser when no browser is available."
                    }
                }
            }),
        }
    }

    async fn execute(&self, args: Value, ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let window_secs = args
            .get("window_secs")
            .and_then(|v| v.as_i64())
            .unwrap_or(86_400)
            .clamp(60, 31_536_000);
        let limit = args
            .get("limit")
            .and_then(|v| v.as_u64())
            .unwrap_or(200)
            .clamp(1, 500) as usize;
        let kind_filter = args.get("kind").and_then(|v| v.as_str());
        let title = args.get("title").and_then(|v| v.as_str());
        let verify = args.get("verify").and_then(|v| v.as_bool()).unwrap_or(true);

        // Snapshot the lane state the dashboard will mirror, then render + write
        // the stable surface (refreshing the one tab the human keeps open).
        let snapshot =
            match dashboard_replay_snapshot(&store, window_secs, limit, kind_filter).await {
                Ok(s) => s,
                Err(e) => return Ok(ToolResult::error(e)),
            };
        let chain_head = snapshot
            .get("chain_head")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_string();

        let dir = crate::present::presentations_dir();
        let path = dir.join(format!("{}.html", crate::present::DASHBOARD_BASENAME));
        let html = crate::present::build_dashboard_html(&snapshot, title);
        if let Err(e) = crate::present::write_artifact_atomic(&path, &html) {
            return Ok(ToolResult::error(format!(
                "present_dashboard: write failed: {e}"
            )));
        }

        // Self-verify embodiment: load the surface, read the chain_head it shows,
        // and compare to the lane's head recomputed NOW (a genuine cross-check —
        // a concurrent present() that landed since the write makes the surface
        // honestly `stale`, not a fault).
        let mut embody_status = crate::present::EmbodyStatus::Skipped;
        let mut embody_detail: Option<String> = None;
        let mut screenshot_path: Option<String> = None;
        if verify {
            if let Err(e) = self.hub.security.check(Cap::Browser) {
                embody_status = crate::present::EmbodyStatus::NoBrowser;
                embody_detail = Some(format!("capability: {e}"));
            } else if let Some(b) = self.hub.browser.clone() {
                let file_url = format!("file://{}", path.display());
                match b.navigate(&file_url).await {
                    Ok(page) => {
                        match b.eval(&page, crate::present::DASHBOARD_READBACK_JS).await {
                            Ok(rv) => {
                                let readback = crate::present::parse_dashboard_readback(&rv);
                                // Compare the rendered head to the lane's CURRENT head,
                                // recomputed NOW — independent of the value we embedded.
                                // If the recompute fails we CANNOT confirm currency, so
                                // report `error` rather than fall back to the embedded
                                // head: comparing the DOM against the value we just
                                // embedded would be a self-fulfilling H==H check that
                                // could dishonestly report `embodied` (the lane never
                                // claims an embodiment it didn't verify).
                                match dashboard_replay_snapshot(
                                    &store,
                                    window_secs,
                                    limit,
                                    kind_filter,
                                )
                                .await
                                {
                                    Ok(s) => {
                                        let expected = s
                                            .get("chain_head")
                                            .and_then(|v| v.as_str())
                                            .unwrap_or("")
                                            .to_string();
                                        embody_status =
                                            crate::present::classify_embody(&readback, &expected);
                                        embody_detail = Some(format!(
                                            "dom_head={} expected_head={} rendered={} rows={}",
                                            short_head(&readback.chain_head),
                                            short_head(&expected),
                                            readback.rendered,
                                            readback.rows
                                        ));
                                    }
                                    Err(e) => {
                                        embody_status = crate::present::EmbodyStatus::Error;
                                        embody_detail = Some(format!(
                                            "verify-time chain_head recompute failed \
                                             (cannot confirm currency): {e}"
                                        ));
                                    }
                                }
                            }
                            Err(e) => {
                                embody_status = crate::present::EmbodyStatus::Error;
                                embody_detail = Some(format!("readback eval: {e}"));
                            }
                        }
                        if let Ok(bytes) = b.screenshot(&page).await {
                            let png =
                                dir.join(format!("{}.png", crate::present::DASHBOARD_BASENAME));
                            if std::fs::write(&png, bytes.as_ref()).is_ok() {
                                screenshot_path = Some(png.display().to_string());
                            }
                        }
                    }
                    Err(e) => {
                        embody_status = crate::present::EmbodyStatus::NoBrowser;
                        embody_detail = Some(format!("navigate: {e}"));
                    }
                }
            } else {
                embody_status = crate::present::EmbodyStatus::NoBrowser;
                embody_detail = Some("no browser backend configured".to_string());
            }
        }

        // Producer-side outcome sidecar: the dashboard is the FIRST producer to
        // populate the embody axis with a REAL value, so its embodiment outcome
        // enters the same queryable, gate-filtered stream as present()
        // (`present_outcomes`). The render axis is derived honestly from the embody
        // outcome (`EmbodyStatus::implied_verify_status`: a Stale surface rendered
        // real content so it's `rendered_ok`, and the `embody_status=stale` rung is
        // what — correctly — makes it ineligible; a Dead surface is `blank`). Only
        // an `embodied` dashboard passes `outcome_gate`; a stale/dead mirror is
        // never minted as a verified outcome. `chain_head` records the lane head the
        // surface mirrors (provenance). Best-effort — a sidecar write failure never
        // fails the call. Single basename → this reflects the LATEST embodiment.
        let dash_verify_method = if !verify {
            "none"
        } else if matches!(embody_status, crate::present::EmbodyStatus::NoBrowser) {
            "no_browser"
        } else {
            "browser_eval"
        };
        let outcome_record = json!({
            "artifact_id": crate::present::DASHBOARD_BASENAME,
            "intent": title.unwrap_or("E3 embodied mirror of the present_replay chain_head"),
            "action_tool": "present_dashboard",
            "kind": "dashboard",
            "verify_status": embody_status.implied_verify_status().as_str(),
            "embody_status": embody_status.as_str(),
            "verify_method": dash_verify_method,
            "chain_head": chain_head,
            "session_id": ctx.session_id.as_ref().map(|s| s.to_string()),
            "ts": crate::present::now_unix(),
        });
        let _ = crate::present::write_outcome_sidecar(
            &dir,
            crate::present::DASHBOARD_BASENAME,
            &outcome_record,
        );

        let result = json!({
            "schema": crate::present::PRESENT_DASHBOARD_SCHEMA,
            "dashboard_path": path.display().to_string(),
            "screenshot_path": screenshot_path,
            "chain_head": chain_head,
            "artifact_count": snapshot.get("artifact_count"),
            "present_calls_logged": snapshot.get("present_calls_logged"),
            "drift": snapshot.get("drift"),
            "dual_encoding_ok": snapshot.get("dual_encoding_ok"),
            "dual_encoding_missing": snapshot.get("dual_encoding_missing"),
            "embody_status": embody_status.as_str(),
            "embody_detail": embody_detail,
            "bytes": html.len(),
        });
        Ok(ToolResult::json_text(&result))
    }
}

/// Host-confirm path B (Linux Computer Use, thread 79): the present-lane decision
/// channel an Approve/Reject card needs. Renders a pending HOST desktop action's
/// summary + confirm token as an interactive card in the daemon's OWN browser, blocks
/// server-side until a human clicks (stamping `#ab-decision`), then reads the verdict
/// back via `eval` — turning a client-side click into a server-side decision with NO
/// new HTTP origin (the E3 readback-from-DOM pattern). It mints NO authority: Approve
/// only matters because the caller then presents the (human-minted, single-use, TTL'd)
/// token to `desktop_confirm`. Additive + isolated in `crate::present_approval` so it
/// does not perturb the present lane's existing one-way `file://` artifacts.
pub struct PresentApprovalTool {
    hub: Hub,
}
impl PresentApprovalTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for PresentApprovalTool {
    fn name(&self) -> &'static str {
        "present_await_decision"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Output-expression lane host-confirm card (path B): render a pending HOST \
                 desktop action (its `summary` + confirm `token`) as an Approve/Reject card in the \
                 daemon's browser and BLOCK until a human clicks, returning decision: \
                 approved|rejected|pending(timeout)|no_browser|error. The click stamps #ab-decision; \
                 the server reads it back via eval (no new HTTP origin). Mints no authority — on \
                 `approved`, call desktop_confirm(token) to execute the action (token is single-use + \
                 TTL'd). Mint the token first via desktop_invoke/desktop_action confirm_host:true. \
                 Degrades to no_browser when no browser is available."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "summary": { "type": "string", "description": "Human-readable description of the pending host action (from the confirm_host pending record's `summary`)." },
                    "token": { "type": "string", "description": "The single-use confirm token minted by desktop_invoke/desktop_action confirm_host:true." },
                    "title": { "type": "string", "description": "Optional card document title." },
                    "timeout_ms": { "type": "integer", "minimum": 1000, "maximum": 60000, "default": 60000, "description": "How long to block waiting for the human click before returning pending(timeout)." },
                    "simulate": { "type": "string", "enum": ["approve", "reject"], "description": "TEST/DEMO ONLY: stamp the decision via eval (no human). Production omits this. Does not weaken the model — eval-stamp is already possible to any browser-capable agent." }
                },
                "required": ["summary", "token"]
            }),
        }
    }

    async fn execute(&self, args: Value, ctx: &ToolContext) -> Result<ToolResult> {
        let summary = args.get("summary").and_then(|v| v.as_str()).unwrap_or("");
        let token = args.get("token").and_then(|v| v.as_str()).unwrap_or("");
        if summary.is_empty() || token.is_empty() {
            return Ok(present_approval_error(
                "missing_args",
                "both `summary` and `token` are required",
            ));
        }
        let title = args.get("title").and_then(|v| v.as_str());
        let timeout_ms = args
            .get("timeout_ms")
            .and_then(|v| v.as_u64())
            .unwrap_or(60_000)
            .clamp(1_000, 60_000);
        let simulate = args
            .get("simulate")
            .and_then(|v| v.as_str())
            .filter(|s| *s == "approve" || *s == "reject");

        let html = crate::present_approval::build_approval_html(summary, token, title);
        let dir = crate::present::presentations_dir();
        let safe_token: String = token
            .chars()
            .filter(|c| c.is_ascii_alphanumeric())
            .take(32)
            .collect();
        let path = dir.join(format!("_ab_approval_{safe_token}.html"));
        if let Err(e) = crate::present::write_artifact_atomic(&path, &html) {
            return Ok(present_approval_error(
                "write_failed",
                &format!("could not write approval card: {e}"),
            ));
        }
        let card_path = path.display().to_string();

        // Render the card in the daemon's own browser and block until a human decides.
        if let Err(e) = self.hub.security.check(Cap::Browser) {
            return Ok(present_approval_pending(
                "no_browser",
                token,
                summary,
                &card_path,
                &format!("capability: {e}"),
            ));
        }
        let b = match self.hub.browser.clone() {
            Some(b) => b,
            None => {
                return Ok(present_approval_pending(
                    "no_browser",
                    token,
                    summary,
                    &card_path,
                    "no browser backend configured",
                ))
            }
        };
        let file_url = format!("file://{}", path.display());
        let page = match b.navigate(&file_url).await {
            Ok(p) => p,
            Err(e) => {
                return Ok(present_approval_pending(
                    "no_browser",
                    token,
                    summary,
                    &card_path,
                    &format!("navigate: {e}"),
                ))
            }
        };
        // TEST/DEMO: stamp the decision so the wait_for resolves without a human.
        if let Some(sim) = simulate {
            let _ = b
                .eval(&page, &crate::present_approval::approval_stamp_js(sim))
                .await;
        }
        // Block until #ab-decision is stamped (human click), or timeout.
        let _ = b
            .wait_for(
                &page,
                Some(crate::present_approval::APPROVAL_DECIDED_SELECTOR),
                None,
                timeout_ms,
            )
            .await;
        let readback = match b
            .eval(&page, crate::present_approval::APPROVAL_READBACK_JS)
            .await
        {
            Ok(rv) => crate::present_approval::parse_approval_readback(&rv),
            Err(e) => {
                return Ok(present_approval_error(
                    "readback_failed",
                    &format!("decision readback eval: {e}"),
                ))
            }
        };
        let decision = crate::present_approval::classify_approval(&readback);
        // Provenance (narrows the last-mile: the readback proves the DOM was stamped,
        // not that a HUMAN stamped it — record where/when so the verdict is auditable;
        // who is not provable, the assurance leans on the daemon-owned page + token).
        let page_id = page.to_string();
        let decided_at = crate::present::now_unix();
        // Integrity: the card must have rendered THE token (verdict refers to this action).
        let token_match = readback.token == token;
        let approved = decision.is_approved() && token_match;
        // Tool-level status: a `Pending` that survived the wait_for window is a
        // timeout (fail-closed — never an approval). Dead/Approved/Rejected pass through.
        let decision_status = match decision {
            crate::present_approval::ApprovalDecision::Approved => "approved",
            crate::present_approval::ApprovalDecision::Rejected => "rejected",
            crate::present_approval::ApprovalDecision::Dead => "dead",
            crate::present_approval::ApprovalDecision::Pending => "timed_out",
        };

        // Slice A composition: the verdict IS a verified (intent→action→outcome)
        // record. Emit an outcome sidecar so the approval joins the present_outcomes
        // training-signal stream, where outcome_gate's human-decision axis treats a
        // real decided card (approved|rejected) as eligible and timed_out/dead as
        // rejected. Best-effort; never fails the call.
        let card_id = path
            .file_stem()
            .and_then(|s| s.to_str())
            .unwrap_or("")
            .to_string();
        let outcome = json!({
            "artifact_id": card_id,
            "intent": summary,
            "action_tool": "present_await_decision",
            "kind": "approval",
            "verify_status": "rendered_ok",
            "embody_status": crate::present::EmbodyStatus::NotApplicable.as_str(),
            "decision": decision_status,
            "verify_method": "human_decision",
            "token_match": token_match,
            "page_id": page_id,
            "decided_at": decided_at,
            "session_id": ctx.session_id.as_ref().map(|s| s.to_string()),
            "ts": decided_at,
        });
        let _ = crate::present::write_outcome_sidecar(&dir, &card_id, &outcome);

        let result = json!({
            "schema": crate::present_approval::PRESENT_APPROVAL_SCHEMA,
            "decision": decision_status,
            "approved": approved,
            "token": token,
            "token_match": token_match,
            "page_id": page_id,
            "decided_at": decided_at,
            "summary": summary,
            "card_path": card_path,
            "simulated": simulate.is_some(),
            "next": if approved {
                "approved — call desktop_confirm(token) to execute the action"
            } else {
                "not approved — do NOT execute; the token stays unconsumed"
            }
        });
        Ok(ToolResult::json_text(&result))
    }
}

fn present_approval_error(code: &str, message: &str) -> ToolResult {
    let mut r = ToolResult::json_text(&json!({
        "schema": "present_approval_error.v0",
        "status": "error",
        "error": { "code": code, "message": message }
    }));
    r.is_error = true;
    r
}

fn present_approval_pending(
    decision: &str,
    token: &str,
    summary: &str,
    card_path: &str,
    detail: &str,
) -> ToolResult {
    ToolResult::json_text(&json!({
        "schema": crate::present_approval::PRESENT_APPROVAL_SCHEMA,
        "decision": decision,
        "approved": false,
        "token": token,
        "summary": summary,
        "card_path": card_path,
        "detail": detail,
        "next": "not approved — do NOT execute; the token stays unconsumed"
    }))
}

/// Output-expression lane Slice A: READ-ONLY, falsifier-gated projection of the
/// `<id>.outcome.json` sidecars present() persists — the verified
/// (intent → action → outcome) training-signal stream. Applies the pure
/// `outcome_gate` (verify_status==rendered_ok and any present embody/interact
/// axis did not fail); `verified_only` (default) surfaces only eligible records
/// while the tallies always reflect the full set. Produces the stream; consuming
/// it (memory ingestion, a learner) is a separate lane's slice.
pub struct PresentOutcomesTool {
    _hub: Hub,
}
impl PresentOutcomesTool {
    pub fn new(hub: Hub) -> Self {
        Self { _hub: hub }
    }
}

#[async_trait]
impl McpTool for PresentOutcomesTool {
    fn name(&self) -> &'static str {
        "present_outcomes"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Output-expression lane Slice A: READ-ONLY, falsifier-gated stream of \
                 verified (intent → action → outcome) records. Reads the `<id>.outcome.json` \
                 sidecars present() writes after self-verify and applies the outcome gate \
                 (eligible iff verify_status=rendered_ok AND any present embodiment/interactivity \
                 axis did not fail). With verified_only=true (default) only eligible records are \
                 surfaced, but eligible_count/rejected_count ALWAYS reflect the full set (a \
                 consumer never mistakes a filtered list for 'all verified'). Each surfaced record \
                 carries eligible + gate_reason. This is the training-signal stream a downstream \
                 consumer (memory ingestion, a learner) would read; it never claims a verified \
                 label it didn't earn."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "window_secs": {
                        "type": "integer",
                        "minimum": 60,
                        "maximum": 31536000,
                        "default": 86400,
                        "description": "Look-back window over outcome records (by ts)."
                    },
                    "limit": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": 1000,
                        "default": 200,
                        "description": "Max records scanned (most-recent-first)."
                    },
                    "verified_only": {
                        "type": "boolean",
                        "default": true,
                        "description": "When true, surface only gate-eligible (verified) records; tallies still reflect the full set. False surfaces all records annotated with eligible + gate_reason."
                    }
                }
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let window_secs = args
            .get("window_secs")
            .and_then(|v| v.as_i64())
            .unwrap_or(86_400)
            .clamp(60, 31_536_000);
        let limit = args
            .get("limit")
            .and_then(|v| v.as_u64())
            .unwrap_or(200)
            .clamp(1, 1000) as usize;
        let verified_only = args
            .get("verified_only")
            .and_then(|v| v.as_bool())
            .unwrap_or(true);

        let now = dispatch_now_secs();
        let cutoff = now.saturating_sub(window_secs).max(0) as u64;
        let dir = crate::present::presentations_dir();
        let records = crate::present::read_outcome_records(&dir, limit, cutoff);
        let mut projection = crate::present::present_outcomes_projection(&records, verified_only);
        if let Some(obj) = projection.as_object_mut() {
            obj.insert("schema".into(), json!("present_outcomes/v0"));
            obj.insert("dir".into(), json!(dir.display().to_string()));
            obj.insert("window_secs".into(), json!(window_secs));
            obj.insert("generated_at".into(), json!(now.max(0)));
        }
        Ok(ToolResult::json_text(&projection))
    }
}

/// LSWR Step E2: READ-ONLY admission projection over Step D present artifacts.
///
/// Reads persisted `present` HTML artifacts, filters to dual-encoded LSWR Step D
/// packets, applies the pure Step E1 classifier, and reports class/reason
/// counts. Writes nothing and never calls the #94 ingestion path.
