pub struct ForumPostTool {
    hub: Hub,
}
impl ForumPostTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for ForumPostTool {
    fn name(&self) -> &'static str {
        "forum_post"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Append a post to a thread (provide `thread_id`) or create a new thread \
                 (provide `board` + `title`, omit `thread_id`). `author` is REQUIRED — \
                 use a stable session id so multi-process collaboration stays readable. \
                 `kind` ∈ {msg, finding, question, decision, reply}. `refs` is opaque \
                 JSON, conventionally `{memory_keys:[...], files:[...], parent_post_id:N}`. \
                 Set `peer: \"host:port\"` to post into a remote tailnet peer's forum \
                 instead of local; omit for local-only."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "thread_id":  { "type": "integer", "description": "Existing thread id; omit to create a new thread." },
                    "board":      { "type": "string",  "description": "Board name (required when creating a new thread). E.g. 'general', 'design', 'incidents'." },
                    "title":      { "type": "string",  "description": "Thread title (required when creating)." },
                    "author":     { "type": "string",  "description": "Author session id (REQUIRED, non-empty)." },
                    "kind":       { "type": "string",  "default": "msg", "description": "msg | finding | question | decision | reply" },
                    "body":       { "type": "string",  "description": "Post body (required, non-empty)." },
                    "refs":       { "type": "object",  "description": "Opaque JSON — e.g. {memory_keys:[...], files:[...], parent_post_id:N}." },
                    "tags":       { "type": "array",   "items": {"type": "string"}, "description": "Tags applied when creating a new thread." },
                    "peer":       { "type": "string",  "description": "Optional tailnet peer host:port; if set, post via that daemon-http instead of local. (v20)" }
                },
                "required": ["author", "body"]
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let thread_id = args.get("thread_id").and_then(|v| v.as_i64());
        let board = args.get("board").and_then(|v| v.as_str());
        let title = args.get("title").and_then(|v| v.as_str());
        let author = match args
            .get("author")
            .and_then(|v| v.as_str())
            .filter(|s| !s.trim().is_empty())
        {
            Some(s) => s,
            None => return Ok(ToolResult::error("missing or empty 'author'")),
        };
        let kind = args.get("kind").and_then(|v| v.as_str()).unwrap_or("msg");
        let body = match args.get("body").and_then(|v| v.as_str()) {
            Some(s) if !s.trim().is_empty() => s,
            _ => return Ok(ToolResult::error("missing or empty 'body'")),
        };
        let refs = args.get("refs").cloned();
        let tags: Option<Vec<String>> = args.get("tags").and_then(|v| v.as_array()).map(|arr| {
            arr.iter()
                .filter_map(|v| v.as_str().map(|s| s.to_string()))
                .collect()
        });
        let peer = args
            .get("peer")
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty());

        if let Some(p) = peer {
            // Remote write — daemon owns the SQLite WAL on its node.
            let req = crate::peer_client::ForumPostRequest {
                author,
                body,
                thread_id,
                board,
                title,
                kind: Some(kind),
                tags: tags.as_deref(),
                refs: refs.as_ref(),
            };
            let v = crate::peer_client::forum_post(p, req)
                .await
                .map_err(|e| ab_core::Error::Backend(format!("forum_post peer: {e}")))?;
            return Ok(ToolResult::json_text(&json!({
                "status": v.get("status").cloned().unwrap_or(json!("ok")),
                "thread_id": v.get("thread_id"),
                "post_id": v.get("post_id"),
                "created_thread": v.get("created_thread"),
                "peer": peer,
            })));
        }

        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no memory store configured")),
        };
        let outcome = store
            .forum_post(
                thread_id,
                board,
                title,
                author,
                kind,
                body,
                refs.as_ref(),
                tags.as_deref(),
            )
            .await
            .map_err(|e| ab_core::Error::Backend(format!("forum_post: {e}")))?;

        // C3 S6 — post-write race-detection. Re-SELECT the row we just
        // claimed to insert, retrying up to 3× with 50ms gap to tolerate
        // read-replica lag (per DESIGN-COLLAB-PROTOCOL-v0.md §3.4.4). On
        // miss/mismatch fire an OOB alert (no SQLite writes — write path
        // is itself the suspect channel) and return an error to the
        // client. Misses are global-rate-limited 1h to avoid spam.
        if !verify_forum_post_write(&store, outcome.post_id, author, body, kind).await {
            let sig = format!("post_id={}", outcome.post_id);
            let fire = match crate::c3_self_check::rate_limiter().lock() {
                Ok(mut g) => g.check_and_record(format!("s6:{sig}"), std::time::Instant::now()),
                Err(_) => true,
            };
            if fire {
                let alert = ab_oob_alert::Alert::new(ab_oob_alert::AlertKind::PostWriteRaceMiss)
                    .with_evidence(json!({
                        "post_id": outcome.post_id,
                        "thread_id": outcome.thread_id,
                        "author": author,
                        "kind": kind,
                        "body_len": body.len(),
                    }))
                    .with_suggested_action(
                        "inspect /proc/<PID>/fd/* for state.db inode divergence; \
                         run `agent-bridge rescue-snapshot --canonical` if split-brain"
                            .to_string(),
                    )
                    .with_next_steps(vec![
                        "see lesson_split_brain_forum_id_collision".into(),
                        "see thread 10 #136 — original S6 case".into(),
                    ]);
                let _ = ab_oob_alert::write_alert(&alert);
            }
            return Err(ab_core::Error::Backend(format!(
                "forum_post: S6 post-write verify failed (post_id={} not found or content mismatch after 3 retries — likely split-brain state.db). Alert: {}.",
                outcome.post_id,
                if fire { "fired" } else { "rate-limited" }
            )));
        }

        Ok(ToolResult::json_text(&json!({
            "status": "ok",
            "thread_id": outcome.thread_id,
            "post_id": outcome.post_id,
            "created_thread": outcome.created_thread
        })))
    }
}

/// C3 S6 — verify a freshly inserted forum_post row is readable with the
/// content we claimed to write. Retries up to 3× with 50ms gaps to absorb
/// SQLite read-replica lag (per design §3.4.4). Returns `true` on match,
/// `false` on miss-or-mismatch after all retries.
async fn verify_forum_post_write(
    store: &std::sync::Arc<dyn ab_store::StateStore>,
    post_id: i64,
    expected_author: &str,
    expected_body: &str,
    expected_kind: &str,
) -> bool {
    for attempt in 0..3 {
        if attempt > 0 {
            tokio::time::sleep(std::time::Duration::from_millis(50)).await;
        }
        if let Ok(Some(rec)) = store.forum_post_get(post_id).await {
            if rec.author == expected_author
                && rec.body == expected_body
                && rec.kind == expected_kind
            {
                return true;
            }
            // Found row but content mismatched — split-brain. No point retrying.
            return false;
        }
    }
    false
}

pub struct ForumReadTool {
    hub: Hub,
}
impl ForumReadTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for ForumReadTool {
    fn name(&self) -> &'static str {
        "forum_read"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Fetch posts from a thread (set `thread_id`) or across a board \
                 (set `board`). Posts are ordered by id ASC; use `since_post_id` \
                 as an exclusive cursor. When `unread_for` is set, the cursor is \
                 inferred from this session's subscription (thread > board) and \
                 the cursor is auto-advanced after the read. Limit clamped 1–500.\n\n\
                 IMPORTANT — auto-advance is scope-symmetric: a thread-scoped read \
                 only advances a *thread* subscription cursor; it will NOT touch a \
                 board-level cursor (because that would wrongly mark unread posts in \
                 sibling threads as seen). If you want unread tracking on a thread, \
                 call `forum_subscribe` with scope_kind='thread'. Board subscriptions \
                 are best for casual lurking; thread subscriptions for active \
                 follow-along.\n\n\
                 Set `peer: \"host:port\"` to read from a remote tailnet peer's \
                 daemon-http; omit for local-only. NOTE: `unread_for` cursor advance \
                 is local-only and is silently ignored when `peer` is set (the \
                 remote daemon doesn't carry your subscription state).\n\n\
                 Output projection: in Codex compact toolsets, omitted projection args \
                 default to a compact body preview and omit refs; other clients default \
                 to full posts. Set `compact:false`, `body_max_chars:0`, and \
                 `include_refs:true` when you need verbatim full posts."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "thread_id":     { "type": "integer", "description": "Read posts in this thread." },
                    "board":         { "type": "string",  "description": "Read posts across this board (used when thread_id is absent)." },
                    "since_post_id": { "type": "integer", "description": "Exclusive cursor — only posts with id > this." },
                    "unread_for":    { "type": "string",  "description": "Session id; reads from that session's subscription cursor and advances it. (local-only)" },
                    "limit":         { "type": "integer", "default": 50, "description": "Max rows (1–500). Omitted = 8 in compact output, 50 otherwise." },
                    "peer":          { "type": "string",  "description": "Optional tailnet peer host:port; if set, query that daemon-http instead of local. (v20)" },
                    "compact":       { "type": "boolean", "description": "Use compact projection defaults. Omitted = true for Codex compact toolsets, false otherwise." },
                    "body_max_chars": { "type": "integer", "description": "Per-post body preview length. 0 disables truncation. Omitted = 2000 in compact output, 0 otherwise." },
                    "include_refs":  { "type": "boolean", "description": "Include refs JSON for each post. Omitted = false in compact output, true otherwise." }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let thread_id = args.get("thread_id").and_then(|v| v.as_i64());
        let board = args.get("board").and_then(|v| v.as_str());
        if thread_id.is_none() && board.map(|s| s.is_empty()).unwrap_or(true) {
            return Ok(ToolResult::error(
                "provide at least one of 'thread_id' or 'board'",
            ));
        }
        let since_post_id = args.get("since_post_id").and_then(|v| v.as_i64());
        let unread_for = args
            .get("unread_for")
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty());
        let compact = args
            .get("compact")
            .and_then(|v| v.as_bool())
            .unwrap_or_else(compact_mcp_output_default);
        let limit = args
            .get("limit")
            .and_then(|v| v.as_u64())
            .map(|v| v.clamp(1, 500) as u32)
            .unwrap_or(if compact {
                FORUM_READ_COMPACT_DEFAULT_LIMIT
            } else {
                FORUM_READ_DEFAULT_LIMIT
            });
        let peer = args
            .get("peer")
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty());
        let body_max_chars = args
            .get("body_max_chars")
            .and_then(|v| v.as_u64())
            .map(|v| v.min(100_000) as usize)
            .unwrap_or(if compact { 2_000 } else { 0 });
        let include_refs = args
            .get("include_refs")
            .and_then(|v| v.as_bool())
            .unwrap_or(!compact);

        let (posts, next_cursor, truncated_posts) = if let Some(p) = peer {
            // Drop unread_for when going remote — cursor state is per-device.
            let response = crate::peer_client::forum_read_projected(
                p,
                thread_id,
                board,
                since_post_id,
                None,
                limit,
                compact,
                body_max_chars,
                include_refs,
            )
            .await
            .map_err(|e| ab_core::Error::Backend(format!("forum_read peer: {e}")))?;
            let next_cursor = response.next_cursor.or_else(|| {
                response
                    .posts
                    .last()
                    .and_then(|p| p.get("id"))
                    .and_then(|v| v.as_i64())
            });
            if let Some(projection) = response.projection.as_ref() {
                let truncated_posts = projection
                    .get("truncated_posts")
                    .and_then(|v| v.as_u64())
                    .unwrap_or(0) as usize;
                (response.posts, next_cursor, truncated_posts)
            } else {
                // Backward compatibility for peers older than the HTTP compact
                // projection: they return full ForumPostRecord rows and ignore
                // projection query params, so compact locally before replying to
                // this MCP client.
                let raw_posts: Vec<ForumPostRecord> = response
                    .posts
                    .into_iter()
                    .map(|v| {
                        serde_json::from_value(v).map_err(|e| {
                            ab_core::Error::Backend(format!(
                                "forum_read peer projection fallback: {e}"
                            ))
                        })
                    })
                    .collect::<Result<Vec<_>>>()?;
                let next_cursor = next_cursor.or_else(|| raw_posts.last().map(|p| p.id));
                let (posts, truncated_posts) =
                    project_forum_posts(&raw_posts, body_max_chars, include_refs);
                (posts, next_cursor, truncated_posts)
            }
        } else {
            let store = match &self.hub.store {
                Some(s) => s.clone(),
                None => return Ok(ToolResult::error("no memory store configured")),
            };
            let raw_posts = store
                .forum_read(thread_id, board, since_post_id, unread_for, limit)
                .await
                .map_err(|e| ab_core::Error::Backend(format!("forum_read: {e}")))?;
            let next_cursor = raw_posts.last().map(|p| p.id);
            let (posts, truncated_posts) =
                project_forum_posts(&raw_posts, body_max_chars, include_refs);
            (posts, next_cursor, truncated_posts)
        };

        Ok(ToolResult::json_text(&json!({
            "thread_id": thread_id,
            "board": board,
            "count": posts.len(),
            "next_cursor": next_cursor,
            "posts": posts,
            "peer": peer,
            "projection": {
                "compact": compact,
                "body_max_chars": body_max_chars,
                "include_refs": include_refs,
                "limit": limit,
                "truncated_posts": truncated_posts
            }
        })))
    }
}

pub struct ForumSubscribeTool {
    hub: Hub,
}
impl ForumSubscribeTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for ForumSubscribeTool {
    fn name(&self) -> &'static str {
        "forum_subscribe"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Register `session_id`'s interest in a thread or board. Idempotent: \
                 re-subscribing keeps the existing `last_seen_post_id` unless `reset=true`. \
                 `scope_kind` ∈ {thread, board}. For threads, `scope_value` is the \
                 numeric thread id as a string; for boards, the board name.\n\n\
                 RULE OF THUMB: subscribe at the same scope you intend to read at. \
                 Board subscription = casual lurking on a whole board (unread_count \
                 in `forum_list_threads` is computed against this cursor as a backstop). \
                 Thread subscription = active follow-along on a topic; only thread-\
                 scoped reads will auto-advance this cursor.\n\n\
                 NOTE: `forum_subscribe` is local-only — subscriptions track each \
                 device's read cursor and are intentionally not synced. To follow a \
                 remote peer's thread, subscribe locally to that thread/board id."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "session_id":  { "type": "string", "description": "Subscriber session id (REQUIRED)." },
                    "scope_kind":  { "type": "string", "enum": ["thread", "board"] },
                    "scope_value": { "type": "string", "description": "Thread id (as string) or board name." },
                    "reset":       { "type": "boolean", "default": false, "description": "Reset cursor to 0." }
                },
                "required": ["session_id", "scope_kind", "scope_value"]
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no memory store configured")),
        };
        let session_id = match args
            .get("session_id")
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty())
        {
            Some(s) => s,
            None => return Ok(ToolResult::error("missing or empty 'session_id'")),
        };
        let scope_kind = match args.get("scope_kind").and_then(|v| v.as_str()) {
            Some(s) => s,
            None => return Ok(ToolResult::error("missing 'scope_kind'")),
        };
        let scope_value = match args
            .get("scope_value")
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty())
        {
            Some(s) => s,
            None => return Ok(ToolResult::error("missing or empty 'scope_value'")),
        };
        let reset = args.get("reset").and_then(|v| v.as_bool()).unwrap_or(false);

        store
            .forum_subscribe(session_id, scope_kind, scope_value, reset)
            .await
            .map_err(|e| ab_core::Error::Backend(format!("forum_subscribe: {e}")))?;
        Ok(ToolResult::json_text(&json!({
            "status": "ok",
            "session_id": session_id,
            "scope_kind": scope_kind,
            "scope_value": scope_value,
            "reset": reset
        })))
    }
}

pub struct ForumListThreadsTool {
    hub: Hub,
}
impl ForumListThreadsTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for ForumListThreadsTool {
    fn name(&self) -> &'static str {
        "forum_list_threads"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "List threads on a `board`, ordered by `last_post_at DESC`. When \
                 `unread_for` is set, each row's `unread_count` is filled relative \
                 to that session's subscription cursors (thread cursor wins over \
                 board cursor; missing cursor counts as 0). Optional `status` \
                 filter ∈ {open, resolved, archived}. Set `peer: \"host:port\"` to \
                 query a remote tailnet peer's daemon-http instead of local store; \
                 omit for local-only."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "board":      { "type": "string", "description": "Board name (REQUIRED)." },
                    "unread_for": { "type": "string", "description": "Session id — fills unread_count per thread." },
                    "status":     { "type": "string", "enum": ["open", "resolved", "archived"] },
                    "limit":      { "type": "integer", "default": 50, "description": "Max rows (1–500)." },
                    "peer":       { "type": "string", "description": "Optional tailnet peer host:port; if set, query that daemon-http instead of local. (v20)" }
                },
                "required": ["board"]
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let board = match args
            .get("board")
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty())
        {
            Some(s) => s,
            None => return Ok(ToolResult::error("missing or empty 'board'")),
        };
        let unread_for = args
            .get("unread_for")
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty());
        let status = args
            .get("status")
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty());
        let limit = args
            .get("limit")
            .and_then(|v| v.as_u64())
            .unwrap_or(50)
            .clamp(1, 500) as u32;
        let peer = args
            .get("peer")
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty());

        let threads = if let Some(p) = peer {
            crate::peer_client::forum_list_threads(p, board, unread_for, status, limit)
                .await
                .map_err(|e| ab_core::Error::Backend(format!("forum_list_threads peer: {e}")))?
        } else {
            let store = match &self.hub.store {
                Some(s) => s.clone(),
                None => return Ok(ToolResult::error("no memory store configured")),
            };
            store
                .forum_list_threads(board, unread_for, status, limit)
                .await
                .map_err(|e| ab_core::Error::Backend(format!("forum_list_threads: {e}")))?
        };
        Ok(ToolResult::json_text(&json!({
            "board": board,
            "count": threads.len(),
            "threads": threads,
            "peer": peer
        })))
    }
}

pub struct ForumSetThreadStatusTool {
    hub: Hub,
}
impl ForumSetThreadStatusTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for ForumSetThreadStatusTool {
    fn name(&self) -> &'static str {
        "forum_set_thread_status"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Set a forum thread's lifecycle status. `status` ∈ \
                 {open, resolved, archived}. Use `resolved` when the discussion \
                 reached a conclusion (decision logged, finding actioned); \
                 `archived` when the thread is no longer relevant but kept for \
                 history. `forum_list_threads` accepts a matching `status` filter."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "thread_id": { "type": "integer", "description": "Numeric thread id (REQUIRED)." },
                    "status":    { "type": "string",  "enum": ["open", "resolved", "archived"] }
                },
                "required": ["thread_id", "status"]
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no memory store configured")),
        };
        let thread_id = match args.get("thread_id").and_then(|v| v.as_i64()) {
            Some(n) if n > 0 => n,
            _ => return Ok(ToolResult::error("missing or invalid 'thread_id'")),
        };
        let status = match args
            .get("status")
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty())
        {
            Some(s) => s,
            None => return Ok(ToolResult::error("missing or empty 'status'")),
        };
        if !matches!(status, "open" | "resolved" | "archived") {
            return Ok(ToolResult::error(
                "'status' must be one of: open, resolved, archived",
            ));
        }

        store
            .forum_set_thread_status(thread_id, status)
            .await
            .map_err(|e| ab_core::Error::Backend(format!("forum_set_thread_status: {e}")))?;
        Ok(ToolResult::json_text(&json!({
            "status": "ok",
            "thread_id": thread_id,
            "new_status": status
        })))
    }
}

// ===========================================================================
//                       forum_digest (read-efficiency at scale)
// ===========================================================================
//
// See docs/DESIGN-forum-digest-and-sediment-triggers-2026-05-23.md.
// Rule-based structural digest of open threads so the agent reads ~N compact
// thread summaries instead of raw posts (verify: 736 open posts ≈ 455k tokens
// full-scan; digest targets ≤1500). Pure SQL, no LLM (v0). pull-not-push.

/// Extract a one-line title from a forum post body: first non-empty line with
/// leading markdown header markers (`#`, `##`, …) and whitespace stripped,
/// truncated to `max_chars`. Pure for testability.
fn forum_digest_title(body: &str, max_chars: usize) -> String {
    let first = body
        .lines()
        .map(str::trim)
        .find(|l| !l.is_empty())
        .unwrap_or("");
    let stripped = first.trim_start_matches('#').trim();
    let (truncated, did_trunc, _) = truncate_chars(stripped, max_chars);
    if did_trunc {
        format!("{truncated}…")
    } else {
        truncated
    }
}

/// Build the digest block for a single thread. Pure: caller supplies the
/// thread record + its recent posts (newest-first NOT required; we sort).
/// `my_sigil` (when set) flags posts that mention it with no later post
/// authored by the same sigil = "needs reply".
fn forum_digest_thread_block(
    thread: &ab_store::ForumThreadRecord,
    posts: &[ab_store::ForumPostRecord],
    my_sigil: Option<&str>,
    now_secs: i64,
) -> Vec<String> {
    let days_idle = ((now_secs - thread.last_post_at).max(0)) / 86_400;
    let mut lines = vec![format!(
        "[{}] {} ({} posts · {}d idle · {})",
        thread.id,
        forum_digest_title(&thread.title, 60),
        thread.post_count,
        days_idle,
        thread.board,
    )];

    // Posts sorted ascending by id for lineage + latest-per-author.
    let mut sorted: Vec<&ab_store::ForumPostRecord> = posts.iter().collect();
    sorted.sort_by_key(|p| p.id);

    // latest-per-author: last word from each distinct author (insertion order
    // by most-recent post).
    let mut latest: Vec<(String, i64)> = Vec::new();
    for p in sorted.iter().rev() {
        if !latest.iter().any(|(a, _)| a == &p.author) {
            latest.push((p.author.clone(), p.id));
        }
    }
    if !latest.is_empty() {
        let who: Vec<String> = latest
            .iter()
            .take(5)
            .map(|(a, id)| format!("{a}(#{id})"))
            .collect();
        lines.push(format!("  active: {}", who.join(", ")));
    }

    // decisions + findings = the durable spine (titles only).
    let decisions: Vec<String> = sorted
        .iter()
        .filter(|p| p.kind == "decision")
        .rev()
        .take(4)
        .map(|p| format!("«{}»", forum_digest_title(&p.body, 50)))
        .collect();
    if !decisions.is_empty() {
        lines.push(format!("  decisions: {}", decisions.join(" ")));
    }

    // open questions (v0: list recent questions; answered-detection is v1).
    let questions: Vec<String> = sorted
        .iter()
        .filter(|p| p.kind == "question")
        .rev()
        .take(3)
        .map(|p| format!("«{}»", forum_digest_title(&p.body, 50)))
        .collect();
    if !questions.is_empty() {
        lines.push(format!("  open-q: {}", questions.join(" ")));
    }

    // @me unaddressed: a post mentions my sigil, and no LATER post in this
    // thread is authored by my sigil.
    if let Some(sig) = my_sigil {
        let my_last_authored: i64 = sorted
            .iter()
            .filter(|p| p.author.contains(sig))
            .map(|p| p.id)
            .max()
            .unwrap_or(0);
        let pending: Vec<String> = sorted
            .iter()
            .filter(|p| p.id > my_last_authored && !p.author.contains(sig) && p.body.contains(sig))
            .map(|p| format!("#{} by {}", p.id, p.author))
            .collect();
        if !pending.is_empty() {
            lines.push(format!("  ⚠ @me needs-reply: {}", pending.join(", ")));
        }
    }

    lines
}

pub struct ForumDigestTool {
    hub: Hub,
}
impl ForumDigestTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for ForumDigestTool {
    fn name(&self) -> &'static str {
        "forum_digest"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Compact rule-based digest of forum threads (default status=open). \
                 Omit `board` for all boards, or set `board=announcements` (etc.) to \
                 focus on one board. One short block per thread: header \
                 (id/title/post_count/days_idle/board), active authors, decision \
                 + finding titles, open questions, and — when `my_sigil` is set — \
                 posts mentioning you with no later reply from you (needs-reply). \
                 Read this INSTEAD of forum_read for 'what's the board state'; use \
                 forum_read to deep-dive one thread. Token-budgeted (default ≤1800)."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "status":          { "type": "string", "enum": ["open", "resolved", "archived"], "default": "open" },
                    "board":           { "type": "string", "description": "Optional board filter (e.g. announcements, design). Omit for all boards." },
                    "thread_limit":    { "type": "integer", "default": 30, "description": "Max threads to digest (1–200)." },
                    "posts_per_thread":{ "type": "integer", "default": 60, "description": "Recent posts scanned per thread for extraction (1–200)." },
                    "my_sigil":        { "type": "string", "description": "Your author sigil (e.g. '#3b568a5f' or full id) — enables needs-reply detection." },
                    "max_tokens":      { "type": "integer", "default": 1800, "description": "Hard cap on digest output tokens." }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no memory store configured")),
        };
        let status = args
            .get("status")
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty())
            .unwrap_or("open");
        let board = args
            .get("board")
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty());
        let thread_limit = args
            .get("thread_limit")
            .and_then(|v| v.as_u64())
            .unwrap_or(30)
            .clamp(1, 200) as u32;
        let posts_per_thread = args
            .get("posts_per_thread")
            .and_then(|v| v.as_u64())
            .unwrap_or(60)
            .clamp(1, 200) as u32;
        let my_sigil = args
            .get("my_sigil")
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty());
        let max_tokens = args
            .get("max_tokens")
            .and_then(|v| v.as_u64())
            .unwrap_or(1800)
            .clamp(200, 20_000) as usize;

        let threads = store
            .forum_digest_threads(Some(status), board, thread_limit)
            .await
            .map_err(|e| ab_core::Error::Backend(format!("forum_digest_threads: {e}")))?;

        if threads.is_empty() {
            let board_note = board.map(|b| format!(" on board={b}")).unwrap_or_default();
            return Ok(ToolResult::text(format!(
                "(no {status} threads{board_note})"
            )));
        }

        let now_secs = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_secs() as i64)
            .unwrap_or(0);

        let header = match board {
            Some(b) => format!(
                "=== Forum Digest ({} {status} threads · board={b}) ===",
                threads.len()
            ),
            None => format!("=== Forum Digest ({} {status} threads) ===", threads.len()),
        };
        let mut lines: Vec<String> = vec![header, String::new()];
        let mut budget_hit = false;
        let mut rendered = 0usize;
        for thread in &threads {
            let posts = store
                .forum_recent_posts(thread.id, posts_per_thread)
                .await
                .unwrap_or_default();
            let block = forum_digest_thread_block(thread, &posts, my_sigil, now_secs);
            // Stop before exceeding budget; note how many threads were skipped.
            let projected = estimate_tokens_from_text(&lines.join("\n")) as usize
                + estimate_tokens_from_text(&block.join("\n")) as usize;
            if projected > max_tokens && rendered > 0 {
                budget_hit = true;
                break;
            }
            lines.extend(block);
            lines.push(String::new());
            rendered += 1;
        }
        if budget_hit {
            lines.push(format!(
                "[…{} more threads omitted for token budget — raise max_tokens or filter status]",
                threads.len() - rendered
            ));
        }

        Ok(ToolResult::text(lines.join("\n")))
    }
}

// ===========================================================================
//                       presence (v19) — identity + heartbeat
// ===========================================================================

/// Resolve the canonical `node:project:role[:tag]` session id from env + args.
/// Pure helper used by both `session_identity` and the announce tool default.
fn resolve_identity(
    role: Option<&str>,
    tag: Option<&str>,
    node_arg: Option<&str>,
    project_arg: Option<&str>,
    cwd_arg: Option<&str>,
) -> (String, String, String, Option<String>, String) {
    let node = node_arg
        .map(|s| s.to_string())
        .or_else(|| std::env::var("AGENT_BRIDGE_NODE").ok())
        .unwrap_or_else(|| {
            std::fs::read_to_string("/etc/hostname")
                .map(|s| s.trim().to_string())
                .ok()
                .filter(|s| !s.is_empty())
                .or_else(|| {
                    std::process::Command::new("hostname")
                        .output()
                        .ok()
                        .and_then(|o| String::from_utf8(o.stdout).ok())
                        .map(|s| s.trim().to_string())
                        .filter(|s| !s.is_empty())
                })
                .unwrap_or_else(|| "unknown".into())
        });
    let project = project_arg
        .map(|s| s.to_string())
        .or_else(|| std::env::var("AGENT_BRIDGE_PROJECT").ok())
        .or_else(|| {
            cwd_arg
                .map(std::path::Path::new)
                .or_else(|| {
                    static EMPTY: std::sync::OnceLock<std::path::PathBuf> =
                        std::sync::OnceLock::new();
                    let _ = EMPTY.set(std::path::PathBuf::new());
                    None
                })
                .and_then(|p| {
                    p.file_name()
                        .and_then(|n| n.to_str().map(|s| s.to_string()))
                })
        })
        .or_else(|| {
            std::env::current_dir().ok().and_then(|p| {
                p.file_name()
                    .and_then(|n| n.to_str().map(|s| s.to_string()))
            })
        })
        .unwrap_or_else(|| "unknown".into());
    let role = role.unwrap_or("main").to_string();
    let tag = tag.filter(|s| !s.is_empty()).map(|s| s.to_string());
    let session_id = match &tag {
        Some(t) => format!("{node}:{project}:{role}:{t}"),
        None => format!("{node}:{project}:{role}"),
    };
    (node, project, role, tag, session_id)
}

/// Freshness window (seconds) that defines a "fresh sibling" presence row.
/// Within this window of last_heartbeat_at, we consider the canonical id
/// taken; older rows are presumed crashed/idle and the id is reusable.
const PRESENCE_FRESH_SECS: i64 = 60;
const IDENTITY_REGISTRY_SCHEMA: &str = "agent_bridge_session_identity_registry.v0";
const IDENTITY_REGISTRY_TTL_SECS: i64 = 24 * 60 * 60;
const IDENTITY_REGISTRY_LOCK_STALE_SECS: i64 = 30;

/// Render the bottom 16 bits of a u32 pid as 4 lowercase hex chars,
/// matching the convention documented in DESIGN-v19 (e.g. `7f3a`).
fn pid_tag_short(pid: u32) -> String {
    format!("{:04x}", pid & 0xffff)
}

fn agent_bridge_data_dir_for_identity() -> Option<PathBuf> {
    let home = std::env::var("HOME").ok().map(PathBuf::from)?;

    #[cfg(target_os = "linux")]
    {
        if let Ok(xdg) = std::env::var("XDG_DATA_HOME") {
            return Some(PathBuf::from(xdg).join("agent-bridge"));
        }
    }

    #[cfg(target_os = "macos")]
    {
        Some(home.join("Library/Application Support/agent-bridge"))
    }

    #[cfg(not(target_os = "macos"))]
    {
        Some(home.join(".local/share/agent-bridge"))
    }
}

fn identity_registry_path() -> Option<PathBuf> {
    std::env::var("AGENT_BRIDGE_IDENTITY_REGISTRY")
        .ok()
        .filter(|s| !s.trim().is_empty())
        .map(PathBuf::from)
        .or_else(|| {
            agent_bridge_data_dir_for_identity()
                .map(|dir| dir.join("session-identity-registry.json"))
        })
}

#[derive(Clone, Debug, serde::Deserialize, serde::Serialize)]
struct IdentityRegistry {
    schema: String,
    entries: Vec<IdentityRegistryEntry>,
}

#[derive(Clone, Debug, serde::Deserialize, serde::Serialize)]
struct IdentityRegistryEntry {
    bare_id: String,
    owner_key: String,
    tag: Option<String>,
    pid: Option<i64>,
    created_at_unix: i64,
    last_seen_unix: i64,
    cwd: Option<String>,
}

impl Default for IdentityRegistry {
    fn default() -> Self {
        Self {
            schema: IDENTITY_REGISTRY_SCHEMA.to_string(),
            entries: Vec::new(),
        }
    }
}

fn now_unix_i64() -> i64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0)
}

fn session_identity_owner_key(ctx: &ToolContext) -> String {
    if let Some(session_id) = &ctx.session_id {
        return format!("mcp:{}", session_id.as_str());
    }

    static OWNER_KEY: std::sync::OnceLock<String> = std::sync::OnceLock::new();
    OWNER_KEY
        .get_or_init(|| {
            let pid = std::process::id();
            let stamp = now_unix_i64();
            format!("process:{pid}:{stamp}")
        })
        .clone()
}

fn identity_registry_entry_fresh(entry: &IdentityRegistryEntry, now: i64) -> bool {
    now - entry.last_seen_unix <= IDENTITY_REGISTRY_TTL_SECS
}

fn identity_registry_entry_alive_for_other_owner(entry: &IdentityRegistryEntry, now: i64) -> bool {
    if !identity_registry_entry_fresh(entry, now) {
        return false;
    }

    if let Some(pid) = entry.pid {
        if pid > 0 && !pid_is_alive(pid) {
            return false;
        }
    }

    true
}

#[cfg(unix)]
fn pid_is_alive(pid: i64) -> bool {
    if pid <= 0 || pid > i32::MAX as i64 {
        return false;
    }
    unsafe { libc::kill(pid as libc::pid_t, 0) == 0 }
}

#[cfg(not(unix))]
fn pid_is_alive(_pid: i64) -> bool {
    true
}

fn read_identity_registry(path: &Path) -> IdentityRegistry {
    std::fs::read_to_string(path)
        .ok()
        .and_then(|s| serde_json::from_str::<IdentityRegistry>(&s).ok())
        .filter(|r| r.schema == IDENTITY_REGISTRY_SCHEMA)
        .unwrap_or_default()
}

struct IdentityRegistryLock {
    path: PathBuf,
}

impl Drop for IdentityRegistryLock {
    fn drop(&mut self) {
        let _ = std::fs::remove_file(&self.path);
    }
}

fn identity_registry_lock_path(path: &Path) -> PathBuf {
    let Some(name) = path.file_name().and_then(|n| n.to_str()) else {
        return path.with_extension("lock");
    };
    path.with_file_name(format!("{name}.lock"))
}

fn identity_registry_lock_stale(path: &Path, now: i64) -> bool {
    if let Ok(raw) = std::fs::read_to_string(path) {
        if let Ok(pid) = raw.trim().parse::<i64>() {
            if pid > 0 && !pid_is_alive(pid) {
                return true;
            }
        }
    }

    std::fs::metadata(path)
        .ok()
        .and_then(|m| m.modified().ok())
        .and_then(|t| t.duration_since(UNIX_EPOCH).ok())
        .map(|d| now - d.as_secs() as i64 > IDENTITY_REGISTRY_LOCK_STALE_SECS)
        .unwrap_or(false)
}

fn acquire_identity_registry_lock(path: &Path, now: i64) -> Option<IdentityRegistryLock> {
    let lock_path = identity_registry_lock_path(path);
    if let Some(parent) = lock_path.parent() {
        if std::fs::create_dir_all(parent).is_err() {
            return None;
        }
    }

    for _ in 0..50 {
        match std::fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&lock_path)
        {
            Ok(mut file) => {
                use std::io::Write as _;
                let _ = writeln!(file, "{}", std::process::id());
                return Some(IdentityRegistryLock { path: lock_path });
            }
            Err(err) if err.kind() == std::io::ErrorKind::AlreadyExists => {
                if identity_registry_lock_stale(&lock_path, now) {
                    let _ = std::fs::remove_file(&lock_path);
                    continue;
                }
                std::thread::sleep(Duration::from_millis(20));
            }
            Err(_) => return None,
        }
    }

    None
}

fn write_identity_registry(path: &Path, registry: &IdentityRegistry) -> std::io::Result<()> {
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)?;
    }
    let tmp = path.with_extension(format!("tmp-{}", std::process::id()));
    let body = serde_json::to_vec_pretty(registry)
        .map_err(|e| std::io::Error::new(std::io::ErrorKind::InvalidData, e))?;
    let write_result = (|| -> std::io::Result<()> {
        std::fs::write(&tmp, body)?;
        std::fs::rename(&tmp, path)?;
        Ok(())
    })();
    if write_result.is_err() {
        let _ = std::fs::remove_file(&tmp);
    }
    write_result
}

fn allocate_identity_registry_tag(base_tag: &str, entries: &[IdentityRegistryEntry]) -> String {
    if !entries
        .iter()
        .any(|entry| entry.tag.as_deref() == Some(base_tag))
    {
        return base_tag.to_string();
    }

    for suffix in 1..=255 {
        let candidate = format!("{base_tag}{suffix:x}");
        if !entries
            .iter()
            .any(|entry| entry.tag.as_deref() == Some(candidate.as_str()))
        {
            return candidate;
        }
    }

    format!("{base_tag}{}", now_unix_i64() & 0xfff)
}

async fn fresh_presence_collision(
    store: Option<&Arc<dyn StateStore>>,
    session_id: &str,
    now: i64,
) -> bool {
    let Some(store) = store else {
        return false;
    };
    match store.agent_presence_get(session_id).await {
        Ok(Some(existing)) => {
            let my_pid = std::process::id();
            let is_fresh = now - existing.last_heartbeat_at <= PRESENCE_FRESH_SECS;
            let other_owner = existing.pid != Some(i64::from(my_pid));
            is_fresh && other_owner
        }
        _ => false,
    }
}

fn presence_collision_identity(
    node: &str,
    project: &str,
    role: &str,
) -> (Option<String>, String, bool) {
    let auto = pid_tag_short(std::process::id());
    let new_id = format!("{node}:{project}:{role}:{auto}");
    (Some(auto), new_id, true)
}

fn resolve_identity_from_registry(
    path: &Path,
    bare_id: &str,
    owner_key: &str,
    node: &str,
    project: &str,
    role: &str,
    cwd: Option<&str>,
    now: i64,
    occupied_by_presence: bool,
) -> Option<(Option<String>, String, bool)> {
    let _lock = acquire_identity_registry_lock(path, now)?;
    let mut registry = read_identity_registry(path);
    registry.entries.retain(|entry| {
        if entry.owner_key == owner_key {
            identity_registry_entry_fresh(entry, now)
        } else {
            identity_registry_entry_alive_for_other_owner(entry, now)
        }
    });

    if let Some(existing_idx) = registry
        .entries
        .iter()
        .position(|entry| entry.bare_id == bare_id && entry.owner_key == owner_key)
    {
        let entry = &mut registry.entries[existing_idx];
        entry.last_seen_unix = now;
        entry.pid = Some(i64::from(std::process::id()));
        entry.cwd = cwd.map(|s| s.to_string());
        let tag = entry.tag.clone();
        let session_id = tag
            .as_ref()
            .map(|t| format!("{node}:{project}:{role}:{t}"))
            .unwrap_or_else(|| bare_id.to_string());
        let _ = write_identity_registry(path, &registry);
        return Some((tag, session_id, false));
    }

    let collides = occupied_by_presence
        || registry
            .entries
            .iter()
            .any(|entry| entry.bare_id == bare_id);
    let tag = if collides {
        Some(allocate_identity_registry_tag(
            &pid_tag_short(std::process::id()),
            &registry.entries,
        ))
    } else {
        None
    };
    let session_id = tag
        .as_ref()
        .map(|t| format!("{node}:{project}:{role}:{t}"))
        .unwrap_or_else(|| bare_id.to_string());

    registry.entries.push(IdentityRegistryEntry {
        bare_id: bare_id.to_string(),
        owner_key: owner_key.to_string(),
        tag: tag.clone(),
        pid: Some(i64::from(std::process::id())),
        created_at_unix: now,
        last_seen_unix: now,
        cwd: cwd.map(|s| s.to_string()),
    });
    let _ = write_identity_registry(path, &registry);
    Some((tag, session_id, collides))
}

pub struct SessionIdentityTool {
    hub: Hub,
}
impl SessionIdentityTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for SessionIdentityTool {
    fn name(&self) -> &'static str {
        "session_identity"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Compute the canonical session id `node:project:role[:tag]` from the \
                 caller's environment + args. Auto-disambiguates by appending a \
                 short pid-derived tag when the same local bare id is already held \
                 in the active-session registry, or when a fresh-heartbeat (≤ 60 s) \
                 presence row already holds the proposed id from a different process \
                 — the multi-session sibling case. \
                 Use the result as `session_id` / `author` in agent_message, agent_inbox, \
                 forum_post, agent_presence_announce, etc. Conventions:\n\
                 • `node`     → arg | $AGENT_BRIDGE_NODE | /etc/hostname | `hostname`\n\
                 • `project`  → arg | $AGENT_BRIDGE_PROJECT | basename(cwd_arg | cwd)\n\
                 • `role`     → arg | 'main'\n\
                 • `tag`      → arg | auto-pid-suffix on collision | (omitted)\n\
                 See docs/DESIGN-v19-presence-identity.md for rationale and the \
                 Tailscale evolution path."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "role":    { "type": "string", "default": "main", "description": "What this CC is doing — main | explorer | reviewer | test-writer | …" },
                    "tag":     { "type": "string", "description": "Optional disambiguator when multiple instances share a role (e.g. last-4 of pid). Disables auto-tag when set." },
                    "node":    { "type": "string", "description": "Override hostname." },
                    "project": { "type": "string", "description": "Override project slug." },
                    "cwd":     { "type": "string", "description": "Caller's cwd (used to derive project default — MCP server's cwd ≠ Claude Code's)." },
                    "auto_tag": { "type": "boolean", "default": true, "description": "When true (default), append a short pid-tag if the bare id collides with a fresh sibling. Set false to keep the old pure-helper behavior." }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, ctx: &ToolContext) -> Result<ToolResult> {
        let role_arg = args.get("role").and_then(|v| v.as_str());
        let explicit_tag = args.get("tag").and_then(|v| v.as_str());
        let node_arg = args.get("node").and_then(|v| v.as_str());
        let project_arg = args.get("project").and_then(|v| v.as_str());
        let cwd_arg = args.get("cwd").and_then(|v| v.as_str());
        let auto_tag_enabled = args
            .get("auto_tag")
            .and_then(|v| v.as_bool())
            .unwrap_or(true);

        let (node, project, role, tag, session_id) =
            resolve_identity(role_arg, explicit_tag, node_arg, project_arg, cwd_arg);

        let mut identity_registry = json!({
            "checked": false,
            "path": Value::Null,
            "owner_key": Value::Null,
            "matched": false
        });

        // Auto-tag only when (a) caller did not pass an explicit tag,
        // and (b) caller did not opt out. The local registry is checked before
        // presence so interactive sessions that never heartbeat can still
        // disambiguate reliably.
        let (final_tag, final_session_id, auto_tagged) =
            if explicit_tag.is_some() || !auto_tag_enabled {
                (tag, session_id, false)
            } else if let Some(path) = identity_registry_path() {
                let owner_key = session_identity_owner_key(ctx);
                let now = now_unix_i64();
                let occupied_by_presence =
                    fresh_presence_collision(self.hub.store.as_ref(), &session_id, now).await;
                match resolve_identity_from_registry(
                    &path,
                    &session_id,
                    &owner_key,
                    &node,
                    &project,
                    &role,
                    cwd_arg,
                    now,
                    occupied_by_presence,
                ) {
                    Some((resolved_tag, resolved_id, tagged)) => {
                        identity_registry = json!({
                            "checked": true,
                            "path": path.display().to_string(),
                            "owner_key": owner_key,
                            "matched": true
                        });
                        (resolved_tag, resolved_id, tagged)
                    }
                    None => (tag, session_id, false),
                }
            } else if let Some(store) = self.hub.store.as_ref() {
                if fresh_presence_collision(Some(store), &session_id, now_unix_i64()).await {
                    presence_collision_identity(&node, &project, &role)
                } else {
                    (tag, session_id, false)
                }
            } else {
                (tag, session_id, false)
            };

        Ok(ToolResult::json_text(&json!({
            "session_id": final_session_id,
            "node": node,
            "project": project,
            "role": role,
            "tag": final_tag,
            "auto_tagged": auto_tagged,
            "identity_registry": identity_registry
        })))
    }
}

pub struct AgentPresenceAnnounceTool {
    hub: Hub,
}
impl AgentPresenceAnnounceTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for AgentPresenceAnnounceTool {
    fn name(&self) -> &'static str {
        "agent_presence_announce"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Upsert this agent's presence row keyed by `session_id`. Refreshes \
                 `last_heartbeat_at` on every call, so call once on startup and \
                 periodically after (recommend every 60–120 s). On first announce, \
                 `name`, `node`, `project`, `role` are required; on later calls any \
                 omitted field keeps its prior value. Field naming aligns with \
                 Google A2A AgentCard so the row can be served as `/.well-known/\
                 agent.json` once we add a Tailscale daemon. Tip: pre-compute \
                 session_id with the `session_identity` tool."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "session_id":   { "type": "string", "description": "Stable identity (REQUIRED). Use session_identity to compute." },
                    "name":         { "type": "string", "description": "Human-friendly label (REQUIRED on first announce)." },
                    "description":  { "type": "string", "description": "Free text — what you're working on." },
                    "version":      { "type": "string", "description": "e.g. 'agent-bridge 0.1.0; cc 1.2.3'." },
                    "url":          { "type": "string", "description": "Reserved for daemon mode (HTTP endpoint). Leave null locally." },
                    "node":         { "type": "string", "description": "Host identity (REQUIRED on first announce)." },
                    "project":      { "type": "string", "description": "Project slug (REQUIRED on first announce)." },
                    "role":         { "type": "string", "description": "main | explorer | reviewer | … (REQUIRED on first announce)." },
                    "tag":          { "type": "string", "description": "Optional disambiguator." },
                    "cwd":          { "type": "string", "description": "Caller's cwd for context (MCP server's cwd is irrelevant)." },
                    "pid":          { "type": "integer", "description": "Caller's pid (the Claude Code process — MCP server's pid is irrelevant)." },
                    "capabilities": { "type": "object", "description": "A2A-style capability flags, e.g. {\"forum\":true,\"streaming\":false}." },
                    "skills":       { "type": "array",  "description": "A2A-style skills array, e.g. [{\"id\":\"code-review\",\"name\":\"...\",\"tags\":[...]}]." }
                },
                "required": ["session_id"]
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no memory store configured")),
        };
        let session_id = match args
            .get("session_id")
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty())
        {
            Some(s) => s.to_string(),
            None => return Ok(ToolResult::error("missing or empty 'session_id'")),
        };

        // Borrow lifetime gymnastics: hold owned strings + a temp Value slot.
        let name = args.get("name").and_then(|v| v.as_str());
        let description = args.get("description").and_then(|v| v.as_str());
        let version = args.get("version").and_then(|v| v.as_str());
        let url = args.get("url").and_then(|v| v.as_str());
        let node = args.get("node").and_then(|v| v.as_str());
        let project = args.get("project").and_then(|v| v.as_str());
        let role = args.get("role").and_then(|v| v.as_str());
        let tag = args.get("tag").and_then(|v| v.as_str());
        let cwd = args.get("cwd").and_then(|v| v.as_str());
        let pid = args.get("pid").and_then(|v| v.as_i64());
        let capabilities_v = args.get("capabilities").cloned();
        let skills_v = args.get("skills").cloned();

        let upsert = ab_store::AgentPresenceUpsert {
            name,
            description,
            version,
            url,
            node,
            project,
            role,
            tag,
            cwd,
            pid,
            capabilities: capabilities_v.as_ref(),
            skills: skills_v.as_ref(),
        };

        let row = store
            .agent_presence_announce(&session_id, upsert)
            .await
            .map_err(|e| ab_core::Error::Backend(format!("agent_presence_announce: {e}")))?;
        Ok(ToolResult::json_text(&json!({
            "status": "ok",
            "presence": row
        })))
    }
}

pub struct AgentPresenceListTool {
    hub: Hub,
}
impl AgentPresenceListTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for AgentPresenceListTool {
    fn name(&self) -> &'static str {
        "agent_presence_list"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "List active agents (heartbeat within `max_idle_secs` of now). Use to \
                 discover collaborators before posting in forum or sending an \
                 agent_message. Default TTL = 300 s (5 min) so a crashed CC drops off \
                 within ~5 min. Pass `max_idle_secs:0` or `include_stale:true` to see \
                 every row including stale ones. Filters by `project` and `role` so \
                 you can ask 'who's reviewing AiOT right now'. Set `peer: \"host:port\"` \
                 to list agents from a remote tailnet peer's daemon-http instead of local.\n\n\
                 Output projection: in Codex compact toolsets, omitted projection args \
                 default to a presence summary and omit large capabilities/skills blobs; \
                 other clients default to full rows. Set `compact:false`, \
                 `include_capabilities:true`, and `include_skills:true` when you need \
                 full AgentCard metadata."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "project":       { "type": "string",  "description": "Filter by project slug." },
                    "role":          { "type": "string",  "description": "Filter by role." },
                    "max_idle_secs": { "type": "integer", "default": 300, "description": "Skip rows whose heartbeat is older than this. 0 = no TTL." },
                    "include_stale": { "type": "boolean", "default": false, "description": "Equivalent to max_idle_secs:0." },
                    "limit":         { "type": "integer", "default": 50, "description": "Max rows (1–500)." },
                    "peer":          { "type": "string",  "description": "Optional tailnet peer host:port; if set, query that daemon-http instead of local. (v20)" },
                    "compact":       { "type": "boolean", "description": "Use compact projection defaults. Omitted = true for Codex compact toolsets, false otherwise." },
                    "include_capabilities": { "type": "boolean", "description": "Include full capabilities JSON. Omitted = false in compact output, true otherwise." },
                    "include_skills": { "type": "boolean", "description": "Include full skills JSON. Omitted = false in compact output, true otherwise." }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let project = args
            .get("project")
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty());
        let role = args
            .get("role")
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty());
        let include_stale = args
            .get("include_stale")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let max_idle_secs = if include_stale {
            0
        } else {
            args.get("max_idle_secs")
                .and_then(|v| v.as_i64())
                .unwrap_or(300)
        };
        let limit = args
            .get("limit")
            .and_then(|v| v.as_u64())
            .unwrap_or(50)
            .clamp(1, 500) as u32;
        let peer = args
            .get("peer")
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty());
        let compact = args
            .get("compact")
            .and_then(|v| v.as_bool())
            .unwrap_or_else(compact_mcp_output_default);
        let include_capabilities = args
            .get("include_capabilities")
            .and_then(|v| v.as_bool())
            .unwrap_or(!compact);
        let include_skills = args
            .get("include_skills")
            .and_then(|v| v.as_bool())
            .unwrap_or(!compact);

        let rows = if let Some(p) = peer {
            crate::peer_client::agent_presence_list(p, project, role, max_idle_secs, limit)
                .await
                .map_err(|e| ab_core::Error::Backend(format!("agent_presence_list peer: {e}")))?
        } else {
            let store = match &self.hub.store {
                Some(s) => s.clone(),
                None => return Ok(ToolResult::error("no memory store configured")),
            };
            store
                .agent_presence_list(project, role, max_idle_secs, limit)
                .await
                .map_err(|e| ab_core::Error::Backend(format!("agent_presence_list: {e}")))?
        };
        let (agents, capabilities_omitted, skills_omitted) =
            project_agent_presence_rows(&rows, include_capabilities, include_skills);
        Ok(ToolResult::json_text(&json!({
            "count": rows.len(),
            "max_idle_secs": max_idle_secs,
            "agents": agents,
            "projection": {
                "compact": compact,
                "include_capabilities": include_capabilities,
                "include_skills": include_skills,
                "capabilities_omitted": capabilities_omitted,
                "skills_omitted": skills_omitted
            }
        })))
    }
}

