// ===========================================================================
//                       agent session inspection (v0.2)
// ===========================================================================

pub struct AgentSessionListTool {
    hub: Hub,
}
impl AgentSessionListTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for AgentSessionListTool {
    fn name(&self) -> &'static str {
        "agent_session_list"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "List recent agent sessions (default 20, max 1000). Row: id, \
                 runtime, cwd, started_at, ended_at, exit_code. Filters: runtime_id, \
                 cwd_prefix, state, exit_code (negative=signal). Running rows carry \
                 liveness. Use agent_session_get(id) for full output."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "limit":      { "type": "integer", "minimum": 1, "maximum": 1000, "default": 20 },
                    "runtime_id": { "type": "string",  "description": "e.g. 'claude-code'" },
                    "cwd_prefix": { "type": "string",  "description": "Prefix-match the working dir." },
                    "state":      { "type": "string",  "enum": ["running","finished"] },
                    "exit_code":  { "type": "integer", "description": "Exact exit code (negative = signal)." }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let limit = args
            .get("limit")
            .and_then(|v| v.as_u64())
            .unwrap_or(20)
            .min(1000) as u32;
        let filter = SessionFilter {
            runtime_id: args
                .get("runtime_id")
                .and_then(|v| v.as_str())
                .map(|s| s.to_string()),
            cwd_prefix: args
                .get("cwd_prefix")
                .and_then(|v| v.as_str())
                .map(|s| s.to_string()),
            exited_only: args
                .get("state")
                .and_then(|v| v.as_str())
                .and_then(|s| match s {
                    "finished" => Some(true),
                    "running" => Some(false),
                    _ => None,
                }),
            exit_code: args
                .get("exit_code")
                .and_then(|v| v.as_i64())
                .map(|n| n as i32),
        };
        let rows = store.list_sessions(&filter, limit).await?;
        // Strip stdout/stderr to keep the listing compact.
        let summary: Vec<Value> = rows
            .into_iter()
            .map(|s| {
                let running = s.ended_at.is_none();
                let mut row = json!({
                    "id":          s.id.as_str(),
                    "runtime_id":  s.runtime_id,
                    "cwd":         s.cwd,
                    "started_at":  s.started_at,
                    "ended_at":    s.ended_at,
                    "exit_code":   s.exit_code,
                    "running":     running,
                    "stdout_len":  s.stdout.as_ref().map(|x| x.len()).unwrap_or(0),
                    "stderr_len":  s.stderr.as_ref().map(|x| x.len()).unwrap_or(0),
                });
                if running {
                    let (pid, liveness) = agent_session_liveness(&self.hub, &s);
                    if let Some(p) = pid {
                        row["pid"] = json!(p);
                    }
                    row["liveness"] = json!(liveness);
                }
                row
            })
            .collect();
        Ok(ToolResult::json_text(&Value::Array(summary)))
    }
}

pub struct AgentSessionReconcileTool {
    hub: Hub,
}
impl AgentSessionReconcileTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for AgentSessionReconcileTool {
    fn name(&self) -> &'static str {
        "agent_session_reconcile"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Find stale running local agent sessions whose owning MCP process has \
                 likely disappeared, and optionally finalise them. Defaults to dry-run. Use \
                 this after MCP/IDE restarts when agent_session_list shows old running rows \
                 with no live child PID."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "dry_run": {
                        "type": "boolean",
                        "default": true,
                        "description": "When true, report candidates without mutating sessions."
                    },
                    "apply_confirmation": {
                        "type": "string",
                        "description": "Required exact value 'finalise_stale_sessions' when dry_run=false, after reviewing dry-run candidates."
                    },
                    "stale_after_secs": {
                        "type": "integer",
                        "minimum": 60,
                        "maximum": 604800,
                        "default": 300,
                        "description": "Only reconcile running sessions older than this age."
                    },
                    "limit": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": 1000,
                        "default": 100
                    },
                    "runtime_id": {
                        "type": "string",
                        "description": "Optional runtime filter, e.g. kilo or codex."
                    },
                    "cwd_prefix": {
                        "type": "string",
                        "description": "Optional cwd prefix filter."
                    }
                }
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let dry_run = args
            .get("dry_run")
            .and_then(|v| v.as_bool())
            .unwrap_or(true);
        if !dry_run
            && args.get("apply_confirmation").and_then(|v| v.as_str())
                != Some("finalise_stale_sessions")
        {
            return Ok(ToolResult::error(
                "dry_run=false requires apply_confirmation=\"finalise_stale_sessions\" \
                 after reviewing dry-run candidates",
            ));
        }
        let stale_after_secs = args
            .get("stale_after_secs")
            .and_then(|v| v.as_i64())
            .unwrap_or(300)
            .clamp(60, 604_800);
        let limit = args
            .get("limit")
            .and_then(|v| v.as_u64())
            .unwrap_or(100)
            .min(1000) as u32;
        let filter = SessionFilter {
            runtime_id: args
                .get("runtime_id")
                .and_then(|v| v.as_str())
                .map(|s| s.to_string()),
            cwd_prefix: args
                .get("cwd_prefix")
                .and_then(|v| v.as_str())
                .map(|s| s.to_string()),
            exited_only: Some(false),
            exit_code: None,
        };
        let rows = store.list_sessions(&filter, limit).await?;
        let now = dispatch_now_secs();
        let mut candidates = Vec::new();
        let mut finalised_count = 0usize;
        let mut skipped_recent = 0usize;
        let mut skipped_unsupported_runtime = 0usize;
        let mut skipped_alive = 0usize;
        let mut errors = Vec::new();

        for session in rows {
            let age_secs = now.saturating_sub(session.started_at);
            if age_secs < stale_after_secs {
                skipped_recent += 1;
                continue;
            }
            if !is_local_process_agent_runtime(&session.runtime_id) {
                skipped_unsupported_runtime += 1;
                continue;
            }
            let (pid, liveness) = agent_session_liveness(&self.hub, &session);
            if liveness == "alive" {
                skipped_alive += 1;
                continue;
            }
            let reason = format!(
                "agent_session_reconcile: finalised stale running session after {age_secs}s; \
                 liveness={liveness}"
            );
            candidates.push(json!({
                "id": session.id.as_str(),
                "runtime_id": session.runtime_id.as_str(),
                "cwd": session.cwd.as_str(),
                "started_at": session.started_at,
                "age_secs": age_secs,
                "pid": pid,
                "liveness": liveness,
                "exit_code_if_applied": -15,
            }));
            if !dry_run {
                let stderr = append_reconcile_reason(session.stderr.as_deref(), &reason);
                match store
                    .finalise_session(
                        &session.id,
                        now,
                        Some(-15),
                        session.stdout.clone(),
                        Some(stderr),
                    )
                    .await
                {
                    Ok(()) => finalised_count += 1,
                    Err(e) => errors.push(json!({
                        "id": session.id.as_str(),
                        "error": e.to_string(),
                    })),
                }
            }
        }

        Ok(ToolResult::json_text(&json!({
            "dry_run": dry_run,
            "stale_after_secs": stale_after_secs,
            "scanned_count": skipped_recent
                + skipped_unsupported_runtime
                + skipped_alive
                + candidates.len(),
            "candidate_count": candidates.len(),
            "finalised_count": finalised_count,
            "skipped_recent": skipped_recent,
            "skipped_unsupported_runtime": skipped_unsupported_runtime,
            "skipped_alive": skipped_alive,
            "errors": errors,
            "candidates": candidates,
        })))
    }
}

fn append_reconcile_reason(existing: Option<&str>, reason: &str) -> String {
    match existing {
        Some(prev) if !prev.trim().is_empty() => format!("{prev}\n{reason}"),
        _ => reason.to_string(),
    }
}

fn is_local_process_agent_runtime(runtime_id: &str) -> bool {
    matches!(
        runtime_id,
        "claude-code" | "codex" | "kilo" | "opencode" | "gemini" | "auggie"
    )
}

fn resolve_agent_for_session(
    hub: &Hub,
    session: &StoredSession,
) -> std::result::Result<Arc<dyn ab_agent::AgentRuntime>, String> {
    hub.agents
        .get(&session.runtime_id)
        .cloned()
        .or_else(|| {
            hub.agent
                .as_ref()
                .filter(|agent| agent.id() == session.runtime_id)
                .cloned()
        })
        .ok_or_else(|| {
            let mut available: Vec<&str> = hub.agents.keys().map(|s| s.as_str()).collect();
            available.sort();
            format!(
                "agent session {} uses runtime '{}' but this MCP process is not tracking that \
                 runtime; available: [{}]",
                session.id,
                session.runtime_id,
                available.join(", ")
            )
        })
}

fn agent_session_liveness(hub: &Hub, session: &StoredSession) -> (Option<u32>, &'static str) {
    let pid = hub
        .agents
        .get(&session.runtime_id)
        .and_then(|agent| agent.pid_for(&session.id))
        .or_else(|| {
            hub.agent
                .as_ref()
                .filter(|agent| agent.id() == session.runtime_id)
                .and_then(|agent| agent.pid_for(&session.id))
        });
    match pid {
        Some(pid) if process_pid_exists(pid) => (Some(pid), "alive"),
        Some(pid) => (Some(pid), "dead"),
        None => (None, "untracked"),
    }
}

fn process_pid_exists(pid: u32) -> bool {
    #[cfg(unix)]
    {
        std::path::Path::new(&format!("/proc/{pid}")).exists()
    }
    #[cfg(not(unix))]
    {
        let _ = pid;
        false
    }
}

pub struct AgentSessionGetTool {
    hub: Hub,
}
impl AgentSessionGetTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for AgentSessionGetTool {
    fn name(&self) -> &'static str {
        "agent_session_get"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Fetch one agent session row by id, including the full captured \
                 stdout and stderr (each clamped to 64 KiB). Returns null if the \
                 session id is unknown."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": { "id": { "type": "string" } },
                "required": ["id"]
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let id = match args.get("id").and_then(|v| v.as_str()) {
            Some(s) => SessionId::from_raw(s.to_string()),
            None => return Ok(ToolResult::error("missing 'id'")),
        };
        let row = store.load_session(&id).await?;
        Ok(ToolResult::json_text(
            &serde_json::to_value(row).unwrap_or(Value::Null),
        ))
    }
}

pub struct AgentSessionWaitTool {
    hub: Hub,
}
impl AgentSessionWaitTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for AgentSessionWaitTool {
    fn name(&self) -> &'static str {
        "agent_session_wait"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Block until the given session has finished (ended_at != null) or \
                 `timeout_secs` elapses. Polls the store every 500 ms. On success \
                 returns the final row (with stdout/stderr); on timeout returns the \
                 latest in-flight row plus `timed_out=true`."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "id":           { "type": "string" },
                    "timeout_secs": { "type": "integer", "minimum": 1, "maximum": 600, "default": 60 }
                },
                "required": ["id"]
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let id = match args.get("id").and_then(|v| v.as_str()) {
            Some(s) => SessionId::from_raw(s.to_string()),
            None => return Ok(ToolResult::error("missing 'id'")),
        };
        let timeout = Duration::from_secs(
            args.get("timeout_secs")
                .and_then(|v| v.as_u64())
                .unwrap_or(60)
                .min(600),
        );
        let deadline = Instant::now() + timeout;

        // Phase 1: wait for local CLI process to finish (ended_at set).
        let local_row = loop {
            let row = store.load_session(&id).await?;
            if let Some(ref s) = row {
                if s.ended_at.is_some() {
                    break row;
                }
            }
            if Instant::now() >= deadline {
                return Ok(ToolResult::json_text(&json!({
                    "timed_out": true,
                    "session": row,
                })));
            }
            tokio::time::sleep(Duration::from_millis(500)).await;
        };

        // Phase 2 (warp-oz only): if cloud_run_id is set and state is not yet
        // terminal, continue polling via `oz run get` until terminal or timeout.
        let is_warp_oz = local_row
            .as_ref()
            .map(|s| s.runtime_id == "warp-oz")
            .unwrap_or(false);
        let cloud_run_id = local_row.as_ref().and_then(|s| s.cloud_run_id.clone());

        if is_warp_oz {
            if let Some(run_id) = cloud_run_id {
                let bin = oz_binary(&self.hub);
                // Check initial cloud state from store first.
                let already_terminal = local_row
                    .as_ref()
                    .and_then(|s| s.cloud_run_state.as_deref())
                    .map(|st| ab_agent::oz::TERMINAL_STATES.contains(&st))
                    .unwrap_or(false);
                if !already_terminal {
                    // Poll until terminal or deadline.
                    loop {
                        if Instant::now() >= deadline {
                            let row = store.load_session(&id).await?;
                            return Ok(ToolResult::json_text(&json!({
                                "timed_out": true,
                                "session": row,
                            })));
                        }
                        tokio::time::sleep(Duration::from_secs(3)).await;
                        // Call oz run get to get latest state
                        if let Some(status) = fetch_run_status(&bin, &run_id).await {
                            let state_str = status.state.as_deref().unwrap_or("UNKNOWN");
                            let _ = store
                                .set_cloud_run_state(&id, state_str, status.session_link.as_deref())
                                .await;
                            if ab_agent::oz::TERMINAL_STATES.contains(&state_str) {
                                break;
                            }
                        }
                    }
                }
            }
        }

        // Return final row.
        let final_row = store.load_session(&id).await?;
        Ok(ToolResult::json_text(&json!({
            "timed_out": false,
            "session": final_row,
        })))
    }
}

// ===========================================================================
//                       agent self-memory (v0.4)
// ===========================================================================

const MEMORY_SAVE_SYNC_ADVISORY_CONTENT_MAX_BYTES: usize = 2_048;

fn memory_save_sync_advisory_enabled(content: &str) -> bool {
    content.len() <= MEMORY_SAVE_SYNC_ADVISORY_CONTENT_MAX_BYTES
}

/// Build a proactive hint for an agent memory key.
///
/// Heuristic:
/// 1. Count existing edges (via `memory_neighbors`).
/// 2. Build a topical query from the key slug + tags + first content words.
///    Key slugs (e.g. "lesson_bfs_cycle") carry semantic signal; raw content
///    often matches only itself.
/// 3. Run FTS search (hybrid mode for richer recall).
/// 4. Keep top-3 results that aren't the key itself or already linked.
/// 5. Return a compact one-line suggestion, or `None` when nothing useful.
///
/// Errors are swallowed — hints are best-effort and must never break callers.
async fn build_proactive_hint(
    store: &Arc<dyn StateStore>,
    key: &str,
    content: &str,
    tags: &[String],
) -> Option<String> {
    // Existing direct edges
    let neighbors = store.memory_neighbors(key).await.unwrap_or_default();
    let edge_count = neighbors.len();
    let linked: std::collections::HashSet<String> = neighbors
        .into_iter()
        .flat_map(|e| [e.from_key, e.to_key])
        .filter(|k| k != key)
        .collect();

    // Build a topical query using FTS5 OR syntax so any relevant keyword matches.
    //
    // FTS5 uses AND by default; multi-word queries with uncommon words produce zero
    // results.  "tag1 OR tag2 OR word1 OR word2" avoids this while still ranking by
    // how many terms appear.
    //
    // Strategy: tags first (always topical), then first content words.
    // The FTS5 index stores the key as a single token ("lesson_bfs_guard"),
    // so key-slug splits are useless here — skip them.
    // Collect candidate tokens:
    //   tags that are clean identifiers (no hyphens/dots that confuse FTS5)
    //   + first content words that are purely alphabetic, len ≥ 3
    let is_clean = |s: &str| s.len() >= 3 && s.chars().all(|c| c.is_ascii_alphanumeric());
    let tag_terms: Vec<String> = tags.iter().filter(|t| is_clean(t)).cloned().collect();
    let content_terms: Vec<String> = content
        .split_whitespace()
        .map(|w| {
            // Strip leading/trailing punctuation
            w.trim_matches(|c: char| !c.is_alphanumeric()).to_string()
        })
        .filter(|w| is_clean(w) && w.chars().all(|c| c.is_ascii_alphabetic()))
        .take(10)
        .collect();
    let mut seen = std::collections::HashSet::new();
    let terms: Vec<String> = tag_terms
        .into_iter()
        .chain(content_terms)
        .filter(|w| seen.insert(w.to_lowercase()))
        .take(10)
        .collect();
    let query = terms.join(" OR "); // FTS5 OR: any term matches

    if query.trim().is_empty() {
        return None;
    }

    // Hybrid search — broader recall than pure FTS
    // signature: (query, tags, limit, rrf_k, expand_top)
    let tags_empty: Vec<String> = Vec::new();
    let hits = store
        .memory_search_hybrid(&query, &tags_empty, 6, 60.0, 3)
        .await
        .unwrap_or_default();

    // Path C v0.2: bias hint candidates toward records currently in the seed
    // grid's hub_clusters near_keys. Same HashSet as memory_search rerank;
    // structural co-occurrence prior over pure FTS+graph score.
    let hits = apply_seed_boost(hits);

    // Filter: skip self and already-linked; no score threshold (BM25 isn't normalised)
    let candidates: Vec<_> = hits
        .into_iter()
        .filter(|h| h.record.key != key && !linked.contains(&h.record.key))
        .take(3)
        .collect();

    if candidates.is_empty() {
        return None;
    }

    let suggestions = candidates
        .iter()
        .map(|h| h.record.key.clone())
        .collect::<Vec<_>>()
        .join(" · ");

    let edge_note = if edge_count == 0 {
        "no edges yet".to_string()
    } else {
        format!("{edge_count} edge(s)")
    };

    Some(format!("{edge_note} | consider memory_link: {suggestions}"))
}

/// **B3 preflight** (audit-gap B3 v0) — cosine-rank the new save's content against
/// same-kind active prior memories. Emits two structured signals:
///
/// - `prior_decision_warning` (cos ≥ 0.75, capped at 3): likely near-duplicate;
///   sits at p99 of all-pairs same-kind cosines per the 2026-05-17 corpus probe.
/// - `prior_decision_hint`    (0.60 ≤ cos < 0.75, capped at 5): soft "may be
///   adjacent" tier; informational, no enforcement.
///
/// Skips the catalog (kind ∈ CATALOG_KINDS_C3 — `skill` records bulk-imported
/// from external sources have templated boilerplate and would false-positive).
/// Caller is responsible for the AB_REDO_WARN_DISABLE env opt-out (controls both
/// bands per sibling Q4 vote) and for the `memory_correction` path skip — that
/// tool is a separate `MemoryCorrectionTool`, so B3 naturally never fires there.
///
/// Returns (warnings, hints) as JSON arrays ready for direct response embedding.
///
/// Refs:
/// - docs/DESIGN-A1-B1-B3-RECALL-TIMING-v0.md §2.4 mechanism
/// - docs/PROBE-B3-REDO-THRESHOLD-CALIBRATION-2026-05-17.md threshold rationale
/// - thread 10 #218 (probe) + #221/#223 (votes) + #229 (close-out) + #249 (act unlock)
async fn b3_preflight(
    store: &Arc<dyn StateStore>,
    new_key: &str,
    new_content: &str,
    new_kind: &str,
) -> (Vec<Value>, Vec<Value>) {
    const HARD_THRESHOLD: f64 = 0.75;
    const SOFT_THRESHOLD: f64 = 0.60;
    const SOFT_THRESHOLD_F32: f32 = 0.60;
    const WARN_CAP: usize = 3;
    const HINT_CAP: usize = 5;
    const SEARCH_LIMIT: u32 = 30;

    // Round cosine to 3 decimals for stable, readable response payloads.
    fn round3(x: f64) -> f64 {
        (x * 1000.0).round() / 1000.0
    }

    let hits = match store
        .memory_search_semantic(new_content, SEARCH_LIMIT, SOFT_THRESHOLD_F32)
        .await
    {
        Ok(h) => h,
        Err(_) => return (Vec::new(), Vec::new()),
    };

    let mut warnings: Vec<Value> = Vec::new();
    let mut hints: Vec<Value> = Vec::new();
    for hit in hits {
        if hit.record.key == new_key {
            continue;
        }
        if hit.record.kind != new_kind {
            continue;
        }
        if hit.record.status != "active" {
            continue;
        }
        // Raw cosine ∈ [-1, 1] from the semantic path. `score` is blended
        // (cosine + importance/recency bonuses, can exceed 1.0) — wrong
        // metric for threshold checks. Drop hits with no cosine (FTS-only
        // paths can't classify near-duplicates by geometry).
        let cosine = match hit.cosine {
            Some(c) => c as f64,
            None => continue,
        };
        if cosine >= HARD_THRESHOLD {
            if warnings.len() < WARN_CAP {
                warnings.push(json!({
                    "key": hit.record.key,
                    "cosine": round3(cosine),
                    "kind": hit.record.kind,
                }));
            }
        } else if cosine >= SOFT_THRESHOLD && hints.len() < HINT_CAP {
            hints.push(json!({
                "key": hit.record.key,
                "cosine": round3(cosine),
                "kind": hit.record.kind,
            }));
        }
        if warnings.len() >= WARN_CAP && hints.len() >= HINT_CAP {
            break;
        }
    }
    (warnings, hints)
}

/// **Phase 1 P4 (structural)** — Pick top-k cosine neighbors of a freshly
/// saved memory from the in-process embedding cache. The graph-side of
/// A-MEM evolution: insert `evolved` edges from the new memory to its
/// nearest-existing kin, so future `memory_search_hybrid` (graph fusion)
/// surfaces them together. Skill records are excluded from candidates
/// (same intent as P1.5 coactivation filter).
///
/// Pure / synchronous so it's easy to unit-test. Returns full records
/// (cloned from the cache) so callers — notably the P4b LLM filter step —
/// have the body / tags / kind they need without a second round-trip.
fn pick_evolution_neighbors(
    cached: &[(MemoryRecord, Vec<f32>)],
    new_key: &str,
    new_embedding: &[f32],
    threshold: f32,
    top_k: usize,
) -> Vec<(MemoryRecord, f64)> {
    // Status filter is defense-in-depth against a race in MemoryDeleteTool /
    // MemoryCompactTool: those spawn fire-and-forget cache-cleanup tasks, so
    // a tombstoned/superseded record can still appear in `cached` for a few
    // milliseconds after the SQL row was flipped. Without this filter, the
    // P4 evolve spawn would happily form an `evolved` edge to a record that
    // memory_get already returns null for. SQL semantic-search path already
    // filters status='active'; this brings the cache path to parity.
    let mut sims: Vec<(MemoryRecord, f64)> = cached
        .iter()
        .filter(|(rec, _)| rec.key != new_key && rec.kind != "skill" && rec.status == "active")
        .map(|(rec, emb)| {
            let c = cosine_similarity(new_embedding, emb);
            (rec.clone(), c as f64)
        })
        .filter(|(_, c)| (*c as f32) >= threshold)
        .collect();
    sims.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));
    sims.truncate(top_k);
    sims
}

/// **Phase 1 P4b — LLM-driven evolution filter (A-MEM step 3).**
///
/// Cosine similarity (Phase 1 P4) is necessary but not sufficient: two
/// memories sharing a lot of vocabulary about "Rust async" can still be
/// about completely different problems. A-MEM uses an LLM to make the
/// final "are these conceptually linked?" call. This is the same idea,
/// but conservative: we only ASK the LLM to filter the cosine candidate
/// set down to the truly-related subset. Tags and content of the source
/// memory are never modified (we still defer that to a future P4b.2).
///
/// Returns the indices (0-based) into `candidates` that the LLM kept.
/// On any LLM failure (no API key, parse error, network err) returns the
/// full set unchanged — graceful degradation back to pure cosine.
async fn llm_filter_evolution_neighbors(
    client: &crate::llm_client::LlmClient,
    new_key: &str,
    new_kind: &str,
    new_tags: &[String],
    new_content: &str,
    candidates: &[(MemoryRecord, f64)],
) -> Vec<usize> {
    if candidates.is_empty() {
        return Vec::new();
    }
    let pass_through: Vec<usize> = (0..candidates.len()).collect();

    // Build a compact prompt. We truncate bodies aggressively because the
    // LLM only needs a topical hint, not full prose; this keeps token cost
    // ~1-2k input per save (sub-cent at Haiku rates).
    fn truncate(s: &str, max: usize) -> String {
        let chars: Vec<char> = s.chars().collect();
        if chars.len() <= max {
            s.to_string()
        } else {
            let mut out: String = chars[..max].iter().collect();
            out.push_str(" …");
            out
        }
    }
    let mut prompt = String::new();
    prompt.push_str(
        "You filter memory-graph cluster candidates. Given a NEW memory \
and several cosine-similar candidates, identify which candidates are CONCEPTUALLY \
linked to the NEW memory (about the same problem, decision, or system), not just \
sharing vocabulary. Be strict — when unsure, exclude.\n\n",
    );
    prompt.push_str(&format!(
        "NEW MEMORY\nkey: {new_key}\nkind: {new_kind}\ntags: {tags}\nbody: {body}\n\n",
        new_key = new_key,
        new_kind = new_kind,
        tags = new_tags.join(", "),
        body = truncate(new_content, 500),
    ));
    prompt.push_str("CANDIDATES\n");
    for (i, (rec, _score)) in candidates.iter().enumerate() {
        prompt.push_str(&format!(
            "[{n}] key: {k}\n    kind: {kind}, tags: {tags}\n    body: {body}\n\n",
            n = i + 1,
            k = rec.key,
            kind = rec.kind,
            tags = rec.tags.join(", "),
            body = truncate(&rec.content, 300),
        ));
    }
    prompt.push_str(
        "Return ONLY this JSON, no commentary, no markdown, no prose:\n\
         {\"linked_indices\": [1, 3]}\n\
         Use 1-based indices into CANDIDATES. Empty array means none link.",
    );

    let messages = vec![crate::llm_client::Message {
        role: "user".to_string(),
        content: prompt,
    }];

    let model = client.default_model();
    let resp = match client.messages_create(&model, None, &messages, 256).await {
        Ok(r) => r,
        Err(e) => {
            tracing::warn!(
                target: "p4b_evolve",
                key = %new_key,
                error = %e,
                "P4b LLM filter failed; falling back to cosine-only"
            );
            return pass_through;
        }
    };

    parse_llm_filter_response(&resp.text, candidates.len()).unwrap_or_else(|reason| {
        tracing::warn!(
            target: "p4b_evolve",
            key = %new_key,
            reason = reason,
            text_preview = %resp.text.chars().take(200).collect::<String>(),
            "P4b LLM filter parse failed; falling back to cosine-only"
        );
        pass_through
    })
}

/// Parse `{"linked_indices": [1, 3]}` from LLM output. Tolerates leading/trailing
/// markdown fences (` ```json ... ``` `) by extracting the first JSON object.
/// Returns 0-based indices clamped to `[0, candidate_count)`.
fn parse_llm_filter_response(
    text: &str,
    candidate_count: usize,
) -> std::result::Result<Vec<usize>, &'static str> {
    let trimmed = text.trim();
    // Strip ```json ... ``` fences if present.
    let inner = trimmed
        .strip_prefix("```json")
        .or_else(|| trimmed.strip_prefix("```"))
        .unwrap_or(trimmed);
    let inner = inner.strip_suffix("```").unwrap_or(inner);
    // Extract first {...} JSON object — robustness against accidental prose.
    let start = inner.find('{').ok_or("no JSON object")?;
    let end = inner.rfind('}').ok_or("no JSON object close")?;
    if end <= start {
        return Err("JSON braces in wrong order");
    }
    let json_slice = &inner[start..=end];

    let v: serde_json::Value = serde_json::from_str(json_slice).map_err(|_| "JSON parse failed")?;
    let arr = v
        .get("linked_indices")
        .and_then(|x| x.as_array())
        .ok_or("missing linked_indices array")?;
    Ok(arr
        .iter()
        .filter_map(|n| n.as_u64())
        .map(|n| n.saturating_sub(1) as usize) // 1-based → 0-based
        .filter(|&i| i < candidate_count)
        .collect())
}

const CONTINUITY_ROLE_TAG_PREFIX: &str = "continuity_role:";
const CONTINUITY_RETRIEVAL_TRIGGER_TAG_PREFIX: &str = "continuity_retrieval_trigger:";
const CONTINUITY_CONFIDENCE_TAG_PREFIX: &str = "continuity_confidence:";
const CONTINUITY_FRESHNESS_POLICY_TAG_PREFIX: &str = "continuity_freshness_policy:";
const CONTINUITY_ACTIONABILITY_TAG_PREFIX: &str = "continuity_actionability:";
const CONTINUITY_BLAST_RADIUS_TAG_PREFIX: &str = "continuity_blast_radius:";
const CONTINUITY_SUPERSEDES_TAG_PREFIX: &str = "continuity_supersedes:";
const CONTINUITY_RETRIEVAL_TRIGGER_MAX_CHARS: usize = 160;

const CONTINUITY_TAG_PREFIXES: [&str; 7] = [
    CONTINUITY_ROLE_TAG_PREFIX,
    CONTINUITY_RETRIEVAL_TRIGGER_TAG_PREFIX,
    CONTINUITY_CONFIDENCE_TAG_PREFIX,
    CONTINUITY_FRESHNESS_POLICY_TAG_PREFIX,
    CONTINUITY_ACTIONABILITY_TAG_PREFIX,
    CONTINUITY_BLAST_RADIUS_TAG_PREFIX,
    CONTINUITY_SUPERSEDES_TAG_PREFIX,
];

const CONTINUITY_ROLE_INPUT_VALUES: [&str; 8] = [
    "state",
    "constraint",
    "procedure",
    "evidence",
    "preference",
    "warning",
    "archive",
    "decision",
];
const CONTINUITY_CONFIDENCE_VALUES: [&str; 5] =
    ["verified", "observed", "inferred", "user_stated", "stale"];
const CONTINUITY_FRESHNESS_POLICY_VALUES: [&str; 4] = [
    "never_expires",
    "ttl",
    "version_bound",
    "project_phase_bound",
];
const CONTINUITY_ACTIONABILITY_VALUES: [&str; 4] = [
    "background",
    "plan_influence",
    "must_block",
    "needs_review",
];
const CONTINUITY_BLAST_RADIUS_VALUES: [&str; 4] =
    ["current_task", "project", "cross_project", "global"];

#[derive(Clone, Debug, Default, PartialEq, Eq)]
struct MemoryContinuityMetadata {
    continuity_role: Option<String>,
    retrieval_trigger: Option<String>,
    confidence: Option<String>,
    freshness_policy: Option<String>,
    actionability: Option<String>,
    blast_radius: Option<String>,
    supersedes: Vec<String>,
    superseded_by: Option<String>,
}

impl MemoryContinuityMetadata {
    fn is_empty(&self) -> bool {
        self.continuity_role.is_none()
            && self.retrieval_trigger.is_none()
            && self.confidence.is_none()
            && self.freshness_policy.is_none()
            && self.actionability.is_none()
            && self.blast_radius.is_none()
            && self.supersedes.is_empty()
            && self.superseded_by.is_none()
    }

    fn to_json_value(&self) -> Value {
        let mut obj = Map::new();
        if let Some(value) = &self.continuity_role {
            obj.insert("continuity_role".to_string(), Value::String(value.clone()));
        }
        if let Some(value) = &self.retrieval_trigger {
            obj.insert("retrieval_trigger".to_string(), Value::String(value.clone()));
        }
        if let Some(value) = &self.confidence {
            obj.insert("confidence".to_string(), Value::String(value.clone()));
        }
        if let Some(value) = &self.freshness_policy {
            obj.insert("freshness_policy".to_string(), Value::String(value.clone()));
        }
        if let Some(value) = &self.actionability {
            obj.insert("actionability".to_string(), Value::String(value.clone()));
        }
        if let Some(value) = &self.blast_radius {
            obj.insert("blast_radius".to_string(), Value::String(value.clone()));
        }
        if !self.supersedes.is_empty() {
            obj.insert("supersedes".to_string(), json!(self.supersedes));
        }
        if let Some(value) = &self.superseded_by {
            obj.insert("superseded_by".to_string(), Value::String(value.clone()));
        }
        Value::Object(obj)
    }
}

fn memory_validate_continuity_enum(
    field: &str,
    value: &str,
    allowed: &[&str],
) -> std::result::Result<String, String> {
    let trimmed = value.trim();
    if trimmed.is_empty() {
        return Ok(String::new());
    }
    if allowed.contains(&trimmed) {
        Ok(trimmed.to_string())
    } else {
        Err(format!(
            "invalid continuity.{field}: '{trimmed}' (allowed: {})",
            allowed.join(", ")
        ))
    }
}

fn memory_continuity_string_field(obj: &Map<String, Value>, field: &str) -> Option<String> {
    obj.get(field)
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(|s| s.chars().take(CONTINUITY_RETRIEVAL_TRIGGER_MAX_CHARS).collect())
}

fn memory_continuity_enum_field(
    obj: &Map<String, Value>,
    field: &str,
    allowed: &[&str],
) -> std::result::Result<Option<String>, String> {
    match obj.get(field).and_then(Value::as_str) {
        Some(value) => {
            let mut parsed = memory_validate_continuity_enum(field, value, allowed)?;
            if field == "continuity_role" && parsed == "decision" {
                parsed = "state".to_string();
            }
            Ok((!parsed.is_empty()).then_some(parsed))
        }
        None => Ok(None),
    }
}

fn memory_continuity_metadata_from_args(
    args: &Value,
) -> std::result::Result<Option<MemoryContinuityMetadata>, String> {
    let Some(raw) = args.get("continuity") else {
        return Ok(None);
    };
    let Some(obj) = raw.as_object() else {
        return Err("continuity must be an object".to_string());
    };

    let supersedes = obj
        .get("supersedes")
        .and_then(Value::as_array)
        .map(|items| {
            items
                .iter()
                .filter_map(Value::as_str)
                .map(str::trim)
                .filter(|s| !s.is_empty())
                .map(str::to_string)
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    let metadata = MemoryContinuityMetadata {
        continuity_role: memory_continuity_enum_field(
            obj,
            "continuity_role",
            &CONTINUITY_ROLE_INPUT_VALUES,
        )?,
        retrieval_trigger: memory_continuity_string_field(obj, "retrieval_trigger"),
        confidence: memory_continuity_enum_field(obj, "confidence", &CONTINUITY_CONFIDENCE_VALUES)?,
        freshness_policy: memory_continuity_enum_field(
            obj,
            "freshness_policy",
            &CONTINUITY_FRESHNESS_POLICY_VALUES,
        )?,
        actionability: memory_continuity_enum_field(
            obj,
            "actionability",
            &CONTINUITY_ACTIONABILITY_VALUES,
        )?,
        blast_radius: memory_continuity_enum_field(
            obj,
            "blast_radius",
            &CONTINUITY_BLAST_RADIUS_VALUES,
        )?,
        supersedes,
        superseded_by: None,
    };

    Ok((!metadata.is_empty()).then_some(metadata))
}

fn memory_push_unique_tag(tags: &mut Vec<String>, tag: String) {
    if !tags.iter().any(|existing| existing == &tag) {
        tags.push(tag);
    }
}

fn memory_apply_continuity_metadata_tags(
    tags: &mut Vec<String>,
    metadata: &MemoryContinuityMetadata,
) {
    tags.retain(|tag| {
        !CONTINUITY_TAG_PREFIXES
            .iter()
            .any(|prefix| tag.starts_with(prefix))
    });

    if let Some(value) = &metadata.continuity_role {
        memory_push_unique_tag(tags, format!("{CONTINUITY_ROLE_TAG_PREFIX}{value}"));
    }
    if let Some(value) = &metadata.retrieval_trigger {
        memory_push_unique_tag(
            tags,
            format!("{CONTINUITY_RETRIEVAL_TRIGGER_TAG_PREFIX}{value}"),
        );
    }
    if let Some(value) = &metadata.confidence {
        memory_push_unique_tag(tags, format!("{CONTINUITY_CONFIDENCE_TAG_PREFIX}{value}"));
    }
    if let Some(value) = &metadata.freshness_policy {
        memory_push_unique_tag(
            tags,
            format!("{CONTINUITY_FRESHNESS_POLICY_TAG_PREFIX}{value}"),
        );
    }
    if let Some(value) = &metadata.actionability {
        memory_push_unique_tag(tags, format!("{CONTINUITY_ACTIONABILITY_TAG_PREFIX}{value}"));
    }
    if let Some(value) = &metadata.blast_radius {
        memory_push_unique_tag(tags, format!("{CONTINUITY_BLAST_RADIUS_TAG_PREFIX}{value}"));
    }
    for key in &metadata.supersedes {
        memory_push_unique_tag(tags, format!("{CONTINUITY_SUPERSEDES_TAG_PREFIX}{key}"));
    }
}

fn memory_tag_suffix(tags: &[String], prefix: &str) -> Option<String> {
    tags.iter()
        .find_map(|tag| tag.strip_prefix(prefix))
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(str::to_string)
}

fn memory_tag_suffixes(tags: &[String], prefix: &str) -> Vec<String> {
    let mut seen = BTreeSet::new();
    tags.iter()
        .filter_map(|tag| tag.strip_prefix(prefix))
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .filter_map(|s| {
            let value = s.to_string();
            seen.insert(value.clone()).then_some(value)
        })
        .collect()
}

fn memory_continuity_metadata_from_tags(
    tags: &[String],
    superseded_by: Option<&str>,
) -> Option<MemoryContinuityMetadata> {
    let metadata = MemoryContinuityMetadata {
        continuity_role: memory_tag_suffix(tags, CONTINUITY_ROLE_TAG_PREFIX),
        retrieval_trigger: memory_tag_suffix(tags, CONTINUITY_RETRIEVAL_TRIGGER_TAG_PREFIX),
        confidence: memory_tag_suffix(tags, CONTINUITY_CONFIDENCE_TAG_PREFIX),
        freshness_policy: memory_tag_suffix(tags, CONTINUITY_FRESHNESS_POLICY_TAG_PREFIX),
        actionability: memory_tag_suffix(tags, CONTINUITY_ACTIONABILITY_TAG_PREFIX),
        blast_radius: memory_tag_suffix(tags, CONTINUITY_BLAST_RADIUS_TAG_PREFIX),
        supersedes: memory_tag_suffixes(tags, CONTINUITY_SUPERSEDES_TAG_PREFIX),
        superseded_by: superseded_by
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .map(str::to_string),
    };
    (!metadata.is_empty()).then_some(metadata)
}

fn memory_record_value_with_continuity(rec: &MemoryRecord) -> Value {
    let mut value = serde_json::to_value(rec).unwrap_or(Value::Null);
    if let Some(obj) = value.as_object_mut() {
        let metadata =
            memory_continuity_metadata_from_tags(&rec.tags, rec.superseded_by.as_deref())
                .map(|m| m.to_json_value())
                .unwrap_or(Value::Null);
        obj.insert("continuity_metadata".to_string(), metadata);
    }
    value
}

fn memory_search_hit_value_with_continuity(hit: &MemorySearchHit) -> Value {
    let mut value = serde_json::to_value(hit).unwrap_or(Value::Null);
    if let Some(obj) = value.as_object_mut() {
        obj.insert(
            "record".to_string(),
            memory_record_value_with_continuity(&hit.record),
        );
    }
    value
}

pub struct MemorySaveTool {
    hub: Hub,
}
impl MemorySaveTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for MemorySaveTool {
    fn name(&self) -> &'static str {
        "memory_save"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Persist one note to agent self-memory (cross-session). Record \
                 lessons, decisions, todos, or context the next-session-you should know. \
                 Same key overwrites: created_at preserved, updated_at bumps. related_keys: \
                 free-form list of related memory keys."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "key":          { "type": "string", "description": "Unique stable id, e.g. 'v0.5_design' or 'agent_spawn_pitfall'." },
                    "kind":         { "type": "string", "description": "lesson | decision | todo | context | session_handoff | …" },
                    "content":      { "type": "string", "description": "Markdown / free text. Capped at 256 KiB." },
                    "tags":         { "type": "array", "items": { "type": "string" }, "default": [] },
                    "related_keys": { "type": "array", "items": { "type": "string" }, "default": [] },
                    "scope":        { "type": "string", "description": "Visibility: omit/global=everywhere, project:/abs/path=cwd-scoped, domain:rust=tech-domain." },
                    "scope_identity_trace": { "type": "boolean", "default": false, "description": "If true, return a git/project-id identity trace plus no-op scope-write shadow comparison for project scopes without changing the stored scope. Honors explicit project-id scopes, AGENT_BRIDGE_PROJECT_SCOPE_ALIASES policy matches, and AGENT_BRIDGE_PROJECT_ID for dedicated processes." },
                    "importance":   { "type": "number", "minimum": 0.0, "maximum": 1.0, "description": "Override importance (0.0–1.0). Omit to auto-assign from kind: decision=0.8, lesson=0.7, todo=0.6, fact=0.5, observation=0.3." },
                    "trigger_pattern": { "type": "string", "description": "For kind=error_pattern: surfacing when session_bootstrap `error_hint` contains this substring (case-insensitive)." },
                    "continuity": {
                        "type": "object",
                        "description": "Optional continuity metadata encoded in backward-compatible memory tags and surfaced as continuity_metadata on reads.",
                        "properties": {
                            "continuity_role": { "type": "string", "enum": ["state", "constraint", "procedure", "evidence", "preference", "warning", "archive", "decision"], "description": "`decision` is accepted as an input alias and stored as `state`; use `kind: decision` for the memory's durable type." },
                            "retrieval_trigger": { "type": "string", "description": "Short condition under which this memory should be retrieved. Stored with a 160-character cap." },
                            "confidence": { "type": "string", "enum": ["verified", "observed", "inferred", "user_stated", "stale"] },
                            "freshness_policy": { "type": "string", "enum": ["never_expires", "ttl", "version_bound", "project_phase_bound"] },
                            "actionability": { "type": "string", "enum": ["background", "plan_influence", "must_block", "needs_review"] },
                            "blast_radius": { "type": "string", "enum": ["current_task", "project", "cross_project", "global"] },
                            "supersedes": { "type": "array", "items": { "type": "string" }, "default": [] }
                        }
                    }
                },
                "required": ["key", "kind", "content"]
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let key = match args.get("key").and_then(|v| v.as_str()) {
            Some(s) if !s.is_empty() => s.to_string(),
            _ => return Ok(ToolResult::error("missing or empty 'key'")),
        };
        let kind = match args.get("kind").and_then(|v| v.as_str()) {
            Some(s) if !s.is_empty() => s.to_string(),
            _ => return Ok(ToolResult::error("missing or empty 'kind'")),
        };
        let content = args
            .get("content")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_string();
        let mut tags: Vec<String> = args
            .get("tags")
            .and_then(|v| v.as_array())
            .map(|a| {
                a.iter()
                    .filter_map(|x| x.as_str().map(|s| s.to_string()))
                    .collect()
            })
            .unwrap_or_default();
        let mut related_keys: Vec<String> = args
            .get("related_keys")
            .and_then(|v| v.as_array())
            .map(|a| {
                a.iter()
                    .filter_map(|x| x.as_str().map(|s| s.to_string()))
                    .collect()
            })
            .unwrap_or_default();
        let scope = args
            .get("scope")
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty() && *s != "global")
            .map(|s| s.to_string());
        let scope_identity_trace_requested = args
            .get("scope_identity_trace")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let scope_identity_trace = if scope_identity_trace_requested {
            Some(memory_save_scope_identity_trace(scope.as_deref()))
        } else {
            None
        };
        // Optional importance override; 0.5 = "use kind-based default"
        let importance = args
            .get("importance")
            .and_then(|v| v.as_f64())
            .unwrap_or(0.5)
            .clamp(0.0, 1.0);

        let trigger_pattern = args
            .get("trigger_pattern")
            .and_then(|v| v.as_str())
            .map(|s| s.trim().to_string())
            .filter(|s| !s.is_empty());

        let continuity_metadata = match memory_continuity_metadata_from_args(&args) {
            Ok(value) => value,
            Err(message) => return Ok(ToolResult::error(message)),
        };
        if let Some(metadata) = &continuity_metadata {
            memory_apply_continuity_metadata_tags(&mut tags, metadata);
            for key in &metadata.supersedes {
                if !related_keys.iter().any(|existing| existing == key) {
                    related_keys.push(key.clone());
                }
            }
        }

        let mem = MemoryRecord {
            key: key.clone(),
            kind,
            content,
            tags,
            related_keys,
            scope,
            created_at: 0,
            updated_at: 0,
            last_accessed_at: 0,
            access_count: 0,
            importance,
            status: "active".to_string(),
            trigger_pattern,
            superseded_by: None,
        };
        // B3 preflight (audit-gap B3 v0) — see `b3_preflight` rustdoc + design memo.
        // Runs before the save so warnings reach the caller in the same response;
        // the save is not blocked, this is advisory. memory_correction is a
        // separate tool path so naturally untouched per Q2 self-match argument.
        let b3_disabled = std::env::var("AB_REDO_WARN_DISABLE")
            .map(|v| v == "1")
            .unwrap_or(false);
        let b3_eligible_kind = {
            use ab_store::CATALOG_KINDS_C3;
            !CATALOG_KINDS_C3.contains(&mem.kind.as_str())
        };
        let sync_advisory_enabled = memory_save_sync_advisory_enabled(&mem.content);
        let (b3_warnings, b3_hints) = if sync_advisory_enabled && !b3_disabled && b3_eligible_kind {
            b3_preflight(&store, &mem.key, &mem.content, &mem.kind).await
        } else {
            (Vec::new(), Vec::new())
        };
        match store.memory_save(&mem).await {
            Ok(()) => {
                // Keep embedding cache coherent AND auto-evolve the graph:
                // 1) upsert the new record into the cache (best-effort)
                // 2) **Phase 1 P4 structural** — pick top-k cosine neighbors
                //    and write `evolved` edges. The graph densifies organically
                //    as memories are saved (deterministic half of A-MEM
                //    evolution; LLM-driven tag/X rewrite deferred to P4b).
                //
                // **Cache fallback fix**: the embedding cache is `None` until
                // `session_bootstrap` or `memory_reindex` populates it. Pre-fix
                // version silently exited if cache was empty — meaning P4
                // never fired in cold sessions. Now: prefer cache when warm,
                // fall back to `store.memory_search_semantic` when cold so
                // edges always get written. The semantic-search call costs
                // ~11ms per save (one embed + small cosine sweep), which is
                // acceptable for a background spawn.
                {
                    let cache = self.hub.memory_embed_cache.clone();
                    let store_for_evolve = store.clone();
                    let new_key_for_evolve = key.clone();
                    let new_content_for_evolve = mem.content.clone();
                    let rec = mem.clone();
                    let emb = embed_text(&rec.content);
                    let emb_for_evolve = emb.clone();
                    let new_kind_for_evolve = mem.kind.clone();
                    let new_tags_for_evolve = mem.tags.clone();
                    tokio::spawn(async move {
                        tracing::debug!(
                            target: "p4_evolve",
                            key = %new_key_for_evolve,
                            "P4 evolve spawn entry"
                        );
                        // Step 1: cosine candidates (warm cache → in-memory;
                        //   cold cache → store fallback).
                        let candidates: Vec<(MemoryRecord, f64)> = {
                            let mut guard = cache.lock().await;
                            if let Some(ref mut cached) = *guard {
                                cached.retain(|(r, _)| r.key != rec.key);
                                cached.push((rec, emb));
                                let n = pick_evolution_neighbors(
                                    cached,
                                    &new_key_for_evolve,
                                    &emb_for_evolve,
                                    /* threshold */ 0.65,
                                    /* top_k */ 5,
                                );
                                drop(guard);
                                tracing::debug!(
                                    target: "p4_evolve",
                                    key = %new_key_for_evolve,
                                    branch = "warm",
                                    candidates = n.len(),
                                    "P4 evolve cosine candidates picked"
                                );
                                n
                            } else {
                                drop(guard);
                                match store_for_evolve
                                    .memory_search_semantic(
                                        &new_content_for_evolve,
                                        /* limit */ 15,
                                        /* threshold */ 0.65,
                                    )
                                    .await
                                {
                                    Ok(hits) => {
                                        let n: Vec<(MemoryRecord, f64)> = hits
                                            .into_iter()
                                            .filter(|h| {
                                                h.record.key != new_key_for_evolve
                                                    && h.record.kind != "skill"
                                            })
                                            .take(5)
                                            .map(|h| (h.record, h.score))
                                            .collect();
                                        tracing::debug!(
                                            target: "p4_evolve",
                                            key = %new_key_for_evolve,
                                            branch = "cold",
                                            candidates = n.len(),
                                            "P4 evolve cosine candidates picked (cold)"
                                        );
                                        n
                                    }
                                    Err(e) => {
                                        tracing::warn!(
                                            target: "p4_evolve",
                                            key = %new_key_for_evolve,
                                            error = %e,
                                            "P4 evolve cold path memory_search_semantic FAILED"
                                        );
                                        Vec::new()
                                    }
                                }
                            }
                        };

                        // Step 2: P4b — optional LLM filter. If ANTHROPIC_API_KEY
                        // is set, ask the LLM which candidates are conceptually
                        // linked (vs just sharing vocabulary). On any failure
                        // (no key / parse / network), pass everything through —
                        // structural P4 still works without LLM.
                        let kept_indices: Vec<usize> = if candidates.is_empty() {
                            Vec::new()
                        } else {
                            match crate::llm_client::LlmClient::from_env() {
                                Ok(client) => {
                                    let kept = llm_filter_evolution_neighbors(
                                        &client,
                                        &new_key_for_evolve,
                                        &new_kind_for_evolve,
                                        &new_tags_for_evolve,
                                        &new_content_for_evolve,
                                        &candidates,
                                    )
                                    .await;
                                    tracing::debug!(
                                        target: "p4b_evolve",
                                        key = %new_key_for_evolve,
                                        candidates = candidates.len(),
                                        kept = kept.len(),
                                        "P4b LLM filter applied"
                                    );
                                    kept
                                }
                                Err(_) => {
                                    // No API key configured — degrade to cosine-only.
                                    // Logged at debug because this is the expected
                                    // path for users who haven't set up Anthropic.
                                    tracing::debug!(
                                        target: "p4b_evolve",
                                        key = %new_key_for_evolve,
                                        "P4b LLM unavailable (no API key); using all cosine candidates"
                                    );
                                    (0..candidates.len()).collect()
                                }
                            }
                        };

                        // Step 3: write evolution edges for the kept set.
                        for idx in kept_indices {
                            let (neighbor, score) = match candidates.get(idx) {
                                Some(c) => c,
                                None => continue,
                            };
                            match store_for_evolve
                                .memory_link(&new_key_for_evolve, &neighbor.key, "evolved", *score)
                                .await
                            {
                                Ok(()) => tracing::debug!(
                                    target: "p4_evolve",
                                    from = %new_key_for_evolve,
                                    to = %neighbor.key,
                                    score = score,
                                    "P4 evolve edge written"
                                ),
                                Err(e) => tracing::warn!(
                                    target: "p4_evolve",
                                    from = %new_key_for_evolve,
                                    to = %neighbor.key,
                                    error = %e,
                                    "P4 evolve memory_link FAILED"
                                ),
                            }
                        }
                    });
                }
                let hint = if sync_advisory_enabled {
                    build_proactive_hint(&store, &key, &mem.content, &mem.tags).await
                } else {
                    None
                };
                let mut resp = json!({
                    "status": "saved",
                    "key": key,
                    "continuity_metadata": continuity_metadata
                        .as_ref()
                        .map(MemoryContinuityMetadata::to_json_value)
                        .unwrap_or(Value::Null),
                    "proactive_hint": hint,
                    "prior_decision_warnings": b3_warnings,
                    "prior_decision_hints": b3_hints,
                });
                if let Some(trace) = scope_identity_trace {
                    resp["scope_identity_trace"] = trace;
                }
                Ok(ToolResult::json_text(&resp))
            }
            Err(e) => Ok(ToolResult::error(format!("memory: {e}"))),
        }
    }
}

const MEMORY_SAVE_PROJECT_ID_ENV: &str = "AGENT_BRIDGE_PROJECT_ID";

fn memory_save_scope_identity_trace(scope: Option<&str>) -> Value {
    let configured_project_id = std::env::var(MEMORY_SAVE_PROJECT_ID_ENV).ok();
    let project_scope_aliases = std::env::var(PROJECT_SCOPE_ALIASES_ENV).ok();
    memory_save_scope_identity_trace_with_policy(
        scope,
        configured_project_id.as_deref(),
        project_scope_aliases.as_deref(),
    )
}

#[cfg(test)]
fn memory_save_scope_identity_trace_with_project_id(
    scope: Option<&str>,
    configured_project_id: Option<&str>,
) -> Value {
    memory_save_scope_identity_trace_with_policy(scope, configured_project_id, None)
}

fn memory_save_scope_identity_trace_with_policy(
    scope: Option<&str>,
    configured_project_id: Option<&str>,
    project_scope_aliases: Option<&str>,
) -> Value {
    let Some(scope) = scope.map(str::trim).filter(|s| !s.is_empty()) else {
        return json!({
            "status": "not_applicable",
            "reason": "no project scope supplied",
            "write_policy": "trace_only_stored_scope_unchanged",
        });
    };

    let scope_project_id =
        strip_scope_prefix_case_insensitive(scope, crate::project_identity::PROJECT_ID_SCOPE_PREFIX);
    let legacy_project_path =
        strip_scope_prefix_case_insensitive(scope, crate::project_identity::LEGACY_PROJECT_SCOPE_PREFIX);
    if scope_project_id.is_none() && legacy_project_path.is_none() {
        return json!({
            "status": "not_applicable",
            "requested_scope": scope,
            "reason": "non_project_scope",
            "write_policy": "trace_only_stored_scope_unchanged",
        });
    }

    let policy_project_id = project_scope_aliases
        .map(str::trim)
        .filter(|aliases| !aliases.is_empty())
        .and_then(|aliases| crate::project_identity::approved_scope_alias_canonical(scope, aliases));
    let configured_project_id = configured_project_id
        .map(str::trim)
        .filter(|project_id| !project_id.is_empty());
    let canonical_policy_scope =
        memory_save_scope_policy_canonical(policy_project_id.as_deref(), configured_project_id);
    let explicit_project_id = scope_project_id
        .map(|_| scope)
        .or(policy_project_id.as_deref())
        .or(configured_project_id);
    let explicit_project_id_source = if scope_project_id.is_some() {
        "scope"
    } else if policy_project_id.is_some() {
        "policy"
    } else if configured_project_id.is_some() {
        "env"
    } else {
        "none"
    };

    let cwd = legacy_project_path
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(str::to_string)
        .or_else(|| std::env::current_dir().ok().map(|p| p.display().to_string()));

    let Some(cwd) = cwd else {
        return json!({
            "status": "not_applicable",
            "requested_scope": scope,
            "reason": "could not resolve cwd for project identity trace",
            "write_policy": "trace_only_stored_scope_unchanged",
        });
    };

    let cwd_path = Path::new(&cwd);
    let git_remote = memory_save_git_capture(cwd_path, &["remote", "get-url", "origin"]);
    let git_root = memory_save_git_capture(cwd_path, &["rev-parse", "--show-toplevel"]);
    let identity = crate::project_identity::resolve_project_identity(
        crate::project_identity::ProjectIdentityInput {
            cwd: &cwd,
            explicit_project_id,
            git_remote: git_remote.as_deref(),
            git_root: git_root.as_deref(),
        },
    );
    let identity_source = if explicit_project_id_source == "none" {
        identity.evidence.label()
    } else {
        explicit_project_id_source
    };
    let shadow_decision = crate::project_identity::evaluate_scope_write_shadow(
        scope,
        canonical_policy_scope.as_deref(),
        project_scope_aliases,
    );

    json!({
        "status": "ok",
        "requested_scope": scope,
        "stored_scope": scope,
        "stored_scope_changed": false,
        "write_policy": "trace_only_stored_scope_unchanged",
        "identity": identity.identity,
        "canonical_scope": identity.canonical_scope,
        "legacy_scope": identity.legacy_scope,
        "explicit_project_id_source": explicit_project_id_source,
        "evidence": identity.evidence.label(),
        "high_confidence": identity.evidence.is_high_confidence(),
        "git_remote": git_remote,
        "git_root": git_root,
        "scope_write_shadow_comparison": memory_save_scope_shadow_decision_value(
            &shadow_decision,
            identity_source,
            &identity.canonical_scope,
        ),
    })
}

fn memory_save_scope_policy_canonical(
    policy_project_id: Option<&str>,
    configured_project_id: Option<&str>,
) -> Option<String> {
    policy_project_id
        .or(configured_project_id)
        .map(str::trim)
        .filter(|project_id| !project_id.is_empty())
        .and_then(|project_id| {
            crate::project_identity::normalize_project_id(project_id)
                .map(|id| crate::project_identity::project_id_scope(&id))
        })
}

fn memory_save_scope_shadow_decision_value(
    decision: &crate::project_identity::ScopeWriteShadowDecision,
    identity_source: &str,
    resolved_identity_scope: &str,
) -> Value {
    json!({
        "status": "ok",
        "requested_scope": decision.requested_scope,
        "current_stored_scope": decision.requested_scope,
        "stored_scope_changed": false,
        "write_policy": "shadow_only_stored_scope_unchanged",
        "production_write_authorized": false,
        "identity_source": identity_source,
        "resolved_identity_scope": resolved_identity_scope,
        "canonical_policy_scope": decision.canonical_policy_scope,
        "reviewed_alias_registry_match": decision.reviewed_alias_registry_match,
        "shadow_action": decision.action.label(),
        "reason": decision.reason,
        "proposed_scope": decision.proposed_scope,
        "would_store_scope_if_enabled": decision.would_store_scope_if_enabled,
        "legacy_scope_preserved": decision.legacy_scope_preserved,
        "shadow_write_eligible": decision.shadow_write_eligible,
    })
}

fn strip_scope_prefix_case_insensitive<'a>(raw: &'a str, prefix: &str) -> Option<&'a str> {
    raw.get(..prefix.len())
        .filter(|candidate| candidate.eq_ignore_ascii_case(prefix))
        .and_then(|_| raw.get(prefix.len()..))
}

fn memory_save_git_capture(cwd: &Path, args: &[&str]) -> Option<String> {
    let out = std::process::Command::new("git")
        .current_dir(cwd)
        .args(args)
        .output()
        .ok()?;
    if !out.status.success() {
        return None;
    }
    let text = String::from_utf8_lossy(&out.stdout).trim().to_string();
    (!text.is_empty()).then_some(text)
}

/// Phase 0 telemetry helper. Build a `MemoryQueryRecord` with the common
/// fields and dispatch a fire-and-forget log write so the MCP request path
/// stays sub-ms even when the store is contended. We pass the store as `Arc`
/// because `tokio::spawn` needs an owned value.
fn log_memory_query(
    store: Arc<dyn StateStore>,
    kind: &'static str,
    query: String,
    tags_json: String,
    hit_count: u32,
    top_hit_age_secs: Option<i64>,
    top_hit_created_at: Option<i64>,
    duration: Duration,
    source: &'static str,
) {
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0);
    let rec = MemoryQueryRecord {
        kind: kind.to_string(),
        query,
        tags_json,
        hit_count,
        top_hit_age_secs,
        top_hit_created_at,
        duration_us: duration.as_micros().min(u32::MAX as u128) as u32,
        source: source.to_string(),
        at: now,
    };
    tokio::spawn(async move {
        let _ = store.record_memory_query(&rec).await;
    });
}

pub struct MemoryGetTool {
    hub: Hub,
}
impl MemoryGetTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for MemoryGetTool {
    fn name(&self) -> &'static str {
        "memory_get"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Fetch one memory by exact key. Side effect: bumps the row's \
                 access_count and last_accessed_at — this is what gives \
                 `memory_search` ranking and `memory_compact` something to score \
                 against. Returns null if the key is unknown."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": { "key": { "type": "string" } },
                "required": ["key"]
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let key = match args.get("key").and_then(|v| v.as_str()) {
            Some(s) => s.to_string(),
            None => return Ok(ToolResult::error("missing 'key'")),
        };
        let started = Instant::now();
        let row = store.memory_get(&key).await?;
        let elapsed = started.elapsed();

        // Phase 0 telemetry: log hit/miss + age. last_accessed_at was just
        // bumped by memory_get so we use created_at as the recency anchor.
        let now_secs = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_secs() as i64)
            .unwrap_or(0);
        let (hit_count, age, created) = match &row {
            Some(rec) => (1u32, Some(now_secs - rec.created_at), Some(rec.created_at)),
            None => (0u32, None, None),
        };
        log_memory_query(
            store.clone(),
            "get",
            key.clone(),
            "[]".to_string(),
            hit_count,
            age,
            created,
            elapsed,
            "mcp:memory_get",
        );

        match row {
            None => Ok(ToolResult::json_text(&Value::Null)),
            Some(rec) => {
                let hint = build_proactive_hint(&store, &key, &rec.content, &rec.tags).await;
                let mut resp = memory_record_value_with_continuity(&rec);
                if let Some(obj) = resp.as_object_mut() {
                    obj.insert(
                        "proactive_hint".to_string(),
                        hint.map(Value::String).unwrap_or(Value::Null),
                    );
                }
                Ok(ToolResult::json_text(&resp))
            }
        }
    }
}

/// Item B (2026-06-26, #120): is the owner-gated semantic fallback for the
/// FTS-empty recall tail enabled? **Default-OFF** — only an explicit
/// `AGENT_BRIDGE_RECALL_SEMANTIC_FALLBACK=1`/`true` turns it on; until then the
/// default (fts) `memory_search` path is byte-identical to the prior behavior.
/// Rationale: gte-768 semantic recall is ~2x fts on the hard (no-lexical-overlap)
/// recall_eval tier, but only for queries FTS cannot serve at all — so the
/// fallback fires strictly when FTS returns zero rows AND a real (non-hash)
/// embedder is loaded. Pure (env split out) so the policy is unit-tested.
fn recall_semantic_fallback_enabled_from(env_val: Option<&str>) -> bool {
    matches!(env_val, Some(v) if v == "1" || v.eq_ignore_ascii_case("true"))
}

fn recall_semantic_fallback_enabled() -> bool {
    recall_semantic_fallback_enabled_from(
        std::env::var("AGENT_BRIDGE_RECALL_SEMANTIC_FALLBACK")
            .ok()
            .as_deref(),
    )
}

/// Item B real-embedder gate: would a query embed produce a REAL vector (not the
/// hash fallback)? Under remote delegation the embed runs on a warm peer, so the
/// local model state is irrelevant. Otherwise the local ONNX model must have
/// actually loaded AND the active backend must not be the hash fallback — this
/// covers cold-load (model_init_done false), a hash-only build (model_init_done
/// is true unconditionally there, but the backend name is the hash backend), and
/// a permanent model-load failure. Consulted only on the rare FTS-empty branch.
fn fallback_embedder_ready() -> bool {
    if crate::remote_embed::active_remote_url().is_some() {
        return true;
    }
    ab_store::vector::model_init_done()
        && !ab_store::embedding::default_backend()
            .name()
            .to_ascii_lowercase()
            .contains("hash")
}

#[cfg(test)]
mod recall_semantic_fallback_tests {
    use super::recall_semantic_fallback_enabled_from;

    #[test]
    fn semantic_fallback_default_off_unless_truthy() {
        // Default-OFF: unset / "0" / arbitrary values keep the fts path byte-identical.
        assert!(!recall_semantic_fallback_enabled_from(None));
        assert!(!recall_semantic_fallback_enabled_from(Some("0")));
        assert!(!recall_semantic_fallback_enabled_from(Some("")));
        assert!(!recall_semantic_fallback_enabled_from(Some("yes")));
        // Only an explicit truthy value opts in.
        assert!(recall_semantic_fallback_enabled_from(Some("1")));
        assert!(recall_semantic_fallback_enabled_from(Some("true")));
        assert!(recall_semantic_fallback_enabled_from(Some("TRUE")));
    }
}

pub struct MemorySearchTool {
    hub: Hub,
}
impl MemorySearchTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for MemorySearchTool {
    fn name(&self) -> &'static str {
        "memory_search"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Search memories by keyword or semantic similarity. mode='fts': \
                 FTS5 by bm25+recency+importance. mode='hybrid': FTS5 + graph neighbors \
                 via RRF fusion. mode='semantic': cosine over local embeddings — catches \
                 synonyms FTS misses. Excludes archived/superseded."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "query":      { "type": "string", "description": "Search query (FTS5 match syntax for fts/hybrid; natural language for semantic)." },
                    "tags_any":   { "type": "array", "items": { "type": "string" }, "default": [] },
                    "scope":      {
                        "type": "string",
                        "description": "Optional scope hint/filter, e.g. project:/abs/path or domain:rust. Pair with scope_mode to choose local-only recall vs cross-project exploration."
                    },
                    "scope_mode": {
                        "type": "string",
                        "enum": ["local_only", "local_plus_global", "exploratory"],
                        "default": "local_only",
                        "description": "When scope is set: local_only keeps only matching project/domain rows; local_plus_global also allows global/unscoped rows with a small score penalty; exploratory keeps cross-project rows as demoted analogy candidates."
                    },
                    "include_global": {
                        "type": "boolean",
                        "default": false,
                        "description": "Compatibility alias for scope_mode=local_plus_global when scope_mode is omitted."
                    },
                    "limit":      { "type": "integer", "minimum": 1, "maximum": 200, "default": 20 },
                    "mode":       {
                        "type": "string", "enum": ["fts", "hybrid", "semantic"], "default": "fts",
                        "description": "'fts' = keyword BM25; 'hybrid' = FTS5 + graph RRF fusion; 'semantic' = cosine similarity."
                    },
                    "expand_top": {
                        "type": "integer", "minimum": 1, "maximum": 20, "default": 10,
                        "description": "[hybrid only] Number of top FTS5 hits to expand via graph neighbors."
                    },
                    "rrf_k":      {
                        "type": "number", "minimum": 1.0, "maximum": 200.0, "default": 60.0,
                        "description": "[hybrid only] RRF constant k. Higher k = less rank compression."
                    },
                    "threshold":  {
                        "type": "number", "minimum": 0.0, "maximum": 1.0, "default": 0.3,
                        "description": "[semantic only] Minimum cosine similarity to include. 0.3 = broad, 0.7 = tight."
                    },
                    "exclude_kinds": {
                        "type": "array", "items": { "type": "string" }, "default": [],
                        "description": "Drop hits whose `kind` matches any of these from the OUTPUT. \
                            Useful for keeping bulky `skill` records (~88% of store) out of generic queries. \
                            Inner search auto-overfetches 5× to compensate. α coactivation still learns \
                            from the full pre-filter hit set, so cross-kind edges keep forming."
                    }
                },
                "required": ["query"]
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let q = args
            .get("query")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_string();
        let tags: Vec<String> = args
            .get("tags_any")
            .and_then(|v| v.as_array())
            .map(|a| {
                a.iter()
                    .filter_map(|x| x.as_str().map(|s| s.to_string()))
                    .collect()
            })
            .unwrap_or_default();
        let limit = args
            .get("limit")
            .and_then(|v| v.as_u64())
            .unwrap_or(20)
            .min(200) as u32;
        let mode = args.get("mode").and_then(|v| v.as_str()).unwrap_or("fts");
        let scope_filter = args
            .get("scope")
            .and_then(|v| v.as_str())
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .map(str::to_string);
        let include_global = args
            .get("include_global")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let scope_mode = memory_search_scope_mode(&args, include_global);

        let exclude_kinds: Vec<String> = args
            .get("exclude_kinds")
            .and_then(|v| v.as_array())
            .map(|a| {
                a.iter()
                    .filter_map(|x| x.as_str().map(|s| s.to_string()))
                    .collect()
            })
            .unwrap_or_default();
        // When output filters are active, overfetch so the post-filter result
        // can still hit `limit`. 5× covers up to ~80% saturation; cap at 200
        // (the schema's hard upper bound) to avoid pathological queries.
        let inner_limit = if exclude_kinds.is_empty() && scope_filter.is_none() {
            limit
        } else {
            (limit.saturating_mul(5)).min(200)
        };

        let started = Instant::now();
        let mut semantic_fallback_fired = false;
        let hits = if mode == "hybrid" {
            let expand_top = args
                .get("expand_top")
                .and_then(|v| v.as_u64())
                .unwrap_or(10)
                .min(20) as u32;
            let rrf_k = args
                .get("rrf_k")
                .and_then(|v| v.as_f64())
                .unwrap_or(60.0)
                .clamp(1.0, 200.0);
            store
                .memory_search_hybrid(&q, &tags, inner_limit, rrf_k, expand_top)
                .await?
        } else if mode == "semantic" {
            let threshold = args
                .get("threshold")
                .and_then(|v| v.as_f64())
                .unwrap_or(0.3)
                .clamp(0.0, 1.0) as f32;
            let cache_guard = self.hub.memory_embed_cache.lock().await;
            if let Some(cached) = cache_guard.as_ref() {
                let query_vec = embed_text(&q);
                let mut hits: Vec<MemorySearchHit> = cached
                    .iter()
                    // Tombstone/supersede tolerance: cache cleanup is racy
                    // (fire-and-forget spawn), so filter status here to
                    // match the SQL fallback's `WHERE status='active'`.
                    .filter(|(rec, _)| rec.status == "active")
                    .filter_map(|(rec, emb)| {
                        let cosine = cosine_similarity(&query_vec, emb);
                        if cosine < threshold {
                            return None;
                        }
                        Some(MemorySearchHit {
                            score: cosine as f64 + 0.2 * rec.importance,
                            record: rec.clone(),
                            cosine: Some(cosine),
                        })
                    })
                    .collect();
                hits.sort_by(|a, b| {
                    b.score
                        .partial_cmp(&a.score)
                        .unwrap_or(std::cmp::Ordering::Equal)
                });
                hits.truncate(inner_limit as usize);
                drop(cache_guard);
                hits
            } else {
                drop(cache_guard);
                store
                    .memory_search_semantic(&q, inner_limit, threshold)
                    .await?
            }
        } else {
            // Default (fts) path. Item B (2026-06-26, #120): owner-gated semantic
            // fallback for the FTS-empty tail. gte-768 semantic recall is ~2x fts
            // on the hard (no-lexical-overlap) recall_eval tier — but only for the
            // paraphrase queries FTS cannot serve AT ALL, so recover via cosine
            // strictly when FTS returns zero rows AND the flag is on AND a real
            // (non-hash) embedder has loaded (cold-load hash never injects noise).
            // Default-OFF: byte-identical to pure fts until the owner flips it.
            let mut fts_hits = store.memory_search(&q, &tags, inner_limit).await?;
            // Fire only on the no-lexical-overlap tail: FTS truly empty, AND no
            // tag predicate to honor (memory_search_semantic ignores tags_any, so
            // substituting would leak tag-violating rows), AND the flag is on, AND
            // a real embedder is available (cold-load hash never injects noise).
            if fts_hits.is_empty()
                && tags.is_empty()
                && recall_semantic_fallback_enabled()
                && fallback_embedder_ready()
            {
                let threshold = args
                    .get("threshold")
                    .and_then(|v| v.as_f64())
                    .unwrap_or(0.3)
                    .clamp(0.0, 1.0) as f32;
                let fb = store
                    .memory_search_semantic(&q, inner_limit, threshold)
                    .await?;
                if !fb.is_empty() {
                    semantic_fallback_fired = true;
                    fts_hits = fb;
                }
            }
            fts_hits
        };

        // Scope mode is intentionally applied before Seed/coactivation rerank:
        // callers asking for local work should not let discarded cross-project
        // hits affect boosts, while exploratory mode keeps those hits as
        // demoted analogy candidates instead of letting them dominate top-k.
        let mut hits = hits;
        if let Some(scope) = scope_filter.as_deref() {
            // Whether the caller *explicitly* chose a scope_mode. A deliberate
            // `scope_mode:"local_only"` is honored strictly (no silent widening);
            // only the DEFAULT (local_only via omission) gets the recall-recovery
            // fallback inside the helper.
            let scope_mode_explicit = args
                .get("scope_mode")
                .and_then(|v| v.as_str())
                .map(str::trim)
                .map(|s| !s.is_empty())
                .unwrap_or(false);
            hits = memory_search_apply_scope_mode_with_fallback(
                hits,
                scope,
                scope_mode,
                scope_mode_explicit,
            );
        }

        // Path C actuator: rerank using perception_filter hub_clusters.
        // Fail-soft (no state file / disable env / empty hub_clusters → pass-through).
        let hits = apply_seed_boost(hits);

        // Phase 1 P1 — coactivation rerank. For each hit, sum the count of
        // edges connecting it to OTHER hits in the same page. Boost score by
        // `1 + 0.2 * ln(1 + sum)`. Pure no-op when graph is empty (zero
        // edges → boost = 1.0 → score unchanged). Single SQL round-trip.
        let hits = if hits.len() >= 2 {
            let keys: Vec<String> = hits.iter().map(|h| h.record.key.clone()).collect();
            match store.coactivation_among(&keys).await {
                Ok(edges) if !edges.is_empty() => {
                    let mut per_key: HashMap<String, u64> = HashMap::new();
                    for e in &edges {
                        // Each edge contributes count to BOTH endpoints since
                        // an edge means "these two co-fire". A key with N
                        // edges in this page is in a tight cluster.
                        *per_key.entry(e.key_a.clone()).or_insert(0) += e.count;
                        *per_key.entry(e.key_b.clone()).or_insert(0) += e.count;
                    }
                    let boosted: Vec<MemorySearchHit> = hits
                        .into_iter()
                        .map(|mut h| {
                            let c = per_key.get(&h.record.key).copied().unwrap_or(0);
                            let boost = 1.0 + 0.2 * (1.0 + c as f64).ln();
                            h.score *= boost;
                            h
                        })
                        .collect();
                    let mut sorted = boosted;
                    sorted.sort_by(|a, b| {
                        b.score
                            .partial_cmp(&a.score)
                            .unwrap_or(std::cmp::Ordering::Equal)
                    });
                    sorted
                }
                _ => hits,
            }
        } else {
            hits
        };

        // v21 α — Synaptic Trace. Record co-activation pairs for top hits as
        // fire-and-forget background work; never block search latency.
        // ctx_centroid is None for now (mode-agnostic α); follow-up plumbs
        // hit embeddings through for richer trace.
        //
        // **Phase 1 P1.5 — skill filter.** Exclude `kind=skill` records
        // from coactivation writes. Skills are *procedures*, not knowledge
        // facts; they show up in result pages by FTS overlap and would ride
        // the P1 boost loop unfairly (Phase 1 P1 demo confirmed: a Java
        // skill record rode +22% on a Path C query). Same intent as
        // memory_link_audit defaulting to `include_skills=false`. The
        // filter applies pre-record, so the graph stays clean at write
        // time rather than needing a downstream cleanup.
        let coact_keys: Vec<String> = hits
            .iter()
            .filter(|h| h.record.kind != "skill")
            .filter(|h| {
                scope_filter.as_deref().map_or(true, |scope| {
                    memory_search_scope_trace_allowed(&h.record, scope, scope_mode)
                })
            })
            .take(10)
            .map(|h| h.record.key.clone())
            .collect();
        if coact_keys.len() >= 2 {
            let store_clone = store.clone();
            tokio::spawn(async move {
                let _ = store_clone.record_coactivation(&coact_keys, None).await;
            });
        }

        // Apply caller's exclude_kinds and re-truncate to the requested limit.
        let mut hits = hits;
        if !exclude_kinds.is_empty() {
            hits.retain(|h| !exclude_kinds.iter().any(|k| k == &h.record.kind));
        }
        hits.truncate(limit as usize);
        let elapsed = started.elapsed();

        // Phase 0 telemetry: log hit count + top-hit age (post-filter, what the
        // user actually sees). Top-hit age uses created_at as the recency anchor;
        // we deliberately don't use last_accessed_at because memory_search itself
        // bumps it on read in some backends and would self-zero this signal.
        let kind_label = if semantic_fallback_fired {
            // Honest telemetry: a default-path query that FTS could not serve and
            // the gated semantic fallback recovered — never silently labeled fts.
            "search_fts_semantic_fallback"
        } else {
            match mode {
                "hybrid" => "search_hybrid",
                "semantic" => "search_semantic",
                _ => "search_fts",
            }
        };
        let now_secs = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_secs() as i64)
            .unwrap_or(0);
        let (top_age, top_created) = hits
            .first()
            .map(|h| {
                (
                    Some(now_secs - h.record.created_at),
                    Some(h.record.created_at),
                )
            })
            .unwrap_or((None, None));
        let tags_json = serde_json::to_string(&tags).unwrap_or_else(|_| "[]".to_string());
        log_memory_query(
            store.clone(),
            kind_label,
            q.clone(),
            tags_json,
            hits.len() as u32,
            top_age,
            top_created,
            elapsed,
            "mcp:memory_search",
        );

        Ok(ToolResult::json_text(&Value::Array(
            hits.iter()
                .map(memory_search_hit_value_with_continuity)
                .collect(),
        )))
    }
}

pub struct MemoryListTool {
    hub: Hub,
}
impl MemoryListTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for MemoryListTool {
    fn name(&self) -> &'static str {
        "memory_list"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "List memories, optionally filtered by `kind`, sorted by 'recent' \
                 (default, last_accessed_at desc), 'frequent' (access_count desc), or \
                 'newest' (created_at desc). Excludes archived/superseded rows. Long \
                 contents are truncated to `content_max_chars` (default 280) so an \
                 overview list never blows past the MCP token cap; use `memory_get` for \
                 full bodies, or set `content_max_chars=0` to disable truncation. Use at \
                 session start with kind='lesson' to surface what previous-you learned."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "kind":  { "type": "string", "description": "Optional kind filter." },
                    "sort":  { "type": "string", "enum": ["recent","frequent","newest"], "default": "recent" },
                    "limit": { "type": "integer", "minimum": 1, "maximum": 200, "default": 8 },
                    "content_max_chars": {
                        "type": "integer", "minimum": 0, "default": 280,
                        "description": "Per-row content truncation (chars, not bytes — CJK safe). 0 disables."
                    }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let kind = args
            .get("kind")
            .and_then(|v| v.as_str())
            .map(|s| s.to_string());
        let sort = match args
            .get("sort")
            .and_then(|v| v.as_str())
            .unwrap_or("recent")
        {
            "frequent" => MemoryListSort::Frequent,
            "newest" => MemoryListSort::Newest,
            _ => MemoryListSort::Recent,
        };
        let limit = args
            .get("limit")
            .and_then(|v| v.as_u64())
            .unwrap_or(8)
            .min(200) as u32;
        let max_chars = args
            .get("content_max_chars")
            .and_then(|v| v.as_u64())
            .map(|n| n as usize)
            .unwrap_or(280);
        let rows = store.list_memories(kind.as_deref(), sort, limit).await?;
        let mut json_rows = Value::Array(
            rows.iter()
                .map(memory_record_value_with_continuity)
                .collect(),
        );
        if max_chars > 0 {
            if let Some(arr) = json_rows.as_array_mut() {
                for item in arr {
                    if let Some(obj) = item.as_object_mut() {
                        let owned_content = obj
                            .get("content")
                            .and_then(|v| v.as_str())
                            .map(|s| s.to_string());
                        if let Some(content) = owned_content {
                            let total = content.chars().count();
                            if total > max_chars {
                                let head: String = content.chars().take(max_chars).collect();
                                obj.insert(
                                    "content".to_string(),
                                    Value::String(format!(
                                        "{head}…(truncated; total {total} chars — use memory_get for full)"
                                    )),
                                );
                            }
                        }
                    }
                }
            }
        }
        Ok(ToolResult::json_text(&json_rows))
    }
}

pub struct MemoryDeleteTool {
    hub: Hub,
}
impl MemoryDeleteTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for MemoryDeleteTool {
    fn name(&self) -> &'static str {
        "memory_delete"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Delete a memory by key. Returns `{deleted: true}` if a row was removed."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": { "key": { "type": "string" } },
                "required": ["key"]
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let key = match args.get("key").and_then(|v| v.as_str()) {
            Some(s) => s.to_string(),
            None => return Ok(ToolResult::error("missing 'key'")),
        };
        let removed = store.memory_delete(&key).await?;
        if removed {
            let cache = self.hub.memory_embed_cache.clone();
            let del_key = key.clone();
            tokio::spawn(async move {
                let mut guard = cache.lock().await;
                if let Some(ref mut cached) = *guard {
                    cached.retain(|(r, _)| r.key != del_key);
                }
            });
        }
        Ok(ToolResult::json_text(&json!({ "deleted": removed })))
    }
}

const WORK_MEMORY_KIND: &str = "work_memory";
const WORK_MEMORY_DEFAULT_SLOT: &str = "active";
const WORK_MEMORY_MAX_CONTENT_CHARS: usize = 12_000;
const WORK_MEMORY_PRECOMPACT_CHARS: usize = 6_000;
/// Upper bound on work_memory rows scanned (most-recent first, across ALL
/// projects' scopes) for cross-node fan-in in the alias-aware `list`. The scan
/// is then filtered to alias-compatible scopes. NOTE: an alias-compatible
/// sibling lane older than the Nth most-recent work_memory row store-wide is
/// silently NOT surfaced — acceptable because work_memory is a recent-sorted,
/// TTL-bounded scratchpad, but raise this (or scope the broad fetch) if the
/// active work_memory population ever approaches this bound. (Live: ~61 active.)
const WORK_MEMORY_ALIAS_FANIN_SCAN: u32 = 500;

fn unix_now_secs() -> i64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs() as i64
}

fn stable_fnv1a_hex(input: &str) -> String {
    let mut hash: u64 = 0xcbf29ce484222325;
    for b in input.as_bytes() {
        hash ^= *b as u64;
        hash = hash.wrapping_mul(0x100000001b3);
    }
    format!("{hash:016x}")
}

fn sanitize_work_memory_component(value: &str, fallback: &str, max_chars: usize) -> String {
    let mut out = String::new();
    let mut last_dash = false;
    for ch in value.trim().chars() {
        let mapped = if ch.is_ascii_alphanumeric() || ch == '_' || ch == '-' {
            Some(ch.to_ascii_lowercase())
        } else if ch.is_whitespace() || matches!(ch, '/' | ':' | '.' | '@') {
            Some('-')
        } else {
            None
        };
        if let Some(ch) = mapped {
            if ch == '-' {
                if !last_dash && !out.is_empty() {
                    out.push(ch);
                    last_dash = true;
                }
            } else {
                out.push(ch);
                last_dash = false;
            }
        }
        if out.chars().count() >= max_chars {
            break;
        }
    }
    while out.ends_with('-') {
        out.pop();
    }
    if out.is_empty() {
        fallback.to_string()
    } else {
        out
    }
}

fn work_memory_cwd(args: &Value) -> String {
    args.get("cwd")
        .and_then(|v| v.as_str())
        .filter(|s| !s.trim().is_empty())
        .map(|s| s.trim().to_string())
        .or_else(|| {
            std::env::current_dir()
                .ok()
                .map(|p| p.display().to_string())
        })
        .unwrap_or_else(|| "/".to_string())
}

fn work_memory_scope(cwd: &str) -> String {
    format!("project:{cwd}")
}

fn work_memory_key(cwd: &str, session_id: Option<&str>, slot: &str) -> String {
    let scope_hash = stable_fnv1a_hex(cwd);
    let slot = sanitize_work_memory_component(slot, WORK_MEMORY_DEFAULT_SLOT, 48);
    let owner = session_id
        .map(|s| sanitize_work_memory_component(s, "session", 48))
        .unwrap_or_else(|| "shared".to_string());
    format!("work_memory_{}_{}_{}", &scope_hash[..12], owner, slot)
}

/// Cross-node fan-in merge for `work_memory list`.
///
/// `same_node` is the exact-scope result (today's behaviour); `broad` is all
/// work_memory rows across every scope. Returns `same_node` PLUS any `broad` row
/// whose scope is alias-compatible with `requested_scope` — using the same
/// read-time canonicalization `memory_search` uses (`AGENT_BRIDGE_PROJECT_SCOPE_ALIASES`)
/// — that is not already present, sorted most-recently-accessed first and capped
/// to `limit`. This surfaces a sibling node's lanes for the SAME project (e.g.
/// aio2's `project:/Data/...` path) which otherwise sync into state.db but stay
/// invisible to an exact-scope list. Pure (no IO) so the cross-node visibility
/// rule is unit-testable. Keys are never rewritten here, so a cross-node lane
/// surfaces as its own distinct row — read-converge, never write-overwrite.
fn merge_alias_compatible_work_memory(
    mut same_node: Vec<MemoryRecord>,
    broad: Vec<MemoryRecord>,
    requested_scope: &str,
    aliases: &str,
    limit: usize,
) -> Vec<MemoryRecord> {
    let seen: std::collections::HashSet<String> =
        same_node.iter().map(|r| r.key.clone()).collect();
    let mut extra: Vec<MemoryRecord> = broad
        .into_iter()
        .filter(|r| !seen.contains(&r.key))
        .filter(|r| {
            project_scopes_read_time_compatible_with_aliases(
                r.scope.as_deref().unwrap_or(""),
                requested_scope,
                Some(aliases),
            )
        })
        .collect();
    // PIN the same-node lanes (already recent-sorted and capped at `limit` by the
    // SQL): an agent must never lose sight of its OWN current lane. Fill only the
    // REMAINING budget with the most-recently-accessed cross-node lanes. A naive
    // "merge-all then truncate" would let newer sibling lanes evict the local lane
    // entirely under truncate(limit).
    extra.sort_by(|a, b| b.last_accessed_at.cmp(&a.last_accessed_at));
    let room = limit.saturating_sub(same_node.len());
    same_node.extend(extra.into_iter().take(room));
    same_node
}

/// Cross-node "peer" work_memory lanes — the wake delta. Returns lanes that are
/// alias-compatible with `requested_scope` (same logical project) but written
/// under a DIFFERENT scope (i.e. a sibling NODE's path, e.g. aio2's
/// `project:/Data/...` for a Mac session's `project:/Users/...`), with
/// `updated_at > since_ts`, most-recent first. Same-node lanes (scope ==
/// requested_scope) are excluded — those are the agent's own, surfaced by `list`.
///
/// Reliable across nodes because `updated_at` survives state.db sync unchanged
/// (sync's stabilise_sync_metadata zeroes last_accessed_at / access_count /
/// importance but NOT updated_at). Pull/turn-driven by design: it reads lanes
/// already synced into the local store, so a peer's update surfaces once sync has
/// carried it over — there is no live push (that is the sibling node's lane).
fn cross_node_peer_lanes(
    requested_scope: &str,
    broad: Vec<MemoryRecord>,
    aliases: &str,
    since_ts: i64,
    limit: usize,
) -> Vec<MemoryRecord> {
    let mut peers: Vec<MemoryRecord> = broad
        .into_iter()
        .filter(|r| r.updated_at > since_ts)
        // Exclude this session's own scope AND same-node ancestor/descendant
        // scopes (e.g. the parent `project:/Users/.../Projects` of this
        // `…/Projects/agent-bridge`). A TRUE cross-node peer has a different root
        // path (aio2 `/Data/…` vs Mac `/Users/…`), not a prefix relation — those
        // survive; same-node path relatives are the agent's own neighborhood.
        .filter(|r| {
            !scope_is_path_prefix_related(r.scope.as_deref().unwrap_or(""), requested_scope)
        })
        // …but still the SAME logical project (alias-compatible).
        .filter(|r| {
            project_scopes_read_time_compatible_with_aliases(
                r.scope.as_deref().unwrap_or(""),
                requested_scope,
                Some(aliases),
            )
        })
        .collect();
    peers.sort_by(|a, b| b.updated_at.cmp(&a.updated_at));
    peers.truncate(limit);
    peers
}

/// True if `a` and `b` are the same scope or one is a path-segment prefix of the
/// other (same-node ancestor/descendant), e.g.
/// `project:/Users/x/Projects` vs `project:/Users/x/Projects/agent-bridge`.
/// Segment-aware so `…/Projects` does not match `…/Projects-foo`.
fn scope_is_path_prefix_related(a: &str, b: &str) -> bool {
    fn is_segment_prefix(short: &str, long: &str) -> bool {
        long == short
            || (long.starts_with(short) && long.as_bytes().get(short.len()) == Some(&b'/'))
    }
    is_segment_prefix(a, b) || is_segment_prefix(b, a)
}

fn json_string_array(args: &Value, key: &str) -> Vec<String> {
    args.get(key)
        .and_then(|v| v.as_array())
        .map(|a| {
            a.iter()
                .filter_map(|x| x.as_str().map(str::trim))
                .filter(|s| !s.is_empty())
                .map(str::to_string)
                .collect()
        })
        .unwrap_or_default()
}

fn tail_chars(s: &str, max_chars: usize) -> (String, bool, usize) {
    let total = s.chars().count();
    if max_chars == 0 || total <= max_chars {
        (s.to_string(), false, total)
    } else {
        let start = total.saturating_sub(max_chars);
        let tail: String = s.chars().skip(start).collect();
        (
            format!("[trimmed earlier context; total {total} chars]\n{tail}"),
            true,
            total,
        )
    }
}

fn build_work_memory_content(
    args: &Value,
    cwd: &str,
    session_id: Option<&str>,
    slot: &str,
) -> std::result::Result<(String, bool, usize), String> {
    if let Some(content) = args
        .get("content")
        .and_then(|v| v.as_str())
        .map(str::trim)
        .filter(|s| !s.is_empty())
    {
        let (content, truncated, total_chars) =
            truncate_chars(content, WORK_MEMORY_MAX_CONTENT_CHARS);
        return Ok((content, truncated, total_chars));
    }

    let title = args
        .get("title")
        .and_then(|v| v.as_str())
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .unwrap_or("Active Work Memory");
    let summary = args
        .get("summary")
        .and_then(|v| v.as_str())
        .map(str::trim)
        .filter(|s| !s.is_empty());
    let next_step = args
        .get("next_step")
        .and_then(|v| v.as_str())
        .map(str::trim)
        .filter(|s| !s.is_empty());
    let evidence = args
        .get("evidence")
        .and_then(|v| v.as_str())
        .map(str::trim)
        .filter(|s| !s.is_empty());
    let status = args
        .get("status")
        .and_then(|v| v.as_str())
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .unwrap_or("active");
    let files = json_string_array(args, "files");

    if summary.is_none() && next_step.is_none() && evidence.is_none() && files.is_empty() {
        return Err(
            "save requires either content or at least one of summary/next_step/evidence/files"
                .to_string(),
        );
    }

    let mut lines = vec![
        format!("# {title}"),
        format!("cwd: {cwd}"),
        format!("slot: {slot}"),
        format!("status: {status}"),
        format!("updated_at: {}", unix_now_secs()),
    ];
    if let Some(session_id) = session_id {
        lines.push(format!("session_id: {session_id}"));
    }
    if let Some(summary) = summary {
        lines.extend([
            "".to_string(),
            "## Summary".to_string(),
            summary.to_string(),
        ]);
    }
    if let Some(next_step) = next_step {
        lines.extend([
            "".to_string(),
            "## Next Step".to_string(),
            next_step.to_string(),
        ]);
    }
    if let Some(evidence) = evidence {
        lines.extend([
            "".to_string(),
            "## Evidence".to_string(),
            evidence.to_string(),
        ]);
    }
    if !files.is_empty() {
        lines.push(String::new());
        lines.push("## Files".to_string());
        lines.extend(files.iter().map(|f| format!("- {f}")));
    }
    let content = lines.join("\n");
    let (content, truncated, total_chars) = truncate_chars(&content, WORK_MEMORY_MAX_CONTENT_CHARS);
    Ok((content, truncated, total_chars))
}

fn build_precompact_work_memory_content(
    conversation_text: &str,
    cwd: &str,
    session_id: Option<&str>,
) -> (String, bool, usize) {
    let (excerpt, truncated, total_chars) =
        tail_chars(conversation_text, WORK_MEMORY_PRECOMPACT_CHARS);
    let mut lines = vec![
        "# PreCompact Work Memory".to_string(),
        format!("cwd: {cwd}"),
        "slot: precompact".to_string(),
        "source: session_lifecycle_step(precompact)".to_string(),
        format!("updated_at: {}", unix_now_secs()),
    ];
    if let Some(session_id) = session_id {
        lines.push(format!("session_id: {session_id}"));
    }
    lines.extend([
        String::new(),
        "## Recent Context Excerpt".to_string(),
        excerpt,
    ]);
    (lines.join("\n"), truncated, total_chars)
}

fn format_work_memory_block(
    rows: &[MemoryRecord],
    is_compact: bool,
    snippet_len: usize,
) -> Option<Vec<String>> {
    let rows: Vec<MemoryRecord> = rows
        .iter()
        .filter(|r| r.status == "active")
        .take(4)
        .cloned()
        .collect();
    if rows.is_empty() {
        return None;
    }
    let mut out = vec![
        if is_compact {
            "=== Active Work Memory ===".to_string()
        } else {
            "=== Active Work Memory (short-lived scratchpad) ===".to_string()
        },
        String::new(),
    ];
    out.extend(format_bootstrap_memory_rows(&rows, snippet_len));
    out.push(String::new());
    Some(out)
}

/// Format the cross-node peer wake block for session_bootstrap. `rows` are
/// already filtered to cross-node peer lanes (see [`cross_node_peer_lanes`]) and
/// recency-sorted. Shows the sibling node's scope + lane key + a short snippet so
/// a starting session perceives what a peer node changed for this project. None
/// when there are no peer lanes (clean / single-node).
fn format_cross_node_peer_block(rows: &[MemoryRecord], is_compact: bool) -> Option<Vec<String>> {
    if rows.is_empty() {
        return None;
    }
    let mut out = vec![
        if is_compact {
            "=== Cross-node peer work memory ===".to_string()
        } else {
            "=== Cross-node peer work memory (a sibling node updated these lanes for this project) ==="
                .to_string()
        },
        String::new(),
    ];
    for r in rows.iter().take(3) {
        let scope = r.scope.as_deref().unwrap_or("?");
        let (snippet, _, _) = truncate_chars(&r.content, 90);
        let snippet = snippet.replace('\n', " ");
        out.push(format!("[{scope}] {}: {snippet}…", r.key));
    }
    out.push(String::new());
    Some(out)
}

async fn save_precompact_work_memory_snapshot(
    hub: &Hub,
    cwd: &str,
    session_id: Option<&str>,
    conversation_text: &str,
) -> Value {
    let store = match &hub.store {
        Some(s) => s.clone(),
        None => return json!({ "saved": false, "reason": "no store configured" }),
    };
    let (content, truncated, source_chars) =
        build_precompact_work_memory_content(conversation_text, cwd, session_id);
    let key = work_memory_key(cwd, session_id, "precompact");
    let scope = work_memory_scope(cwd);
    let mut tags = vec![
        "work_memory".to_string(),
        "source:precompact".to_string(),
        "ttl:14d".to_string(),
    ];
    if let Some(session_id) = session_id {
        tags.push(format!("session:{session_id}"));
    }
    let mem = MemoryRecord {
        key: key.clone(),
        kind: WORK_MEMORY_KIND.to_string(),
        content,
        tags,
        related_keys: vec![],
        scope: Some(scope.clone()),
        created_at: 0,
        updated_at: 0,
        last_accessed_at: 0,
        access_count: 0,
        importance: 0.62,
        status: "active".to_string(),
        trigger_pattern: None,
        superseded_by: None,
    };
    match store.memory_save(&mem).await {
        Ok(()) => json!({
            "saved": true,
            "key": key,
            "scope": scope,
            "source_chars": source_chars,
            "truncated": truncated,
        }),
        Err(e) => json!({ "saved": false, "error": e.to_string() }),
    }
}

pub struct WorkMemoryTool {
    hub: Hub,
}
impl WorkMemoryTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for WorkMemoryTool {
    fn name(&self) -> &'static str {
        "work_memory"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Manage a short-lived project/session scratchpad outside the model \
                 context. Use it to preserve active task state across context compaction; \
                 durable lessons and decisions still belong in memory_save."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "op": {
                        "type": "string",
                        "enum": ["save", "list", "get", "clear", "peers"],
                        "default": "list",
                        "description": "save overwrites a project/session slot; list returns recent work memories (with cross-node fan-in); get reads one key; clear deletes one slot/key; peers returns ONLY cross-node sibling lanes (a DIFFERENT node working this same project, surfaced via scope-alias) changed since `since_ts` — the cross-node wake delta: 'what did my peers change since I last looked'."
                    },
                    "since_ts": { "type": "integer", "description": "[peers] Only return cross-node lanes with updated_at > this unix-seconds cursor. Pass back the response's next_cursor to poll incrementally. Default 0 = all peer lanes." },
                    "cwd": { "type": "string", "description": "Project path for scoping. Defaults to current working directory." },
                    "session_id": { "type": "string", "description": "Optional session namespace. Omit for a shared project slot." },
                    "slot": { "type": "string", "default": "active", "description": "Short slot name, e.g. active, release, precompact." },
                    "key": { "type": "string", "description": "Explicit key for get/clear. If omitted for clear, cwd/session_id/slot derives the key." },
                    "title": { "type": "string" },
                    "summary": { "type": "string" },
                    "next_step": { "type": "string" },
                    "evidence": { "type": "string" },
                    "files": { "type": "array", "items": { "type": "string" }, "default": [] },
                    "content": { "type": "string", "description": "Optional full Markdown content. Capped at 12000 chars." },
                    "status": { "type": "string", "default": "active" },
                    "tags": { "type": "array", "items": { "type": "string" }, "default": [] },
                    "ttl_days": { "type": "integer", "minimum": 1, "maximum": 90, "default": 14 },
                    "limit": { "type": "integer", "minimum": 1, "maximum": 50, "default": 8 },
                    "compact": { "type": "boolean", "description": "When listing, return compact row summaries. Defaults true for Codex compact profiles." }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let op = args
            .get("op")
            .and_then(|v| v.as_str())
            .unwrap_or("list")
            .trim()
            .to_lowercase();
        let cwd = work_memory_cwd(&args);
        let session_id = args
            .get("session_id")
            .and_then(|v| v.as_str())
            .map(str::trim)
            .filter(|s| !s.is_empty());
        let slot = args
            .get("slot")
            .and_then(|v| v.as_str())
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .unwrap_or(WORK_MEMORY_DEFAULT_SLOT);

        match op.as_str() {
            "save" => {
                let (content, truncated, total_chars) =
                    match build_work_memory_content(&args, &cwd, session_id, slot) {
                        Ok(v) => v,
                        Err(e) => return Ok(ToolResult::error(e)),
                    };
                let key = args
                    .get("key")
                    .and_then(|v| v.as_str())
                    .map(str::trim)
                    .filter(|s| !s.is_empty())
                    .map(str::to_string)
                    .unwrap_or_else(|| work_memory_key(&cwd, session_id, slot));
                let scope = work_memory_scope(&cwd);
                let ttl_days = args
                    .get("ttl_days")
                    .and_then(|v| v.as_u64())
                    .unwrap_or(14)
                    .clamp(1, 90);
                let mut tags = vec![
                    "work_memory".to_string(),
                    format!(
                        "slot:{}",
                        sanitize_work_memory_component(slot, WORK_MEMORY_DEFAULT_SLOT, 48)
                    ),
                    format!("ttl:{ttl_days}d"),
                ];
                if let Some(session_id) = session_id {
                    tags.push(format!("session:{session_id}"));
                }
                tags.extend(json_string_array(&args, "tags"));
                tags.sort();
                tags.dedup();
                let mem = MemoryRecord {
                    key: key.clone(),
                    kind: WORK_MEMORY_KIND.to_string(),
                    content,
                    tags,
                    related_keys: vec![],
                    scope: Some(scope.clone()),
                    created_at: 0,
                    updated_at: 0,
                    last_accessed_at: 0,
                    access_count: 0,
                    importance: 0.65,
                    status: "active".to_string(),
                    trigger_pattern: None,
                    superseded_by: None,
                };
                store.memory_save(&mem).await?;
                Ok(ToolResult::json_text(&json!({
                    "saved": true,
                    "key": key,
                    "scope": scope,
                    "slot": slot,
                    "content_chars": mem.content.chars().count(),
                    "source_chars": total_chars,
                    "truncated": truncated,
                })))
            }
            "list" => {
                let limit = args
                    .get("limit")
                    .and_then(|v| v.as_u64())
                    .unwrap_or(8)
                    .clamp(1, 50) as u32;
                let compact = args
                    .get("compact")
                    .and_then(|v| v.as_bool())
                    .unwrap_or_else(compact_mcp_output_default);
                let mut rows = store
                    .list_memories_in_scope(
                        &cwd,
                        Some(WORK_MEMORY_KIND),
                        MemoryListSort::Recent,
                        limit,
                    )
                    .await?;
                // Cross-node fan-in: work_memory list is otherwise exact-scope,
                // so lanes written under an alias-compatible scope on ANOTHER
                // node (e.g. aio2's project:/Data/... path for this same
                // project) stay invisible even though they sync into state.db.
                // When a scope-alias registry is configured, widen the READ via
                // the same canonicalization memory_search uses so cross-node
                // lanes surface in the fan-in. Key derivation is untouched, so
                // cross-node lanes remain DISTINCT rows (read-converge, never
                // write-overwrite).
                if let Some(aliases) = std::env::var(PROJECT_SCOPE_ALIASES_ENV)
                    .ok()
                    .filter(|s| !s.trim().is_empty())
                {
                    let broad = store
                        .list_memories(
                            Some(WORK_MEMORY_KIND),
                            MemoryListSort::Recent,
                            WORK_MEMORY_ALIAS_FANIN_SCAN,
                        )
                        .await?;
                    rows = merge_alias_compatible_work_memory(
                        rows,
                        broad,
                        &work_memory_scope(&cwd),
                        &aliases,
                        limit as usize,
                    );
                }
                if compact {
                    let rows: Vec<Value> = rows
                        .into_iter()
                        .map(|r| {
                            let (snippet, truncated, total_chars) = truncate_chars(&r.content, 240);
                            json!({
                                "key": r.key,
                                "scope": r.scope,
                                "updated_at": r.updated_at,
                                "tags": r.tags,
                                "snippet": snippet,
                                "truncated": truncated,
                                "content_chars": total_chars,
                            })
                        })
                        .collect();
                    Ok(ToolResult::json_text(&json!({
                        "cwd": cwd,
                        "kind": WORK_MEMORY_KIND,
                        "rows": rows,
                    })))
                } else {
                    Ok(ToolResult::json_text(
                        &serde_json::to_value(rows).unwrap_or(Value::Null),
                    ))
                }
            }
            "get" => {
                let key = match args.get("key").and_then(|v| v.as_str()) {
                    Some(s) if !s.trim().is_empty() => s.trim(),
                    _ => return Ok(ToolResult::error("get requires key")),
                };
                match store.memory_get(key).await? {
                    Some(row) if row.kind == WORK_MEMORY_KIND => Ok(ToolResult::json_text(
                        &serde_json::to_value(row).unwrap_or(Value::Null),
                    )),
                    Some(_) => Ok(ToolResult::error("key exists but is not work_memory")),
                    None => Ok(ToolResult::error("work memory key not found")),
                }
            }
            "clear" => {
                let key = args
                    .get("key")
                    .and_then(|v| v.as_str())
                    .map(str::trim)
                    .filter(|s| !s.is_empty())
                    .map(str::to_string)
                    .unwrap_or_else(|| work_memory_key(&cwd, session_id, slot));
                let deleted = store.memory_delete(&key).await?;
                Ok(ToolResult::json_text(
                    &json!({ "deleted": deleted, "key": key }),
                ))
            }
            "peers" => {
                // Cross-node wake delta: which sibling-NODE lanes for this project
                // changed since the caller's cursor. Requires the scope-alias
                // registry (no aliases = no cross-node concept = empty).
                let since_ts = args.get("since_ts").and_then(|v| v.as_i64()).unwrap_or(0);
                let limit = args
                    .get("limit")
                    .and_then(|v| v.as_u64())
                    .unwrap_or(8)
                    .clamp(1, 50) as usize;
                let peers = match std::env::var(PROJECT_SCOPE_ALIASES_ENV)
                    .ok()
                    .filter(|s| !s.trim().is_empty())
                {
                    Some(aliases) => {
                        let broad = store
                            .list_memories(
                                Some(WORK_MEMORY_KIND),
                                MemoryListSort::Recent,
                                WORK_MEMORY_ALIAS_FANIN_SCAN,
                            )
                            .await?;
                        cross_node_peer_lanes(
                            &work_memory_scope(&cwd),
                            broad,
                            &aliases,
                            since_ts,
                            limit,
                        )
                    }
                    None => Vec::new(),
                };
                // next_cursor lets the caller poll incrementally (pass back as since_ts).
                let next_cursor = peers.iter().map(|r| r.updated_at).max().unwrap_or(since_ts);
                let rows: Vec<Value> = peers
                    .iter()
                    .map(|r| {
                        let (snippet, truncated, total_chars) = truncate_chars(&r.content, 200);
                        json!({
                            "key": r.key,
                            "scope": r.scope,
                            "updated_at": r.updated_at,
                            "tags": r.tags,
                            "snippet": snippet,
                            "truncated": truncated,
                            "content_chars": total_chars,
                        })
                    })
                    .collect();
                Ok(ToolResult::json_text(&json!({
                    "cwd": cwd,
                    "kind": WORK_MEMORY_KIND,
                    "since_ts": since_ts,
                    "next_cursor": next_cursor,
                    "peer_lane_count": rows.len(),
                    "peer_lanes": rows,
                })))
            }
            other => Ok(ToolResult::error(format!(
                "unknown work_memory op: {other} (expected save|list|get|clear|peers)"
            ))),
        }
    }
}

pub struct MemoryCompactTool {
    hub: Hub,
}
impl MemoryCompactTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for MemoryCompactTool {
    fn name(&self) -> &'static str {
        "memory_compact"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Retire low-value memories by tombstoning them (NOT hard-delete; \
                 final removal is memory_purge_tombstones' 7d ladder, and tombstones \
                 propagate the deletion across peers via NewerWins sync). Acts only on \
                 status='active' rows, and only when BOTH match: min_uses (access_count <) \
                 AND older_than_days (last_accessed_at older than). Durable rows are \
                 protected and never retired: importance ≥ 0.6, author-linked \
                 (related_keys), or graph-connected (has edges). 1-hour grace on \
                 created_at. dry_run=true previews. Both omitted → defaults \
                 (min_uses=2, older_than_days=90)."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "min_uses":        { "type": "integer", "minimum": 0 },
                    "older_than_days": { "type": "integer", "minimum": 1 },
                    "dry_run":         { "type": "boolean", "default": false }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let min_uses = args.get("min_uses").and_then(|v| v.as_u64());
        let older_than_secs = args
            .get("older_than_days")
            .and_then(|v| v.as_i64())
            .map(|d| d * 86_400);
        let dry_run = args
            .get("dry_run")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);

        let mut policy = CompactPolicy {
            min_uses,
            older_than_secs,
            dry_run,
        };
        let applied_defaults = policy.is_unset();
        if applied_defaults {
            // v0.8: don't punish callers with a silent no-op; apply the balanced
            // default. dry_run flag is still honoured.
            let mut def = CompactPolicy::healthy_default();
            def.dry_run = dry_run;
            policy = def;
        }
        let keys = store.memory_compact(policy).await?;
        if !dry_run && !keys.is_empty() {
            let cache = self.hub.memory_embed_cache.clone();
            let removed_keys: std::collections::HashSet<String> = keys.iter().cloned().collect();
            tokio::spawn(async move {
                let mut guard = cache.lock().await;
                if let Some(ref mut cached) = *guard {
                    cached.retain(|(r, _)| !removed_keys.contains(&r.key));
                }
            });
        }
        Ok(ToolResult::json_text(&json!({
            "dry_run": dry_run,
            "applied_defaults": applied_defaults,
            "policy": {
                "min_uses": policy.min_uses,
                "older_than_secs": policy.older_than_secs,
            },
            "removed_count": keys.len(),
            "removed_keys": keys,
        })))
    }
}

