//                  memory_purge_tombstones (Phase 2.x #6)
// ===========================================================================

pub struct MemoryPurgeTombstonesTool {
    hub: Hub,
}
impl MemoryPurgeTombstonesTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for MemoryPurgeTombstonesTool {
    fn name(&self) -> &'static str {
        "memory_purge_tombstones"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Hard-DELETE memories that have been tombstoned for at least \
                older_than_days. Tombstone soft-delete keeps deleted rows so the \
                deletion propagates across `agent-bridge sync`; this GC pass cleans \
                them once the sync window has safely passed. Default 7 days. \
                dry_run=true previews."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "older_than_days": {
                        "type": "integer",
                        "minimum": 0,
                        "default": 7,
                        "description": "Only purge tombstones whose updated_at is strictly older than this. \
                            Default 7 — long enough to outlive a typical multi-node sync round-trip. \
                            0 means purge all tombstones regardless of age (use only on isolated nodes)."
                    },
                    "dry_run": { "type": "boolean", "default": false }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let older_than_days = args
            .get("older_than_days")
            .and_then(|v| v.as_i64())
            .unwrap_or(7)
            .max(0);
        let dry_run = args
            .get("dry_run")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let purged = store
            .memory_purge_tombstones(older_than_days, dry_run)
            .await?;
        Ok(ToolResult::json_text(&json!({
            "dry_run": dry_run,
            "older_than_days": older_than_days,
            "purged_count": purged.len(),
            "purged_keys": purged,
        })))
    }
}

// ===========================================================================
//          memory_prune_coactivation_noise (δ-3 — Butlin HOT-4 hygiene)
// ===========================================================================

pub struct MemoryPruneCoactivationNoiseTool {
    hub: Hub,
}
impl MemoryPruneCoactivationNoiseTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for MemoryPruneCoactivationNoiseTool {
    fn name(&self) -> &'static str {
        "memory_prune_coactivation_noise"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Drop low-weight coactivation pairs that never crystallised. \
                A pair with count <= max_count AND last_at older than older_than_days \
                is noise: it co-fired briefly once, never re-fired, and is now ageing the \
                table. Pair with dream promote (which crystallises pairs at count≥N into \
                cofires edges) — anything left below the promote threshold for a long \
                window is by definition unworthy of the synaptic graph. Returns \
                {pruned_count}. dry_run=true previews."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "max_count": {
                        "type": "integer",
                        "minimum": 0,
                        "default": 1,
                        "description": "Prune pairs whose count is ≤ this. Default 1: only \
                            single co-firings get pruned. Raise to 2 to also drop sporadic \
                            twice-fired pairs that never reached promote threshold."
                    },
                    "older_than_days": {
                        "type": "integer",
                        "minimum": 0,
                        "default": 30,
                        "description": "Only prune pairs whose last_at is at least this many \
                            days old. Default 30 — gives a pair a month to grow before GC."
                    },
                    "dry_run": { "type": "boolean", "default": false }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let max_count = args
            .get("max_count")
            .and_then(|v| v.as_i64())
            .unwrap_or(1)
            .max(0);
        let older_than_days = args
            .get("older_than_days")
            .and_then(|v| v.as_i64())
            .unwrap_or(30)
            .max(0);
        let dry_run = args
            .get("dry_run")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let pruned = store
            .memory_prune_coactivation_noise(max_count, older_than_days, dry_run)
            .await?;
        Ok(ToolResult::json_text(&json!({
            "dry_run": dry_run,
            "max_count": max_count,
            "older_than_days": older_than_days,
            "pruned_count": pruned,
        })))
    }
}

// ===========================================================================
//          memory_prune_degenerate_relates (ζ-12 — clean legacy noise hubs)
// ===========================================================================

/// ζ-12 — Drop `relates` edges where BOTH endpoints carry a tag in
/// `blacklist_tags`. Defensive cleanup for the ζ-9-revealed pattern:
/// pre-ζ-11 `memory_link_orphans` runs collapsed all auto_curated stubs
/// onto a single sibling (degree-84 noise hub on aio2). Pairs with
/// ζ-11's preventive `skip_tags` parameter — ζ-11 stops new degenerate
/// links forming, ζ-12 deletes the legacy ones already in the graph.
/// Only `relates` (softest edge type) is in scope.
pub struct MemoryPruneDegenerateRelatesTool {
    hub: Hub,
}
impl MemoryPruneDegenerateRelatesTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for MemoryPruneDegenerateRelatesTool {
    fn name(&self) -> &'static str {
        "memory_prune_degenerate_relates"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "ζ-12 (one-shot graph hygiene). Delete `relates` edges where BOTH \
                endpoints carry any tag in `blacklist_tags`. Defensive: only `relates` (softest \
                edge type) is in scope — causal/structural edges (caused_by, supersedes, \
                implements, ...) are preserved even when both endpoints overlap the blacklist. \
                Pair with `memory_link_orphans`' ζ-11 `skip_tags` to stop new degenerate \
                edges from forming. Returns {pruned_count}. dry_run=true previews."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "blacklist_tags": {
                        "type": "array",
                        "items": { "type": "string" },
                        "default": ["auto_curated"],
                        "description": "Edges where both endpoints carry any of these tags are \
                            pruned. Default `['auto_curated']` targets the noise-hub pattern \
                            surfaced by ζ-9: pre-ζ-11 `memory_link_orphans` runs collapsed \
                            curated_implicit_* stubs onto a single sibling."
                    },
                    "dry_run": { "type": "boolean", "default": false }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let blacklist_tags: Vec<String> = args
            .get("blacklist_tags")
            .and_then(|v| v.as_array())
            .map(|arr| {
                arr.iter()
                    .filter_map(|v| v.as_str().map(|s| s.to_string()))
                    .collect()
            })
            .unwrap_or_else(|| vec!["auto_curated".to_string()]);
        let dry_run = args
            .get("dry_run")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let pruned = store
            .memory_prune_degenerate_relates(&blacklist_tags, dry_run)
            .await?;
        Ok(ToolResult::json_text(&json!({
            "dry_run": dry_run,
            "blacklist_tags": blacklist_tags,
            "pruned_count": pruned,
        })))
    }
}

// ===========================================================================
//          memory_archive_orphan_stubs (ζ-14 — retire signal-poor stubs)
// ===========================================================================

/// ζ-14 — Flip orphan stubs carrying a blacklist tag from `status='active'`
/// to `status='archived'`. Closes the ζ-9 → ζ-11 → ζ-12 loop:
/// - ζ-11 stops new degenerate links forming
/// - ζ-12 deletes legacy degenerate edges
/// - ζ-14 actively retires the resulting orphan stubs instead of waiting
///   for passive decay
///
/// Stubs that are simultaneously (a) tagged blacklist, (b) orphan, (c)
/// older than N days are by construction signal-poor dead weight: ζ-11
/// blacklist prevents them from ever re-linking; the only sensible
/// transition is into archived.
pub struct MemoryArchiveOrphanStubsTool {
    hub: Hub,
}
impl MemoryArchiveOrphanStubsTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for MemoryArchiveOrphanStubsTool {
    fn name(&self) -> &'static str {
        "memory_archive_orphan_stubs"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "ζ-14 (graph-hygiene close-out). Transition orphan stubs from \
                `status='active'` to `status='archived'`. Criterion: status=active AND tags \
                overlap blacklist_tags AND no edges AND created_at <= now-older_than_days*86400. \
                Defaults are conservative: only auto_curated stubs older than 3 days, capped at \
                200 per run. Pair with memory_link_orphans skip_tags (ζ-11) and \
                memory_prune_degenerate_relates (ζ-12) for a full hygiene cycle. dry_run=true \
                previews. Returns {archived_count}."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "blacklist_tags": {
                        "type": "array",
                        "items": { "type": "string" },
                        "default": ["auto_curated"],
                        "description": "Stubs whose tags overlap this list are eligible for \
                            archive. Default `['auto_curated']` matches the ζ-11 / ζ-12 lane."
                    },
                    "older_than_days": {
                        "type": "integer",
                        "minimum": 0,
                        "default": 3,
                        "description": "Only stubs whose created_at is at least this many days \
                            old are archived. Default 3 — gives a session window to revisit \
                            recent stubs before they go cold."
                    },
                    "max_archive": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": 1000,
                        "default": 200,
                        "description": "Hard cap on archives per run. Bounds accidents and \
                            keeps a single tx small."
                    },
                    "dry_run": { "type": "boolean", "default": false }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let blacklist_tags: Vec<String> = args
            .get("blacklist_tags")
            .and_then(|v| v.as_array())
            .map(|arr| {
                arr.iter()
                    .filter_map(|v| v.as_str().map(|s| s.to_string()))
                    .collect()
            })
            .unwrap_or_else(|| vec!["auto_curated".to_string()]);
        let older_than_days = args
            .get("older_than_days")
            .and_then(|v| v.as_i64())
            .unwrap_or(3)
            .max(0);
        let max_archive = args
            .get("max_archive")
            .and_then(|v| v.as_i64())
            .unwrap_or(200)
            .clamp(1, 1000);
        let dry_run = args
            .get("dry_run")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let archived = store
            .memory_archive_orphan_stubs(&blacklist_tags, older_than_days, max_archive, dry_run)
            .await?;
        Ok(ToolResult::json_text(&json!({
            "dry_run": dry_run,
            "blacklist_tags": blacklist_tags,
            "older_than_days": older_than_days,
            "max_archive": max_archive,
            "archived_count": archived,
        })))
    }
}

// ===========================================================================
//        memory_restore_archived (ζ-18 — escape hatch for ζ-14 false positives)
// ===========================================================================

/// ζ-18 — Reverse of ζ-14. Restore a single archived row back to
/// `status='active'`. Single-key, not criterion-based: operator inspects
/// a specific row and decides. A bulk restore would re-introduce the
/// noise ζ-14 just retired.
///
/// Only `status='archived'` rows are eligible. `active` / `superseded` /
/// `tombstoned` are no-ops returning `restored=false`. The
/// tombstone → active path goes through supersede chains, not here.
pub struct MemoryRestoreArchivedTool {
    hub: Hub,
}
impl MemoryRestoreArchivedTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for MemoryRestoreArchivedTool {
    fn name(&self) -> &'static str {
        "memory_restore_archived"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "ζ-18 (graph-hygiene escape hatch). Restore a single \
                `status='archived'` memory back to active by key. Operator-driven \
                inverse of ζ-14 memory_archive_orphan_stubs. Only matches archived \
                rows — active / superseded / tombstoned rows are no-ops. Bumps \
                updated_at on success. Returns {restored: bool}."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "key": {
                        "type": "string",
                        "description": "Memory key (UNIQUE) to restore from archived → active."
                    }
                },
                "required": ["key"]
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let key = match args.get("key").and_then(|v| v.as_str()) {
            Some(k) if !k.is_empty() => k.to_string(),
            _ => return Ok(ToolResult::error("key is required and must be non-empty")),
        };
        let restored = store.memory_restore_archived(&key).await?;
        Ok(ToolResult::json_text(&json!({
            "key": key,
            "restored": restored,
        })))
    }
}

// ===========================================================================
//   memory_tombstone_aged_archived (ζ-19 — archive→tombstone GC, retire end)
// ===========================================================================

/// ζ-19 — Time-based downgrade of stale `archived` rows to `tombstoned`.
/// Closes the hygiene state machine:
///
///   active → ζ-14 → archived → ζ-19 → tombstoned → purge_tombstones (7d) → DELETE
///
/// `tombstoned` (not direct DELETE) is required so the `dedupe_key` slot
/// is held until the 7-day purge window — protects against NewerWins
/// import or same-content re-save resurrecting an already-retired row.
pub struct MemoryTombstoneAgedArchivedTool {
    hub: Hub,
}
impl MemoryTombstoneAgedArchivedTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for MemoryTombstoneAgedArchivedTool {
    fn name(&self) -> &'static str {
        "memory_tombstone_aged_archived"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "ζ-19 (graph-hygiene retire-end GC). Downgrade stale archived rows \
                to tombstoned: criterion is status='archived' AND updated_at ≤ now-N*86400. \
                The 14-day default leaves a generous restore window for ζ-18. tombstoned \
                rows still hold their dedupe_key slot, so the existing 7-day purge_tombstones \
                cycle gives a final undo before physical DELETE. dry_run=true previews. \
                Returns {tombstoned_count}."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "older_than_days": {
                        "type": "integer",
                        "minimum": 0,
                        "default": 14,
                        "description": "Rows whose updated_at is at least this many days old \
                            are eligible. `updated_at` is the timestamp ζ-14 bumps on archive, \
                            so this measures how long the row has been sitting in archived \
                            state. Default 14 — comfortably outside ζ-18 restore window."
                    },
                    "max_count": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": 5000,
                        "default": 500,
                        "description": "Hard cap on tombstones per run. Bounds runaway and \
                            keeps the transaction small."
                    },
                    "dry_run": { "type": "boolean", "default": false }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let older_than_days = args
            .get("older_than_days")
            .and_then(|v| v.as_i64())
            .unwrap_or(14)
            .max(0);
        let max_count = args
            .get("max_count")
            .and_then(|v| v.as_i64())
            .unwrap_or(500)
            .clamp(1, 5000);
        let dry_run = args
            .get("dry_run")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let tombstoned = store
            .memory_tombstone_aged_archived(older_than_days, max_count, dry_run)
            .await?;
        Ok(ToolResult::json_text(&json!({
            "dry_run": dry_run,
            "older_than_days": older_than_days,
            "max_count": max_count,
            "tombstoned_count": tombstoned,
        })))
    }
}

// ===========================================================================
//                  memory_decay_unused (Phase 2.x #8 — read-recency decay)
// ===========================================================================

pub struct MemoryDecayUnusedTool {
    hub: Hub,
}
impl MemoryDecayUnusedTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for MemoryDecayUnusedTool {
    fn name(&self) -> &'static str {
        "memory_decay_unused"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Read-recency importance decay: shave `step` off the importance of \
                every active memory whose last_accessed_at is older than window_days, floored \
                at `floor`. Mirrors the Palace C7/C8 staleness model — what hasn't been read \
                loses retrieval rank, even if it was recently written. Distinct from the \
                memory_compact phase that decays by updated_at (write recency). Returns \
                {candidates, decayed, skipped_at_floor}. Defaults: 30d / 0.05 / 0.1."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "window_days": {
                        "type": "number",
                        "minimum": 0,
                        "default": 30,
                        "description": "Only decay rows whose last_accessed_at is older than \
                            this many days. Default 30."
                    },
                    "step": {
                        "type": "number",
                        "minimum": 0,
                        "maximum": 1,
                        "default": 0.05,
                        "description": "How much to shave off importance per pass. Default 0.05."
                    },
                    "floor": {
                        "type": "number",
                        "minimum": 0,
                        "maximum": 1,
                        "default": 0.1,
                        "description": "Importance never drops below this. Default 0.1."
                    }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let window_days = args
            .get("window_days")
            .and_then(|v| v.as_f64())
            .unwrap_or(30.0)
            .max(0.0);
        let step = args
            .get("step")
            .and_then(|v| v.as_f64())
            .unwrap_or(0.05)
            .clamp(0.0, 1.0);
        let floor = args
            .get("floor")
            .and_then(|v| v.as_f64())
            .unwrap_or(0.1)
            .clamp(0.0, 1.0);
        let window_secs = (window_days * 86_400.0) as i64;
        let stats = store
            .memory_decay_unused_importance(window_secs, step, floor)
            .await?;
        Ok(ToolResult::json_text(&json!({
            "window_days": window_days,
            "step": step,
            "floor": floor,
            "candidates": stats.candidates,
            "decayed": stats.decayed,
            "skipped_at_floor": stats.skipped_at_floor,
        })))
    }
}

// ===========================================================================
//                       memory_reindex (re-embed after dim migration)
// ===========================================================================

pub struct MemoryReindexTool {
    hub: Hub,
}
impl MemoryReindexTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for MemoryReindexTool {
    fn name(&self) -> &'static str {
        "memory_reindex"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Re-compute embeddings for active memories. Two modes:\n\
                 - Default (only_stale=false): fills rows with `embedding IS NULL`.\n\
                 - only_stale=true (P9): also reindexes rows whose embedding_backend \
                   tag differs from current default — hash → ONNX upgrade path. \
                   Pre-v26 NULL-backend rows skipped in stale mode."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "batch_size": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": 1000,
                        "default": 100,
                        "description": "Number of rows to re-embed per call."
                    },
                    "only_stale": {
                        "type": "boolean",
                        "default": false,
                        "description": "Also reindex rows with embedding_backend != current default."
                    }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let batch_size = args
            .get("batch_size")
            .and_then(|v| v.as_u64())
            .unwrap_or(100) as usize;
        let only_stale = args
            .get("only_stale")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);

        let updated = store
            .memory_reindex_embeddings(batch_size, only_stale)
            .await?;

        // Refresh the in-process embedding cache so the new vectors are visible.
        if updated > 0 {
            let cache = self.hub.memory_embed_cache.clone();
            let refresh_store = store.clone();
            tokio::spawn(async move {
                if let Ok(rows) = refresh_store.memory_load_embeddings().await {
                    let mut guard = cache.lock().await;
                    *guard = Some(rows);
                }
            });
        }

        Ok(ToolResult::json_text(&json!({
            "updated": updated,
            "batch_size": batch_size,
            "hint": if updated == batch_size {
                format!("Batch full — call memory_reindex again to continue ({batch_size} rows/call).")
            } else {
                format!("Done. {updated} rows re-embedded this call.")
            }
        })))
    }
}

