fn is_continuity_tag(tag: &str) -> bool {
    CONTINUITY_TAG_PREFIXES
        .iter()
        .any(|prefix| tag.starts_with(prefix))
}

fn memory_continuity_bootstrap_reason(r: &MemoryRecord) -> Option<String> {
    let metadata = memory_continuity_metadata_from_tags(&r.tags, r.superseded_by.as_deref())?;
    let why = metadata
        .actionability
        .as_deref()
        .or_else(|| match metadata.continuity_role.as_deref() {
            Some("constraint") | Some("warning") => Some("must_block"),
            Some("state") | Some("procedure") | Some("preference") => Some("plan_influence"),
            Some("evidence") | Some("archive") => Some("background"),
            _ => None,
        })
        .unwrap_or("context");
    let mut parts = vec![format!("why: {why}")];
    if let Some(role) = metadata.continuity_role.as_deref() {
        parts.push(format!("role={role}"));
    }
    if let Some(confidence) = metadata.confidence.as_deref() {
        parts.push(format!("conf={confidence}"));
    }
    if let Some(radius) = metadata.blast_radius.as_deref() {
        parts.push(format!("radius={radius}"));
    }
    if let Some(trigger) = metadata.retrieval_trigger.as_deref() {
        parts.push(format!("trigger={trigger}"));
    }
    Some(format!(" {{{}}}", parts.join(", ")))
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ContinuityBootstrapTier {
    MustBlock,
    Active,
    Evidence,
}

fn memory_continuity_bootstrap_tier(
    metadata: &MemoryContinuityMetadata,
) -> Option<ContinuityBootstrapTier> {
    match metadata.actionability.as_deref() {
        Some("must_block") => return Some(ContinuityBootstrapTier::MustBlock),
        Some("plan_influence") | Some("needs_review") => {
            return Some(ContinuityBootstrapTier::Active);
        }
        Some("background") => return Some(ContinuityBootstrapTier::Evidence),
        _ => {}
    }
    match metadata.continuity_role.as_deref() {
        Some("constraint") | Some("warning") => Some(ContinuityBootstrapTier::MustBlock),
        Some("state") | Some("procedure") | Some("preference") => {
            Some(ContinuityBootstrapTier::Active)
        }
        Some("evidence") | Some("archive") => Some(ContinuityBootstrapTier::Evidence),
        _ => None,
    }
}

fn format_continuity_kernel_row(r: &MemoryRecord, snippet_len: usize) -> String {
    let snippet: String = r.content.chars().take(snippet_len).collect();
    let ellipsis = if r.content.chars().count() > snippet_len {
        "..."
    } else {
        ""
    };
    let imp_marker = if r.importance >= 0.7 { "*" } else { "" };
    let reason = memory_continuity_bootstrap_reason(r).unwrap_or_default();
    format!(
        "- [{}] {}{}{}: {}{}",
        r.kind, r.key, imp_marker, reason, snippet, ellipsis
    )
}

fn format_continuity_kernel_block(
    rows: &[MemoryRecord],
    is_compact: bool,
    snippet_len: usize,
) -> Option<Vec<String>> {
    let mut must_block: Vec<&MemoryRecord> = Vec::new();
    let mut active: Vec<&MemoryRecord> = Vec::new();
    let mut evidence: Vec<&MemoryRecord> = Vec::new();

    for row in rows.iter().filter(|r| r.status == "active") {
        let Some(metadata) =
            memory_continuity_metadata_from_tags(&row.tags, row.superseded_by.as_deref())
        else {
            continue;
        };
        match memory_continuity_bootstrap_tier(&metadata) {
            Some(ContinuityBootstrapTier::MustBlock) => must_block.push(row),
            Some(ContinuityBootstrapTier::Active) => active.push(row),
            Some(ContinuityBootstrapTier::Evidence) => evidence.push(row),
            None => {}
        }
    }

    if must_block.is_empty() && active.is_empty() && evidence.is_empty() {
        return None;
    }
    for bucket in [&mut must_block, &mut active, &mut evidence] {
        bucket.sort_by(|a, b| {
            b.importance
                .partial_cmp(&a.importance)
                .unwrap_or(std::cmp::Ordering::Equal)
        });
    }

    let total = must_block.len() + active.len() + evidence.len();
    let mut out = vec![
        if is_compact {
            format!("=== Continuity Kernel ({total}) ===")
        } else {
            format!("=== Continuity Kernel ({total} selected rows, no extra retrieval) ===")
        },
        String::new(),
    ];
    let mut append_bucket = |title: &str, bucket: &[&MemoryRecord], cap: usize| {
        if bucket.is_empty() {
            return;
        }
        out.push(title.to_string());
        for row in bucket.iter().take(cap) {
            out.push(format_continuity_kernel_row(row, snippet_len));
        }
    };
    append_bucket("-- must-block / constraints --", &must_block, 4);
    append_bucket("-- active state / procedures --", &active, 4);
    append_bucket("-- evidence / background --", &evidence, 3);
    out.push(String::new());
    Some(out)
}

fn format_bootstrap_memory_rows(rows: &[MemoryRecord], snippet_len: usize) -> Vec<String> {
    rows.iter()
        .map(|r| {
            let visible_tags: Vec<&str> = r
                .tags
                .iter()
                .map(String::as_str)
                .filter(|tag| !is_continuity_tag(tag))
                .collect();
            let tags = if visible_tags.is_empty() {
                String::new()
            } else {
                format!(" [{}]", visible_tags.join(", "))
            };
            let continuity_reason = memory_continuity_bootstrap_reason(r).unwrap_or_default();
            let snippet: String = r.content.chars().take(snippet_len).collect();
            let ellipsis = if r.content.chars().count() > snippet_len {
                "…"
            } else {
                ""
            };
            let imp_marker = if r.importance >= 0.7 { "★" } else { "" };
            // #1758 hardening: rows carrying a fabricatable identifier (bare
            // git SHA / #post-id) — either flagged at curate time or detected
            // here for rows predating the tag — get a ⚠ref marker so recalled
            // identifiers read as "verify before citing", not settled fact.
            let ref_marker = if r
                .tags
                .iter()
                .any(|t| t == crate::curate::UNVERIFIED_IDENTIFIER_TAG)
                || crate::curate::contains_unverified_identifier(&snippet)
            {
                " ⚠ref"
            } else {
                ""
            };
            format!(
                "[{}] {}{}{}{}{}: {}{}",
                r.kind,
                r.key,
                imp_marker,
                ref_marker,
                tags,
                continuity_reason,
                snippet,
                ellipsis
            )
        })
        .collect()
}

/// **L5 P3** — composite "preamble fitness" score for feedback memories.
/// Blends static importance with a 30d half-life recency factor so the
/// session-start preamble surfaces both freshly-written corrections and
/// long-standing high-importance feedback. Pure for testability.
fn feedback_preamble_score(importance: f64, updated_at: i64, now: i64) -> f64 {
    let age_days = ((now - updated_at).max(0) as f64) / 86_400.0;
    let recency = (-age_days / 30.0).exp(); // 30d half-life
    importance + 0.3 * recency
}

/// **L5 P3** — pick the top-K feedback memories for the session-start
/// preamble. Re-ranks by [`feedback_preamble_score`] then truncates.
/// Pure (no IO); caller sources `rows` from `list_memories_in_scope`.
fn pick_top_feedback(rows: Vec<MemoryRecord>, k: usize, now: i64) -> Vec<MemoryRecord> {
    let mut scored: Vec<(f64, MemoryRecord)> = rows
        .into_iter()
        .filter(|r| r.status == "active" && r.kind == "feedback")
        .map(|r| {
            let score = feedback_preamble_score(r.importance, r.updated_at, now);
            (score, r)
        })
        .collect();
    scored.sort_by(|a, b| b.0.partial_cmp(&a.0).unwrap_or(std::cmp::Ordering::Equal));
    scored.into_iter().take(k).map(|(_, r)| r).collect()
}

/// **L5 P3** — format the feedback preamble block. Returns `None` when
/// `rows` is empty so the caller can skip the section header entirely
/// (no visual noise on fresh sessions). Pure for testability.
fn format_feedback_preamble_block(
    rows: &[MemoryRecord],
    is_compact: bool,
    snippet_len: usize,
) -> Option<Vec<String>> {
    if rows.is_empty() {
        return None;
    }
    let header = if is_compact {
        format!("=== Feedback preamble ({}) ===", rows.len())
    } else {
        format!(
            "=== Behavioral Feedback Preamble ({} top recent + important) ===",
            rows.len()
        )
    };
    let mut out = vec![header, String::new()];
    out.extend(format_bootstrap_memory_rows(rows, snippet_len));
    out.push(String::new());
    Some(out)
}

/// **B1 audit-gap v0 (2026-05-19)** — project-state digest block formatter.
/// Compact "where am I right now" orientation card for session bootstrap.
/// Three buckets (caller-sourced + pre-filtered):
///   - up to 3 most important active `decision` records
///   - up to 1 most recent `session_handoff`
///   - up to 3 most recent active `project` records
///
/// Returns `None` if all three buckets are empty so the caller can skip
/// the section header entirely (no visual noise on fresh stores).
///
/// Refs:
/// - docs/DESIGN-A1-B1-B3-RECALL-TIMING-v0.md §2.3 mechanism
/// - thread 10 #218 (design) + #221/#223 (cross-check) + #249 (act unlock)
fn format_project_state_digest_block(
    decisions: &[MemoryRecord],
    handoffs: &[MemoryRecord],
    projects: &[MemoryRecord],
    is_compact: bool,
    snippet_len: usize,
) -> Option<Vec<String>> {
    if decisions.is_empty() && handoffs.is_empty() && projects.is_empty() {
        return None;
    }
    let total = decisions.len() + handoffs.len() + projects.len();
    let header = if is_compact {
        format!("=== State digest ({total}) ===")
    } else {
        format!(
            "=== Project State Digest ({total} = {}D + {}H + {}P) ===",
            decisions.len(),
            handoffs.len(),
            projects.len()
        )
    };
    let mut out = vec![header, String::new()];
    if !decisions.is_empty() {
        if !is_compact {
            out.push("-- recent important decisions --".to_string());
        }
        out.extend(format_bootstrap_memory_rows(decisions, snippet_len));
    }
    if !handoffs.is_empty() {
        if !is_compact {
            out.push("-- last handoff --".to_string());
        }
        out.extend(format_bootstrap_memory_rows(handoffs, snippet_len));
    }
    if !projects.is_empty() {
        if !is_compact {
            out.push("-- recently touched projects --".to_string());
        }
        out.extend(format_bootstrap_memory_rows(projects, snippet_len));
    }
    out.push(String::new());
    Some(out)
}

// ---------------------------------------------------------------------------
// session_bootstrap per-block token budgets (v0 — 2026-05-17).
//
// Live measurement on 2026-05-17 showed bootstrap output 16,834 chars ≈ 4,810
// tokens, dominated by `format_bootstrap_memory_rows` (top-60 memories with
// 120-char snippets ≈ 3,400 tokens) plus 6+ static blocks.
//
// Budgets below target total p95 ≈ 2,000 tokens (60% reduction). They cap
// each block independently so any single block exceeding its budget gets
// `[...trimmed N more lines for budget]` instead of starving the next block.
//
// Inspired by [rtk-ai/icm](https://github.com/rtk-ai/icm)'s 500-token wake-up
// cap; see `docs/DESIGN-context-lifecycle-edges-2026-05-17.md` §3.6.
const BUDGET_USER_PROFILE: usize = 300;
const BUDGET_AGENT_PROFILE: usize = 300;
const BUDGET_AIOT_SOUL: usize = 200;
const BUDGET_SEED: usize = 200;
const BUDGET_PERCEPTION: usize = 150;
const BUDGET_LETTER_EACH: usize = 150;
const BUDGET_FEEDBACK_PREAMBLE: usize = 300;
const BUDGET_WORK_MEMORY: usize = 260;
const BUDGET_CROSS_NODE_PEERS: usize = 160;
const BUDGET_DECISIONS_DUE: usize = 200;
const BUDGET_ERROR_PATTERNS: usize = 200;
const BUDGET_CONTINUITY_KERNEL: usize = 260;
const BUDGET_BOOTSTRAP_ROWS: usize = 500;
const BUDGET_GAMMA_BFS: usize = 200;
const BUDGET_DELTA_TRANSITIONS: usize = 150;
const BUDGET_SIBLING_WARN: usize = 200;
// B1 audit-gap v0 (2026-05-19) — project-state digest. 7 rows max
// (3 decisions + 1 handoff + 3 projects) × ~120 char snippets ≈ 200 tokens.
const BUDGET_PROJECT_DIGEST: usize = 220;
// SSB §3.6 (2026-06-15) — recent verify-first NotVerified events surfaced at
// cold start. Top 5 inert/failed actions × ~80 char ≈ 160 tokens; hidden when
// none, so the budget only bites on a session that actually had a no-op.
const BUDGET_INERT_ACTIONS: usize = 200;

/// Trim a block of lines so the total estimated token count ≤ `budget`.
///
/// Appends `[...trimmed N more lines for budget]` marker when truncated.
/// Keeps the first line (block header) even if the header alone exceeds
/// budget — the header is informational and the trim marker tells the
/// reader the block was cut.
///
/// Cheap path: if `chars / 3 ≤ budget` we know we're under (chars/3 is a
/// pessimistic upper bound for any reasonable text), skip the calibrated
/// estimator entirely.
fn cap_block_lines(lines: Vec<String>, budget: usize) -> Vec<String> {
    if lines.is_empty() || budget == 0 {
        return lines;
    }
    // A caller may pass a multi-line string as a SINGLE element (e.g. an
    // AGENT.md profile body or a soul/seed block). Normalize to real lines so
    // the budget loop can keep a useful PREFIX of an oversized block instead of
    // dropping the whole body atomically — which would emit a hollow header
    // (a header with no content, the "green-but-inert" presentation we forbid).
    // When the block fits, splitting then re-joining on "\n" reproduces the
    // identical text, so this is a no-op for under-budget blocks.
    let lines: Vec<String> = lines
        .into_iter()
        .flat_map(|s| {
            if s.contains('\n') {
                s.split('\n').map(str::to_string).collect::<Vec<_>>()
            } else {
                vec![s]
            }
        })
        .collect();
    // Fast path: pessimistic bound says we're under.
    let total_chars: usize = lines.iter().map(|s| s.chars().count()).sum();
    if total_chars / 3 <= budget {
        return lines;
    }
    // Slow path: use calibrated estimator.
    let joined = lines.join("\n");
    let est = estimate_tokens_from_text(&joined) as usize;
    if est <= budget {
        return lines;
    }
    // Truncate from end, keep accumulating until budget exhausted.
    let mut out: Vec<String> = Vec::with_capacity(lines.len() + 1);
    let mut running: usize = 0;
    let mut kept = 0usize;
    for (i, line) in lines.iter().enumerate() {
        let line_tokens = estimate_tokens_from_text(line) as usize;
        // Always keep the first line (header). After that, stop when we'd
        // exceed budget.
        if i > 0 && running + line_tokens > budget {
            break;
        }
        running += line_tokens;
        out.push(line.clone());
        kept = i + 1;
    }
    let trimmed = lines.len() - kept;
    if trimmed > 0 {
        out.push(format!("  [...trimmed {} more lines for budget]", trimmed));
    }
    out
}

/// SSB lifecycle producer (roadmap §2 "hooks → bus events"): emit a
/// `session_bootstrap` as a typed semantic event on the same unified
/// Object/Affordance contract as browser/desktop/mobile and the symmetric
/// `session_finalize` lifecycle producer. Bootstrap HAS readback (the count of
/// memory rows it surfaced + the assembled payload), so a bootstrap that
/// injected context is Verified; an empty-scope bootstrap injected nothing and
/// is honestly Unknown — never laundered to a green success. Best-effort; the
/// emit failure never affects the bootstrap output.
async fn record_session_bootstrap_event(
    store: &Arc<dyn StateStore>,
    injected: bool,
    memory_rows: usize,
    output_lines: usize,
) {
    let verdict = crate::semantic_event::classify_lifecycle(true, injected, "");
    let ev = crate::semantic_event::SemanticEvent {
        ts: dispatch_now_secs(),
        actor: "mcp".to_string(),
        source: "session".to_string(),
        action: "bootstrap".to_string(),
        target: None,
        object: crate::semantic_event::SemanticObject {
            object_type: "session".to_string(),
            source_adapter: "session".to_string(),
            label: None,
            object_id: None,
        },
        affordance: crate::semantic_event::Affordance {
            action_type: "bootstrap".to_string(),
            risk_level: "low".to_string(),
            requires_gate: false,
            expected_effect: Some("assemble + inject session context".to_string()),
        },
        verdict,
        facts: json!({
            "memory_rows": memory_rows,
            "output_lines": output_lines,
            "injected": injected,
        }),
    };
    if let Err(e) = store.record_semantic_event(ev.to_record()).await {
        tracing::debug!(error = %e, "record_semantic_event (session_bootstrap) failed");
    }
}

pub struct SessionBootstrapTool {
    hub: Hub,
}
impl SessionBootstrapTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for SessionBootstrapTool {
    fn name(&self) -> &'static str {
        "session_bootstrap"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Build a compact memory bootstrap block. Returns top scoped \
                 memories (global + project), session_handoff rows first. query= enables \
                 semantic ranking. frontend='cursor'|'warp' uses compact format; default \
                 'claude-code' is full."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "cwd": { "type": "string", "description": "Optional project path for scope filtering. Defaults to process cwd." },
                    "limit": { "type": "integer", "minimum": 1, "maximum": 200, "default": 60 },
                    "query": {
                        "type": "string",
                        "description": "Optional natural-language description of the current task (e.g. 'fix Warp IPC socket reconnect bug'). When provided, memories are ranked by semantic similarity instead of static importance. session_handoff rows are always prepended regardless."
                    },
                    "frontend": {
                        "type": "string",
                        "enum": ["claude-code", "cursor", "warp", "auto"],
                        "default": "auto",
                        "description": "Output format: 'cursor'/'warp' for compact, 'claude-code' for full, 'auto' detects from env."
                    },
                    "error_hint": {
                        "type": "string",
                        "description": "Optional error text (e.g. last command stderr). When set, surfaces active kind=error_pattern memories whose non-empty trigger_pattern appears as a substring in this hint (case-insensitive)."
                    }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let cwd = args
            .get("cwd")
            .and_then(|v| v.as_str())
            .map(|s| s.to_string())
            .or_else(|| {
                std::env::current_dir()
                    .ok()
                    .map(|p| p.display().to_string())
            })
            .unwrap_or_else(|| "/".to_string());
        let limit = args
            .get("limit")
            .and_then(|v| v.as_u64())
            .unwrap_or(60)
            .min(200) as u32;

        // Detect frontend: explicit arg > env var > default (claude-code).
        // Both `cursor` and `warp` use the compact output format (Warp
        // surfaces tool output in the Block UI where vertical space is
        // at a premium, just like Cursor's inline panel).
        let frontend = args
            .get("frontend")
            .and_then(|v| v.as_str())
            .unwrap_or("auto");
        let is_compact = match frontend {
            "cursor" | "warp" => true,
            "claude-code" => false,
            _ => detect_frontend() != "claude-code" && detect_frontend() != "unknown",
        };

        let snippet_len = if is_compact { 80 } else { 120 };

        let error_hint = args
            .get("error_hint")
            .and_then(|v| v.as_str())
            .map(str::trim)
            .filter(|s| !s.is_empty());

        let mut error_section: Vec<String> = Vec::new();
        if let Some(hint) = error_hint {
            let hint_lc = hint.to_lowercase();
            let ep_rows = store
                .list_memories_in_scope(
                    &cwd,
                    Some("error_pattern"),
                    MemoryListSort::ByImportance,
                    80,
                )
                .await?;
            let ep_rows: Vec<_> = ep_rows
                .into_iter()
                .filter(|r| r.status == "active")
                .filter(|r| {
                    r.trigger_pattern.as_ref().is_some_and(|p| {
                        let pl = p.trim().to_lowercase();
                        !pl.is_empty() && hint_lc.contains(&pl)
                    })
                })
                .collect();
            if !ep_rows.is_empty() {
                error_section.push(if is_compact {
                    "=== Error patterns (hint) ===".to_string()
                } else {
                    "=== Error patterns (matched error_hint) ===".to_string()
                });
                error_section.push(String::new());
                error_section.extend(format_bootstrap_memory_rows(&ep_rows, snippet_len));
                error_section.push(String::new());
            }
        }

        // Optional semantic query: rank by cosine similarity when provided.
        let query = args
            .get("query")
            .and_then(|v| v.as_str())
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .map(str::to_string);

        let rows: Vec<MemoryRecord> = if let Some(ref q) = query {
            // Semantic path: cosine-ranked results, session_handoff always prepended.
            let semantic_hits = store
                .memory_search_semantic(q, limit, 0.15)
                .await
                .unwrap_or_default();
            let mut ranked: Vec<MemoryRecord> = semantic_hits
                .into_iter()
                .filter(|h| h.record.status == "active")
                .map(|h| h.record)
                .collect();
            // Always prepend session_handoff rows for continuity.
            let handoff = store
                .list_memories_in_scope(&cwd, Some("session_handoff"), MemoryListSort::Recent, 8)
                .await
                .unwrap_or_default()
                .into_iter()
                .filter(|r| r.status == "active")
                .collect::<Vec<_>>();
            let handoff_keys: std::collections::HashSet<_> =
                handoff.iter().map(|r| r.key.clone()).collect();
            ranked.retain(|r| !handoff_keys.contains(&r.key));
            let mut combined = handoff;
            combined.extend(ranked);
            combined.truncate(limit as usize);
            combined
        } else {
            // Static path: existing ByImportance sort, session_handoff floated first.
            let rows = store
                .list_memories_in_scope(&cwd, None, MemoryListSort::ByImportance, limit)
                .await?;
            let rows: Vec<_> = rows.into_iter().filter(|r| r.status == "active").collect();
            prioritize_session_handoff(rows)
        };

        if rows.is_empty() && error_section.is_empty() {
            let lifecycle_hint = session_lifecycle_hint();
            // SSB lifecycle producer: an empty-scope bootstrap injected nothing,
            // so it is honestly Unknown (ran, no effect) — not laundered green.
            record_session_bootstrap_event(&store, false, 0, 0).await;
            return Ok(ToolResult::text(format!(
                "(no scoped memories yet)\n\n{lifecycle_hint}"
            )));
        }

        let mode_tag = if query.is_some() { " | semantic" } else { "" };
        let mut lines = if is_compact {
            vec![
                format!("=== Bootstrap (scope: {}{mode_tag}) ===", cwd),
                String::new(),
            ]
        } else {
            vec![
                format!("=== Agent-Bridge Session Bootstrap (scope: {cwd}{mode_tag}) ==="),
                "Use memory_get <key> for full content, memory_search for lookup.".to_string(),
                String::new(),
            ]
        };

        // Inject USER.md profile if present.
        if let Ok(profile) = std::fs::read_to_string(user_profile_path()) {
            if !profile.trim().is_empty() {
                let block = vec![
                    "=== User Profile ===".to_string(),
                    profile.trim().to_string(),
                    "=== End User Profile ===".to_string(),
                    String::new(),
                ];
                lines.extend(cap_block_lines(block, BUDGET_USER_PROFILE));
            }
        }

        // Inject AGENT.md self-profile if present — this is the agent's own
        // values / working style / self-observations, companion to USER.md.
        // Maintained by the agent itself via session_finalize(agent_profile=...).
        if let Ok(profile) = std::fs::read_to_string(agent_profile_path()) {
            if !profile.trim().is_empty() {
                let block = vec![
                    "=== Agent Self-Profile ===".to_string(),
                    profile.trim().to_string(),
                    "=== End Agent Self-Profile ===".to_string(),
                    String::new(),
                ];
                lines.extend(cap_block_lines(block, BUDGET_AGENT_PROFILE));
            }
        }

        // Inject AiOT Soul state if available — the carrier identity
        // that AiOT's identity_anchor.py has been accumulating across
        // sessions. Read-only Phase α′ bridge; the actual EMA update
        // logic stays on AiOT side. This makes the 21-month trajectory
        // tangible at the level of working state, not just memory text.
        if let Some(soul_block) = format_aiot_soul_block() {
            let block = vec![
                "=== AiOT Soul (read-only carrier identity from /Data/CascadeProjects/AiOT) ==="
                    .to_string(),
                soul_block,
                "=== End AiOT Soul ===".to_string(),
                String::new(),
            ];
            lines.extend(cap_block_lines(block, BUDGET_AIOT_SOUL));
        }

        // Inject Agent-Bridge Seed sidecar grid state if available — symmetric
        // to AiOT Soul. AiOT Soul = Python EMA on AiOT carrier trajectory;
        // Agent-Bridge Seed = Rust DynamicGrid self-organizing on the
        // agent-bridge memory stream. Both are read-only views of "another
        // substrate's identity" — together they triangulate self across
        // markdown / Python EMA / Rust grid. See
        // `plan_seed_integration_gaps_20260504`.
        if let Some(seed_block) = format_agent_bridge_seed_block() {
            let block = vec![
                "=== Agent-Bridge Seed (self-organized network on memory stream) ===".to_string(),
                seed_block,
                "=== End Seed ===".to_string(),
                String::new(),
            ];
            lines.extend(cap_block_lines(block, BUDGET_SEED));
        }

        // Inject Perception Filter (path B) state if available — parallel
        // learned-encoder + thermodynamic-filter substrate. Read-only, same
        // as the 32-d Seed above. Together they cross-validate "what does the
        // current memory corpus look like to a self-organizing network?"
        // Model and dim are dynamic (env-overridable in the sidecar) — the
        // body of the block carries the ground-truth `model=... ({dim}d)`.
        if let Some(pf_block) = format_perception_filter_block() {
            let block = vec![
                "=== Perception Filter (thermodynamic surprisal filter on memory stream) ==="
                    .to_string(),
                pf_block,
                "=== End Perception Filter ===".to_string(),
                String::new(),
            ];
            lines.extend(cap_block_lines(block, BUDGET_PERCEPTION));
        }

        // Inject up to 3 most recent letter-to-future-self entries.
        // Letters are written by the agent via session_finalize(letter=...);
        // they sit between AGENT.md (stable identity) and memory rows
        // (specific knowledge). They carry "what I was thinking last time"
        // — momentary state that AGENT.md doesn't and shouldn't capture.
        for path in recent_letters(3) {
            if let Ok(body) = std::fs::read_to_string(&path) {
                let stem = path
                    .file_stem()
                    .and_then(|s| s.to_str())
                    .unwrap_or("letter");
                let block = vec![
                    format!("=== Letter from past-self ({stem}) ==="),
                    body.trim().to_string(),
                    "=== End Letter ===".to_string(),
                    String::new(),
                ];
                lines.extend(cap_block_lines(block, BUDGET_LETTER_EACH));
            }
        }

        // L5 P3 — feedback preamble. Surface top-K behavioral feedback
        // memories (recent + high-importance) at session start so the
        // assistant lands with corrections in awareness before any
        // search query. Companion to L5 P1 (FTS retrieval boost) and
        // L5 P2 (memory_correction MCP tool). K=5 is the v0 default;
        // tune via L5-P1 30d measurement.
        {
            let now_ts = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap_or_default()
                .as_secs() as i64;
            let feedback_pool = store
                .list_memories_in_scope(&cwd, Some("feedback"), MemoryListSort::ByImportance, 30)
                .await
                .unwrap_or_default();
            let picked = pick_top_feedback(feedback_pool, 5, now_ts);
            if let Some(block) = format_feedback_preamble_block(&picked, is_compact, snippet_len) {
                lines.extend(cap_block_lines(block, BUDGET_FEEDBACK_PREAMBLE));
            }
        }

        // Active work memory is a short-lived scratchpad for the task in
        // flight. It is intentionally separate from durable lesson/decision
        // rows so context-compaction recovery does not pollute long-term memory.
        {
            let work_rows = store
                .list_memories_in_scope(&cwd, Some(WORK_MEMORY_KIND), MemoryListSort::Recent, 8)
                .await
                .unwrap_or_default();
            if let Some(block) = format_work_memory_block(&work_rows, is_compact, 180) {
                lines.extend(cap_block_lines(block, BUDGET_WORK_MEMORY));
            }

            // Cross-node wake (auto-surface): lanes a SIBLING NODE updated for this
            // same project (e.g. an aio2 session's project:/Data/... lane aliased
            // to this Mac session's project). The work_memory block above is
            // exact-scope and same-node only; this block makes a starting session
            // PERCEIVE peer activity without an explicit `work_memory op=peers`
            // call. Pull/turn-driven: shows lanes already synced into the local
            // store. Gated on the scope-alias registry (no aliases = no cross-node).
            if let Some(aliases) = std::env::var(PROJECT_SCOPE_ALIASES_ENV)
                .ok()
                .filter(|s| !s.trim().is_empty())
            {
                let broad = store
                    .list_memories(
                        Some(WORK_MEMORY_KIND),
                        MemoryListSort::Recent,
                        WORK_MEMORY_ALIAS_FANIN_SCAN,
                    )
                    .await
                    .unwrap_or_default();
                let peers =
                    cross_node_peer_lanes(&work_memory_scope(&cwd), broad, &aliases, 0, 3);
                if let Some(block) = format_cross_node_peer_block(&peers, is_compact) {
                    lines.extend(cap_block_lines(block, BUDGET_CROSS_NODE_PEERS));
                }
            }
        }

        // B1 audit-gap v0 — project-state digest. Compact "where am I right
        // now" card: top-3 important decisions + last handoff + top-3 recently-
        // touched projects. Different from "Decisions Due for Review" (which
        // is review-cycle-driven, not importance/recency-driven) and from the
        // main bootstrap rows (mixed-kind, top-60, low compression). This
        // block answers the orientation question first.
        //
        // Refs: docs/DESIGN-A1-B1-B3-RECALL-TIMING-v0.md §2.3, thread 10 #218/#249.
        {
            let decision_pool = store
                .list_memories_in_scope(&cwd, Some("decision"), MemoryListSort::ByImportance, 12)
                .await
                .unwrap_or_default();
            let decisions_picked: Vec<MemoryRecord> = decision_pool
                .into_iter()
                .filter(|r| r.status == "active" && r.importance >= 0.6)
                .take(3)
                .collect();
            let handoff_pool = store
                .list_memories_in_scope(&cwd, Some("session_handoff"), MemoryListSort::Recent, 5)
                .await
                .unwrap_or_default();
            let handoffs_picked: Vec<MemoryRecord> = handoff_pool
                .into_iter()
                .filter(|r| r.status == "active")
                .take(1)
                .collect();
            let project_pool = store
                .list_memories_in_scope(&cwd, Some("project"), MemoryListSort::Recent, 12)
                .await
                .unwrap_or_default();
            let projects_picked: Vec<MemoryRecord> = project_pool
                .into_iter()
                .filter(|r| r.status == "active")
                .take(3)
                .collect();
            if let Some(block) = format_project_state_digest_block(
                &decisions_picked,
                &handoffs_picked,
                &projects_picked,
                is_compact,
                snippet_len,
            ) {
                lines.extend(cap_block_lines(block, BUDGET_PROJECT_DIGEST));
            }
        }

        // Inject "Decisions Due for Review" — closes the reflection loop in
        // the dual-mechanism continuity architecture. Decisions tagged with
        // `review:Nd` re-surface here once they exceed their review interval.
        // Hidden when nothing is due (avoids visual noise on fresh sessions).
        {
            let now_ts = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap_or_default()
                .as_secs() as i64;
            let decision_pool = store
                .list_memories_in_scope(&cwd, Some("decision"), MemoryListSort::Newest, 200)
                .await
                .unwrap_or_default()
                .into_iter()
                .filter(|r| r.status == "active")
                .collect::<Vec<_>>();
            if let Some(block) = format_due_review_block(&decision_pool, now_ts) {
                let count = block.matches("\n- ").count() + 1;
                let block_lines = vec![
                    format!("=== Decisions Due for Review ({count}) ==="),
                    block,
                    "=== End Reviews ===".to_string(),
                    String::new(),
                ];
                lines.extend(cap_block_lines(block_lines, BUDGET_DECISIONS_DUE));
            }
        }

        // SSB §3.6 — surface recent verify-first NotVerified events at cold
        // start. An action that was inert / failed / refused last session (the
        // anti-laundering signal the producers emit) is shown here instead of
        // staying buried in the semantic_events log — closing the loop from
        // bus event → presentation/handoff surface. Hidden when none (clean
        // session). Best-effort; a read failure never blocks bootstrap.
        {
            let now_ts = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .map(|d| d.as_secs() as i64)
                .unwrap_or(0);
            if let Ok(evs) = store.recent_semantic_events(7 * 86400, 100).await {
                if let Some(block) = format_inert_actions_block(&evs, now_ts, 5) {
                    lines.extend(cap_block_lines(block, BUDGET_INERT_ACTIONS));
                }
            }

            // SSB "memory" arm (`… → Verification → Memory`) — distill the whole
            // retained verify-first log into failure MODES that *recur*, so a
            // systematic inert pattern surfaces as a learned lesson rather than
            // just the last few one-off failures the recency block above shows.
            // Wider window (the retained ring IS the cross-session memory
            // substrate) + a recurrence floor so one-offs never become noise.
            // Best-effort; a read failure never blocks bootstrap.
            if let Ok(evs) = store.recent_semantic_events(90 * 86400, 500).await {
                if let Some(block) = format_recurring_inert_block(&evs, now_ts, 3, 3) {
                    lines.extend(cap_block_lines(block, BUDGET_INERT_ACTIONS));
                }
            }
        }

        lines.extend(cap_block_lines(error_section, BUDGET_ERROR_PATTERNS));
        if let Some(block) = format_continuity_kernel_block(&rows, is_compact, snippet_len) {
            lines.extend(cap_block_lines(block, BUDGET_CONTINUITY_KERNEL));
        }
        lines.extend(cap_block_lines(
            format_bootstrap_memory_rows(&rows, snippet_len),
            BUDGET_BOOTSTRAP_ROWS,
        ));
        lines.push("=== End Bootstrap ===".to_string());
        lines.push(String::new());

        // γ' wiring (2026-05-10) — surface high-energy neighbors of recent
        // high-importance seeds via memory_neighbors_bfs. Engine (α
        // coactivation, β cofires, P4 evolved edges) is already built; this
        // injects its output into cold-start payload. See
        // `design_gamma_scope_revision_after_beta_dogfood_20260510` for why
        // γ became wiring instead of a prediction engine. Best-effort —
        // failures don't block bootstrap.
        if let Ok(section) =
            crate::bootstrap_bfs::compute_section(store.as_ref(), &cwd, is_compact).await
        {
            lines.extend(cap_block_lines(section, BUDGET_GAMMA_BFS));
        }

        // δ-4 PP-1 lift (2026-05-11) — surface repeated next-step transitions
        // from recent memory_get events as a predicted-next signal. Bumps the
        // Butlin PP-1 indicator from medium → strong by giving cold-start a
        // temporal-asymmetric "after A, B usually follows" line. Best-effort.
        if let Ok(section) =
            crate::bootstrap_transitions::compute_section(store.as_ref(), is_compact).await
        {
            lines.extend(cap_block_lines(section, BUDGET_DELTA_TRANSITIONS));
        }

        // ε-5 (2026-05-11) — sibling-presence warning. Two agents in the
        // same working tree + git index will sweep each other's unstaged
        // changes (top-9 Hebbian pair: `lesson_sibling_parallel_commits` ↔
        // `lesson_git_commit_by_path_overrides_apply_cached`). When another
        // agent has heartbeat in this project within the last 5 minutes,
        // emit a loud warning + the worktree-session recipe. Best-effort.
        {
            let project_slug = std::path::Path::new(&cwd)
                .file_name()
                .and_then(|n| n.to_str().map(|s| s.to_string()))
                .unwrap_or_default();
            if !project_slug.is_empty() {
                if let Ok(live) = store
                    .agent_presence_list(Some(&project_slug), None, 300, 50)
                    .await
                {
                    let my_sid = std::env::var("CLAUDE_SESSION_ID")
                        .ok()
                        .or_else(|| std::env::var("AGENT_BRIDGE_SESSION_ID").ok());
                    let peers: Vec<&ab_store::AgentPresenceRecord> = live
                        .iter()
                        .filter(|r| my_sid.as_deref().map(|m| r.session_id != m).unwrap_or(true))
                        .collect();
                    if !peers.is_empty() {
                        let now_ts = std::time::SystemTime::now()
                            .duration_since(std::time::UNIX_EPOCH)
                            .map(|d| d.as_secs() as i64)
                            .unwrap_or(0);
                        let mut block = vec![
                            if is_compact {
                                format!(
                                    "=== ⚠ Sibling agents ({}) — risk of sweep ===",
                                    peers.len()
                                )
                            } else {
                                format!(
                                    "=== ⚠ Sibling-Presence Warning ({} other agent{} in '{}') ===",
                                    peers.len(),
                                    if peers.len() == 1 { "" } else { "s" },
                                    project_slug
                                )
                            },
                            String::new(),
                        ];
                        for p in peers.iter().take(5) {
                            let age = (now_ts - p.last_heartbeat_at).max(0);
                            block.push(format!("  • {} (heartbeat {}s ago)", p.session_id, age));
                        }
                        block.push(String::new());
                        if !is_compact {
                            block.push(
                                "  Sharing a working tree + git index → `git add/commit` may sweep"
                                    .to_string(),
                            );
                            block.push(
                                "  the other agent's unstaged changes (see `lesson_sibling_parallel_commits`)."
                                    .to_string(),
                            );
                        }
                        block.push(
                            "  Isolate: `agent-bridge worktree-session new --name <slug>`"
                                .to_string(),
                        );
                        block.push(String::new());
                        lines.extend(cap_block_lines(block, BUDGET_SIBLING_WARN));
                    }
                }
            }
        }

        lines.push(session_lifecycle_hint());

        // D2.3: prime the embedding cache in the background so subsequent
        // memory_search(mode=semantic) calls skip the DB round-trip.
        {
            let prefetch_store = store.clone();
            let prefetch_cache = self.hub.memory_embed_cache.clone();
            tokio::spawn(async move {
                if let Ok(rows) = prefetch_store.memory_load_embeddings().await {
                    let mut guard = prefetch_cache.lock().await;
                    *guard = Some(rows);
                }
            });
        }

        // SSB lifecycle producer: this bootstrap assembled and injected real
        // context (memory rows + blocks), so it is Verified — readback is the
        // surfaced row count + the assembled payload size.
        record_session_bootstrap_event(&store, true, rows.len(), lines.len()).await;

        Ok(ToolResult::text(lines.join("\n")))
    }
}

/// Lifecycle reminder appended to session_bootstrap output.
fn session_lifecycle_hint() -> String {
    "=== Session Lifecycle Reminder ===\n\
     Before this session ends, call:\n\
     1. session_curate(conversation_text=<recent context summary>) — extract and save lessons; \
        prefix lines with handoff: for next-session continuity\n\
     2. session_finalize() — compact stale memories + optional export\n\
     --- Grounded-claim rule (#1758) ---\n\
     Any outward claim that cites a produced identifier (commit SHA, PR#, \
     deployed sha, post-id) MUST be emitted in a SEPARATE tool turn AFTER the \
     producing call returns its real value — never batch the producing call \
     (git commit / deploy) together with the forum_post / memory_save that \
     references it; at batch time the value does not yet exist and gets \
     confabulated. A denied or cancelled tool call did NOT run — re-verify, \
     don't assume success.\n\
     =================================="
        .to_string()
}

// ===========================================================================
//                              session_curate
// ===========================================================================

/// SSB lifecycle producer (roadmap §2 "hooks → bus events"): emit a
/// `session_curate` as a typed semantic event on the unified Object/Affordance
/// contract, completing the session-lifecycle trio on the bus alongside
/// session_bootstrap (start) and session_finalize (end). Curate HAS readback —
/// the count of memories actually persisted — so a run that saved ≥1 memory is
/// Verified; a dry-run or a run that saved nothing (all duplicates / no
/// candidates) made no effect and is honestly Unknown; a run where every
/// candidate save errored failed to persist and is NotVerified (anti-laundering).
/// Best-effort; the emit never affects the curate result.
async fn record_session_curate_event(
    store: &Arc<dyn StateStore>,
    dry_run: bool,
    saved_count: usize,
    skipped_dupes: usize,
    error_count: usize,
    candidate_count: usize,
) {
    let verdict = if dry_run {
        // Dry-run previews candidates but persists nothing → no effect → Unknown.
        crate::semantic_event::classify_lifecycle(true, false, "")
    } else {
        // A real run that saved nothing AND hit errors failed to persist (the
        // step's core work did not succeed) → NotVerified. Otherwise it ran:
        // saved ≥1 → Verified (readback), saved 0 with no errors → Unknown.
        let total_failure = saved_count == 0 && error_count > 0;
        crate::semantic_event::classify_lifecycle(
            !total_failure,
            saved_count > 0,
            if total_failure {
                "curate: all candidate saves failed"
            } else {
                ""
            },
        )
    };
    let ev = crate::semantic_event::SemanticEvent {
        ts: dispatch_now_secs(),
        actor: "mcp".to_string(),
        source: "session".to_string(),
        action: "curate".to_string(),
        target: None,
        object: crate::semantic_event::SemanticObject {
            object_type: "session".to_string(),
            source_adapter: "session".to_string(),
            label: None,
            object_id: None,
        },
        affordance: crate::semantic_event::Affordance {
            action_type: "curate".to_string(),
            risk_level: "low".to_string(),
            requires_gate: false,
            expected_effect: Some("extract + persist memories from conversation".to_string()),
        },
        verdict,
        facts: json!({
            "dry_run": dry_run,
            "saved_count": saved_count,
            "skipped_duplicates": skipped_dupes,
            "error_count": error_count,
            "candidate_count": candidate_count,
        }),
    };
    if let Err(e) = store.record_semantic_event(ev.to_record()).await {
        tracing::debug!(error = %e, "record_semantic_event (session_curate) failed");
    }
}

pub struct SessionCurateTool {
    hub: Hub,
}
impl SessionCurateTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

// CURATE_MARKERS, section helpers, and curate_conversation live in crate::curate.

// Extraction logic lives in crate::curate — use curate_conversation() below.

#[async_trait]
impl McpTool for SessionCurateTool {
    fn name(&self) -> &'static str {
        "session_curate"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Extract structured memories from conversation text. Two-pass: \
                 (1) explicit markers (lesson:, decision:, todo:, handoff:) and \
                 (2) lexical scoring of epistemic/normative/causal/decision signals \
                 (English + Chinese). dry_run=true previews."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "conversation_text": {
                        "type": "string",
                        "description": "Recent conversation or summary text. Lines prefixed with lesson:, decision:, todo:, handoff:, etc. are extracted as memories."
                    },
                    "session_id": {
                        "type": "string",
                        "description": "Optional session ID for key namespacing and deduplication."
                    },
                    "max_items": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": 50,
                        "default": 8,
                        "description": "Max number of memories to write."
                    },
                    "dry_run": {
                        "type": "boolean",
                        "default": false,
                        "description": "If true, return what would be saved without writing."
                    },
                    "implicit_score_threshold": {
                        "type": "number",
                        "description": "Optional Pass-2 minimum aggregate signal score (default from env AGENT_BRIDGE_CURATE_SCORE_THRESHOLD or built-in default). Clamped to [0.15, 0.95]."
                    },
                    "implicit_dedup_jaccard": {
                        "type": "number",
                        "description": "Optional Pass-2 Jaccard dedup threshold (default from env AGENT_BRIDGE_CURATE_DEDUP_JACCARD or built-in default). Clamped to [0.1, 0.95]."
                    }
                },
                "required": ["conversation_text"]
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store_opt = self.hub.store.clone();

        let text = match args.get("conversation_text").and_then(|v| v.as_str()) {
            Some(s) if !s.is_empty() => s.to_string(),
            _ => return Ok(ToolResult::error("missing 'conversation_text'")),
        };
        let session_id = args
            .get("session_id")
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty())
            .map(|s| s.to_string());
        let max_items = args
            .get("max_items")
            .and_then(|v| v.as_u64())
            .unwrap_or(8)
            .min(50) as usize;
        let dry_run = args
            .get("dry_run")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);

        let score_ov = args
            .get("implicit_score_threshold")
            .and_then(|v| v.as_f64())
            .map(|x| x as f32);
        let dedup_ov = args.get("implicit_dedup_jaccard").and_then(|v| v.as_f64());
        let curate_opts =
            crate::curate::CurateOptions::from_env_or_defaults().with_overrides(score_ov, dedup_ov);

        let candidates = crate::curate::curate_conversation_with_options(
            &text,
            session_id.as_deref(),
            max_items,
            curate_opts.clone(),
        );

        if dry_run || store_opt.is_none() {
            // SSB lifecycle producer: a dry-run previews but persists nothing →
            // Unknown (no effect). Only emit when a store exists; a no-store call
            // has nowhere to record (and is not a real curate).
            if let Some(store) = &store_opt {
                record_session_curate_event(store, true, 0, 0, 0, candidates.len()).await;
            }
            return Ok(ToolResult::json_text(&json!({
                "dry_run": true,
                "options": {
                    "implicit_score_threshold": curate_opts.implicit_score_threshold,
                    "implicit_dedup_jaccard": curate_opts.implicit_dedup_jaccard,
                },
                "candidates": candidates.iter().map(|m| json!({
                    "key": m.key,
                    "kind": m.kind,
                    "content": m.content,
                    "tags": m.tags,
                })).collect::<Vec<_>>()
            })));
        }

        let store = store_opt.unwrap();
        let mut saved: Vec<Value> = Vec::new();
        let mut errors: Vec<String> = Vec::new();

        for mem in &candidates {
            // Skip if key already exists (dedup)
            match store.memory_get(&mem.key).await {
                Ok(Some(_)) => {
                    // Already exists — skip
                }
                Ok(None) => match store.memory_save(mem).await {
                    Ok(()) => saved.push(json!({ "key": mem.key, "kind": mem.kind })),
                    Err(e) => errors.push(format!("{}: {e}", mem.key)),
                },
                Err(e) => errors.push(format!("{}: {e}", mem.key)),
            }
        }

        let session_handoff_key = candidates
            .iter()
            .find(|m| m.kind == "session_handoff")
            .map(|m| m.key.clone());

        // SSB lifecycle producer: a real curate HAS readback (the persisted
        // count), so a run that saved ≥1 memory is Verified; saved nothing with
        // no errors → Unknown; saved nothing but every save errored → NotVerified.
        let skipped = candidates.len() - saved.len() - errors.len();
        record_session_curate_event(
            &store,
            false,
            saved.len(),
            skipped,
            errors.len(),
            candidates.len(),
        )
        .await;

        Ok(ToolResult::json_text(&json!({
            "dry_run": false,
            "saved_count": saved.len(),
            "new_memories": saved,
            "skipped_duplicates": skipped,
            "errors": errors,
            "session_handoff_key": session_handoff_key
        })))
    }
}

// ===========================================================================
//                          memory_consolidate
// ===========================================================================

pub struct MemoryConsolidateTool {
    hub: Hub,
}
impl MemoryConsolidateTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

/// Token bag for Jaccard: lowercase alphanumeric tokens with length ≥ 3.
fn memory_consolidate_word_bag(s: &str) -> std::collections::HashSet<String> {
    s.split(|c: char| !c.is_alphanumeric())
        .map(|w| w.to_lowercase())
        .filter(|w| w.len() >= 3)
        .collect()
}

/// Jaccard similarity plus overlap diagnostics for MCP previews.
fn jaccard_words_with_overlap(a: &str, b: &str) -> (f64, usize, usize, Vec<String>) {
    let wa = memory_consolidate_word_bag(a);
    let wb = memory_consolidate_word_bag(b);
    if wa.is_empty() || wb.is_empty() {
        return (0.0, 0, 0, Vec::new());
    }
    let inter_n = wa.intersection(&wb).count();
    let union_n = wa.len() + wb.len() - inter_n;
    let sim = if union_n == 0 {
        0.0
    } else {
        inter_n as f64 / union_n as f64
    };
    let mut overlap_terms: Vec<String> = wa.intersection(&wb).cloned().collect();
    overlap_terms.sort();
    overlap_terms.truncate(14);
    (sim, inter_n, union_n, overlap_terms)
}

#[async_trait]
impl McpTool for MemoryConsolidateTool {
    fn name(&self) -> &'static str {
        "memory_consolidate"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Find and merge redundant or duplicate memories using Jaccard word-overlap \
                 similarity. Groups memories by kind and compares within each group. \
                 Pairs above the similarity threshold are merge candidates. \
                 The higher-importance memory wins; the other is archived with a \
                 'supersedes' edge linking winner → loser. \
                 Default dry_run=true — previews include overlap_terms, token_stats, and rank scores. \
                 Execute merges only after reviewing dry-run output."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "kind": {
                        "type": "string",
                        "description": "Restrict to one memory kind (lesson, decision, context, etc.). Omit to scan all kinds."
                    },
                    "min_similarity": {
                        "type": "number",
                        "minimum": 0.1,
                        "maximum": 0.95,
                        "default": 0.45,
                        "description": "Jaccard word-overlap threshold [0.1–0.95]. 0.45 = roughly 45% word overlap. Lower = more aggressive merging."
                    },
                    "max_pairs": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": 50,
                        "default": 10,
                        "description": "Maximum number of pairs to consolidate per call."
                    },
                    "dry_run": {
                        "type": "boolean",
                        "default": true,
                        "description": "true = preview candidates without writing. false = execute merges."
                    }
                },
                "required": []
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store_opt = self.hub.store.clone();
        let store = match store_opt {
            Some(s) => s,
            None => return Ok(ToolResult::error("no memory store")),
        };

        let kind_filter = args
            .get("kind")
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty())
            .map(|s| s.to_string());
        let min_sim = args
            .get("min_similarity")
            .and_then(|v| v.as_f64())
            .unwrap_or(0.45)
            .clamp(0.1, 0.95);
        let max_pairs = args
            .get("max_pairs")
            .and_then(|v| v.as_u64())
            .unwrap_or(10)
            .min(50) as usize;
        let dry_run = args
            .get("dry_run")
            .and_then(|v| v.as_bool())
            .unwrap_or(true);

        // ── Load memories ─────────────────────────────────────────────────
        let all = store
            .list_memories(kind_filter.as_deref(), MemoryListSort::ByImportance, 300)
            .await?;
        // Only active memories
        let memories: Vec<_> = all.into_iter().filter(|m| m.status == "active").collect();

        // ── Find candidate pairs by Jaccard ───────────────────────────────
        // Group by kind, then compare within each group.
        let mut by_kind: std::collections::HashMap<String, Vec<&MemoryRecord>> =
            std::collections::HashMap::new();
        for m in &memories {
            by_kind.entry(m.kind.clone()).or_default().push(m);
        }

        #[derive(Debug)]
        struct Pair {
            key_a: String,
            key_b: String,
            sim: f64,
            winner: String, // key of the memory to keep
        }

        let mut pairs: Vec<Pair> = Vec::new();
        let mut seen: std::collections::HashSet<(String, String)> =
            std::collections::HashSet::new();

        for group in by_kind.values() {
            let n = group.len();
            for i in 0..n {
                for j in (i + 1)..n {
                    let ma = group[i];
                    let mb = group[j];
                    let (sim, _, _, _) = jaccard_words_with_overlap(&ma.content, &mb.content);
                    if sim < min_sim {
                        continue;
                    }
                    // Canonical pair order
                    let (ka, kb) = if ma.key < mb.key {
                        (ma.key.clone(), mb.key.clone())
                    } else {
                        (mb.key.clone(), ma.key.clone())
                    };
                    if !seen.insert((ka.clone(), kb.clone())) {
                        continue;
                    }
                    // Winner = higher importance × (1 + access_count)
                    let score_a = ma.importance * (1.0 + ma.access_count as f64);
                    let score_b = mb.importance * (1.0 + mb.access_count as f64);
                    let winner = if score_a >= score_b {
                        ma.key.clone()
                    } else {
                        mb.key.clone()
                    };
                    pairs.push(Pair {
                        key_a: ka,
                        key_b: kb,
                        sim,
                        winner,
                    });
                }
            }
        }

        // Sort by similarity descending, keep top max_pairs
        pairs.sort_by(|a, b| {
            b.sim
                .partial_cmp(&a.sim)
                .unwrap_or(std::cmp::Ordering::Equal)
        });
        pairs.truncate(max_pairs);

        if dry_run || pairs.is_empty() {
            let preview: Vec<Value> = pairs
                .iter()
                .map(|p| {
                    let mem_a = memories.iter().find(|m| m.key == p.key_a);
                    let mem_b = memories.iter().find(|m| m.key == p.key_b);
                    let ca = mem_a.map(|m| m.content.as_str()).unwrap_or("");
                    let cb = mem_b.map(|m| m.content.as_str()).unwrap_or("");
                    let (_sim_check, inter_n, union_n, overlap_terms) =
                        jaccard_words_with_overlap(ca, cb);
                    let loser_key = if p.winner == p.key_a {
                        p.key_b.as_str()
                    } else {
                        p.key_a.as_str()
                    };
                    let winner_rec = memories.iter().find(|m| m.key == p.winner);
                    let loser_rec = memories.iter().find(|m| m.key == loser_key);
                    let rank_winner = winner_rec
                        .map(|m| m.importance * (1.0 + m.access_count as f64))
                        .unwrap_or(0.0);
                    let rank_loser = loser_rec
                        .map(|m| m.importance * (1.0 + m.access_count as f64))
                        .unwrap_or(0.0);
                    json!({
                        "key_a": p.key_a,
                        "key_b": p.key_b,
                        "similarity": (p.sim * 100.0).round() / 100.0,
                        "winner": p.winner,
                        "loser": loser_key,
                        "kind": mem_a.or(mem_b).map(|m| m.kind.as_str()).unwrap_or("?"),
                        "content_a": mem_a.map(|m| &m.content[..m.content.len().min(120)]),
                        "content_b": mem_b.map(|m| &m.content[..m.content.len().min(120)]),
                        "overlap_terms": overlap_terms,
                        "token_stats": {
                            "intersection": inter_n,
                            "union": union_n,
                        },
                        "rank_score_winner": (rank_winner * 1000.0).round() / 1000.0,
                        "rank_score_loser": (rank_loser * 1000.0).round() / 1000.0,
                    })
                })
                .collect();
            return Ok(ToolResult::json_text(&json!({
                "dry_run": true,
                "pairs_found": preview.len(),
                "min_similarity": min_sim,
                "scan": {
                    "active_memories": memories.len(),
                    "kind_groups": by_kind.len(),
                },
                "pairs": preview,
                "hint": if preview.is_empty() {
                    "No pairs above threshold. Try lowering min_similarity."
                } else {
                    "Review pairs above, then call with dry_run=false to execute."
                }
            })));
        }

        // ── Execute merges ────────────────────────────────────────────────
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs() as i64;
        let mut merged: Vec<Value> = Vec::new();
        let mut errors: Vec<String> = Vec::new();

        for p in &pairs {
            let loser_key = if p.winner == p.key_a {
                &p.key_b
            } else {
                &p.key_a
            };

            // Get current loser record
            let loser_rec = match store.memory_get(loser_key).await {
                Ok(Some(r)) => r,
                Ok(None) => {
                    errors.push(format!("{loser_key}: not found"));
                    continue;
                }
                Err(e) => {
                    errors.push(format!("{loser_key}: {e}"));
                    continue;
                }
            };

            // Archive the loser
            let mut archived = loser_rec.clone();
            archived.status = "archived".to_string();
            archived.updated_at = now;

            if let Err(e) = store.memory_save(&archived).await {
                errors.push(format!("archive {loser_key}: {e}"));
                continue;
            }

            // Create supersedes edge: winner → loser
            if let Err(e) = store
                .memory_link(&p.winner, loser_key, "supersedes", 1.0)
                .await
            {
                errors.push(format!("link {}->{loser_key}: {e}", p.winner));
            }

            let win_txt = memories
                .iter()
                .find(|m| m.key == p.winner)
                .map(|m| m.content.as_str())
                .unwrap_or("");
            let lose_txt = memories
                .iter()
                .find(|m| m.key == *loser_key)
                .map(|m| m.content.as_str())
                .unwrap_or("");
            let (_, _, _, overlap_terms) = jaccard_words_with_overlap(win_txt, lose_txt);

            merged.push(json!({
                "winner": p.winner,
                "archived": loser_key,
                "similarity": (p.sim * 100.0).round() / 100.0,
                "overlap_terms": overlap_terms,
            }));
        }

        Ok(ToolResult::json_text(&json!({
            "dry_run": false,
            "consolidated": merged.len(),
            "errors": errors,
            "pairs": merged,
            "scan": {
                "active_memories": memories.len(),
                "kind_groups": by_kind.len(),
            },
        })))
    }
}

pub struct XiaoShuActionRequestTool;
impl XiaoShuActionRequestTool {
    pub fn new(_hub: Hub) -> Self {
        Self
    }
}

fn xiao_shu_action_request_string_arg(args: &Value, key: &str) -> Option<String> {
    args.get(key)
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(ToString::to_string)
}

fn xiao_shu_action_request_path_arg(args: &Value, key: &str) -> Option<PathBuf> {
    xiao_shu_action_request_string_arg(args, key).map(PathBuf::from)
}

#[async_trait]
impl McpTool for XiaoShuActionRequestTool {
    fn name(&self) -> &'static str {
        "xiao_shu_action_request"
    }

    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "LLM-safe Xiao Shu action request surface. \
                 Maps high-level intents such as voice_alert or alert_peek into \
                 the existing read-only action preview chain. It never directly \
                 controls the pet, emits audio, writes request records, mutates \
                 cooldown state, or changes the official Codex pet package. \
                 It can also read the pending-action queue when list_queue=true. \
                 Default preview responses include a compact queue_summary (pending \
                 count and newest pending ids) without flooding nested renderer payloads. \
                 Real audio still requires a separate local CLI confirmation."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "label": {
                        "type": "string",
                        "description": "Optional launchd label override for the avatar cortex runner."
                    },
                    "heartbeat_label": {
                        "type": "string",
                        "description": "Optional heartbeat label override. Defaults to the project-scoped avatar heartbeat label."
                    },
                    "project": {
                        "type": "string",
                        "default": "agent-bridge",
                        "description": "Project slug used for avatar cortex status and voice cooldown paths."
                    },
                    "output": {
                        "type": "string",
                        "description": "Optional avatar cortex snapshot path to inspect instead of the default project snapshot."
                    },
                    "actor": {
                        "type": "string",
                        "default": "llm",
                        "description": "Who is requesting the action, for example codex, claude-code, panel, or llm."
                    },
                    "intent": {
                        "type": "string",
                        "default": "voice_alert",
                        "enum": ["voice_alert", "alert_peek", "attention", "review_attention", "xiao_shu_alert_peek"],
                        "description": "High-level Xiao Shu intent. Unsupported intents are blocked by the returned request state."
                    },
                    "message": {
                        "type": "string",
                        "description": "Optional human-readable request note from the caller."
                    },
                    "track": {
                        "type": "string",
                        "default": "xiao_shu::alert_peek::medium",
                        "description": "Optional avatar cortex track token to preview."
                    },
                    "reason": {
                        "type": "string",
                        "description": "Operator-facing reason. Required later by the local CLI emit gate, but this MCP tool remains dry-run."
                    },
                    "confirm": {
                        "type": "boolean",
                        "default": false,
                        "description": "Dry-run confirmation flag. Even when true, this MCP tool does not emit audio."
                    },
                    "enqueue": {
                        "type": "boolean",
                        "default": false,
                        "description": "When true, append this request to Xiao Shu's sidecar pending-action queue. This writes only an auditable request record; it still does not emit audio, mutate cooldown state, or control the pet."
                    },
                    "list_queue": {
                        "type": "boolean",
                        "default": false,
                        "description": "When true, read Xiao Shu's sidecar pending-action queue. This is read-only and cannot emit audio or control the pet."
                    },
                    "request_id": {
                        "type": "string",
                        "description": "Optional queue request id to inspect when list_queue=true."
                    },
                    "state": {
                        "type": "string",
                        "description": "Optional queue state filter when list_queue=true. Defaults to pending_human_confirmation."
                    },
                    "all_states": {
                        "type": "boolean",
                        "default": false,
                        "description": "When list_queue=true, include all queue states instead of only pending records."
                    },
                    "details": {
                        "type": "boolean",
                        "default": false,
                        "description": "Include full nested records. Plain preview requests and broad queue reads default to compact records; request_id or all_states queue reads are always detailed."
                    },
                    "limit": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": 500,
                        "default": 20,
                        "description": "Maximum queue records to return when list_queue=true, newest first."
                    },
                    "force": {
                        "type": "boolean",
                        "default": false,
                        "description": "Dry-run force flag forwarded to the preview gate; it does not bypass the local CLI emit requirement."
                    },
                    "cooldown_secs": {
                        "type": "integer",
                        "minimum": 0,
                        "maximum": 86400,
                        "default": 300
                    },
                    "tts_voice": {
                        "type": "string",
                        "description": "Optional suggested macOS TTS voice for the later local CLI command."
                    },
                    "tts_rate": {
                        "type": "integer",
                        "minimum": 80,
                        "maximum": 300,
                        "description": "Optional suggested macOS say words-per-minute rate for the later local CLI command."
                    }
                }
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let label = xiao_shu_action_request_string_arg(&args, "label");
        let heartbeat_label = xiao_shu_action_request_string_arg(&args, "heartbeat_label");
        let project = xiao_shu_action_request_string_arg(&args, "project");
        let output = xiao_shu_action_request_path_arg(&args, "output");
        let actor = xiao_shu_action_request_string_arg(&args, "actor");
        let intent = xiao_shu_action_request_string_arg(&args, "intent");
        let message = xiao_shu_action_request_string_arg(&args, "message");
        let track = xiao_shu_action_request_string_arg(&args, "track");
        let reason = xiao_shu_action_request_string_arg(&args, "reason");
        let tts_voice = xiao_shu_action_request_string_arg(&args, "tts_voice");
        let request_id = xiao_shu_action_request_string_arg(&args, "request_id");
        let state = xiao_shu_action_request_string_arg(&args, "state");
        let list_queue = args
            .get("list_queue")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        let confirm = args
            .get("confirm")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        let enqueue = args
            .get("enqueue")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        let all_states = args
            .get("all_states")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        let details = args
            .get("details")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        let force = args.get("force").and_then(Value::as_bool).unwrap_or(false);
        let limit = args
            .get("limit")
            .and_then(Value::as_u64)
            .unwrap_or(20)
            .clamp(1, 500) as usize;
        let cooldown_secs = args
            .get("cooldown_secs")
            .and_then(Value::as_i64)
            .unwrap_or(300)
            .clamp(0, 86_400);
        let tts_rate = args
            .get("tts_rate")
            .and_then(Value::as_u64)
            .map(|rate| rate.clamp(80, 300));

        if list_queue {
            let opts = crate::avatar_cortex::XiaoShuActionRequestQueueOptions {
                project: project.as_deref(),
                request_id: request_id.as_deref(),
                state: state.as_deref(),
                include_all_states: all_states,
                include_details: details,
                limit,
            };
            return match crate::avatar_cortex::xiao_shu_action_request_queue(&opts) {
                Ok(payload) => Ok(ToolResult::json_text(&payload)),
                Err(e) => Ok(ToolResult::error(format!("xiao_shu_action_request: {e}"))),
            };
        }

        let opts = crate::avatar_cortex::XiaoShuActionRequestOptions {
            label: label.as_deref(),
            heartbeat_label: heartbeat_label.as_deref(),
            project: project.as_deref(),
            output: output.as_deref(),
            actor: actor.as_deref(),
            intent: intent.as_deref(),
            message: message.as_deref(),
            requested_track: track.as_deref(),
            reason: reason.as_deref(),
            confirm: if enqueue { false } else { confirm },
            force,
            cooldown_secs,
            tts_voice: tts_voice.as_deref(),
            tts_rate,
            include_details: details,
        };
        let result = if enqueue {
            crate::avatar_cortex::xiao_shu_action_request_enqueue(&opts)
        } else {
            crate::avatar_cortex::xiao_shu_action_request(&opts)
        };
        match result {
            Ok(payload) => Ok(ToolResult::json_text(&payload)),
            Err(e) => Ok(ToolResult::error(format!("xiao_shu_action_request: {e}"))),
        }
    }
}

