pub struct PetStateGetTool;
impl PetStateGetTool {
    pub fn new(_hub: Hub) -> Self {
        Self
    }
}

#[async_trait]
impl McpTool for PetStateGetTool {
    fn name(&self) -> &'static str {
        "pet_state_get"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Read the sidecar JSON state for a Codex custom pet. \
                 Use this to inspect the current pet presence state written by \
                 Agent-Bridge hooks without touching the official Codex pet package."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "pet_id": {
                        "type": "string",
                        "default": crate::pet_state::DEFAULT_PET_ID,
                        "description": "Pet id to inspect. Defaults to AB_PET_ID, then the current Codex selected custom avatar, then xiao-shu-v2."
                    }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let pet_id =
            crate::pet_state::normalize_pet_id(args.get("pet_id").and_then(|v| v.as_str()));
        let path = crate::pet_state::pet_state_path(&pet_id);
        match crate::pet_state::read_pet_state(&pet_id) {
            Ok(state) => Ok(ToolResult::json_text(&json!({
                "pet_id": pet_id,
                "path": path.display().to_string(),
                "exists": state.is_some(),
                "state": state,
            }))),
            Err(e) => Ok(ToolResult::error(format!(
                "pet_state_get: failed to read {}: {e}",
                path.display()
            ))),
        }
    }
}

pub struct PetStateSetTool {
    hub: Hub,
}
impl PetStateSetTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

fn pet_state_valid_mode(mode: &str) -> bool {
    matches!(
        mode,
        "idle"
            | "orienting"
            | "working"
            | "reviewing"
            | "waiting_for_user"
            | "failed"
            | "verified"
            | "handoff"
    )
}

fn pet_state_string_or_default(args: &Value, key: &str, default: &str) -> String {
    pet_state_optional_string(args, key)
        .map(str::to_string)
        .unwrap_or_else(|| default.to_string())
}

fn pet_state_optional_string<'a>(args: &'a Value, key: &str) -> Option<&'a str> {
    args.get(key)
        .and_then(|v| v.as_str())
        .map(str::trim)
        .filter(|s| !s.is_empty())
}

fn pet_state_optional_string_or_null(args: &Value, key: &str) -> Value {
    pet_state_optional_string(args, key)
        .map(|s| json!(s))
        .unwrap_or(Value::Null)
}

const PET_STATE_BEHAVIOR_FACET_KEYS: &[&str] = &[
    "activity_state",
    "focus",
    "risk_level",
    "blocked_reason",
    "evidence",
    "next_action",
];

fn pet_state_insert_behavior_facets(state: &mut Value, args: &Value) {
    let Some(state) = state.as_object_mut() else {
        return;
    };
    for key in PET_STATE_BEHAVIOR_FACET_KEYS {
        if let Some(value) = pet_state_optional_string(args, key) {
            state.insert((*key).to_string(), json!(value));
        }
    }
}

fn pet_state_env_u64(env_key: &str) -> Option<u64> {
    std::env::var(env_key)
        .ok()
        .and_then(|v| v.trim().parse::<u64>().ok())
}

fn pet_state_auto_spec_allows(spec: &str, mode: &str) -> bool {
    let mode = mode.to_ascii_lowercase();
    let tokens: Vec<String> = spec
        .split(|c: char| c == ',' || c == ';' || c.is_ascii_whitespace())
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(|s| s.to_ascii_lowercase())
        .collect();
    if tokens
        .iter()
        .any(|t| matches!(t.as_str(), "0" | "false" | "off" | "no" | "none"))
    {
        return false;
    }
    tokens.iter().any(|t| match t.as_str() {
        "1" | "true" | "yes" | "on" | "all" => true,
        "completion" | "complete" | "success" => mode == "verified",
        "wait" | "waiting" | "input" | "input-required" => mode == "waiting_for_user",
        "handoff" | "sessionend" | "session-end" => mode == "handoff",
        other => other == mode,
    })
}

fn pet_state_auto_ritual_enabled(args: &Value, mode: &str) -> bool {
    if let Some(auto) = args.get("auto_ritual").and_then(|v| v.as_bool()) {
        return auto;
    }
    std::env::var("AB_PET_AUTO_TTS")
        .ok()
        .map(|spec| pet_state_auto_spec_allows(&spec, mode))
        .unwrap_or(false)
}

fn pet_state_auto_ritual_args(args: &Value, pet_id: &str) -> Value {
    let channel = pet_state_str_field(args, "ritual_channel")
        .or_else(|| {
            std::env::var("AB_PET_AUTO_TTS_CHANNEL")
                .ok()
                .map(|v| v.trim().to_string())
                .filter(|v| !v.is_empty())
        })
        .filter(|v| matches!(v.as_str(), "tts" | "notification" | "both"))
        .unwrap_or_else(|| "tts".to_string());
    let cooldown_seconds = args
        .get("ritual_cooldown_seconds")
        .and_then(|v| v.as_u64())
        .or_else(|| pet_state_env_u64("AB_PET_AUTO_TTS_COOLDOWN_SECONDS"))
        .unwrap_or(300)
        .min(86_400);
    let force = args
        .get("force_ritual")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    json!({
        "pet_id": pet_id,
        "channel": channel,
        "enabled": true,
        "cooldown_seconds": cooldown_seconds,
        "force": force,
    })
}

fn pet_state_tool_result_json(result: &ToolResult) -> Value {
    match result.content.first() {
        Some(ContentBlock::Text { text }) => {
            serde_json::from_str(text).unwrap_or_else(|_| json!({ "text": text }))
        }
        Some(_) => json!({ "content": result.content }),
        None => Value::Null,
    }
}

#[async_trait]
impl McpTool for PetStateSetTool {
    fn name(&self) -> &'static str {
        "pet_state_set"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Write the sidecar JSON state for a Codex custom pet. \
                 This updates only Agent-Bridge pet presence state; it does not \
                 modify the official Codex pet package, memory DB, or user files."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "pet_id": {
                        "type": "string",
                        "default": crate::pet_state::DEFAULT_PET_ID,
                        "description": "Defaults to AB_PET_ID, then the current Codex selected custom avatar, then xiao-shu-v2."
                    },
                    "mode": {
                        "type": "string",
                        "enum": ["idle", "orienting", "working", "reviewing", "waiting_for_user", "failed", "verified", "handoff"]
                    },
                    "mood": { "type": "string", "default": "calm" },
                    "reason": { "type": "string" },
                    "last_event": { "type": "string", "default": "pet_state_set" },
                    "project": { "type": "string" },
                    "cwd": { "type": "string" },
                    "activity_state": { "type": "string", "description": "Optional fine-grained work posture such as planning, implementing, verifying, or documenting." },
                    "focus": { "type": "string", "description": "Optional compact domain label such as mcp, hooks, voice, presence, docs, or tests." },
                    "risk_level": { "type": "string", "description": "Optional low/medium/high risk hint for UI and presence surfaces." },
                    "blocked_reason": { "type": "string", "description": "Optional compact human-actionable reason when input is needed." },
                    "evidence": { "type": "string", "description": "Optional compact proof string, not a command transcript." },
                    "next_action": { "type": "string", "description": "Optional next local step for presence and read-only panels." },
                    "session_id": { "type": "string" },
                    "voice_line": { "type": "string", "description": "Optional one-line voice cue. Empty means null." },
                    "ritual": { "type": "string", "description": "Optional ritual cue. Empty means null." },
                    "last_verified_at": {
                        "type": "string",
                        "description": "Optional RFC3339 timestamp. Defaults to now when mode=verified, otherwise null."
                    },
                    "auto_ritual": {
                        "type": "boolean",
                        "description": "When true, immediately runs the ritual gate after writing state. If omitted, AB_PET_AUTO_TTS can enable selected modes."
                    },
                    "ritual_channel": {
                        "type": "string",
                        "enum": ["tts", "notification", "both"],
                        "description": "Channel for auto_ritual. Defaults to AB_PET_AUTO_TTS_CHANNEL, then tts."
                    },
                    "ritual_cooldown_seconds": {
                        "type": "integer",
                        "minimum": 0,
                        "maximum": 86400,
                        "description": "Cooldown for auto_ritual. Defaults to AB_PET_AUTO_TTS_COOLDOWN_SECONDS, then 300."
                    },
                    "force_ritual": {
                        "type": "boolean",
                        "default": false,
                        "description": "Bypass duplicate-event and silence-window checks for auto_ritual."
                    }
                },
                "required": ["mode"]
            }),
        }
    }
    async fn execute(&self, args: Value, ctx: &ToolContext) -> Result<ToolResult> {
        let mode = pet_state_string_or_default(&args, "mode", "");
        if !pet_state_valid_mode(&mode) {
            return Ok(ToolResult::error(format!(
                "pet_state_set: invalid mode '{mode}'"
            )));
        }

        let pet_id =
            crate::pet_state::normalize_pet_id(args.get("pet_id").and_then(|v| v.as_str()));
        let cwd = args
            .get("cwd")
            .and_then(|v| v.as_str())
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .map(|s| s.to_string())
            .unwrap_or_else(|| {
                std::env::current_dir()
                    .map(|p| p.display().to_string())
                    .unwrap_or_else(|_| "/".to_string())
            });
        let project_default = std::path::Path::new(&cwd)
            .file_name()
            .and_then(|s| s.to_str())
            .filter(|s| !s.is_empty())
            .unwrap_or(&cwd)
            .to_string();
        let project = pet_state_string_or_default(&args, "project", &project_default);
        let mood = pet_state_string_or_default(&args, "mood", "calm");
        let reason = pet_state_string_or_default(&args, "reason", "manual pet state update");
        let last_event = pet_state_string_or_default(&args, "last_event", "pet_state_set");
        let now = crate::pet_state::now_utc_rfc3339();
        let last_verified_at = args
            .get("last_verified_at")
            .and_then(|v| v.as_str())
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .map(|s| json!(s))
            .unwrap_or_else(|| {
                if mode == "verified" {
                    json!(now.clone())
                } else {
                    Value::Null
                }
            });

        let mut state = json!({
            "schema_version": 1,
            "pet_id": pet_id.clone(),
            "project": project,
            "cwd": cwd,
            "mode": mode,
            "mood": mood,
            "reason": reason,
            "last_event": last_event,
            "last_verified_at": last_verified_at,
            "voice_line": pet_state_optional_string_or_null(&args, "voice_line"),
            "ritual": pet_state_optional_string_or_null(&args, "ritual"),
            "source": "mcp:pet_state_set",
            "session_id": pet_state_optional_string_or_null(&args, "session_id"),
            "updated_at": now,
        });
        pet_state_insert_behavior_facets(&mut state, &args);

        match crate::pet_state::write_pet_state_value(&pet_id, &state) {
            Ok(path) => {
                let auto_ritual = if pet_state_auto_ritual_enabled(&args, &mode) {
                    let ritual_args = pet_state_auto_ritual_args(&args, &pet_id);
                    let result = PetStateRitualTool::new(self.hub.clone())
                        .execute(ritual_args, ctx)
                        .await?;
                    json!({
                        "enabled": true,
                        "is_error": result.is_error,
                        "result": pet_state_tool_result_json(&result),
                    })
                } else {
                    json!({
                        "enabled": false,
                        "reason": "not_requested"
                    })
                };
                Ok(ToolResult::json_text(&json!({
                    "status": "ok",
                    "pet_id": pet_id,
                    "path": path.display().to_string(),
                    "state": state,
                    "auto_ritual": auto_ritual,
                })))
            }
            Err(e) => Ok(ToolResult::error(format!("pet_state_set: {e}"))),
        }
    }
}

pub struct PetStateRitualTool {
    hub: Hub,
}
impl PetStateRitualTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

struct PetRitualDefault {
    line: &'static str,
    ritual: &'static str,
    severity: NotifySeverity,
}

fn pet_state_default_ritual(mode: &str) -> Option<PetRitualDefault> {
    Some(match mode {
        "verified" => PetRitualDefault {
            line: "已验收。",
            ritual: "seal",
            severity: NotifySeverity::Success,
        },
        "failed" => PetRitualDefault {
            line: "这里卡住了，需要看一眼。",
            ritual: "ink_dim",
            severity: NotifySeverity::Error,
        },
        "waiting_for_user" => PetRitualDefault {
            line: "等你拍板。",
            ritual: "lantern",
            severity: NotifySeverity::Attention,
        },
        "handoff" => PetRitualDefault {
            line: "本轮交接已完成。",
            ritual: "handoff",
            severity: NotifySeverity::Success,
        },
        _ => return None,
    })
}

fn pet_state_str_field(value: &Value, key: &str) -> Option<String> {
    value
        .get(key)
        .and_then(|v| v.as_str())
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(ToString::to_string)
}

fn pet_state_bool_or_env(args: &Value, key: &str, env_key: &str) -> bool {
    args.get(key).and_then(|v| v.as_bool()).unwrap_or_else(|| {
        std::env::var(env_key)
            .ok()
            .map(|v| {
                matches!(
                    v.trim().to_ascii_lowercase().as_str(),
                    "1" | "true" | "yes" | "on"
                )
            })
            .unwrap_or(false)
    })
}

fn pet_state_string_or_env(args: &Value, key: &str, env_key: &str) -> Option<String> {
    pet_state_str_field(args, key).or_else(|| {
        std::env::var(env_key)
            .ok()
            .map(|v| v.trim().to_string())
            .filter(|v| !v.is_empty())
    })
}

fn pet_state_tts_rate(args: &Value) -> Option<u64> {
    args.get("tts_rate")
        .and_then(|v| v.as_u64())
        .or_else(|| {
            std::env::var("AB_PET_TTS_RATE")
                .ok()
                .and_then(|v| v.trim().parse::<u64>().ok())
        })
        .map(|rate| rate.clamp(80, 300))
}

fn pet_state_now_unix_secs() -> i64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0)
}

fn pet_state_ritual_event_key(state: &Value, mode: &str) -> String {
    let last_event = pet_state_str_field(state, "last_event").unwrap_or_default();
    let session_id = pet_state_str_field(state, "session_id").unwrap_or_default();
    let cwd = pet_state_str_field(state, "cwd").unwrap_or_default();
    format!("{mode}|{last_event}|{session_id}|{cwd}")
}

#[async_trait]
impl McpTool for PetStateRitualTool {
    fn name(&self) -> &'static str {
        "pet_state_ritual"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Preview or emit a throttled ritual cue for the current Codex pet state. \
                 By default this only previews. Actual notification/TTS requires enabled=true \
                 or AB_PET_RITUAL_ENABLE=1, so hooks stay silent and JSON-safe."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "pet_id": {
                        "type": "string",
                        "default": crate::pet_state::DEFAULT_PET_ID,
                        "description": "Defaults to AB_PET_ID, then the current Codex selected custom avatar, then xiao-shu-v2."
                    },
                    "channel": {
                        "type": "string",
                        "enum": ["preview", "notification", "tts", "both"],
                        "default": "preview"
                    },
                    "enabled": {
                        "type": "boolean",
                        "description": "Required for real notification/TTS unless AB_PET_RITUAL_ENABLE=1."
                    },
                    "force": {
                        "type": "boolean",
                        "default": false,
                        "description": "Bypass duplicate-event and silence-window checks."
                    },
                    "cooldown_seconds": {
                        "type": "integer",
                        "minimum": 0,
                        "maximum": 86400,
                        "default": 300
                    },
                    "voice_line": { "type": "string", "description": "Override the state/default voice line." },
                    "ritual": { "type": "string", "description": "Override the state/default ritual cue." },
                    "tts_voice": {
                        "type": "string",
                        "description": "Optional macOS say voice, for example Tingting. Can also use AB_PET_TTS_VOICE."
                    },
                    "tts_rate": {
                        "type": "integer",
                        "minimum": 80,
                        "maximum": 300,
                        "description": "Optional macOS say words-per-minute rate. Can also use AB_PET_TTS_RATE."
                    }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let pet_id =
            crate::pet_state::normalize_pet_id(args.get("pet_id").and_then(|v| v.as_str()));
        let state_path = crate::pet_state::pet_state_path(&pet_id);
        let state = match crate::pet_state::read_pet_state(&pet_id) {
            Ok(Some(state)) => state,
            Ok(None) => {
                return Ok(ToolResult::error(format!(
                    "pet_state_ritual: no state file at {}",
                    state_path.display()
                )));
            }
            Err(e) => {
                return Ok(ToolResult::error(format!(
                    "pet_state_ritual: failed to read {}: {e}",
                    state_path.display()
                )));
            }
        };

        let mode = pet_state_str_field(&state, "mode").unwrap_or_else(|| "idle".to_string());
        let defaults = match pet_state_default_ritual(&mode) {
            Some(defaults) => defaults,
            None => {
                return Ok(ToolResult::json_text(&json!({
                    "status": "ignored",
                    "emitted": false,
                    "reason": "mode has no ritual cue",
                    "pet_id": pet_id,
                    "mode": mode,
                })));
            }
        };

        let channel = pet_state_string_or_default(&args, "channel", "preview");
        if !matches!(
            channel.as_str(),
            "preview" | "notification" | "tts" | "both"
        ) {
            return Ok(ToolResult::error(format!(
                "pet_state_ritual: invalid channel '{channel}'"
            )));
        }
        let enabled = pet_state_bool_or_env(&args, "enabled", "AB_PET_RITUAL_ENABLE");
        let force = args.get("force").and_then(|v| v.as_bool()).unwrap_or(false);
        let cooldown_seconds = args
            .get("cooldown_seconds")
            .and_then(|v| v.as_u64())
            .unwrap_or(300)
            .min(86_400) as i64;
        let line = pet_state_str_field(&args, "voice_line")
            .or_else(|| pet_state_str_field(&state, "voice_line"))
            .unwrap_or_else(|| defaults.line.to_string());
        let ritual = pet_state_str_field(&args, "ritual")
            .or_else(|| pet_state_str_field(&state, "ritual"))
            .unwrap_or_else(|| defaults.ritual.to_string());
        let tts_voice = pet_state_string_or_env(&args, "tts_voice", "AB_PET_TTS_VOICE");
        let tts_rate = pet_state_tts_rate(&args);
        let event_key = pet_state_ritual_event_key(&state, &mode);
        let now_unix = pet_state_now_unix_secs();
        let now = crate::pet_state::unix_secs_to_utc_rfc3339(now_unix);
        let receipt_path = crate::pet_state::pet_ritual_state_path(&pet_id);
        let last_receipt = crate::pet_state::read_pet_state_path(&receipt_path).unwrap_or(None);
        let duplicate_event = last_receipt
            .as_ref()
            .and_then(|v| v.get("event_key"))
            .and_then(|v| v.as_str())
            .map(|v| v == event_key)
            .unwrap_or(false);
        let in_silence_window = last_receipt
            .as_ref()
            .and_then(|v| v.get("emitted_at_unix"))
            .and_then(|v| v.as_i64())
            .map(|then| {
                cooldown_seconds > 0 && now_unix >= then && now_unix - then < cooldown_seconds
            })
            .unwrap_or(false);

        let blocked_reason = if channel == "preview" {
            Some("preview")
        } else if !enabled {
            Some("not_enabled")
        } else if !force && duplicate_event {
            Some("duplicate_event")
        } else if !force && in_silence_window {
            Some("silence_window")
        } else {
            None
        };
        let should_emit = blocked_reason.is_none();
        let mut notification = Value::Null;
        let mut tts = Value::Null;

        if should_emit && matches!(channel.as_str(), "notification" | "both") {
            let evt = NotifyEvent {
                source: NotifySource::Mcp,
                severity: defaults.severity,
                title: "小舒".into(),
                body: line.clone(),
                session_id: None,
                context: json!({
                    "pet_id": pet_id.clone(),
                    "mode": mode.clone(),
                    "ritual": ritual.clone(),
                    "event_key": event_key.clone(),
                }),
            };
            let (delivered, persisted) = self.hub.deliver(&evt).await;
            notification = json!({
                "delivered": delivered,
                "persisted": persisted,
            });
        }

        if should_emit && matches!(channel.as_str(), "tts" | "both") {
            if cfg!(target_os = "macos") {
                let mut cmd = killable_command("say");
                if let Some(voice) = &tts_voice {
                    cmd.arg("-v").arg(voice);
                }
                if let Some(rate) = tts_rate {
                    cmd.arg("-r").arg(rate.to_string());
                }
                match cmd.arg(&line).status().await {
                    Ok(status) => {
                        tts = json!({
                            "ok": status.success(),
                            "exit_code": status.code(),
                            "voice": tts_voice,
                            "rate": tts_rate,
                        });
                    }
                    Err(e) => {
                        tts = json!({
                            "ok": false,
                            "error": e.to_string(),
                            "voice": tts_voice,
                            "rate": tts_rate,
                        });
                    }
                }
            } else {
                tts = json!({
                    "ok": false,
                    "error": "tts channel currently supports macOS 'say' only",
                });
            }
        }

        if should_emit {
            let receipt = json!({
                "schema_version": 1,
                "pet_id": pet_id.clone(),
                "mode": mode.clone(),
                "line": line.clone(),
                "ritual": ritual.clone(),
                "channel": channel.clone(),
                "event_key": event_key.clone(),
                "tts_voice": tts_voice,
                "tts_rate": tts_rate,
                "source": "pet_state_ritual",
                "emitted_at": now,
                "emitted_at_unix": now_unix,
            });
            if let Err(e) = crate::pet_state::write_pet_state_path(&receipt_path, &receipt) {
                return Ok(ToolResult::error(format!(
                    "pet_state_ritual: failed to write {}: {e}",
                    receipt_path.display()
                )));
            }
        }

        Ok(ToolResult::json_text(&json!({
            "status": if should_emit { "emitted" } else { "skipped" },
            "emitted": should_emit,
            "blocked_reason": blocked_reason,
            "pet_id": pet_id,
            "mode": mode,
            "line": line,
            "ritual": ritual,
            "channel": channel,
            "tts_voice": tts_voice,
            "tts_rate": tts_rate,
            "enabled": enabled,
            "force": force,
            "cooldown_seconds": cooldown_seconds,
            "duplicate_event": duplicate_event,
            "in_silence_window": in_silence_window,
            "event_key": event_key,
            "receipt_path": receipt_path.display().to_string(),
            "notification": notification,
            "tts": tts,
        })))
    }
}

// ===========================================================================
//                              hook_status
// ===========================================================================

pub struct HookStatusTool;
impl HookStatusTool {
    pub fn new(_hub: Hub) -> Self {
        Self
    }
}

/// Path of the hook run log file.
fn hook_run_log_path() -> PathBuf {
    agent_bridge_state_dir().join("hook-runs.jsonl")
}

fn dirs_home() -> PathBuf {
    std::env::var("HOME")
        .map(PathBuf::from)
        .unwrap_or_else(|_| PathBuf::from("/tmp"))
}

fn agent_bridge_state_dir() -> PathBuf {
    if let Ok(xdg) = std::env::var("XDG_DATA_HOME") {
        return PathBuf::from(xdg).join("agent-bridge");
    }
    let home = dirs_home();
    if cfg!(target_os = "macos") {
        return home
            .join("Library")
            .join("Application Support")
            .join("agent-bridge");
    }
    home.join(".local").join("share").join("agent-bridge")
}

/// Parse the most recent hook run entry from the JSONL log for a given event name.
fn last_hook_run(event: &str, log_path: &std::path::Path) -> Option<Value> {
    let content = std::fs::read_to_string(log_path).ok()?;
    content
        .lines()
        .rev()
        .filter_map(|line| serde_json::from_str::<Value>(line).ok())
        .find(|v| v.get("event").and_then(|e| e.as_str()) == Some(event))
}

/// Well-known hook configurations: (event_name, default_script_path)
fn known_hooks() -> Vec<(&'static str, &'static str)> {
    let home = dirs_home();
    // We build static paths at this point; ownership of the string is managed below
    // by converting to owned — but since we need &'static str we embed them literally.
    // Instead, use a Vec<(String, String)> and convert.
    let _ = home; // suppress warning
    vec![
        ("beforeSubmitPrompt", "ab-memory-hook"),
        ("preCompact", "ab-precompact-hook"),
        ("sessionEndCurate", "ab-precompact-hook"),
        ("stop", "ab-session-end-hook"),
        ("sessionEnd", "ab-session-end-hook"),
    ]
}

/// Source script paths inside the agent-bridge repo hooks dir.
fn hook_source_paths() -> HashMap<&'static str, &'static str> {
    let mut m = HashMap::new();
    m.insert("beforeSubmitPrompt", "ab-memory-hook.sh");
    m.insert("preCompact", "ab-precompact-hook.sh");
    m.insert("sessionEndCurate", "ab-precompact-hook.sh");
    m.insert("stop", "ab-session-end-hook.sh");
    m.insert("sessionEnd", "ab-session-end-hook.sh");
    m
}

fn sha256_file(path: &std::path::Path) -> Option<String> {
    use std::io::Read;
    let mut f = std::fs::File::open(path).ok()?;
    let mut buf = Vec::new();
    f.read_to_end(&mut buf).ok()?;
    // Simple FNV-1a 64-bit hash as a lightweight alternative to sha256
    // (avoids pulling in sha2 crate; sufficient for change detection)
    let mut hash: u64 = 14695981039346656037;
    for byte in &buf {
        hash ^= *byte as u64;
        hash = hash.wrapping_mul(1099511628211);
    }
    Some(format!("{hash:016x}"))
}

#[async_trait]
impl McpTool for HookStatusTool {
    fn name(&self) -> &'static str {
        "hook_status"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Return the status of each agent-bridge hook script: existence, \
                 executability, last run time, exit code, output bytes, and whether \
                 the installed script is in sync with the repo source. \
                 Use this to diagnose hook configuration problems."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "repo_hooks_dir": {
                        "type": "string",
                        "description": "Optional path to the agent-bridge repo hooks dir for sync check. Defaults to auto-detect."
                    }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let home = dirs_home();
        let bin_dir = home.join(".local").join("bin");
        let log_path = hook_run_log_path();
        let source_names = hook_source_paths();

        // Find repo hooks dir: explicit arg > detect from binary symlink > CARGO_MANIFEST_DIR
        let repo_hooks_dir: Option<PathBuf> = args
            .get("repo_hooks_dir")
            .and_then(|v| v.as_str())
            .map(PathBuf::from)
            .or_else(|| {
                // Try to resolve symlink of the agent-bridge binary
                let bin = bin_dir.join("agent-bridge");
                std::fs::read_link(&bin)
                    .ok()
                    .and_then(|target| target.parent().map(|p| p.to_path_buf()))
                    .and_then(|dir| {
                        // Walk up to find crates/bridge/src/hooks
                        let mut d = dir.clone();
                        for _ in 0..6 {
                            let candidate =
                                d.join("crates").join("bridge").join("src").join("hooks");
                            if candidate.is_dir() {
                                return Some(candidate);
                            }
                            if !d.pop() {
                                break;
                            }
                        }
                        None
                    })
            });

        let hooks = known_hooks();
        let mut hook_statuses: Vec<Value> = Vec::new();

        for (event, script_basename) in &hooks {
            let installed_path = bin_dir.join(script_basename);
            let exists = installed_path.exists();
            let executable = exists && {
                use std::os::unix::fs::PermissionsExt;
                std::fs::metadata(&installed_path)
                    .map(|m| m.permissions().mode() & 0o111 != 0)
                    .unwrap_or(false)
            };

            let last_run = last_hook_run(event, &log_path);
            let last_run_ts = last_run
                .as_ref()
                .and_then(|v| v.get("ts"))
                .cloned()
                .unwrap_or(Value::Null);
            let last_exit_code = last_run
                .as_ref()
                .and_then(|v| v.get("exit_code"))
                .cloned()
                .unwrap_or(Value::Null);
            let last_output_bytes = last_run
                .as_ref()
                .and_then(|v| v.get("output_bytes"))
                .cloned()
                .unwrap_or(Value::Null);

            // Sync check
            let sync_info = if let Some(ref hooks_dir) = repo_hooks_dir {
                let source_name = source_names.get(*event).copied().unwrap_or("");
                let source_path = hooks_dir.join(source_name);
                let installed_hash = sha256_file(&installed_path);
                let source_hash = sha256_file(&source_path);
                let in_sync = installed_hash.is_some()
                    && source_hash.is_some()
                    && installed_hash == source_hash;
                json!({
                    "installed_hash": installed_hash,
                    "source_hash": source_hash,
                    "source_path": source_path.display().to_string(),
                    "in_sync": in_sync
                })
            } else {
                json!({ "in_sync": null, "note": "provide repo_hooks_dir for sync check" })
            };

            hook_statuses.push(json!({
                "event": event,
                "script": installed_path.display().to_string(),
                "exists": exists,
                "executable": executable,
                "last_run_ts": last_run_ts,
                "last_exit_code": last_exit_code,
                "last_output_bytes": last_output_bytes,
                "sync": sync_info
            }));
        }

        Ok(ToolResult::json_text(&json!({
            "hooks": hook_statuses,
            "log_path": log_path.display().to_string(),
            "log_exists": log_path.exists()
        })))
    }
}

// ===========================================================================
//                       mcp_recent_errors (Phase C)
// ===========================================================================

pub struct McpRecentErrorsTool {
    hub: Hub,
}
impl McpRecentErrorsTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

#[async_trait]
impl McpTool for McpRecentErrorsTool {
    fn name(&self) -> &'static str {
        "mcp_recent_errors"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Return recent MCP tools/call failures persisted in the state DB \
                 (newest first, ring buffer). Use to debug flaky tools or client integration \
                 after `isError` responses or tool panics."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "limit": {
                        "type": "integer",
                        "description": "Max rows to return (1–500). Default 20."
                    }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let limit = args
            .get("limit")
            .and_then(|v| v.as_u64())
            .unwrap_or(20)
            .clamp(1, 500) as u32;
        match store.recent_mcp_tool_errors(limit).await {
            Ok(rows) => {
                let n = rows.len();
                let cap = ab_store::MCP_TOOL_ERROR_RING_CAP;
                Ok(ToolResult::json_text(&json!({
                    "errors": rows,
                    "returned": n,
                    "ring_cap": cap,
                })))
            }
            Err(e) => Ok(ToolResult::error(format!("store: {e}"))),
        }
    }
}

