async fn mobile_capabilities_json(policy: ToolPolicy) -> Value {
    let exposed: Vec<String> = build_registry_with_policy(Hub::builder().build(), policy)
        .list()
        .into_iter()
        .map(|s| s.name)
        .filter(|n| n.starts_with("mobile_"))
        .collect();
    let adb_on_path = which_binary("adb");
    let devices = if adb_on_path {
        match mobile_online_devices(3_000).await {
            Ok(list) => json!({
                "ok": true,
                "online_count": list.len(),
                "serials": list.iter().map(|d| &d.serial).collect::<Vec<_>>(),
            }),
            Err(e) => json!({ "ok": false, "error": e }),
        }
    } else {
        json!({ "ok": false, "error": "adb not on PATH" })
    };
    json!({
        "backend": "adb",
        "adb_on_path": adb_on_path,
        "exposed_tools": exposed,
        "default_serial": devices
            .get("serials")
            .and_then(|v| v.as_array())
            .and_then(|a| a.first())
            .and_then(|v| v.as_str()),
        "devices": devices,
        "security_note": "mobile_install_apk and other write tools respect AB_ALLOW_* policy via capabilities.security"
    })
}

fn compact_instinct_observer_status_json(mut status: Value, include_sessions: bool) -> Value {
    if include_sessions {
        return status;
    }
    let Some(obj) = status.as_object_mut() else {
        return status;
    };
    let omitted = obj
        .remove("per_session")
        .and_then(|v| v.as_object().map(|o| o.len()))
        .unwrap_or(0);
    if omitted > 0 {
        obj.insert("per_session_omitted".to_string(), json!(true));
        obj.insert("per_session_count".to_string(), json!(omitted));
        obj.insert(
            "detail_hint".to_string(),
            json!(
                "pass include_instinct_sessions:true or compact:false to include per-session diagnostics"
            ),
        );
    }
    status
}

