// ===========================================================================
//          memory_link_orphans (ζ-7 — clear orphan backlog)
// ===========================================================================

/// ζ-7 — Find non-skill active memories with **zero** edges (orphans),
/// score candidates via `compute_link_suggestions`, auto-link the top
/// match per orphan when confidence ≥ threshold. Symmetric to
/// `memory_prune_coactivation_noise` in spirit: a one-shot graph-hygiene
/// pass. Pair with proactive `memory_save` -> `memory_link` habits.
pub struct MemoryLinkOrphansTool {
    hub: Hub,
}
impl MemoryLinkOrphansTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for MemoryLinkOrphansTool {
    fn name(&self) -> &'static str {
        "memory_link_orphans"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Find non-skill active memories with zero edges (orphans). \
                For each, run `compute_link_suggestions` over all memories and, \
                when the top candidate scores >= threshold, write a `relates` \
                edge. Returns {examined, eligible, linked, skipped_low_score, \
                links}. dry_run=true previews without writing. Idempotent: \
                anything already linked is excluded from the orphan set."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "threshold": {
                        "type": "number",
                        "minimum": 0.0,
                        "maximum": 2.0,
                        "default": 0.85,
                        "description": "Top candidate must score ≥ this to auto-link. \
                            Default 0.85 is conservative after the 2026-05-23 PageRank-readiness \
                            dry-run showed 0.7 would link too many volatile alert/work-memory \
                            clusters. Lower for higher recall, raise for higher precision."
                    },
                    "min_content_len": {
                        "type": "integer",
                        "minimum": 0,
                        "default": 50,
                        "description": "Skip orphans whose content is shorter than this many \
                            bytes. Default 50 — `curated_implicit_*` 44-byte stubs are signal-poor \
                            and rarely have meaningful suggestions; let them age out instead."
                    },
                    "max_orphans": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": 500,
                        "default": 100,
                        "description": "Cap on orphans examined per run."
                    },
                    "skip_tags": {
                        "type": "array",
                        "items": { "type": "string" },
                        "default": ["auto_curated", "alert", "ttl:7d"],
                        "description": "ζ-11 noise-hub fix. Orphans whose tags overlap this list \
                            are skipped (don't pick a target) AND candidates whose tags overlap \
                            this list cannot be picked as targets. Defaults skip auto-curated \
                            stubs, alert bursts, and short-lived work-memory TTL rows before \
                            graph centrality can amplify them."
                    },
                    "skip_kinds": {
                        "type": "array",
                        "items": { "type": "string" },
                        "default": ["alert", "work_memory", "session_handoff", "snapshot"],
                        "description": "ζ-20 conservative graph-hygiene guardrail. Source \
                            orphans and candidate targets with these memory kinds are skipped. \
                            Empty array disables. Defaults avoid linking volatile alerts, \
                            scratch work memory, broad session handoffs, and snapshots."
                    },
                    "require_scope_compatible": {
                        "type": "boolean",
                        "default": true,
                        "description": "When true, candidates with a concrete non-global scope \
                            must match the orphan's concrete non-global scope. Global or missing \
                            scopes remain compatible so older memories still participate."
                    },
                    "scope": {
                        "type": "string",
                        "description": "Optional source-orphan scope filter, e.g. project:/abs/path or domain:rust. \
                            Use this before live runs to avoid broad cross-project graph hygiene."
                    },
                    "scope_mode": {
                        "type": "string",
                        "enum": ["local_only", "local_plus_global", "exploratory"],
                        "default": "local_only",
                        "description": "When scope is set: local_only scans only matching source orphans; \
                            local_plus_global also scans global/unscoped source orphans; exploratory scans \
                            all source orphans. Candidate compatibility still follows require_scope_compatible."
                    },
                    "dedupe_undirected_pairs": {
                        "type": "boolean",
                        "default": true,
                        "description": "When true, avoid writing both A→B and B→A `relates` \
                            edges in the same run. `relates` is treated as symmetric for \
                            hygiene purposes."
                    },
                    "max_inbound_per_target": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": 50,
                        "default": 5,
                        "description": "ζ-11 defense-in-depth. Within a single run, no target \
                            receives more than this many new inbound `relates` edges. If the \
                            top-1 candidate is already at cap, the tool falls back to the next \
                            of up to 5 alternatives before giving up on the orphan."
                    },
                    "dry_run": { "type": "boolean", "default": false }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let threshold = args
            .get("threshold")
            .and_then(|v| v.as_f64())
            .unwrap_or(0.85);
        let min_content_len = args
            .get("min_content_len")
            .and_then(|v| v.as_u64())
            .unwrap_or(50) as usize;
        let max_orphans = args
            .get("max_orphans")
            .and_then(|v| v.as_u64())
            .unwrap_or(100)
            .min(500) as usize;
        // ζ-20 defaults: keep volatile rows out of durable graph hygiene so
        // later PageRank-like priors do not amplify alert/scratch clusters.
        // Empty arrays intentionally disable the corresponding filters.
        let skip_tags =
            memory_string_array_arg(&args, "skip_tags", &["auto_curated", "alert", "ttl:7d"]);
        let skip_kinds = memory_string_array_arg(
            &args,
            "skip_kinds",
            &["alert", "work_memory", "session_handoff", "snapshot"],
        );
        let require_scope_compatible = args
            .get("require_scope_compatible")
            .and_then(|v| v.as_bool())
            .unwrap_or(true);
        let requested_scope = args
            .get("scope")
            .and_then(|v| v.as_str())
            .map(str::trim)
            .filter(|s| !s.is_empty());
        let scope_mode = MemorySearchScopeMode::parse(
            args.get("scope_mode")
                .and_then(|v| v.as_str())
                .map(str::trim)
                .filter(|s| !s.is_empty()),
            false,
        );
        let dedupe_undirected_pairs = args
            .get("dedupe_undirected_pairs")
            .and_then(|v| v.as_bool())
            .unwrap_or(true);
        let max_inbound_per_target = args
            .get("max_inbound_per_target")
            .and_then(|v| v.as_u64())
            .unwrap_or(5)
            .clamp(1, 50) as u32;
        let dry_run = args
            .get("dry_run")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);

        // Single store pass: load all active memories (capped to 1000 — generous
        // for the orphan corpus, scoring is in-memory O(n) per orphan).
        let all = store
            .list_memories(None, MemoryListSort::Recent, 1000)
            .await
            .unwrap_or_default();

        // Identify orphans: non-skill, active, ≥ min_content_len, zero edges.
        // For each candidate we batch-check via memory_neighbors. Loop is N
        // small (typically <200) so cheap enough; could be one SQL pass if
        // we ever need to scale.
        let mut orphans: Vec<MemoryRecord> = Vec::new();
        let mut examined: u64 = 0;
        let mut skipped_blacklisted_orphan: u64 = 0;
        let mut skipped_blacklisted_kind: u64 = 0;
        for rec in all.iter() {
            if rec.kind == "skill" {
                continue;
            }
            if rec.status != "active" && !rec.status.is_empty() {
                continue;
            }
            if rec.content.len() < min_content_len {
                continue;
            }
            if let Some(scope) = requested_scope {
                if !memory_search_scope_mode_matches(rec, scope, scope_mode) {
                    continue;
                }
            }
            examined += 1;
            let nbrs = store.memory_neighbors(&rec.key).await.unwrap_or_default();
            if !nbrs.is_empty() {
                continue;
            }
            // ζ-11 source-side blacklist: stubs tagged `auto_curated` should
            // decay/archive naturally, not get force-linked.
            if memory_has_any_tag(rec, &skip_tags) {
                skipped_blacklisted_orphan += 1;
                continue;
            }
            if memory_kind_is_any(rec, &skip_kinds) {
                skipped_blacklisted_kind += 1;
                continue;
            }
            orphans.push(rec.clone());
            if orphans.len() >= max_orphans {
                break;
            }
        }

        // For each orphan, score against the full corpus and pick the first
        // viable target. ζ-11: ask for top-5 alternatives so that if the
        // top-1 hit the per-target inbound cap we can fall back gracefully.
        let mut linked = 0u64;
        let mut skipped_low_score = 0u64;
        let mut skipped_overloaded_target = 0u64;
        let mut skipped_duplicate_pair = 0u64;
        let mut skipped_no_compatible_target = 0u64;
        let mut target_inbound_this_run: std::collections::HashMap<String, u32> =
            std::collections::HashMap::new();
        let mut linked_pairs_this_run: std::collections::HashSet<(String, String)> =
            std::collections::HashSet::new();
        let mut decisions: Vec<Value> = Vec::new();
        for orphan in &orphans {
            // already_linked is empty since orphan has no edges by definition.
            let already_linked: std::collections::HashSet<String> =
                std::collections::HashSet::new();
            let candidate_pool: Vec<MemoryRecord> = all
                .iter()
                .filter(|candidate| {
                    memory_link_orphan_candidate_allowed(
                        orphan,
                        candidate,
                        &skip_tags,
                        &skip_kinds,
                        require_scope_compatible,
                    )
                })
                .cloned()
                .collect();
            let sugg =
                compute_link_suggestions(orphan, &candidate_pool, &already_linked, 5, &skip_tags);
            if sugg.is_empty() {
                skipped_low_score += 1;
                continue;
            }
            let top_conf = sugg.first().map(|s| s.1).unwrap_or(0.0);
            if top_conf < threshold {
                skipped_low_score += 1;
                continue;
            }
            // Walk candidates in confidence order; pick the first that
            // still has headroom under the per-target inbound cap.
            let mut chosen: Option<(String, f64, String)> = None;
            let mut saw_overloaded_target = false;
            let mut saw_duplicate_pair = false;
            for (target, conf, reason) in sugg.iter() {
                if *conf < threshold {
                    break;
                }
                if target == &orphan.key {
                    continue;
                }
                let pair = undirected_memory_pair_key(&orphan.key, target);
                if dedupe_undirected_pairs && linked_pairs_this_run.contains(&pair) {
                    saw_duplicate_pair = true;
                    skipped_duplicate_pair += 1;
                    continue;
                }
                let cur = target_inbound_this_run.get(target).copied().unwrap_or(0);
                if cur >= max_inbound_per_target {
                    saw_overloaded_target = true;
                    continue;
                }
                chosen = Some((target.clone(), *conf, reason.clone()));
                break;
            }
            let Some((target, conf, reason)) = chosen else {
                if saw_overloaded_target {
                    skipped_overloaded_target += 1;
                } else if !saw_duplicate_pair {
                    skipped_no_compatible_target += 1;
                }
                continue;
            };
            if !dry_run {
                store
                    .memory_link(&orphan.key, &target, "relates", 1.0)
                    .await
                    .ok();
            }
            if dedupe_undirected_pairs {
                linked_pairs_this_run.insert(undirected_memory_pair_key(&orphan.key, &target));
            }
            *target_inbound_this_run.entry(target.clone()).or_insert(0) += 1;
            linked += 1;
            decisions.push(json!({
                "orphan": orphan.key,
                "target": target,
                "confidence": conf,
                "reason": reason,
            }));
        }

        Ok(ToolResult::json_text(&json!({
            "dry_run": dry_run,
            "threshold": threshold,
            "min_content_len": min_content_len,
            "skip_tags": skip_tags,
            "skip_kinds": skip_kinds,
            "require_scope_compatible": require_scope_compatible,
            "scope": requested_scope,
            "scope_mode": scope_mode.label(),
            "dedupe_undirected_pairs": dedupe_undirected_pairs,
            "max_inbound_per_target": max_inbound_per_target,
            "examined": examined,
            "eligible_orphans": orphans.len(),
            "linked": linked,
            "skipped_low_score": skipped_low_score,
            "skipped_blacklisted_orphan": skipped_blacklisted_orphan,
            "skipped_blacklisted_kind": skipped_blacklisted_kind,
            "skipped_overloaded_target": skipped_overloaded_target,
            "skipped_duplicate_pair": skipped_duplicate_pair,
            "skipped_no_compatible_target": skipped_no_compatible_target,
            "links": decisions,
        })))
    }
}

pub struct SessionFinalizeTool {
    hub: Hub,
}
impl SessionFinalizeTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for SessionFinalizeTool {
    fn name(&self) -> &'static str {
        "session_finalize"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Manual session-end maintenance: importance decay, compact stale \
                 memories, optionally export JSONL. Equivalent to Claude Code's Stop hook \
                 pipeline. Response includes follow_up with active_total and a hint to run \
                 memory_consolidate if the graph is large."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "older_than_days": { "type": "integer", "minimum": 1, "default": 90 },
                    "min_uses": { "type": "integer", "minimum": 0 },
                    "dry_run": { "type": "boolean", "default": false },
                    "decay_half_life_days": {
                        "type": "number", "minimum": 1.0, "default": 30.0,
                        "description": "Importance half-life in days. Default 30 = importance halves every month."
                    },
                    "decay_archive_threshold": {
                        "type": "number", "minimum": 0.0, "maximum": 1.0, "default": 0.05,
                        "description": "Memories with decayed importance below this are marked archived."
                    },
                    "skip_decay": {
                        "type": "boolean", "default": false,
                        "description": "If true, skip the importance decay pass (compact still runs)."
                    },
                    "export_path": { "type": "string", "description": "Optional JSONL export output path." },
                    "user_profile": {
                        "type": "string",
                        "description": "Markdown text describing the user (name, role, expertise, preferences, focus). \
                            Written to ~/.local/share/agent-bridge/USER.md and injected into \
                            future session_bootstrap calls. Synthesize from the current session before calling."
                    },
                    "agent_profile": {
                        "type": "string",
                        "description": "Markdown text describing the AGENT's own values, working style, and \
                            self-observations on this project. Written to ~/.local/share/agent-bridge/AGENT.md \
                            and injected as `Agent Self-Profile` block in future session_bootstrap calls. \
                            Maintained by the agent itself for cross-session identity continuity. \
                            Long-term destination: AiOT Seed `SelfModel` initialization (see memory \
                            decision_aiot_seed_as_agent_continuity_substrate_20260503). \
                            **Drift cap**: writes that change > 50% of line-set (Jaccard distance) \
                            are rejected unless `agent_profile_force=true`. Borrowed from AiOT \
                            identity_anchor.py MAX_STEP_DRIFT — stable identity should not be \
                            rewritable in one shot."
                    },
                    "agent_profile_force": {
                        "type": "boolean",
                        "default": false,
                        "description": "Bypass the 50% drift cap on AGENT.md. Use only when intentionally \
                            doing a large rewrite (e.g. project migration, major reframing). The response \
                            always reports `agent_profile_diff_ratio` so the caller can decide afterwards \
                            whether the change was as expected."
                    },
                    "letter": {
                        "type": "string",
                        "description": "Letter-to-future-self: a momentary snapshot of what the agent was thinking, \
                            working toward, or wanting future-self to know. Written append-only to \
                            ~/.local/share/agent-bridge/letters/letter_<unix_ts>.md. The 3 most recent letters \
                            are auto-injected into future session_bootstrap calls between AGENT.md and memory rows. \
                            Use for: state-at-time-of-writing, anticipations, hopes, warnings to future-self. \
                            Distinct from AGENT.md (stable identity) and session_handoff (factual progress log). \
                            Suggested 3-section structure: State / Direction / Notes-to-future-me."
                    },
                    "apply_outcome_gated": {
                        "type": "boolean",
                        "default": false,
                        "description": "Opt-in (Stage 5b): after maintenance, delegate to the Stage 5 \
                            outcome_gated_consolidation_apply WRITE executor using the supplied \
                            approval_packet + owner refs. Default false ⇒ the gated path is NOT \
                            invoked and behavior is unchanged. When true, the executor enforces ALL \
                            of its own gates (AB_OUTCOME_GATED_CONSOLIDATION on + operator not \
                            disabled + per_call_opt_in + anchor; approval_packet approved + \
                            apply_token reproduced from refs; live diff_hash match; confirm_apply). \
                            If this finalize call is dry_run, the sub-call is forced to preview (no \
                            writes). The delegation runs BEFORE this call's own decay/compact \
                            maintenance, so those passes never self-invalidate a just-approved plan \
                            (external drift since approval is still caught by the live diff_hash gate). \
                            Any Stage 5 scoping args present (scope, scope_mode, skip_tags, \
                            skip_kinds, min_similarity, …) are forwarded and MUST match the trial \
                            that produced the approval, or the diff_hash check fails closed. The full \
                            executor result is returned under `outcome_gated_consolidation`."
                    },
                    "approval_packet": {
                        "type": "object",
                        "description": "Stage 4 outcome_gated_consolidation_approval_packet (status=approved). \
                            Required when apply_outcome_gated=true; ignored otherwise."
                    },
                    "reviewer": { "type": "string", "description": "Owner ref forwarded to the Stage 5 executor (apply_outcome_gated=true): the same approving reviewer used at Stage 4, re-supplied so the executor reproduces apply_token." },
                    "commit": { "type": "string", "description": "Owner ref forwarded to the Stage 5 executor (apply_outcome_gated=true)." },
                    "forum_post_id": { "type": "string", "description": "Owner ref forwarded to the Stage 5 executor (apply_outcome_gated=true)." },
                    "memory_key": { "type": "string", "description": "Owner ref forwarded to the Stage 5 executor (apply_outcome_gated=true)." },
                    "regression_anchor": { "type": "string", "description": "Must equal the current outcome-gated anchor; forwarded to the Stage 5 executor (apply_outcome_gated=true)." },
                    "per_call_opt_in": { "type": "boolean", "default": false, "description": "Per-call opt-in forwarded to the Stage 5 executor (apply_outcome_gated=true)." },
                    "confirm_apply": { "type": "boolean", "default": false, "description": "Final write confirmation forwarded to the Stage 5 executor. Default false ⇒ verified preview, no writes. Forced false when this finalize call is dry_run." }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let older_than_days = args
            .get("older_than_days")
            .and_then(|v| v.as_i64())
            .unwrap_or(90);
        let min_uses = args.get("min_uses").and_then(|v| v.as_u64());
        let dry_run = args
            .get("dry_run")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let half_life = args
            .get("decay_half_life_days")
            .and_then(|v| v.as_f64())
            .unwrap_or(30.0)
            .max(1.0);
        let archive_threshold = args
            .get("decay_archive_threshold")
            .and_then(|v| v.as_f64())
            .unwrap_or(0.05)
            .clamp(0.0, 1.0);
        let skip_decay = args
            .get("skip_decay")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);

        // Stage 5b: optional delegation to the Stage 5 outcome-gated WRITE
        // executor. Runs BEFORE the decay/compact maintenance passes below, on
        // purpose: a freshly-approved consolidation plan is then evaluated against
        // the same pre-maintenance store the operator approved against, so
        // finalize's OWN decay (which mutates importance → consolidate rank) and
        // compact (which can tombstone a plan participant) can never
        // self-invalidate the approval's frozen diff_hash within this one call.
        // (External drift since approval is still caught by the executor's live
        // diff_hash gate → blocked_diff_hash_stale.) Housekeeping then runs on the
        // post-apply result. Default-OFF: when apply_outcome_gated is absent/false
        // this is a no-op and the response is byte-identical (the
        // `outcome_gated_consolidation` key is omitted). When true, session_finalize
        // adds NOTHING of its own — it forwards args to the executor, which
        // independently enforces ALL of its gates (runtime env, approval-packet
        // validity + apply_token reproduction, live diff_hash match, confirm_apply).
        // A dry_run finalize forces the sub-call to preview, so finalize(dry_run)
        // never mutates memory.
        let apply_outcome_gated = args
            .get("apply_outcome_gated")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let outcome_gated_consolidation = if apply_outcome_gated {
            let mut sub_args = args.clone();
            if dry_run {
                sub_args["confirm_apply"] = json!(false);
            }
            let apply_tool = OutcomeGatedConsolidationApplyTool::new(self.hub.clone());
            match apply_tool.execute(sub_args, _ctx).await {
                Ok(res) => tool_result_first_json(&res).unwrap_or(Value::Null),
                Err(e) => json!({ "error": e.to_string() }),
            }
        } else {
            Value::Null
        };

        // 1. Importance decay pass (unless skipped or dry_run)
        let decay_archived = if skip_decay || dry_run {
            0u64
        } else {
            store
                .memory_decay_importance(half_life, archive_threshold)
                .await
                .unwrap_or(0)
        };

        // 2. Compact stale memories
        let policy = CompactPolicy {
            min_uses,
            older_than_secs: Some(older_than_days * 86_400),
            dry_run,
        };
        let removed = store.memory_compact(policy).await?;

        // 3. Optional export
        let mut export_summary = Value::Null;
        if let Some(path) = args.get("export_path").and_then(|v| v.as_str()) {
            let filter = MemoryExportFilter::default();
            let exported = store.memory_export(&filter, &PathBuf::from(path)).await?;
            export_summary = json!({
                "path": path,
                "exported": exported.memories_written,
                "memories_written": exported.memories_written,
                "edges_written": exported.edges_written,
            });
        }

        // After compaction/decay, nudge operators toward periodic dedup when the graph grows.
        const CONSOLIDATE_HINT_ACTIVE_THRESHOLD: u64 = 60;
        let follow_up = match store.memory_stats().await {
            Ok(st) => {
                let active_total = st.counts_by_status.get("active").copied().unwrap_or(0);
                let suggest = active_total >= CONSOLIDATE_HINT_ACTIVE_THRESHOLD;
                let hint = if suggest {
                    json!(format!(
                        "Active memories {} ≥ {} — preview merges with memory_consolidate(dry_run:true, min_similarity:0.45, max_pairs:10).",
                        active_total, CONSOLIDATE_HINT_ACTIVE_THRESHOLD
                    ))
                } else {
                    Value::Null
                };
                // Read-only Stage 5b pointer (no writes here): when the graph is
                // large enough to suggest consolidation, also surface that an
                // outcome-gated WRITE path exists. It is default-OFF and only
                // reachable via the full Stage 3→4→5 trial/approval/apply ladder,
                // or by re-calling session_finalize with apply_outcome_gated=true
                // plus an approved approval_packet. Null when not suggesting.
                let outcome_gated_apply = if suggest {
                    json!(
                        "An outcome-gated apply path exists (default-OFF): run the Stage 3→4 \
                         trial+approval, then session_finalize(apply_outcome_gated:true, \
                         approval_packet:…, confirm_apply:true) or outcome_gated_consolidation_apply. \
                         Requires AB_OUTCOME_GATED_CONSOLIDATION + per_call_opt_in + a reproduced apply_token."
                    )
                } else {
                    Value::Null
                };
                json!({
                    "active_total": active_total,
                    "edge_count": st.edge_count,
                    "suggest_memory_consolidate": suggest,
                    "hint": hint,
                    "outcome_gated_apply": outcome_gated_apply,
                })
            }
            Err(_) => json!({
                "active_total": Value::Null,
                "edge_count": Value::Null,
                "suggest_memory_consolidate": false,
                "hint": Value::Null,
                "outcome_gated_apply": Value::Null,
            }),
        };

        // Optional: persist user profile to USER.md for future session_bootstrap.
        let user_profile_written =
            if let Some(profile) = args.get("user_profile").and_then(|v| v.as_str()) {
                if !profile.trim().is_empty() && !dry_run {
                    let path = user_profile_path();
                    if let Some(parent) = path.parent() {
                        let _ = std::fs::create_dir_all(parent);
                    }
                    std::fs::write(&path, profile.as_bytes()).is_ok()
                } else {
                    false
                }
            } else {
                false
            };

        // Optional: persist agent self-profile to AGENT.md, with drift cap.
        // Returns (written: bool, diff_ratio: f32, capped: bool, reason: Option<String>).
        let force_profile = args
            .get("agent_profile_force")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let (
            agent_profile_written,
            agent_profile_diff_ratio_v,
            agent_profile_capped,
            agent_profile_reason,
        ) = if let Some(profile) = args.get("agent_profile").and_then(|v| v.as_str()) {
            if profile.trim().is_empty() {
                (false, 0.0_f32, false, None)
            } else {
                let path = agent_profile_path();
                let old = std::fs::read_to_string(&path).unwrap_or_default();
                let ratio = agent_profile_diff_ratio(&old, profile);
                let exceeds = ratio > AGENT_PROFILE_DRIFT_CAP;
                if exceeds && !force_profile && !old.trim().is_empty() {
                    // Reject — would rewrite > 50% of identity. Caller can retry
                    // with agent_profile_force=true if intentional.
                    (
                        false,
                        ratio,
                        true,
                        Some(format!(
                            "drift {:.1}% > cap {:.0}%; pass agent_profile_force=true to override",
                            ratio * 100.0,
                            AGENT_PROFILE_DRIFT_CAP * 100.0
                        )),
                    )
                } else if dry_run {
                    (false, ratio, false, None)
                } else {
                    if let Some(parent) = path.parent() {
                        let _ = std::fs::create_dir_all(parent);
                    }
                    let ok = std::fs::write(&path, profile.as_bytes()).is_ok();
                    (ok, ratio, exceeds && force_profile, None)
                }
            }
        } else {
            (false, 0.0, false, None)
        };

        // Optional: persist letter-to-future-self. Append-only — each call
        // creates a new file letter_<unix_ts>.md. Latest 3 are auto-injected
        // at session_bootstrap.
        let letter_written = if let Some(letter_body) = args.get("letter").and_then(|v| v.as_str())
        {
            if !letter_body.trim().is_empty() && !dry_run {
                let dir = letters_dir();
                let _ = std::fs::create_dir_all(&dir);
                let ts = std::time::SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)
                    .map(|d| d.as_secs())
                    .unwrap_or(0);
                let path = dir.join(format!("letter_{ts}.md"));
                std::fs::write(&path, letter_body.as_bytes())
                    .ok()
                    .map(|_| path.display().to_string())
            } else {
                None
            }
        } else {
            None
        };

        // SSB lifecycle producer (roadmap §2 "hooks → bus events"): emit the
        // session-finalize lifecycle as a typed semantic event on the same unified
        // contract as browser/desktop/mobile. Unlike input taps, finalize HAS
        // readback (the maintenance counts), so a real run is Verified — the first
        // producer whose verified verdict rests on a concrete effect count rather
        // than an actionability probe. A dry-run made no change, so it is Unknown.
        let removed_n = removed.len();
        let verdict = if dry_run {
            crate::semantic_event::Verdict {
                status: crate::semantic_event::VerdictStatus::Unknown,
                method: "dry_run_no_changes".to_string(),
                evidence: json!({ "note": "dry-run: no maintenance applied" }),
            }
        } else {
            crate::semantic_event::Verdict {
                status: crate::semantic_event::VerdictStatus::Verified,
                method: "finalize_readback".to_string(),
                evidence: json!({ "decay_archived": decay_archived, "removed_count": removed_n }),
            }
        };
        let lifecycle_event = crate::semantic_event::SemanticEvent {
            ts: dispatch_now_secs(),
            actor: "mcp".to_string(),
            source: "session".to_string(),
            action: "finalize".to_string(),
            target: None,
            object: crate::semantic_event::SemanticObject {
                object_type: "session".to_string(),
                source_adapter: "session".to_string(),
                label: None,
                object_id: None,
            },
            affordance: crate::semantic_event::Affordance {
                action_type: "finalize".to_string(),
                risk_level: "low".to_string(),
                requires_gate: false,
                expected_effect: Some("decay + compact stale memories".to_string()),
            },
            verdict,
            facts: json!({ "dry_run": dry_run, "decay_archived": decay_archived, "removed_count": removed_n }),
        };
        if let Err(e) = store
            .record_semantic_event(lifecycle_event.to_record())
            .await
        {
            tracing::debug!(error = %e, "record_semantic_event (session_finalize) failed");
        }

        let mut payload = json!({
            "dry_run": dry_run,
            "decay": {
                "half_life_days": half_life,
                "archive_threshold": archive_threshold,
                "archived_count": decay_archived,
                "skipped": skip_decay || dry_run
            },
            "policy": {
                "older_than_days": older_than_days,
                "min_uses": min_uses
            },
            "removed_count": removed.len(),
            "removed_keys": removed,
            "export": export_summary,
            "follow_up": follow_up,
            "user_profile_written": user_profile_written,
            "agent_profile_written": agent_profile_written,
            "agent_profile_diff_ratio": agent_profile_diff_ratio_v,
            "agent_profile_capped": agent_profile_capped,
            "agent_profile_reason": agent_profile_reason,
            "letter_written": letter_written,
        });
        // Stage 5b: surface the gated executor result only when opted in, so the
        // default (apply_outcome_gated=false) response shape is unchanged.
        if apply_outcome_gated {
            payload["outcome_gated_consolidation"] = outcome_gated_consolidation;
        }
        Ok(ToolResult::json_text(&payload))
    }
}

fn tool_result_first_json(tr: &ToolResult) -> Option<Value> {
    tr.content.iter().find_map(|b| {
        if let ContentBlock::Text { text } = b {
            serde_json::from_str::<Value>(text).ok()
        } else {
            None
        }
    })
}

