pub struct IdeCommandTool {
    #[allow(dead_code)]
    hub: Hub,
}

impl IdeCommandTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

#[async_trait]
impl McpTool for IdeCommandTool {
    fn name(&self) -> &'static str {
        "ide_command"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Queue a lightweight command for an IDE extension to execute via the \
                 file bridge. Supported commands: open_file, reveal_range, run_task, \
                 write_snapshot, apply_workspace_edit, save_file, format_document. The \
                 response includes advisory command-dir and workspace-boundary evidence for \
                 path-carrying commands; mutating edit/save/format commands are blocked before queueing unless \
                 their paths canonicalize inside the workspace, except explicit \
                 apply_workspace_edit create edits may queue through create_file_gate evidence \
                 when the parent is contained and the target is missing. The IDE extension still \
                 remains final containment authority. Writes JSONL to \
                 <workspace>/.agent-bridge/ide-commands.jsonl (or command_dir / \
                 AGENT_BRIDGE_IDE_COMMAND_DIR) and optionally waits for a matching response \
                 in ide-responses.jsonl. Optional command_dir_policy=contained_or_existing \
                 blocks auto-creating an external or unknown command directory while keeping \
                 existing directories compatible."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "command": {
                        "type": "string",
                        "enum": ["open_file", "reveal_range", "run_task", "write_snapshot", "apply_workspace_edit", "save_file", "format_document"],
                        "description": "IDE action to request."
                    },
                    "args": {
                        "type": "object",
                        "default": {},
                        "description": "Command-specific JSON args. open_file/reveal_range use {path, range?, preview?, preserve_focus?}; run_task uses {name}; write_snapshot uses {}; apply_workspace_edit uses {edits:[{path, range?, text, create?}], save?} (omit range to replace the whole file); save_file uses {path}; format_document uses {path, save?}. Optional workspace_root/workspaceRoot can anchor workspace_boundary evidence; otherwise cwd or <workspace>/.agent-bridge is used when available. Mutating paths must exist and canonicalize inside the workspace before queueing, except apply_workspace_edit edits with create:true may create a missing leaf file when the parent exists and canonicalizes inside the workspace, text is present as full file contents, and range is absent/null."
                    },
                    "cwd": {
                        "type": "string",
                        "description": "Workspace directory used to resolve .agent-bridge command files."
                    },
                    "command_dir": {
                        "type": "string",
                        "description": "Optional explicit directory containing ide-commands.jsonl and ide-responses.jsonl."
                    },
                    "command_dir_policy": {
                        "type": "string",
                        "enum": ["advisory", "contained_or_existing"],
                        "default": "advisory",
                        "description": "Queue-directory safety policy. advisory only reports command_dir_boundary evidence. contained_or_existing blocks auto-creating a command directory unless command_dir_boundary proves it will be inside the workspace; already-existing external directories remain compatible."
                    },
                    "wait_ms": {
                        "type": "integer",
                        "minimum": 0,
                        "maximum": 30000,
                        "default": 0,
                        "description": "Wait for an IDE response before returning. 0 = enqueue only."
                    }
                },
                "required": ["command"]
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let command = args
            .get("command")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_string();
        let command_args = args.get("args").cloned().unwrap_or_else(|| json!({}));
        let command_dir = args
            .get("command_dir")
            .and_then(|v| v.as_str())
            .filter(|s| !s.trim().is_empty())
            .map(PathBuf::from);
        let cwd = match args.get("cwd").and_then(|v| v.as_str()) {
            Some(s) if !s.trim().is_empty() => match resolve_cwd(Some(s)) {
                Ok(p) => Some(p),
                Err(e) => return Ok(ToolResult::error(e.to_string())),
            },
            _ => None,
        };
        let wait_ms = args
            .get("wait_ms")
            .and_then(|v| v.as_u64())
            .unwrap_or(0)
            .min(30_000);
        let command_dir_policy = match args
            .get("command_dir_policy")
            .and_then(|v| v.as_str())
            .and_then(IdeCommandDirPolicy::from_str)
        {
            Some(policy) => policy,
            None if args.get("command_dir_policy").is_some() => {
                return Ok(ToolResult::error(
                    "invalid command_dir_policy; expected advisory or contained_or_existing",
                ))
            }
            None => IdeCommandDirPolicy::default(),
        };
        let options = IdeCommandOptions {
            command_dir,
            cwd,
            wait_ms,
        };

        let res = tokio::task::spawn_blocking(move || {
            queue_ide_command_with_dir_policy(&command, command_args, options, command_dir_policy)
        })
        .await
        .map_err(|e| ab_core::Error::Backend(format!("ide_command task: {e}")))?;
        match res {
            Ok(v) => Ok(ToolResult::json_text(&v)),
            Err(e) => Ok(ToolResult::error(e.to_string())),
        }
    }
}

