pub struct ContextBudgetTool;

impl ContextBudgetTool {
    pub fn new() -> Self {
        Self
    }
}

#[async_trait]
impl McpTool for ContextBudgetTool {
    fn name(&self) -> &'static str {
        "context_budget"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Estimate token usage from optional conversation text + turn count using offline heuristics; \
                 compare to an approximate model context limit and get a compaction recommendation. No API calls."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "model": {
                        "type": "string",
                        "description": "Model name hint for context window size (default: claude-sonnet-4).",
                        "default": "claude-sonnet-4"
                    },
                    "context_window": {
                        "type": "integer",
                        "minimum": 1,
                        "description": "Explicit context-window size in tokens — overrides the model→limit lookup. Pass 1000000 for long-context-beta (opus-4.x / sonnet-4.x @ 1M) sessions; the model name alone can't reveal the 200K-vs-1M SKU. Precedence: this arg > AGENT_BRIDGE_CONTEXT_WINDOW env > model default."
                    },
                    "conversation_turns": {
                        "type": "integer",
                        "minimum": 0,
                        "description": "When transcript is unavailable, each turn adds a coarse token guess.",
                        "default": 0
                    },
                    "text_sample": {
                        "type": "string",
                        "description": "Optional excerpt / transcript sample to token-estimate (mixed EN/CJK heuristic)."
                    }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let model = args
            .get("model")
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty())
            .unwrap_or("claude-sonnet-4");
        let turns = args
            .get("conversation_turns")
            .and_then(|v| v.as_u64())
            .unwrap_or(0);
        let text = args
            .get("text_sample")
            .and_then(|v| v.as_str())
            .unwrap_or("");
        // Window precedence: explicit arg > AGENT_BRIDGE_CONTEXT_WINDOW env >
        // conservative model default (see context_pressure_estimate / #1758).
        let explicit_window = args
            .get("context_window")
            .or_else(|| args.get("model_limit"))
            .and_then(|v| v.as_u64());
        let (limit, limit_source) =
            resolve_context_window(explicit_window, env_context_window(), model);
        let estimated = estimated_usage_tokens(text, turns);
        let pct_raw = if limit == 0 {
            0.0
        } else {
            (estimated as f64 / limit as f64) * 100.0
        };
        let pct_used = (pct_raw * 10.0).round() / 10.0;
        let recommendation = budget_recommendation(pct_raw);
        Ok(ToolResult::json_text(&json!({
            "model_hint": model,
            "model_limit": limit,
            "model_limit_source": limit_source,
            "estimated_tokens_used": estimated,
            "pct_used": pct_used,
            "recommendation": recommendation,
            "heuristic_note": "Offline estimate only; actual tokenizer usage varies.",
        })))
    }
}

// ===========================================================================
//        context_pressure_estimate — L6 P3 metacognition probe
// ===========================================================================

/// L6 P3 — `context_pressure_estimate` MCP tool.
///
/// Companion to `context_budget` but framed for **introspection**: the
/// assistant reads its own context-window pressure as a categorical
/// fatigue tier (`fresh|engaged|strained|saturated`) plus distance to
/// compaction. Roadmap §3 L6 P3 (~0.3d).
///
/// Backed entirely by the existing offline `context_budget` heuristic —
/// no API calls, no LLM judge. Cheap enough to call at session
/// bootstrap + per-turn if desired.
pub struct ContextPressureEstimateTool;

impl ContextPressureEstimateTool {
    pub fn new() -> Self {
        Self
    }
}

impl Default for ContextPressureEstimateTool {
    fn default() -> Self {
        Self::new()
    }
}

#[async_trait]
impl McpTool for ContextPressureEstimateTool {
    fn name(&self) -> &'static str {
        "context_pressure_estimate"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "L6 P3 metacognition probe — read the assistant's own \
                 context-window pressure as a categorical fatigue tier (fresh / \
                 engaged / strained / saturated) plus distance-to-compaction. \
                 Backed by the same offline heuristic as `context_budget` but \
                 surfaced for introspective decisions (\"should I compact \
                 before starting another long task?\"). No API calls."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "model": {
                        "type": "string",
                        "description": "Model name hint for context window size (default: claude-sonnet-4).",
                        "default": "claude-sonnet-4"
                    },
                    "context_window": {
                        "type": "integer",
                        "minimum": 1,
                        "description": "Explicit context-window size in tokens — overrides the model→limit lookup. Use on long-context-beta sessions (e.g. opus-4.x / sonnet-4.x @ 1M): the model name alone cannot reveal the 200K-vs-1M SKU, so omitting this defaults to a conservative 200K and inflates pressure up to 5×. Pass 1000000 when on the 1M beta. Precedence: this arg > AGENT_BRIDGE_CONTEXT_WINDOW env > model default (set the env once machine-wide to avoid per-call args)."
                    },
                    "conversation_turns": {
                        "type": "integer",
                        "minimum": 0,
                        "description": "Turn count for coarse-overhead estimate when no transcript is available.",
                        "default": 0
                    },
                    "text_sample": {
                        "type": "string",
                        "description": "Optional transcript / excerpt sample for token-estimation (mixed EN/CJK heuristic)."
                    }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        use crate::context_budget::{
            budget_recommendation, env_context_window, estimated_usage_tokens, fatigue_tier,
            model_supports_1m_beta, resolve_context_window,
        };
        let model = args
            .get("model")
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty())
            .unwrap_or("claude-sonnet-4");
        let turns = args
            .get("conversation_turns")
            .and_then(|v| v.as_u64())
            .unwrap_or(0);
        let text_raw = args
            .get("text_sample")
            .and_then(|v| v.as_str())
            .unwrap_or("");
        let text_sample_provided = !text_raw.is_empty();

        // Resolve the window: explicit caller arg > AGENT_BRIDGE_CONTEXT_WINDOW
        // env (machine-level truth, survives a client stripping the unknown
        // arg) > conservative model default. `model_limit` accepted as a
        // defensive alias for callers following the orchestrate_scan hint.
        let explicit_window = args
            .get("context_window")
            .or_else(|| args.get("model_limit"))
            .and_then(|v| v.as_u64());
        let (limit, limit_source) =
            resolve_context_window(explicit_window, env_context_window(), model);
        // Flag the 1M ambiguity only when we fell all the way back to the
        // model default AND the model is a long-context-beta family — tells
        // the caller to set the window (guards the #1758 5× inflation).
        let one_m_beta_possible = limit_source == "model_default" && model_supports_1m_beta(model);
        let estimated = estimated_usage_tokens(text_raw, turns);
        let pct_raw = if limit == 0 {
            0.0
        } else {
            (estimated as f64 / limit as f64) * 100.0
        };
        let pct_used = (pct_raw * 10.0).round() / 10.0;
        let tier = fatigue_tier(pct_raw);
        let recommendation = budget_recommendation(pct_raw);
        // Distance to soft compaction trigger (urgent_handoff at 80%).
        // Clamped at 0 — we never report "negative distance" since past
        // the threshold the model has already overrun the safe zone.
        let soft_trigger = (limit as f64 * 0.80) as u64;
        let distance_to_compaction = soft_trigger.saturating_sub(estimated);

        // L6 P3 dogfood 5/13 + 5/19: no-sample reading systematically
        // under-counted. Flag confidence so the caller can weight the
        // tier accordingly rather than treating heuristic-only as ground
        // truth.
        let confidence = if text_sample_provided { "high" } else { "low" };
        let mut note = String::from(if text_sample_provided {
            "Estimate uses turn × per-turn guess + actual sample tokens + system baseline."
        } else {
            "No text_sample passed — estimate is heuristic-only and may under-count tool-heavy turns. Pass `text_sample` (recent transcript excerpt) for higher confidence."
        });
        if one_m_beta_possible {
            note.push_str(
                " NOTE: limit defaulted to 200K but this is a long-context-beta family (opus-4.x / sonnet-4.x); if the session runs the 1M beta, pass context_window=1000000 (or set AGENT_BRIDGE_CONTEXT_WINDOW=1000000 once, machine-wide — survives clients that strip the arg) — otherwise pct_used / fatigue_tier are inflated up to 5×.",
            );
        }

        Ok(ToolResult::json_text(&json!({
            "model_hint": model,
            "model_limit": limit,
            "model_limit_source": limit_source,
            "long_context_beta_possible": one_m_beta_possible,
            "estimated_tokens_used": estimated,
            "pct_used": pct_used,
            "fatigue_tier": tier,
            "distance_to_compaction_tokens": distance_to_compaction,
            "recommendation": recommendation,
            "text_sample_provided": text_sample_provided,
            "confidence": confidence,
            "note": note,
            "heuristic_note": "Offline estimate; actual tokenizer usage varies. Tier bands per roadmap §3 L6 P3.",
        })))
    }
}

// ===========================================================================
//        research_cycle_plan - read-only/advisory research control packet
// ===========================================================================

pub struct ResearchCyclePlanTool;

impl ResearchCyclePlanTool {
    pub fn new() -> Self {
        Self
    }
}

impl Default for ResearchCyclePlanTool {
    fn default() -> Self {
        Self::new()
    }
}

fn research_cycle_text(args: &Value, key: &str) -> String {
    args.get(key)
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(str::to_string)
        .unwrap_or_default()
}

fn research_cycle_text_list(args: &Value, key: &str) -> Vec<String> {
    match args.get(key) {
        Some(Value::Array(values)) => values
            .iter()
            .filter_map(Value::as_str)
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .map(str::to_string)
            .take(20)
            .collect(),
        Some(Value::String(raw)) => {
            let trimmed = raw.trim();
            if trimmed.is_empty() {
                Vec::new()
            } else {
                vec![trimmed.to_string()]
            }
        }
        _ => Vec::new(),
    }
}

fn research_cycle_requested_actions(args: &Value) -> BTreeSet<String> {
    research_cycle_text_list(args, "requested_actions")
        .into_iter()
        .map(|action| {
            action
                .chars()
                .map(|c| {
                    if c.is_ascii_alphanumeric() {
                        c.to_ascii_lowercase()
                    } else {
                        '_'
                    }
                })
                .collect::<String>()
        })
        .collect()
}

fn research_cycle_action(rank: u32, action: &str, reason: &str, mutation: bool) -> Value {
    json!({
        "rank": rank,
        "action": action,
        "reason": reason,
        "requires_separate_tool_call": mutation,
        "this_tool_mutates_state": false,
    })
}

fn build_research_cycle_plan(args: &Value) -> Value {
    let research_question = research_cycle_text(args, "research_question");
    let hypothesis = research_cycle_text(args, "hypothesis");
    let source_anchors = research_cycle_text_list(args, "source_anchors");
    let proposed_experiment = research_cycle_text(args, "proposed_experiment");
    let experiment_command = research_cycle_text(args, "experiment_command");
    let evidence_summary = research_cycle_text(args, "evidence_summary");
    let reproducibility_handle = research_cycle_text(args, "reproducibility_handle");
    let expected_artifact = research_cycle_text(args, "expected_artifact");
    let falsifier = research_cycle_text(args, "falsifier");
    let owner = research_cycle_text(args, "owner");
    let reviewer = research_cycle_text(args, "reviewer");
    let forum_thread_id = args.get("forum_thread_id").and_then(Value::as_u64);
    let memory_key = research_cycle_text(args, "memory_key");
    let requested_actions = research_cycle_requested_actions(args);

    let mut blockers = Vec::<Value>::new();
    if hypothesis.is_empty() {
        blockers.push(json!("hypothesis_missing"));
    }
    if source_anchors.is_empty() {
        blockers.push(json!("source_anchors_missing"));
    }
    if proposed_experiment.is_empty() {
        blockers.push(json!("proposed_experiment_missing"));
    }
    if experiment_command.is_empty() {
        blockers.push(json!("experiment_command_missing"));
    }
    if evidence_summary.is_empty() {
        blockers.push(json!("evidence_summary_missing"));
    }
    if reproducibility_handle.is_empty() {
        blockers.push(json!("reproducibility_handle_missing"));
    }
    if falsifier.is_empty() {
        blockers.push(json!("falsifier_missing"));
    }
    if requested_actions
        .iter()
        .any(|a| a.contains("execute") || a.contains("run_code") || a.contains("spawn"))
    {
        blockers.push(json!("execution_not_authorized"));
    }
    if requested_actions
        .iter()
        .any(|a| a.contains("write_memory") || a.contains("memory_save") || a.contains("ingest"))
    {
        blockers.push(json!("memory_write_not_authorized"));
    }
    if requested_actions
        .iter()
        .any(|a| a.contains("manuscript") || a.contains("paper_generation"))
    {
        blockers.push(json!("manuscript_generation_not_authorized"));
    }

    let status = if blockers.is_empty() {
        "ready_for_human_review"
    } else {
        "planned_needs_evidence"
    };
    let mut actions = Vec::new();
    let mut rank = 1u32;
    if blockers.is_empty() {
        actions.push(research_cycle_action(
            rank,
            "publish_review_packet_to_forum",
            "Evidence handles are present; the next step is human-readable review, not automatic ingestion.",
            true,
        ));
        rank += 1;
        actions.push(research_cycle_action(
            rank,
            "await_owner_memory_ingest_decision",
            "Durable AB memory should only receive accepted conclusions after owner/reviewer approval.",
            false,
        ));
    } else {
        actions.push(research_cycle_action(
            rank,
            "capture_missing_evidence",
            "The plan is advisory until source, command, evidence, reproducibility, and falsifier handles are complete.",
            false,
        ));
        rank += 1;
        actions.push(research_cycle_action(
            rank,
            "post_blockers_for_review",
            "Visible blockers keep speculative research branches from becoming durable claims.",
            true,
        ));
    }
    actions.push(research_cycle_action(
        actions.len() as u32 + 1,
        "keep_execution_in_separate_authorized_lane",
        "This v0 packet borrows research-loop structure without executing LLM-written code or generating manuscripts.",
        false,
    ));

    json!({
        "schema": "agent_bridge.research_cycle.plan.v0",
        "source_pattern": "ai_scientist_v2_research_loop",
        "inspired_by": {
            "paper": "Towards end-to-end automation of AI research",
            "doi": "10.1038/s41586-026-10265-5",
            "repo": "https://github.com/SakanaAI/AI-Scientist-v2",
            "borrowed_pattern": "staged research lifecycle with experiment journal and advisory review",
            "code_reuse": false,
            "license_review_required_for_code_reuse": true,
        },
        "inputs": {
            "research_question": research_question,
            "hypothesis": hypothesis,
            "source_anchors": source_anchors,
            "source_anchor_count": source_anchors.len(),
            "proposed_experiment": proposed_experiment,
            "experiment_command": experiment_command,
            "evidence_summary": evidence_summary,
            "reproducibility_handle": reproducibility_handle,
            "expected_artifact": expected_artifact,
            "falsifier": falsifier,
            "owner": owner,
            "reviewer": reviewer,
            "forum_thread_id": forum_thread_id,
            "memory_key": memory_key,
        },
        "research_tree": {
            "mode": "single_root_first_branch_v0",
            "autonomous_branching": false,
            "root": {
                "id": "root",
                "kind": "hypothesis",
                "status": status,
                "question_present": !research_question.is_empty(),
                "hypothesis_present": !hypothesis.is_empty(),
                "source_anchor_count": source_anchors.len(),
            },
            "candidate_branches": [
                {
                    "id": "branch_001",
                    "kind": "proposed_experiment",
                    "status": status,
                    "requires_human_review": true,
                    "may_execute_from_this_packet": false,
                }
            ],
        },
        "evidence_contract": {
            "requires_source_anchors": true,
            "requires_experiment_command": true,
            "requires_evidence_summary": true,
            "requires_reproducibility_handle": true,
            "requires_falsifier": true,
            "negative_results_policy": "negative_results_are_evidence_and_may_close_or_reframe_the_branch",
            "claims_without_evidence_allowed": false,
        },
        "review_contract": {
            "review_is_advisory": true,
            "critic_dimensions": [
                "novelty",
                "method",
                "implementation_correctness",
                "evidence_strength",
                "safety_and_license",
                "memory_ingest_readiness"
            ],
            "human_review_required": true,
        },
        "gates": {
            "may_execute": false,
            "may_spawn_agents": false,
            "may_write_memory": false,
            "may_write_forum": false,
            "may_generate_manuscript": false,
            "may_change_runtime_policy": false,
            "requires_owner_review_before_ingest": true,
        },
        "tool_activity": {
            "calls_memory_search": false,
            "writes_memory": false,
            "writes_forum": false,
            "spawns_agents": false,
            "executes_commands": false,
            "imports_external_code": false,
        },
        "guardrails": {
            "read_only_packet": true,
            "does_not_call_memory_search": true,
            "does_not_write_memory": true,
            "does_not_spawn_agents": true,
            "does_not_execute_commands": true,
            "does_not_generate_manuscripts": true,
            "does_not_reopen_parked_embedding_runtime": true,
        },
        "blockers": blockers,
        "recommended_next_actions": actions,
    })
}

#[async_trait]
impl McpTool for ResearchCyclePlanTool {
    fn name(&self) -> &'static str {
        "research_cycle_plan"
    }

    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Read-only/advisory research-cycle planning packet inspired by AI \
                 Scientist-v2's staged research loop. It structures a hypothesis, source \
                 anchors, experiment evidence handles, review contract, blockers, and \
                 owner-gated memory-ingest posture. It never searches memory, writes memory \
                 or forum posts, spawns agents, executes commands, imports external code, \
                 generates manuscripts, or changes runtime policy."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "research_question": { "type": "string" },
                    "hypothesis": { "type": "string" },
                    "source_anchors": {
                        "oneOf": [
                            { "type": "array", "items": { "type": "string" } },
                            { "type": "string" }
                        ],
                        "description": "URLs, memory keys, forum posts, commits, or file paths that anchor the claim."
                    },
                    "proposed_experiment": { "type": "string" },
                    "experiment_command": {
                        "type": "string",
                        "description": "Command that would verify the experiment in a separate authorized lane. This tool does not run it."
                    },
                    "evidence_summary": { "type": "string" },
                    "reproducibility_handle": { "type": "string" },
                    "expected_artifact": { "type": "string" },
                    "falsifier": { "type": "string" },
                    "owner": { "type": "string" },
                    "reviewer": { "type": "string" },
                    "forum_thread_id": { "type": "integer" },
                    "memory_key": { "type": "string" },
                    "requested_actions": {
                        "type": "array",
                        "items": { "type": "string" },
                        "description": "Optional requested actions; execution/write/manuscript requests are reported as blockers, never performed."
                    }
                }
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        Ok(ToolResult::json_text(&build_research_cycle_plan(&args)))
    }
}

// ===========================================================================
//        context_governor_snapshot - read-only lifecycle decision packet
// ===========================================================================

pub struct ContextGovernorSnapshotTool;

impl ContextGovernorSnapshotTool {
    pub fn new() -> Self {
        Self
    }
}

impl Default for ContextGovernorSnapshotTool {
    fn default() -> Self {
        Self::new()
    }
}

fn context_governor_action(
    rank: u32,
    action: &str,
    reason: &str,
    effect: &str,
    mutation: bool,
) -> Value {
    json!({
        "rank": rank,
        "action": action,
        "reason": reason,
        "effect": effect,
        "requires_separate_tool_call": mutation,
        "snapshot_mutates_state": false,
    })
}

fn context_governor_suggested_actions(tier: &str, confidence: &str) -> Vec<Value> {
    let mut actions = Vec::new();
    let mut rank = 1u32;

    if confidence == "low" {
        actions.push(context_governor_action(
            rank,
            "provide_text_sample_before_aggressive_pruning",
            "No text_sample was provided, so the pressure estimate is turn-count based.",
            "Improves confidence before deciding to handoff, compact, or reduce context.",
            false,
        ));
        rank += 1;
    }

    match tier {
        "fresh" => {
            actions.push(context_governor_action(
                rank,
                "continue_current_flow",
                "Context pressure is below the first fatigue band.",
                "No lifecycle intervention is needed yet.",
                false,
            ));
            rank += 1;
            actions.push(context_governor_action(
                rank,
                "use_semantic_bootstrap_on_scope_shift",
                "If the task changes topic, retrieve by task query instead of carrying broad prior context.",
                "Keeps down-slide injection relevant.",
                true,
            ));
        }
        "engaged" => {
            actions.push(context_governor_action(
                rank,
                "save_active_work_memory_before_long_branch",
                "The session has meaningful pressure but is not near the urgent band.",
                "Preserves active state outside the model window before expanding scope.",
                true,
            ));
            rank += 1;
            actions.push(context_governor_action(
                rank,
                "prefer_targeted_retrieval",
                "Avoid reloading broad transcripts or large file dumps when scoped lookup will do.",
                "Reduces avoidable context growth.",
                false,
            ));
        }
        "strained" => {
            actions.push(context_governor_action(
                rank,
                "save_work_memory_now",
                "Context pressure is in the strained band.",
                "Captures active files, hypothesis, evidence, and next step before compaction risk.",
                true,
            ));
            rank += 1;
            actions.push(context_governor_action(
                rank,
                "prepare_handoff_or_compaction_point",
                "Further broad exploration risks losing relevant state to lossy compaction.",
                "Creates a deliberate boundary before continuing.",
                true,
            ));
            rank += 1;
            actions.push(context_governor_action(
                rank,
                "avoid_broad_context_injection",
                "Large unfiltered snippets are the main controllable growth source.",
                "Use semantic memory_search/session_bootstrap query and short snippets.",
                false,
            ));
        }
        "saturated" => {
            actions.push(context_governor_action(
                rank,
                "stop_expanding_current_thread",
                "Context pressure is at or past the saturation band.",
                "Prevents more work from entering a low-reliability window.",
                false,
            ));
            rank += 1;
            actions.push(context_governor_action(
                rank,
                "save_work_memory_and_handoff",
                "The active task state should be externalized before more tool output is added.",
                "Preserves recoverable state for a fresh window.",
                true,
            ));
            rank += 1;
            actions.push(context_governor_action(
                rank,
                "run_precompact_or_session_finalize",
                "A lifecycle boundary is safer than continuing with an overloaded transcript.",
                "Lets existing curate/finalize paths extract durable lessons and decisions.",
                true,
            ));
        }
        _ => {
            actions.push(context_governor_action(
                rank,
                "inspect_context_pressure",
                "Unknown fatigue tier returned by the estimator.",
                "Treat this as diagnostic-only and avoid automatic pruning.",
                false,
            ));
        }
    }

    actions.push(context_governor_action(
        actions.len() as u32 + 1,
        "keep_or_verify_lean_tool_surface",
        "Eager clients pay for exposed tool schemas every request.",
        "Keep codex-lean or run a measured A/B before widening the toolset.",
        false,
    ));

    actions
}

fn build_context_governor_snapshot(args: &Value) -> Value {
    let cwd = args
        .get("cwd")
        .and_then(|v| v.as_str())
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(str::to_string)
        .or_else(|| {
            std::env::current_dir()
                .ok()
                .map(|p| p.display().to_string())
        })
        .unwrap_or_else(|| "/".to_string());
    let model_default = std::env::var("AGENT_BRIDGE_MODEL").unwrap_or_else(|_| "gpt-5.5".into());
    let model = args
        .get("model")
        .and_then(|v| v.as_str())
        .filter(|s| !s.trim().is_empty())
        .unwrap_or(&model_default);
    let turns = args
        .get("conversation_turns")
        .and_then(|v| v.as_u64())
        .unwrap_or(0);
    let text_raw = args
        .get("text_sample")
        .and_then(|v| v.as_str())
        .unwrap_or("");
    let text_sample_provided = !text_raw.is_empty();
    let explicit_window = args
        .get("context_window")
        .or_else(|| args.get("model_limit"))
        .and_then(|v| v.as_u64());
    let (limit, limit_source) =
        resolve_context_window(explicit_window, env_context_window(), model);
    let estimated = estimated_usage_tokens(text_raw, turns);
    let pct_raw = if limit == 0 {
        0.0
    } else {
        (estimated as f64 / limit as f64) * 100.0
    };
    let pct_used = (pct_raw * 10.0).round() / 10.0;
    let tier = fatigue_tier(pct_raw);
    let recommendation = budget_recommendation(pct_raw);
    let soft_trigger = (limit as f64 * 0.80) as u64;
    let distance_to_compaction = soft_trigger.saturating_sub(estimated);
    let confidence = if text_sample_provided { "high" } else { "low" };
    let long_context_beta_possible =
        limit_source == "model_default" && model_supports_1m_beta(model);

    let toolset_env = std::env::var("AGENT_BRIDGE_TOOLSET").ok();
    let client_env = std::env::var("AGENT_BRIDGE_CLIENT").ok();
    let source_env = std::env::var("AGENT_BRIDGE_MCP_SOURCE").ok();
    let profile_env = std::env::var("AGENT_BRIDGE_TOOL_PROFILE").ok();
    let policy = ToolPolicy::from_values(
        toolset_env.as_deref(),
        client_env.as_deref(),
        source_env.as_deref(),
        profile_env.as_deref(),
    );
    let exposed_tool_count = exposed_tool_count_for(
        toolset_env.as_deref(),
        client_env.as_deref(),
        profile_env.as_deref(),
    );

    json!({
        "schema": "agent_bridge.context_governor.snapshot.v0",
        "cwd": cwd,
        "direct_model_context_pruning": {
            "supported": false,
            "reason": "Agent-Bridge cannot delete or reorder content already admitted to the host model window. It governs lifecycle inputs, saved scratch state, bootstrap recall, and tool-surface size around the host."
        },
        "pressure": {
            "model_hint": model,
            "model_limit": limit,
            "model_limit_source": limit_source,
            "long_context_beta_possible": long_context_beta_possible,
            "estimated_tokens_used": estimated,
            "pct_used": pct_used,
            "fatigue_tier": tier,
            "recommendation": recommendation,
            "distance_to_compaction_tokens": distance_to_compaction,
            "soft_trigger_pct": 80,
            "text_sample_provided": text_sample_provided,
            "text_sample_chars": text_raw.chars().count(),
            "text_sample_tokens_estimate": estimate_tokens_from_text(text_raw),
            "confidence": confidence,
            "heuristic_note": "Offline estimate only; pass text_sample for higher confidence on tool-heavy sessions."
        },
        "controls": {
            "toolset": policy.label(),
            "tool_profile": policy.profile().label(),
            "toolset_env": toolset_env,
            "tool_profile_env": profile_env,
            "client_env": client_env,
            "source_env": source_env,
            "exposed_tool_count": exposed_tool_count,
            "surfaces": [
                {
                    "name": "work_memory",
                    "role": "short-lived active task scratchpad outside model context",
                    "mutation_requires_separate_tool": true
                },
                {
                    "name": "session_bootstrap",
                    "role": "bounded down-slide recall with per-block budgets and optional semantic query",
                    "mutation_requires_separate_tool": false
                },
                {
                    "name": "session_lifecycle_step(precompact)",
                    "role": "pre-compaction capture plus curate/finalize path",
                    "mutation_requires_separate_tool": true
                },
                {
                    "name": "codex-lean",
                    "role": "eager tool-schema surface reduction for Codex-like clients",
                    "mutation_requires_separate_tool": false
                }
            ]
        },
        "suggested_actions": context_governor_suggested_actions(tier, confidence),
        "guardrails": {
            "snapshot_is_read_only": true,
            "does_not_write_memory": true,
            "does_not_compact_session": true,
            "does_not_change_tool_profile": true,
            "does_not_execute_remote_code": true
        }
    })
}

