    #[test]
    fn dispatch_recent_errors_for_audit_scopes_to_failing_tools_and_window() {
        let now = dispatch_now_secs();
        let stats = vec![
            ab_store::McpToolCallStats {
                tool_name: "forum_read".into(),
                call_count: 2,
                error_count: 1,
                avg_duration_ms: 1.0,
                p95_duration_ms: 2,
                max_duration_ms: 3,
                avg_result_size: 100.0,
                client_name: None,
                profile: None,
                source: Some("codex".into()),
                model: None,
                model_reasoning_effort: None,
                codex_host: None,
            },
            ab_store::McpToolCallStats {
                tool_name: "capabilities".into(),
                call_count: 4,
                error_count: 0,
                avg_duration_ms: 1.0,
                p95_duration_ms: 2,
                max_duration_ms: 3,
                avg_result_size: 100.0,
                client_name: None,
                profile: None,
                source: Some("codex".into()),
                model: None,
                model_reasoning_effort: None,
                codex_host: None,
            },
        ];
        let rows = vec![
            ab_store::McpToolErrorRecord {
                ts: now,
                tool_name: "forum_read".into(),
                message: "current scoped error".into(),
            },
            ab_store::McpToolErrorRecord {
                ts: now.saturating_sub(3_600),
                tool_name: "forum_read".into(),
                message: "old error".into(),
            },
            ab_store::McpToolErrorRecord {
                ts: now,
                tool_name: "capabilities".into(),
                message: "healthy tool historical error".into(),
            },
        ];

        let scoped = dispatch_recent_errors_for_audit(rows, 5, 900, &stats, &HashMap::new());
        assert_eq!(scoped.len(), 1);
        assert_eq!(scoped[0].tool_name, "forum_read");
        assert_eq!(scoped[0].message, "current scoped error");
    }

    #[test]
    fn project_forum_posts_truncates_body_and_omits_refs() {
        let posts = vec![ForumPostRecord {
            id: 7,
            thread_id: 18,
            author: "codex".into(),
            kind: "finding".into(),
            body: "abcdef".into(),
            refs: json!({"files": ["a.rs"]}),
            created_at: 123,
        }];
        let (rows, truncated) = project_forum_posts(&posts, 3, false);
        assert_eq!(truncated, 1);
        assert_eq!(rows[0]["body"], json!("abc…"));
        assert_eq!(rows[0]["body_truncated"], json!(true));
        assert_eq!(rows[0]["body_total_chars"], json!(6));
        assert_eq!(rows[0]["refs_omitted"], json!(true));
        assert!(rows[0].get("refs").is_none());
    }

    #[tokio::test]
    async fn forum_read_compact_default_caps_implicit_limit() {
        let (hub, temp_dir) = mk_test_hub_with_store().await;
        let store = hub.store.as_ref().expect("store").clone();
        let created = store
            .forum_post(
                None,
                Some("payload"),
                Some("Compact payload"),
                "codex",
                "msg",
                &"opening ".repeat(400),
                None,
                None,
            )
            .await
            .expect("create thread");
        for idx in 0..19 {
            store
                .forum_post(
                    Some(created.thread_id),
                    None,
                    None,
                    "codex",
                    "reply",
                    &format!("reply-{idx} {}", "body ".repeat(400)),
                    None,
                    None,
                )
                .await
                .expect("reply");
        }

        let res = ForumReadTool::new(hub)
            .execute(
                json!({"thread_id": created.thread_id, "compact": true}),
                &ToolContext::default(),
            )
            .await
            .expect("forum_read");
        let body = result_json(&res);

        assert_eq!(body["projection"]["compact"], json!(true));
        assert_eq!(body["projection"]["limit"], json!(8));
        assert_eq!(body["count"], json!(8));
        assert_eq!(body["projection"]["body_max_chars"], json!(2000));
        assert_eq!(body["projection"]["truncated_posts"], json!(8));

        let explicit = ForumReadTool::new(crate::Hub::builder().store(store).build())
            .execute(
                json!({"thread_id": created.thread_id, "compact": true, "limit": 12}),
                &ToolContext::default(),
            )
            .await
            .expect("explicit forum_read");
        assert_eq!(result_json(&explicit)["count"], json!(12));

        let _ = tokio::fs::remove_dir_all(&temp_dir).await;
    }

