    #[test]
    fn memory_related_keys_review_packet_can_prioritize_orphan_reduction() {
        let mut anchored_source = mk_mem_scoped(
            "anchored_source",
            "decision",
            "anchored source content with durable detail",
            &[],
            Some("project:/repo"),
        );
        anchored_source.related_keys = vec!["anchored_target".into()];
        let anchored_target = mk_mem_scoped(
            "anchored_target",
            "lesson",
            "anchored target content with durable detail",
            &[],
            Some("project:/repo"),
        );
        let anchored_neighbor = mk_mem_scoped(
            "anchored_neighbor",
            "context",
            "anchored neighbor content",
            &[],
            Some("project:/repo"),
        );

        let mut orphan_source = mk_mem_scoped(
            "orphan_source",
            "decision",
            "orphan source content with durable detail",
            &[],
            Some("project:/repo"),
        );
        orphan_source.related_keys = vec!["orphan_target".into()];
        let orphan_target = mk_mem_scoped(
            "orphan_target",
            "lesson",
            "orphan target content with durable detail",
            &[],
            Some("project:/repo"),
        );
        let all = vec![
            anchored_source,
            anchored_target,
            anchored_neighbor,
            orphan_source,
            orphan_target,
        ];
        let mut edges_by_key = HashMap::new();
        edges_by_key.insert(
            "anchored_source".to_string(),
            vec![mk_edge("anchored_source", "anchored_neighbor", "relates")],
        );
        edges_by_key.insert(
            "anchored_target".to_string(),
            vec![mk_edge("anchored_target", "anchored_neighbor", "relates")],
        );

        let default_packet = memory_related_keys_review_packet_from_records(
            &all,
            &edges_by_key,
            Some("project:/repo"),
            MemorySearchScopeMode::LocalOnly,
            MemoryRelatedKeysReviewScopeFilter::Exact,
            MemoryRelatedKeysSelectionStrategy::PreserveOrder,
            1,
            80,
        );
        let orphan_packet = memory_related_keys_review_packet_from_records(
            &all,
            &edges_by_key,
            Some("project:/repo"),
            MemorySearchScopeMode::LocalOnly,
            MemoryRelatedKeysReviewScopeFilter::Exact,
            MemoryRelatedKeysSelectionStrategy::OrphanReduction,
            1,
            80,
        );

        assert_eq!(
            default_packet["review_packet"]["selected_edges"][0]["from_key"],
            json!("anchored_source")
        );
        assert_eq!(
            default_packet["review_packet"]["orphans_reduced_by_selected"],
            json!(0)
        );
        assert_eq!(
            orphan_packet["filters"]["selection_strategy"],
            json!("orphan_reduction")
        );
        assert_eq!(
            orphan_packet["review_packet"]["selected_edges"][0]["from_key"],
            json!("orphan_source")
        );
        assert_eq!(
            orphan_packet["review_packet"]["orphans_reduced_by_selected"],
            json!(2)
        );
    }

    #[test]
    fn tool_policy_codex_essential_exposes_related_keys_review_packet_not_materializer() {
        let p = ToolPolicy::from_values(Some("codex-essential"), None, None, None);
        let extras = p.extras();
        assert!(extras.contains(&"memory_related_keys_review_packet"));
        assert!(!extras.contains(&"memory_related_keys_materialize"));

        let names: Vec<String> = build_registry_with_policy(Hub::builder().build(), p)
            .list()
            .into_iter()
            .map(|schema| schema.name)
            .collect();
        assert!(names.iter().any(|name| name == "memory_related_keys_review_packet"));
        assert!(!names.iter().any(|name| name == "memory_related_keys_materialize"));
    }

    #[test]
    fn memory_search_scope_filter_is_strict_by_default() {
        let scoped = mk_mem_scoped(
            "scoped",
            "decision",
            "content content content content",
            &[],
            Some("project:/repo/a"),
        );
        let nested = mk_mem_scoped(
            "nested",
            "decision",
            "content content content content",
            &[],
            Some("project:/repo/a/sub"),
        );
        let other = mk_mem_scoped(
            "other",
            "decision",
            "content content content content",
            &[],
            Some("project:/repo/b"),
        );
        let global = mk_mem_scoped(
            "global",
            "decision",
            "content content content content",
            &[],
            Some("global"),
        );
        let unscoped = mk_mem(
            "unscoped",
            "decision",
            "content content content content",
            &[],
        );

        assert!(memory_search_scope_mode_matches(
            &scoped,
            "project:/repo/a",
            MemorySearchScopeMode::LocalOnly
        ));
        assert!(memory_search_scope_mode_matches(
            &nested,
            "project:/repo/a",
            MemorySearchScopeMode::LocalOnly
        ));
        assert!(memory_search_scope_mode_matches(
            &scoped,
            "project:/repo/a/sub",
            MemorySearchScopeMode::LocalOnly
        ));
        assert!(!memory_search_scope_mode_matches(
            &other,
            "project:/repo/a",
            MemorySearchScopeMode::LocalOnly
        ));
        assert!(!memory_search_scope_mode_matches(
            &global,
            "project:/repo/a",
            MemorySearchScopeMode::LocalOnly
        ));
        assert!(!memory_search_scope_mode_matches(
            &unscoped,
            "project:/repo/a",
            MemorySearchScopeMode::LocalOnly
        ));
        assert!(memory_search_scope_mode_matches(
            &global,
            "project:/repo/a",
            MemorySearchScopeMode::LocalPlusGlobal
        ));
        assert!(memory_search_scope_mode_matches(
            &unscoped,
            "project:/repo/a",
            MemorySearchScopeMode::LocalPlusGlobal
        ));
    }

