    fn mk_sev(
        source: &str,
        action: &str,
        verdict: &str,
        method: &str,
        target: Option<&str>,
        ts: i64,
    ) -> ab_store::SemanticEventRecord {
        ab_store::SemanticEventRecord {
            ts,
            actor: "mcp".into(),
            source: source.into(),
            action: action.into(),
            target: target.map(|s| s.into()),
            verdict_status: verdict.into(),
            verdict_method: method.into(),
            evidence: None,
            facts: "{}".into(),
            descriptor: None,
        }
    }

