    #[test]
    fn inert_actions_block_surfaces_not_verified_only() {
        let now = 1_780_000_000_i64;
        let evs = vec![
            mk_sev(
                "desktop",
                "action",
                "not_verified",
                "preflight_refusal",
                None,
                now - 300,
            ),
            mk_sev(
                "browser",
                "click",
                "verified",
                "ref_ok",
                Some("@e1"),
                now - 600,
            ),
            mk_sev(
                "mobile",
                "tap",
                "not_verified",
                "no_device",
                Some("@n3"),
                now - 90000,
            ),
        ];
        let block = format_inert_actions_block(&evs, now, 5).expect("has inert events");
        let text = block.join("\n");
        // Count in header reflects the 2 not_verified events (verified excluded).
        assert!(text.contains("Recent Inert/Failed Actions (2)"), "{text}");
        assert!(text.contains("desktop/action"), "{text}");
        assert!(text.contains("preflight_refusal"), "{text}");
        assert!(text.contains("mobile/tap @n3"), "{text}");
        // The verified row must NOT leak into the inert surface (anti-laundering
        // in reverse: we only surface the honestly-failed ones).
        assert!(!text.contains("ref_ok"), "verified row leaked: {text}");
        // §3.5 recover hints accompany each surfaced inert action.
        assert!(text.contains("↳ recover:"), "missing recover hint: {text}");
        assert!(text.contains("use_grant"), "preflight recover hint: {text}");
        assert!(
            text.contains("attach 设备"),
            "no_device recover hint: {text}"
        );
    }

    #[test]
    fn recover_hint_maps_known_failure_modes() {
        assert!(recover_hint("preflight_refusal")
            .unwrap()
            .contains("desktop_confirm"));
        assert!(recover_hint("dry-run_failed")
            .unwrap()
            .contains("desktop_verify"));
        assert!(recover_hint("isolated_injection_failed")
            .unwrap()
            .contains("desktop_verify"));
        assert!(recover_hint("no_device").unwrap().contains("adb"));
        assert!(recover_hint("adb_tap_failed").unwrap().contains("adb"));
        assert!(recover_hint("cdp_actionability_probe")
            .unwrap()
            .contains("browser_snapshot"));
        assert!(recover_hint("css_selector_dispatch")
            .unwrap()
            .contains("@eN"));
        assert!(recover_hint("lifecycle_failed").unwrap().contains("store"));
        // Methods with no obvious local remedy get no hint (not every NotVerified
        // is mechanically recoverable).
        assert!(recover_hint("ref_resolution_or_transport").is_none());
        assert!(recover_hint("some_unknown_method").is_none());
    }

    #[test]
    fn inert_actions_block_caps_and_counts_overflow() {
        let now = 1_780_000_000_i64;
        let evs: Vec<_> = (0..7)
            .map(|i| {
                mk_sev(
                    "desktop",
                    "action",
                    "not_verified",
                    "injection_failed",
                    None,
                    now - (i as i64) * 60,
                )
            })
            .collect();
        let block = format_inert_actions_block(&evs, now, 3).expect("has inert events");
        let text = block.join("\n");
        assert!(text.contains("Recent Inert/Failed Actions (7)"), "{text}");
        // 3 shown + an overflow line for the remaining 4.
        assert!(text.contains("… 4 more"), "{text}");
        let bullets = text.matches("  • ").count();
        assert_eq!(bullets, 3, "should cap to max_items: {text}");
    }

