    #[test]
    fn readiness_setup_state_file_row_reports_applied_state() {
        let nonce = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .expect("clock after epoch")
            .as_nanos();
        let dir = std::env::temp_dir().join(format!(
            "agent-bridge-readiness-setup-state-{}-{nonce}",
            std::process::id()
        ));
        std::fs::create_dir_all(&dir).expect("mkdir");
        let path = dir.join("setup-state.json");
        std::fs::write(
            &path,
            serde_json::to_string_pretty(&json!({
                "schema": "agent_bridge_setup_state.v0",
                "status": "applied",
                "applied_at_unix": 1_780_000_001_u64,
                "frontend": "codex",
                "codex_toolset": "codex-lean",
                "codex_tool_profile": "essential",
                "operation_count": 7,
                "state_path": path.display().to_string(),
            }))
            .expect("json"),
        )
        .expect("write state");

        let row = readiness_setup_state_file_row(&path);

        assert_eq!(row["checked"], json!(true));
        assert_eq!(row["exists"], json!(true));
        assert_eq!(row["readable"], json!(true));
        assert_eq!(row["valid_json"], json!(true));
        assert_eq!(row["ready"], json!(true));
        assert_eq!(row["schema"], "agent_bridge_setup_state.v0");
        assert_eq!(row["status"], "applied");
        assert_eq!(row["frontend"], "codex");
        assert_eq!(row["codex_toolset"], "codex-lean");
        assert_eq!(row["codex_tool_profile"], "essential");
        assert_eq!(row["operation_count"], json!(7));
        assert_eq!(row["applied_at_unix"], json!(1_780_000_001_u64));
        assert_eq!(row["state_path_matches"], json!(true));

        std::fs::remove_dir_all(&dir).ok();
    }

    // ── tool profile tier filter ──────────────────────────────────────────

    #[test]
    fn tool_profile_includes_correct_tiers() {
        // Essential profile: only essential tools.
        let p = ToolProfile::Essential;
        assert!(p.includes(Tier::Essential));
        assert!(!p.includes(Tier::Standard));
        assert!(!p.includes(Tier::Niche));

        // Standard profile: essential + standard, not niche.
        let p = ToolProfile::Standard;
        assert!(p.includes(Tier::Essential));
        assert!(p.includes(Tier::Standard));
        assert!(!p.includes(Tier::Niche));

        // All profile: everything.
        let p = ToolProfile::All;
        assert!(p.includes(Tier::Essential));
        assert!(p.includes(Tier::Standard));
        assert!(p.includes(Tier::Niche));
    }

    #[test]
    fn gate_ceremony_tools_stay_niche_out_of_eager_profile() {
        // Goal B / iron-law anti-bloat (RFC #1238). D1 gate-chain work tends to
        // mint one MCP tool per gate (preflight / acceptance / review-packet /
        // decision-record / runtime-gate / admission / persistence-chain …).
        // Left unchecked that grows the per-request schema of the EAGER profiles.
        // The rule: gate tools default to Tier::Niche (all-only, reachable via
        // the `all` profile / deferred), so the Standard eager profile stays
        // bounded. This guard fails if a gate-ceremony-named tool is exposed in
        // Standard without a justified allowlist entry — it forces "earn eager
        // exposure" over "one tool per gate". See memory
        // `project_goal_b_surface_per_request_bounded_keep_gate_tools_niche_20260622`.
        let policy = ToolPolicy::from_values(None, None, None, Some("standard"));
        let exposed: Vec<String> = build_registry_with_policy(Hub::builder().build(), policy)
            .list()
            .into_iter()
            .map(|schema| schema.name)
            .collect();

        const GATE_PATTERNS: &[&str] = &[
            "_preflight",
            "_review_packet",
            "_acceptance",
            "_dry_run",
            "_decision_record",
            "_runtime_gate",
            "_human_review",
            "_admission",
            "_persistence_chain",
            "_write_evidence",
        ];
        // Gate-named tools still justified in the eager Standard profile.
        // The T6 candidate-expansion gate chain is now Tier::Niche/all-only;
        // this allowlist should stay small and explicit.
        const EAGER_ALLOWLIST: &[&str] = &[
            "git_topology_preflight",
            "biocortex_retrieval_opt_in_dry_run",
            // Explicit-link diagnostics remain Standard for graph-hygiene
            // review lanes; write-capable materialize stays outside Essential.
            "memory_related_keys_preflight",
            "memory_related_keys_review_packet",
        ];

        let leaked: Vec<&str> = exposed
            .iter()
            .map(|s| s.as_str())
            .filter(|n| GATE_PATTERNS.iter().any(|p| n.contains(p)))
            .filter(|n| !EAGER_ALLOWLIST.contains(n))
            .collect();

        assert!(
            leaked.is_empty(),
            "gate-ceremony tools leaked into the eager Standard profile — keep them \
             Tier::Niche (all-only) or add a justified EAGER_ALLOWLIST entry: {leaked:?}"
        );
    }

