        assert!(p.includes(Tier::Standard, "forum_post"));
        assert!(p.includes(Tier::Standard, "forum_read"));
        assert!(p.includes(Tier::Standard, "forum_list_threads"));
        assert!(p.includes(Tier::Standard, "forum_subscribe"));
