    // A5 — with no browser backend, verify degrades to no_browser and the
    // artifact is STILL written + dual-encoded (degrade, don't fail).
    #[tokio::test]
    async fn present_degrades_to_no_browser_and_still_writes_artifact() {
        let _env = PRESENTATIONS_DIR_ENV_LOCK
            .lock()
            .unwrap_or_else(|e| e.into_inner());
        let dir = std::env::temp_dir().join(format!(
            "ab-present-test-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap_or_default()
                .as_nanos()
        ));
        std::env::set_var("AGENT_BRIDGE_PRESENTATIONS_DIR", &dir);

        let tool = PresentTool::new(Hub::builder().build());
        let out = tool
            .execute(
                json!({
                    "kind": "table",
                    "payload": [{"name": "e5", "dims": 384}],
                    "title": "A5",
                    "verify": true
                }),
                &ToolContext::default(),
            )
            .await
            .expect("execute");
        let res = result_text_as_json(&out);

        assert_eq!(res["verify_status"], "no_browser");
        assert_eq!(res["dual_encoding"], true);
        assert_eq!(res["kind"], "table");
        let artifact_path = res["artifact_path"].as_str().expect("artifact_path");
        let html = std::fs::read_to_string(artifact_path).expect("artifact written");
        assert!(html.contains("<table>"));
        assert!(html.contains("<td>e5</td>"));
        let recovered = crate::present::extract_ab_payload(&html).expect("payload recoverable");
        assert_eq!(recovered, json!([{"name": "e5", "dims": 384}]));
        let id = res["id"].as_str().expect("id");
        let outcome_path = dir.join(format!("{id}.outcome.json"));
        let outcome: serde_json::Value =
            serde_json::from_str(&std::fs::read_to_string(outcome_path).expect("outcome sidecar"))
                .expect("outcome json");
        assert_eq!(outcome["action_tool"], "present");
        assert_eq!(outcome["embody_status"], "not_applicable");

        std::env::remove_var("AGENT_BRIDGE_PRESENTATIONS_DIR");
        let _ = std::fs::remove_dir_all(&dir);
    }

    // present is a Niche opt-in tool: exposed only under the `all` profile
    // (like browser_*), absent from standard. Locks the tier against drift.
    #[test]
    fn present_is_niche_opt_in_and_registers_under_all() {
        let all = ToolPolicy::from_values(None, None, None, Some("all"));
        assert!(all.includes(Tier::Niche, "present"));
        let std_p = ToolPolicy::from_values(None, None, None, Some("standard"));
        assert!(!std_p.includes(Tier::Niche, "present"));
        // slice 2 present_replay + E3 present_dashboard are the same Niche opt-in shape.
        assert!(all.includes(Tier::Niche, "present_replay"));
        assert!(!std_p.includes(Tier::Niche, "present_replay"));
        assert!(all.includes(Tier::Niche, "present_dashboard"));
        assert!(!std_p.includes(Tier::Niche, "present_dashboard"));
        // Slice A present_outcomes is the same Niche opt-in shape.
        assert!(all.includes(Tier::Niche, "present_outcomes"));
        assert!(!std_p.includes(Tier::Niche, "present_outcomes"));
        // LSWR Step E2 admission projection is also Niche/all only.
        assert!(all.includes(Tier::Niche, "lswr_outcome_admissions"));
        assert!(!std_p.includes(Tier::Niche, "lswr_outcome_admissions"));
        // LSWR Step E3 admission dry-run adapter is also Niche/all only.
        assert!(all.includes(Tier::Niche, "lswr_outcome_admissions_dry_run"));
        assert!(!std_p.includes(Tier::Niche, "lswr_outcome_admissions_dry_run"));
        // LSWR Step E4c approval packet is also Niche/all only and read-only.
        assert!(all.includes(Tier::Niche, "lswr_outcome_admissions_approval_packet"));
        assert!(!std_p.includes(Tier::Niche, "lswr_outcome_admissions_approval_packet"));
        // LSWR Step E4d preflight is also Niche/all only and read-only.
        assert!(all.includes(Tier::Niche, "lswr_outcome_admissions_write_preflight"));
        assert!(!std_p.includes(Tier::Niche, "lswr_outcome_admissions_write_preflight"));
        // Audio embodiment present_voice is the same Niche opt-in shape.
        assert!(all.includes(Tier::Niche, "present_voice"));
        assert!(!std_p.includes(Tier::Niche, "present_voice"));
        // Live semantic world tools are Step C Niche opt-ins; absent from
        // standard/default profile surfaces until explicitly requested.
        for t in [
            "world_query",
            "world_patch",
            "world_visibility_query",
            "world_present",
        ] {
            assert!(
                all.includes(Tier::Niche, t),
                "{t} must be available under all"
            );
            assert!(
                !std_p.includes(Tier::Niche, t),
                "{t} must stay out of standard"
            );
        }
        // LSWR interaction-feedback/report display wrappers follow the same
        // all-profile opt-in shape as the world tools, but stay read-only and
        // explicit-payload-backed.
        assert!(all.includes(Tier::Niche, "lswr_interaction_feedback_consumption_report"));
        assert!(!std_p.includes(Tier::Niche, "lswr_interaction_feedback_consumption_report"));
        assert!(all.includes(Tier::Niche, "lswr_readonly_bridge_display"));
        assert!(!std_p.includes(Tier::Niche, "lswr_readonly_bridge_display"));
        let codex_essential = ToolPolicy::from_values(Some("codex-essential"), None, None, None);
        assert!(
            !codex_essential.includes(Tier::Niche, "lswr_interaction_feedback_consumption_report")
        );
        assert!(!codex_essential.includes(Tier::Niche, "lswr_readonly_bridge_display"));
        assert!(!codex_essential.includes(Tier::Niche, "lswr_outcome_admissions"));
        assert!(!codex_essential.includes(Tier::Niche, "lswr_outcome_admissions_dry_run"));
        assert!(!codex_essential.includes(Tier::Niche, "lswr_outcome_admissions_approval_packet"));
        assert!(!codex_essential.includes(Tier::Niche, "lswr_outcome_admissions_write_preflight"));
        let schemas = build_registry_with_policy(Hub::builder().build(), all).list();
        assert!(
            schemas.iter().any(|s| s.name == "present"),
            "present must register under the all profile"
        );
        assert!(
            schemas.iter().any(|s| s.name == "present_replay"),
            "present_replay must register under the all profile"
        );
        assert!(
            schemas.iter().any(|s| s.name == "present_dashboard"),
            "present_dashboard must register under the all profile"
        );
        assert!(
            schemas.iter().any(|s| s.name == "present_outcomes"),
            "present_outcomes must register under the all profile"
        );
        assert!(
            schemas.iter().any(|s| s.name == "lswr_outcome_admissions"),
            "lswr_outcome_admissions must register under the all profile"
        );
        assert!(
            schemas
                .iter()
                .any(|s| s.name == "lswr_outcome_admissions_dry_run"),
            "lswr_outcome_admissions_dry_run must register under the all profile"
        );
        assert!(
            schemas
                .iter()
                .any(|s| s.name == "lswr_outcome_admissions_approval_packet"),
            "lswr_outcome_admissions_approval_packet must register under the all profile"
        );
        assert!(
            schemas
                .iter()
                .any(|s| s.name == "lswr_outcome_admissions_write_preflight"),
            "lswr_outcome_admissions_write_preflight must register under the all profile"
        );
        assert!(
            schemas
                .iter()
                .any(|s| s.name == "lswr_outcome_admissions_ingest"),
            "lswr_outcome_admissions_ingest must register under the all profile"
        );
        assert!(
            schemas.iter().any(|s| s.name == "present_voice"),
            "present_voice must register under the all profile"
        );
        for t in [
            "world_query",
            "world_patch",
            "world_visibility_query",
            "world_present",
        ] {
            assert!(
                schemas.iter().any(|s| s.name == t),
                "{t} must register under the all profile"
            );
        }
        assert!(
            schemas
                .iter()
                .any(|s| s.name == "lswr_interaction_feedback_consumption_report"),
            "lswr_interaction_feedback_consumption_report must register under the all profile"
        );
        assert!(
            schemas
                .iter()
                .any(|s| s.name == "lswr_readonly_bridge_display"),
            "lswr_readonly_bridge_display must register under the all profile"
        );
        let standard_schemas = build_registry_with_policy(Hub::builder().build(), std_p).list();
        assert!(
            !standard_schemas
                .iter()
                .any(|s| s.name == "lswr_interaction_feedback_consumption_report"),
            "lswr_interaction_feedback_consumption_report must stay out of standard"
        );
        assert!(
            !standard_schemas
                .iter()
                .any(|s| s.name == "lswr_readonly_bridge_display"),
            "lswr_readonly_bridge_display must stay out of standard"
        );
        assert!(
            !standard_schemas
                .iter()
                .any(|s| s.name == "lswr_outcome_admissions"),
            "lswr_outcome_admissions must stay out of standard"
        );
        assert!(
            !standard_schemas
                .iter()
                .any(|s| s.name == "lswr_outcome_admissions_dry_run"),
            "lswr_outcome_admissions_dry_run must stay out of standard"
        );
        assert!(
            !standard_schemas
                .iter()
                .any(|s| s.name == "lswr_outcome_admissions_approval_packet"),
            "lswr_outcome_admissions_approval_packet must stay out of standard"
        );
        assert!(
            !standard_schemas
                .iter()
                .any(|s| s.name == "lswr_outcome_admissions_write_preflight"),
            "lswr_outcome_admissions_write_preflight must stay out of standard"
        );
        assert!(
            !standard_schemas
                .iter()
                .any(|s| s.name == "lswr_outcome_admissions_ingest"),
            "lswr_outcome_admissions_ingest must stay out of standard"
        );
        let codex_schemas =
            build_registry_with_policy(Hub::builder().build(), codex_essential).list();
        assert!(
            !codex_schemas
                .iter()
                .any(|s| s.name == "lswr_interaction_feedback_consumption_report"),
            "lswr_interaction_feedback_consumption_report must stay out of codex-essential"
        );
        assert!(
            !codex_schemas
                .iter()
                .any(|s| s.name == "lswr_outcome_admissions"),
            "lswr_outcome_admissions must stay out of codex-essential"
        );
        assert!(
            !codex_schemas
                .iter()
                .any(|s| s.name == "lswr_outcome_admissions_dry_run"),
            "lswr_outcome_admissions_dry_run must stay out of codex-essential"
        );
        assert!(
            !codex_schemas
                .iter()
                .any(|s| s.name == "lswr_outcome_admissions_approval_packet"),
            "lswr_outcome_admissions_approval_packet must stay out of codex-essential"
        );
        assert!(
            !codex_schemas
                .iter()
                .any(|s| s.name == "lswr_outcome_admissions_write_preflight"),
            "lswr_outcome_admissions_write_preflight must stay out of codex-essential"
        );
        assert!(
            !codex_schemas
                .iter()
                .any(|s| s.name == "lswr_outcome_admissions_ingest"),
            "lswr_outcome_admissions_ingest must stay out of codex-essential"
        );
    }

    #[test]
    fn lswr_outcome_admissions_dry_run_schema_has_no_write_switch() {
        let all = ToolPolicy::from_values(None, None, None, Some("all"));
        let schemas = build_registry_with_policy(Hub::builder().build(), all).list();
        let tool = schemas
            .iter()
            .find(|s| s.name == "lswr_outcome_admissions_dry_run")
            .expect("lswr_outcome_admissions_dry_run schema");

        assert!(tool.description.contains("DRY-RUN-ONLY"));
        assert!(tool.description.contains("Writes nothing"));
        assert_eq!(
            tool.input_schema["additionalProperties"],
            serde_json::Value::Bool(false)
        );
        assert!(tool.input_schema["properties"]
            .get("max_candidates")
            .is_some());
        for forbidden in ["dry_run", "max_writes", "write", "persist", "memory_save"] {
            assert!(
                tool.input_schema["properties"].get(forbidden).is_none(),
                "{forbidden} must not be exposed by the E3 dry-run tool"
            );
        }
    }

