    fn e4_unique_presentations_dir(tag: &str) -> std::path::PathBuf {
        std::env::temp_dir().join(format!(
            "ab-e4-ingest-{tag}-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap_or_default()
                .as_nanos()
        ))
    }

