    async fn save_store_trial_memory(hub: &Hub, key: &str, importance: f64, content: &str) {
        let store = hub.store.as_ref().expect("store");
        store
            .memory_save(&ab_store::MemoryRecord {
                key: key.to_string(),
                kind: "fact".to_string(),
                content: content.to_string(),
                tags: vec![],
                related_keys: vec![],
                scope: None,
                created_at: 0,
                updated_at: 0,
                last_accessed_at: 0,
                access_count: 0,
                importance,
                status: String::new(),
                trigger_pattern: None,
                superseded_by: None,
            })
            .await
            .expect("save memory");
    }

    async fn save_trigger_trial_memory(
        hub: &Hub,
        key: &str,
        content: &str,
        scope: Option<&str>,
    ) {
        let store = hub.store.as_ref().expect("store");
        store
            .memory_save(&ab_store::MemoryRecord {
                key: key.to_string(),
                kind: "decision".to_string(),
                content: content.to_string(),
                tags: vec![],
                related_keys: vec![],
                scope: scope.map(str::to_string),
                created_at: 0,
                updated_at: 0,
                last_accessed_at: 0,
                access_count: 0,
                importance: 0.9,
                status: String::new(),
                trigger_pattern: None,
                superseded_by: None,
            })
            .await
            .expect("save trigger trial memory");
    }

