    #[tokio::test]
    async fn memory_correction_is_idempotent_for_same_body() {
        // Same target + same correction_body → same derived key. The
        // second call must not error (memory_save replaces, memory_link
        // upserts).
        let (hub, temp_dir) = mk_test_hub_with_store().await;
        let store = hub.store.clone().expect("store");

        let target = MemoryRecord {
            key: "tests:idemp_target".into(),
            kind: "fact".into(),
            content: "anchor".into(),
            tags: vec![],
            related_keys: vec![],
            scope: None,
            created_at: 0,
            updated_at: 0,
            last_accessed_at: 0,
            access_count: 0,
            importance: 0.5,
            status: "active".into(),
            trigger_pattern: None,
            superseded_by: None,
        };
        store.memory_save(&target).await.expect("seed");

        let tool = MemoryCorrectionTool::new(hub.clone());
        let ctx = ToolContext::default();
        let args = json!({
            "target_key": "tests:idemp_target",
            "correction_body": "same correction text twice",
        });

        let r1 = tool.execute(args.clone(), &ctx).await.expect("call 1");
        let r2 = tool.execute(args.clone(), &ctx).await.expect("call 2");
        let extract = |r: &ab_mcp::ToolResult| -> String {
            match r.content.first() {
                Some(ab_mcp::ContentBlock::Text { text }) => text.clone(),
                _ => panic!("expected text content"),
            }
        };
        let v1: Value = serde_json::from_str(&extract(&r1)).unwrap();
        let v2: Value = serde_json::from_str(&extract(&r2)).unwrap();
        assert_eq!(v1["correction_key"], v2["correction_key"]);
        assert_eq!(v1["status"], json!("ok"));
        assert_eq!(v2["status"], json!("ok"));

        let _ = tokio::fs::remove_dir_all(&temp_dir).await;
    }

    #[tokio::test]
    async fn memory_retrieval_feedback_records_targeted_outcome_and_edge() {
        let (hub, temp_dir) = mk_test_hub_with_store().await;
        let store = hub.store.clone().expect("store");
        store
            .memory_save(&MemoryRecord {
                key: "tests:retrieved_stale_target".into(),
                kind: "decision".into(),
                content: "old retrieval target".into(),
                tags: vec![],
                related_keys: vec![],
                scope: None,
                created_at: 0,
                updated_at: 0,
                last_accessed_at: 0,
                access_count: 0,
                importance: 0.8,
                status: "active".into(),
                trigger_pattern: None,
                superseded_by: None,
            })
            .await
            .expect("seed target");

        let tool = MemoryRetrievalFeedbackTool::new(hub.clone());
        let out = tool
            .execute(
                json!({
                    "memory_key": "tests:retrieved_stale_target",
                    "outcome": "stale",
                    "source": "memory_search",
                    "query": "current task query",
                    "note": "The result referenced obsolete bootstrap behavior.",
                    "retrieved_keys": ["tests:retrieved_stale_target", "tests:missing_context"]
                }),
                &ToolContext::default(),
            )
            .await
            .expect("execute");
        let payload = result_text_as_json(&out);
        assert_eq!(payload["status"], json!("ok"));
        assert_eq!(payload["outcome"], json!("stale"));
        assert_eq!(payload["target_key"], json!("tests:retrieved_stale_target"));
        assert_eq!(payload["edge"]["edge_type"], json!("retrieval_stale"));
        let hint = payload["hint"].as_str().expect("hint");
        assert!(hint.contains("default FTS order is unchanged"));
        assert!(hint.contains("hybrid retrieval may observe"));

        let feedback_key = payload["feedback_key"].as_str().expect("feedback_key");
        let saved = store
            .memory_get(feedback_key)
            .await
            .expect("get feedback")
            .expect("feedback exists");
        assert_eq!(saved.kind, "feedback");
        assert!(saved.tags.contains(&"retrieval_feedback".to_string()));
        assert!(saved.tags.contains(&"retrieval_feedback:stale".to_string()));
        assert!(saved.tags.contains(&"retrieval_source:memory_search".to_string()));
        assert!(saved
            .related_keys
            .contains(&"tests:retrieved_stale_target".to_string()));
        assert!(saved.content.contains("outcome: stale"));
        assert!(saved.content.contains("query: current task query"));
        assert!(saved
            .content
            .contains("The result referenced obsolete bootstrap behavior."));

        let edges = store.memory_neighbors(feedback_key).await.expect("neighbors");
        assert!(
            edges.iter().any(|e| {
                e.edge_type == "retrieval_stale" && e.to_key == "tests:retrieved_stale_target"
            }),
            "expected retrieval_stale edge to target, got {edges:?}"
        );

        let _ = tokio::fs::remove_dir_all(&temp_dir).await;
    }

