    // ── L5 P3 — session-start feedback preamble ────────────────────────

    fn mk_feedback(key: &str, importance: f64, updated_at: i64) -> MemoryRecord {
        MemoryRecord {
            key: key.into(),
            kind: "feedback".into(),
            content: format!("body of {key}"),
            tags: vec![],
            related_keys: vec![],
            scope: None,
            created_at: updated_at,
            updated_at,
            last_accessed_at: 0,
            access_count: 0,
            importance,
            status: "active".into(),
            trigger_pattern: None,
            superseded_by: None,
        }
    }

    #[test]
    fn feedback_preamble_score_today_high_importance_beats_old_high_importance() {
        let now: i64 = 1_700_000_000;
        let one_day = 86_400;
        // Both importance 0.7; one written today, one 90d ago.
        let fresh = feedback_preamble_score(0.7, now, now);
        let old = feedback_preamble_score(0.7, now - 90 * one_day, now);
        assert!(
            fresh > old,
            "fresh feedback must outrank 90d-old at equal importance ({fresh} vs {old})"
        );
        // Recency contribution capped at 0.3 (multiplier × max recency 1.0).
        assert!(
            fresh - old <= 0.3 + 1e-9,
            "recency delta capped at 0.3 (got {})",
            fresh - old
        );
    }

    #[test]
    fn feedback_preamble_score_high_importance_beats_low_importance_at_equal_age() {
        let now: i64 = 1_700_000_000;
        let high = feedback_preamble_score(0.9, now, now);
        let low = feedback_preamble_score(0.3, now, now);
        assert!(high > low);
        assert!(
            (high - low - 0.6).abs() < 1e-9,
            "importance delta must dominate at zero age"
        );
    }

    #[test]
    fn pick_top_feedback_filters_non_feedback_and_non_active() {
        let now: i64 = 1_700_000_000;
        let mut rows = vec![mk_feedback("fb1", 0.9, now), mk_feedback("fb2", 0.5, now)];
        // Add a non-feedback row → must be filtered.
        let mut wrong_kind = mk_feedback("not_fb", 1.0, now);
        wrong_kind.kind = "fact".into();
        rows.push(wrong_kind);
        // Add an archived feedback row → must be filtered.
        let mut archived = mk_feedback("fb_archived", 1.0, now);
        archived.status = "archived".into();
        rows.push(archived);

        let picked = pick_top_feedback(rows, 5, now);
        assert_eq!(picked.len(), 2, "only active feedback survives");
        assert_eq!(picked[0].key, "fb1", "highest importance first");
        assert_eq!(picked[1].key, "fb2");
    }

    #[test]
    fn pick_top_feedback_truncates_to_k() {
        let now: i64 = 1_700_000_000;
        let rows: Vec<_> = (0..10)
            .map(|i| mk_feedback(&format!("fb{i}"), 0.5 + (i as f64) * 0.01, now))
            .collect();
        let picked = pick_top_feedback(rows, 3, now);
        assert_eq!(picked.len(), 3);
        // Highest importance (i=9, imp=0.59) wins.
        assert_eq!(picked[0].key, "fb9");
        assert_eq!(picked[1].key, "fb8");
        assert_eq!(picked[2].key, "fb7");
    }

    #[test]
    fn format_feedback_preamble_block_returns_none_on_empty() {
        let out = format_feedback_preamble_block(&[], false, 80);
        assert!(
            out.is_none(),
            "empty input → no section (avoids visual noise)"
        );
    }

    #[test]
    fn format_feedback_preamble_block_header_changes_with_compact_flag() {
        let now: i64 = 1_700_000_000;
        let rows = vec![mk_feedback("fb1", 0.7, now)];
        let full = format_feedback_preamble_block(&rows, false, 80).expect("non-empty");
        let compact = format_feedback_preamble_block(&rows, true, 80).expect("non-empty");
        assert!(
            full[0].contains("Behavioral Feedback Preamble"),
            "full header has long form, got {}",
            full[0]
        );
        assert!(
            compact[0].contains("Feedback preamble"),
            "compact header has short form, got {}",
            compact[0]
        );
        // Both modes include at least: header, blank, row, blank.
        assert!(full.len() >= 4);
        assert!(compact.len() >= 4);
    }

    // ── session_bootstrap per-block token cap (C, 2026-05-17) ───────────

    #[test]
    fn cap_block_lines_empty_input_returns_empty() {
        let got = cap_block_lines(vec![], 100);
        assert!(got.is_empty());
    }

    #[test]
    fn cap_block_lines_under_budget_unchanged() {
        // Short block well under any reasonable budget — no trim marker.
        let block = vec![
            "=== Header ===".to_string(),
            "short body".to_string(),
            "=== End ===".to_string(),
        ];
        let got = cap_block_lines(block.clone(), 200);
        assert_eq!(got, block, "under-budget block must be returned verbatim");
        assert!(
            !got.iter().any(|l| l.contains("trimmed")),
            "no trim marker when under budget"
        );
    }

    #[test]
    fn cap_block_lines_over_budget_truncates_with_marker() {
        // Build a 20-line block where each line is ~30 chars of alpha
        // (~7-8 tokens each, ~140-160 tokens total).
        let line_body = "x".repeat(30);
        let mut block: Vec<String> = vec!["=== Header ===".to_string()];
        for i in 0..20 {
            block.push(format!("line {} {}", i, line_body));
        }
        // Budget 30 tokens — should keep ~3-4 lines + marker.
        let got = cap_block_lines(block.clone(), 30);
        assert!(got.len() < block.len(), "truncated");
        let last = got.last().unwrap();
        assert!(
            last.contains("trimmed") && last.contains("more lines"),
            "trim marker present, got {:?}",
            last
        );
        // Header is always preserved.
        assert_eq!(got[0], "=== Header ===");
    }

    #[test]
    fn cap_block_lines_preserves_header_even_when_alone_over_budget() {
        // Header line bigger than budget — still kept because it's the
        // informational anchor; trim marker follows.
        let header = format!("=== {} ===", "X".repeat(200));
        let block = vec![header.clone(), "body line".to_string()];
        let got = cap_block_lines(block, 5);
        assert_eq!(got[0], header, "header preserved");
        // Either the body got dropped and marker added, or the body
        // fit in (header itself doesn't count toward budget cutoff for
        // line 0). We just require that the result is no larger than
        // the input.
        assert!(got.len() <= 2 || got[1].contains("trimmed"));
    }

    #[test]
    fn cap_block_lines_zero_budget_returns_unchanged() {
        // Defensive: budget=0 means "no cap requested" — pass through.
        let block = vec!["a".to_string(), "b".to_string()];
        let got = cap_block_lines(block.clone(), 0);
        assert_eq!(got, block);
    }

    #[test]
    fn cap_block_lines_trim_marker_exit_path_after_first_line() {
        // Confirm the truncation marker is exactly the trim string we
        // chose (regression-pin: callers grep this string in audits).
        let line_body = "y".repeat(40);
        let mut block: Vec<String> = vec!["=== Header ===".to_string()];
        for i in 0..10 {
            block.push(format!("line {} {}", i, line_body));
        }
        let got = cap_block_lines(block, 20);
        let last = got.last().unwrap();
        assert!(
            last.starts_with("  [...trimmed ") && last.ends_with(" more lines for budget]"),
            "exact trim marker shape, got {:?}",
            last
        );
    }

    #[test]
    fn cap_block_lines_oversized_multiline_body_keeps_prefix_not_hollow_header() {
        // The AGENT.md profile failure mode: a header followed by a SINGLE
        // multi-line body element that alone exceeds budget. Before the split
        // fix this dropped the whole body (header + bare trim marker = hollow);
        // now the body is split so a useful PREFIX survives.
        let body = (0..30)
            .map(|i| format!("discipline line {i} with some descriptive text"))
            .collect::<Vec<_>>()
            .join("\n");
        let block = vec![
            "=== Agent Self-Profile ===".to_string(),
            body,
            "=== End ===".to_string(),
        ];
        let got = cap_block_lines(block, 40);
        assert_eq!(got[0], "=== Agent Self-Profile ===", "header kept");
        // At least one real body line survived — not a hollow header+marker.
        assert!(
            got.iter().any(|l| l.contains("discipline line 0")),
            "a body prefix must survive, got {:?}",
            got
        );
        assert!(
            got.last().unwrap().contains("trimmed"),
            "trim marker present when truncated"
        );
    }

    #[test]
    fn cap_block_lines_multiline_under_budget_roundtrips_text() {
        // A multi-line single element under budget must reproduce identical
        // text after the split normalization (zero-regression invariant).
        let block = vec![
            "=== Header ===".to_string(),
            "alpha\nbeta\ngamma".to_string(),
            "=== End ===".to_string(),
        ];
        let got = cap_block_lines(block.clone(), 500);
        assert_eq!(
            got.join("\n"),
            block.join("\n"),
            "under-budget multiline must round-trip identically"
        );
        assert!(!got.iter().any(|l| l.contains("trimmed")));
    }

